// Machine-assisted translation, unreviewed. French TL;DRs keyed by entity id.
// Coverage: all cancers. Drug and brand names stay in Latin script.
export const tldr_fr: Record<string, string> = {
  // ---- cancers ----
  tnbc: "Un cancer du sein dépourvu des trois récepteurs (œstrogène, progestérone, HER2) par lesquels on traite les autres cancers du sein. Ce fut le sous-type le plus difficile pendant des décennies ; depuis 2020, l'immunothérapie et les ADC ont changé la donne.",
  "breast-hr-positive": "Le cancer du sein le plus fréquent, alimenté par les œstrogènes. Traité pendant des années par des comprimés bloquant les hormones, aujourd'hui rejoints par les inhibiteurs de CDK4/6, les médicaments de la voie PI3K, les dégradeurs et les ADC.",
  "breast-her2-positive": "Autrefois le sous-type le plus agressif, aujourd'hui l'un des plus traitables grâce au trastuzumab et, plus récemment, à Enhertu.",
  nsclc: "Le cancer qui tue le plus et le terrain d'essai de la médecine de précision : une douzaine de mutations ciblables, l'immunothérapie pour le reste, et les ADC et bispécifiques qui arrivent maintenant.",
  sclc: "Un cancer du poumon à croissance rapide qui répond à la chimiothérapie puis récidive vite. Après 30 ans sans progrès, les engageurs de lymphocytes T et les ADC font enfin bouger les choses.",
  colorectal: "Le cancer où le dépistage marche le mieux et où l'immunothérapie peut faire disparaître complètement certaines tumeurs, alors que la plupart des maladies métastatiques dépendent encore de la chimiothérapie.",
  pancreatic: "Le cancer courant le plus mortel. Presque toutes les tumeurs portent une mutation de KRAS et, pour la première fois, des médicaments dirigés contre elle sont en essais pivots.",
  gastric: "Un cancer avec trois nouvelles cibles en cinq ans : Claudine 18.2, FGFR2b et HER2 avec de nouveaux ADC, plus l'immunothérapie en première ligne.",
  esophageal: "Le cancer de l'œsophage est en réalité deux maladies dans un même organe : le carcinome épidermoïde, dominant en Asie, et l'adénocarcinome, dominant en Occident et traité comme le cancer gastrique. L'immunothérapie est désormais standard, et l'ADC bispécifique iza-bren a obtenu une phase 3 positive dans le type épidermoïde en 2026.",
  hcc: "Le cancer du foie se développe presque toujours dans un foie déjà abîmé par une hépatite, l'alcool ou la stéatose. C'est l'un des cancers les plus évitables, et depuis 2020 les combinaisons d'immunothérapie ont à peu près doublé la survie des formes avancées.",
  cholangiocarcinoma: "Le cholangiocarcinome est un cancer des voies biliaires ou de la vésicule. Rare et souvent découvert tard, il s'est révélé porter plus de mutations ciblables que presque tout autre cancer digestif, et l'immunothérapie s'ajoute désormais à la chimiothérapie dès le premier traitement.",
  prostate: "Le berceau de la théranostique : le TEP au PSMA le trouve, les radioligands du PSMA le traitent. L'hormonothérapie reste la base, avec des inhibiteurs de PARP et d'AKT ajoutés selon le génotype.",
  urothelial: "Le cancer de la vessie est passé de 40 ans de cisplatine à une association ADC-immunothérapie qui a presque doublé la survie, et en 2026 à la première approbation guidée par un test sanguin.",
  rcc: "Le cancer du rein est le lieu où les antiangiogéniques et l'immunothérapie se sont rejoints, et où une voie de détection de l'oxygène couronnée par un Nobel a donné un médicament, le belzutifan.",
  ovarian: "Souvent découvert tard. Les inhibiteurs de PARP ont transformé le traitement d'entretien, et des ADC contre le récepteur des folates et CDH6 arrivent pour la maladie résistante au platine.",
  endometrial: "Le cancer gynécologique où l'immunothérapie a eu le plus grand impact, guidée par la classification moléculaire.",
  cervical: "Un cancer que la vaccination anti-HPV et le dépistage pourraient éliminer. Pour celles qui le développent, l'immunothérapie et un ADC dirigé contre le facteur tissulaire ont amélioré la survie.",
  melanoma: "Le cancer qui a prouvé que l'immunothérapie fonctionne : la moitié des patients avancés vivent désormais 10 ans. Aussi le premier avec une thérapie TIL approuvée, un virus oncolytique et un vaccin personnalisé avec une phase 3 positive.",
  glioblastoma: "Le glioblastome est la tumeur cérébrale la plus mortelle, à peine améliorée depuis 2005. Les gliomes de bas grade avec mutation d'IDH, eux, ont reçu leur premier médicament ciblé en 2024.",
  "head-and-neck": "Cancers de la bouche et de la gorge, de plus en plus causés par le HPV. L'immunothérapie est la première ligne en maladie avancée et s'utilise désormais avant la chirurgie.",
  sarcoma: "Des dizaines de cancers rares de l'os et des tissus conjonctifs. Le GIST fut la première tumeur solide guérie en pratique par un comprimé ciblé ; le sarcome synovial a reçu la première thérapie TCR-T.",
  thyroid: "Le cancer de la thyroïde se guérit généralement par chirurgie et iode radioactif, la théranostique originelle. Les rares formes agressives répondent aux inhibiteurs de RET et de BRAF.",
  neuroendocrine: "Une famille de tumeurs généralement lentes qui naissent dans les cellules productrices d'hormones de l'intestin, du pancréas et des poumons. Elles ont ouvert la voie à l'idée d'utiliser la même molécule pour voir une tumeur à l'imagerie puis la traiter par radiation.",
  mesothelioma: "Un cancer de la plèvre causé par l'amiante. Les doublets d'immunothérapie ont remplacé la chimiothérapie en 2020, et un CAR-T contre la mésothéline est à l'étude.",
  neuroblastoma: "Un cancer des cellules nerveuses de l'enfant où les anticorps anti-GD2 et, récemment, les CAR-T anti-GD2 ont amélioré la survie dans la maladie à haut risque.",
  aml: "La leucémie aiguë myéloïde est un cancer du sang agressif où, après 40 ans de la même chimiothérapie, une vague de médicaments ciblés est arrivée (FLT3, IDH, BCL-2, ménine).",
  "all-leukemia": "La leucémie aiguë lymphoblastique est l'histoire à succès du cancer de l'enfant, et fut la première maladie traitée par CAR-T et par un engageur de lymphocytes T.",
  cll: "Une leucémie lente qui n'a plus besoin de chimiothérapie : les inhibiteurs de BTK et le vénétoclax la contrôlent pendant des années, souvent en cures de durée fixe.",
  dlbcl: "Le lymphome diffus à grandes cellules B (DLBCL) est un lymphome agressif mais curable. Le CAR-T guérit environ 40 % des patients en rechute, et des bispécifiques prêts à l'emploi sont désormais approuvés.",
  "hodgkin-lymphoma": "Le lymphome de Hodgkin est l'un des cancers les plus curables ; l'objectif est désormais de guérir avec moins de toxicité, avec le brentuximab et, depuis 2026, le nivolumab en première ligne.",
  "multiple-myeloma": "Le myélome multiple est un cancer des plasmocytes qui compte plus de nouvelles classes de médicaments que tout autre : inhibiteurs du protéasome, IMiD, anticorps anti-CD38, CAR-T anti-BCMA, bispécifiques et un ADC.",
  adrenocortical: "Le carcinome corticosurrénalien est un cancer rare et agressif de la glande surrénale qui produit souvent trop d'hormones. La chirurgie est la seule guérison, le mitotane est le seul médicament qui lui soit propre (avec une vraie toxicité), et la chimiothérapie ou l'immunothérapie n'aident qu'une minorité.",
  anal: "Un cancer du canal anal causé par le HPV, généralement guéri sans chirurgie par l'association de chimiothérapie et de radiothérapie. La prévention (vaccination anti-HPV, dépistage des groupes à risque) et l'immunothérapie pour la maladie avancée sont les nouveaux fronts.",
  appendiceal: "Des tumeurs rares de l'appendice, allant de proliférations lentes qui produisent du mucus et remplissent l'abdomen (pseudomyxome péritonéal) à des adénocarcinomes agressifs. Les formes lentes sont traitées par une chirurgie étendue avec chimiothérapie chauffée dans l'abdomen ; les rapides comme un cancer du côlon.",
  "basal-cell-carcinoma": "Le carcinome basocellulaire est le cancer le plus fréquent de tous, causé par le soleil et presque jamais mortel. Presque tous sont retirés chirurgicalement ; les rares cas avancés sont traités par des médicaments bloquant la voie de signalisation hedgehog, puis par immunothérapie si ceux-ci échouent.",
  bpdcn: "Un cancer du sang très rare et agressif issu des précurseurs des cellules dendritiques, qui se manifeste souvent par des lésions cutanées ressemblant à des bleus. Deux médicaments dirigés contre CD123 sont les premières thérapies ciblées ; la greffe reste nécessaire pour guérir.",
  "cancer-of-unknown-primary": "Un cancer découvert déjà disséminé, dont les médecins ne trouvent pas l'origine. La plupart des cas reçoivent une chimiothérapie générale et évoluent mal ; les tests moléculaires pour deviner l'origine ou trouver une cible changent lentement la situation.",
  cml: "La leucémie myéloïde chronique est un cancer du sang provoqué par un seul gène de fusion, BCR-ABL. L'imatinib, en 2001, a transformé une maladie dont la survie médiane était d'environ cinq ans en une maladie avec laquelle la plupart des gens vivent, et beaucoup peuvent désormais arrêter tout traitement.",
  "cutaneous-scc": "Un cancer de la peau très fréquent lié au soleil, presque toujours guéri par son ablation. La petite fraction qui s'enfonce ou se dissémine répond désormais bien à l'immunothérapie anti-PD-1, également donnée après la chirurgie dans les cas à haut risque.",
  "ewing-sarcoma": "Le sarcome d'Ewing est un cancer de l'os et des tissus mous de l'adolescent, provoqué par un seul gène de fusion, EWSR1-FLI1. Une chimiothérapie intensive avec chirurgie ou radiothérapie guérit la plupart des cas localisés ; la maladie disséminée et la rechute restent très difficiles, et la protéine de fusion elle-même a résisté à la conception de médicaments.",
  "follicular-lymphoma": "Le lymphome folliculaire est le lymphome lent le plus fréquent. La plupart des gens vivent de nombreuses années avec, traités seulement quand il pose problème ; il se contrôle à répétition mais se guérit rarement, et une minorité se transforme en lymphome agressif.",
  gist: "Le GIST est un sarcome de la paroi digestive presque toujours provoqué par une mutation de KIT ou de PDGFRA. Il a prouvé qu'un comprimé peut contrôler une tumeur solide : l'imatinib a fait passer la survie médiane d'environ un an à huit ans ou plus, et la mutation dicte désormais le médicament à utiliser.",
  "gestational-trophoblastic": "Des cancers qui naissent du tissu placentaire après une grossesse. Ils produisent une hormone (hCG) qui sert de test sanguin parfait, et ils furent le premier cancer solide jamais guéri par chimiothérapie. L'immunothérapie sauve désormais les rares cas résistants aux médicaments.",
  "hairy-cell-leukemia": "La leucémie à tricholeucocytes est une leucémie B rare et lente avec une seule mutation caractéristique (BRAF V600E), exceptionnellement curable : une semaine d'analogue des purines met la plupart des gens en rémission pour des années, et les médicaments anti-BRAF sauvent ceux qui rechutent.",
  hepatoblastoma: "Un cancer du foie du jeune enfant, hautement curable par chimiothérapie au cisplatine et chirurgie, y compris la greffe de foie quand la tumeur ne peut pas être retirée. Un succès récent a été de prouver qu'un simple antidote prévient la perte d'audition permanente causée par le cisplatine.",
  "kaposi-sarcoma": "Un cancer des vaisseaux sanguins causé par un herpèsvirus, rendu célèbre par l'épidémie de sida. Chez les personnes vivant avec le VIH, le traitement antirétroviral seul le fait souvent régresser ; la chimiothérapie comme la doxorubicine liposomale ou le paclitaxel traite la maladie avancée, et il reste un cancer majeur en Afrique.",
  "mantle-cell-lymphoma": "Un lymphome B peu fréquent, provoqué par la cycline D1, qui évoluait mal chez presque tout le monde. Les inhibiteurs de BTK, le CAR-T et désormais les médicaments anti-BCL2 l'ont fait passer de la chimiothérapie plus greffe aux combinaisons ciblées.",
  medulloblastoma: "Le médulloblastome est la tumeur cérébrale maligne la plus fréquente de l'enfant, née dans le cervelet. Chirurgie, irradiation de tout le cerveau et de la moelle, et chimiothérapie guérissent environ 70 %, à un lourd prix pour la pensée et la croissance ; le traitement est désormais adapté à quatre sous-groupes moléculaires pour que les enfants à faible risque en reçoivent moins.",
  "merkel-cell-carcinoma": "Le carcinome à cellules de Merkel est un cancer de la peau rare et à croissance rapide, généralement causé par un virus courant (le polyomavirus des cellules de Merkel) ou par les dégâts du soleil. Presque intraitable une fois disséminé, il répond désormais durablement à l'immunothérapie anti-PD-1/PD-L1 chez environ la moitié des patients.",
  mds: "Des maladies de la moelle osseuse où les cellules sanguines sont mal fabriquées et trop peu atteignent le sang ; un tiers évolue vers une leucémie aiguë. Le traitement va des transfusions et facteurs de croissance aux agents hypométhylants et, pour les patients en forme, à la greffe.",
  "myeloproliferative-neoplasms": "Des cancers du sang à évolution lente dans lesquels la moelle produit trop de globules rouges, de plaquettes ou de tissu cicatriciel. Presque tous portent une mutation de JAK2, CALR ou MPL. Le traitement vise à prévenir les caillots, à contrôler les symptômes et, dans la myélofibrose, à réduire la rate.",
  nasopharyngeal: "Un cancer de l'arrière du nez, dû en grande partie au virus d'Epstein-Barr et fréquent dans le sud de la Chine et en Asie du Sud-Est. La radiothérapie guérit la plupart des cas précoces ; l'ajout de chimiothérapie et, récemment, d'immunothérapie anti-PD-1 a amélioré les résultats en maladie avancée, et un test sanguin de l'ADN viral peut le détecter tôt.",
  osteosarcoma: "L'ostéosarcome est le cancer de l'os le plus fréquent, surtout chez les adolescents. Chimiothérapie plus chirurgie guérissent environ deux tiers des cas non disséminés, mais la survie n'a pas progressé en 30 ans et aucun nouveau médicament n'a réussi dans un grand essai.",
  "peripheral-t-cell-lymphoma": "Les lymphomes T périphériques sont des lymphomes des lymphocytes T plutôt que B. Ils sont plus rares, plus variés et, à part quelques sous-types, plus difficiles à traiter que les lymphomes B ; plusieurs nouveaux médicaments n'aident que des sous-types précis.",
  "primary-cns-lymphoma": "Le lymphome primitif du système nerveux central est un lymphome confiné au cerveau, aux yeux et au liquide céphalorachidien. Contrairement à la plupart des tumeurs cérébrales, il est chimiosensible : un traitement à base de méthotrexate à haute dose guérit une minorité substantielle, et la consolidation par autogreffe a remplacé l'irradiation du cerveau entier chez les patients en forme.",
  retinoblastoma: "Un cancer de l'œil du nourrisson causé par la perte du gène RB1, le premier gène suppresseur de tumeur jamais découvert. Dans les pays riches, presque tous les enfants survivent et la plupart des yeux sont sauvés par une chimiothérapie délivrée par l'artère de l'œil ; dans les pays pauvres, beaucoup d'enfants meurent encore parce qu'il est découvert trop tard.",
  rhabdomyosarcoma: "Un cancer des tissus mous de l'enfant, fait de cellules ressemblant à du muscle, qui peut apparaître de l'orbite à la vessie. La plupart des enfants sont guéris par chimiothérapie, chirurgie et radiothérapie, et un gène de fusion (PAX-FOXO1) décide désormais de l'intensité du traitement.",
  "salivary-gland": "Les cancers des glandes salivaires forment une famille de plus de 20 cancers rares, chacun avec son propre comportement et souvent sa propre fusion génique. Chirurgie et radiothérapie traitent la plupart ; le traitement médicamenteux est désormais choisi selon le sous-type, des anti-HER2 ou anti-androgènes aux inhibiteurs de NTRK.",
  testicular: "Les tumeurs germinales du testicule sont le cancer solide de l'adulte le plus curable. La chimiothérapie à base de cisplatine guérit la grande majorité, même en cas de dissémination étendue ; la recherche actuelle cherche à traiter moins la majorité tout en sauvant les rares patients qui rechutent.",
  "thymic-epithelial": "Le thymome et le carcinome thymique sont des tumeurs rares du thymus, dans le thorax. Les thymomes évoluent lentement, causent souvent des maladies auto-immunes comme la myasthénie et se guérissent généralement par chirurgie ; les carcinomes thymiques se comportent comme d'autres cancers agressifs et disposent de peu de médicaments efficaces.",
  "uveal-melanoma": "Un mélanome à l'intérieur de l'œil, biologiquement sans rapport avec le mélanome cutané : des mutations différentes, pas de réponse à l'immunothérapie standard, et une tendance à se disséminer au foie des années plus tard. Le tebentafusp est le premier médicament à avoir prolongé la survie dans la maladie métastatique.",
  vulvar: "Un cancer peu fréquent des organes génitaux externes avec deux causes distinctes : l'infection à HPV chez les femmes jeunes et l'inflammation cutanée chronique chez les femmes âgées. La chirurgie reste le pilier, et la biopsie du ganglion sentinelle l'a rendue bien moins mutilante.",
  waldenstrom: "Un lymphome lent qui produit un anticorps IgM anormal, causant un sang épais, une anémie et des atteintes nerveuses. Presque tous les cas partagent une mutation (MYD88 L265P), et les inhibiteurs de BTK le contrôlent pendant des années.",
  "wilms-tumor": "La tumeur de Wilms est un cancer du rein du jeune enfant et l'une des réussites de l'oncologie pédiatrique : la chirurgie plus quelques mois de chimiothérapie guérissent environ neuf enfants sur dix. Les essais actuels visent à donner presque aucune chimiothérapie aux enfants à plus faible risque tout en repérant les rares cas à biologie agressive.",
  // ---- most-connected records without translations (2026-09 wave) ----
  aacr: "L'AACR est la plus ancienne et la plus grande société de recherche sur le cancer ; c'est lors de son congrès d'avril qu'apparaissent la science à un stade précoce et les premières données chez l'humain.",
  abbvie: "AbbVie possède Venclexta et Elahere, et a racheté Capstan, la principale entreprise de CAR-T in vivo.",
  abemaciclib: "L'abemaciclib a été le premier inhibiteur de CDK4/6 approuvé après la chirurgie pour le cancer du sein hormonosensible à haut risque.",
  abiraterone: "Abiraterone est un comprimé qui arrête la production de testostérone partout dans l'organisme, y compris à l'intérieur de la tumeur. Découvert à l'Institute of Cancer Research, il est aujourd'hui générique et utilisé dès le premier diagnostic de métastases.",
  acalabrutinib: "Acalabrutinib est un bloqueur de BTK plus propre, avec moins de problèmes cardiaques et de saignements que l'ibrutinib. En février 2026, il est devenu la moitié du premier traitement de la leucémie lymphoïde chronique (CLL) entièrement par voie orale et de durée fixe.",
  "accelerated-approval": "Approbation de la FDA fondée sur des preuves précoces (comme la réduction de la tumeur), à condition qu'un essai de confirmation suive.",
  "active-surveillance": "Pour le cancer de la prostate à faible risque, une surveillance par PSA, MRI et biopsies répétées au lieu d'un traitement, car la plupart de ces cancers ne causent jamais de dommages.",
  actrec: "Le campus de recherche et développement du Tata Memorial Centre, où a été mise au point la première thérapie CAR-T indigène de l'Inde et où sont conçus des essais à faible coût.",
  adagrasib: "Adagrasib a été le deuxième inhibiteur de KRAS G12C, avec une longue demi-vie et une pénétration dans le cerveau, et il est approuvé dans le cancer du poumon et le cancer colorectal.",
  adc: "Un conjugué anticorps-médicament est un missile guidé : un anticorps se dirige vers la cellule tumorale, y est absorbé, puis libère une chimiothérapie si puissante qu'elle ne pourrait jamais être administrée seule.",
  "adc-generations": "Vingt-cinq ans d'efforts pour que la chimiothérapie ne frappe que les cellules cancéreuses, du premier ADC instable aux blockbusters de troisième génération d'aujourd'hui et à la quatrième génération actuellement en essais.",
  "adc-sequencing": "La question encore ouverte de savoir si un second ADC fonctionne après l'échec du premier, surtout lorsque les deux transportent le même type de charge utile.",
  adcs: "Un anticorps qui trouve la tumeur, porteur d'une dose minuscule de chimiothérapie très puissante qui n'est libérée qu'à l'intérieur de celle-ci.",
  "ai-computation": "Des logiciels qui lisent les images médicales et les lames, prédisent les résultats, conçoivent des médicaments et orientent les patients vers des essais.",
  "ai-drug-design": "Utiliser l'apprentissage automatique pour choisir des cibles, concevoir des molécules et des anticorps, et prédire quel ADC fonctionnera.",
  "ai-oncology-clinic": "Comment l'IA passe de lecteurs d'images et de lames limités à une seule tâche à des systèmes qui pèsent tout ce qui concerne un patient, et ce que les régulateurs et les preuves exigent encore.",
  "ai-trial-matching": "Des logiciels, de plus en plus fondés sur des LLM, qui lisent le dossier d'un patient et trouvent les essais ou les options recommandées par les guides de pratique auxquels il est admissible.",
  akt: "AKT est une kinase de survie centrale située en aval de PI3K, bloquée par le capivasertib dans le cancer du sein et désormais dans le cancer de la prostate.",
  alk: "Une fusion de gènes présente dans environ 5 % des cancers du poumon, qui répond de façon spectaculaire à des comprimés, désormais pendant de nombreuses années.",
  "allogeneic-cell-therapy": "Des thérapies cellulaires fabriquées à l'avance à partir de donneurs sains, pour que les patients n'aient pas à attendre que leurs propres cellules soient modifiées.",
  "allogeneic-hsct": "Remplacer le système sanguin d'un patient par celui d'un donneur, afin que les cellules immunitaires du donneur traquent toute leucémie restante. C'est encore le seul traitement curatif pour de nombreuses leucémies à haut risque.",
  amgen: "Amgen a inventé le format BiTE d'engageurs de cellules T et le premier inhibiteur de KRAS.",
  amivantamab: "Un anticorps à deux bras qui bloque EGFR et son partenaire d'échappement MET, désormais utilisé en première ligne avec le lazertinib dans le cancer du poumon avec mutation d'EGFR.",
  ampullary: "Le cancer ampullaire naît à l'endroit où les canaux biliaire et pancréatique se déversent dans l'intestin grêle. Comme il bloque tôt l'écoulement de la bile, il est souvent détecté alors qu'il est encore opérable, et l'intervention de Whipple guérit une bonne part des patients. Les tumeurs sont de deux types, de type intestinal et de type pancréatique, et la chimiothérapie est de plus en plus choisie selon celui que le pathologiste observe.",
  "androgen-deprivation": "La privation androgénique abaisse la testostérone ou bloque son récepteur, et constitue le fondement du traitement du cancer de la prostate depuis 1941 (prix Nobel 1966).",
  "androgen-receptor": "L'interrupteur hormonal qui alimente le cancer de la prostate, attaqué par la castration et par des comprimés qui bloquent le récepteur.",
  "angiogenic-switch": "Une tumeur ne peut pas grossir au-delà de quelques millimètres sans son propre apport sanguin. L'« interrupteur » bascule lorsque les signaux appelant de nouveaux vaisseaux (VEGF, FGF, angiopoïétine) l'emportent sur ceux qui les freinent (thrombospondine). Les vaisseaux qui en résultent sont perméables et désordonnés, ce qui prive la tumeur d'oxygène, bloque les médicaments et offre aux cellules cancéreuses une porte de sortie.",
  antiangiogenic: "La thérapie anti-angiogénique coupe l'apport sanguin de la tumeur ; elle est aujourd'hui surtout utilisée pour aider l'immunothérapie à mieux fonctionner.",
  "antigen-presentation-immunoediting": "Comment le système immunitaire voit le cancer, et comment le cancer apprend à se cacher. Les tumeurs exposent des fragments de leurs protéines sur les molécules du MHC ; les cellules T tuent celles qu'elles reconnaissent ; les survivantes sont celles qui ont cessé de montrer des fragments ou qui ont activé des freins.",
  anzup: "Le groupe australien d'essais en cancérologie génito-urinaire à l'origine de TheraP et proPSMA, les essais qui ont fait connaître l'imagerie PSMA et le traitement par lutétium-PSMA.",
  "apoptosis-bcl2": "L'apoptose intrinsèque est l'interrupteur d'autodestruction de la cellule. BCL-2 le maintient fermé ; BAX et BAK l'ouvrent. Le venetoclax décroche BCL-2 pour que l'interrupteur puisse se déclencher.",
  "ar-signaling": "La signalisation du récepteur des androgènes est le moteur du cancer de la prostate. La testostérone est transformée en DHT, se lie au récepteur des androgènes et active les gènes de croissance. La castration supprime le carburant ; les nouveaux comprimés bloquent le récepteur ou l'enzyme qui fabrique du carburant à l'intérieur de la tumeur.",
  "armored-car": "Des cellules CAR-T améliorées qui sécrètent aussi des stimulants immunitaires, résistent à l'épuisement ou ne s'activent qu'en présence de deux signaux.",
  asco: "L'ASCO est la plus grande société professionnelle d'oncologie du monde ; son congrès annuel, chaque mois de juin, est le lieu où la plupart des essais qui changent la pratique clinique sont présentés pour la première fois.",
  "aspirin-cancer-prevention": "L'aspirine quotidienne à faible dose réduit le risque de cancer de l'intestin chez les personnes atteintes du syndrome de Lynch et semble diminuer les récidives des cancers de l'intestin porteurs d'une mutation particulière. Chez les personnes âgées en bonne santé, elle a fait plus de mal que de bien.",
  astrazeneca: "AstraZeneca est le grand laboratoire pharmaceutique le plus engagé dans les ADC, copropriétaire d'Enhertu et de Datroway, avec de forts paris sur les thérapies ciblées et la radiopharmacie.",
  atezolizumab: "Un inhibiteur de PD-L1 utilisé dans les cancers du poumon, du foie et de la vessie. En 2026, il est devenu le premier médicament approuvé sur la base d'un test sanguin montrant un reste de cancer après une chirurgie de la vessie.",
  atr: "ATR est une kinase qui donne l'alerte en cas de dommages à l'ADN. La bloquer fait s'effondrer les tumeurs dont les systèmes de réparation sont défaillants, sous le poids de leur propre stress de réplication.",
  atrt: "L'ATRT est une tumeur cérébrale agressive des bébés et des tout-petits, causée par la perte d'un seul gène, SMARCB1, qui fait partie de la machinerie qui ouvre et ferme l'ADN. Une chimiothérapie intensive avec sauvetage par cellules souches, et une radiothérapie lorsque l'âge le permet, guérissent aujourd'hui une part significative des enfants qui avaient autrefois peu de chances, et des médicaments visant la conséquence épigénétique de la perte de SMARCB1 (les inhibiteurs d'EZH2) sont en cours d'essais.",
  "autologous-stem-cell-transplant": "On prélève les cellules souches sanguines du patient lui-même, on administre une dose très élevée de chimiothérapie qui détruirait autrement la moelle, puis on lui réinjecte ses cellules pour la reconstruire.",
  "axicabtagene-ciloleucel": "Une CAR-T anti-CD19 qui guérit environ 40 % des patients atteints d'un lymphome à grandes cellules B chez qui tout avait échoué, et qui a surpassé la greffe en deuxième ligne.",
  azacitidine: "Une chimiothérapie douce qui réactive des gènes mis en silence. Associée au venetoclax, elle est devenue le traitement standard des personnes âgées atteintes d'AML qui ne peuvent pas recevoir de traitement intensif.",
  "b-aging-comorbidity": "La plupart des personnes atteintes de cancer ont plus de 65 ans, mais la plupart des patients des essais sont plus jeunes et en meilleure forme. Nous devinons comment traiter la majorité.",
  "b-ai-validation": "Des milliers de modèles d'IA en cancérologie sont publiés ; une poignée est utilisée en clinique, et encore moins ont démontré qu'ils aident les patients.",
  "b-biomarker-validation": "Les tests qui décident qui reçoit un médicament ne sont souvent pas validés de manière prospective et sont mesurés différemment dans chaque laboratoire.",
  "b-brain-delivery": "La plupart des médicaments ne peuvent pas pénétrer dans le cerveau, si bien que les tumeurs cérébrales et les métastases cérébrales accusent un retard par rapport à toutes les autres localisations.",
  "b-cachexia-supportive": "Le dépérissement et l'intolérance aux traitements empêchent de nombreux patients de recevoir les doses qui seraient efficaces. Soigner le patient, et pas seulement la tumeur, reste très en retard.",
  "b-care-fragmentation": "Les patients passent entre les mailles du filet entre spécialistes, attendent des orientations et, souvent, ne reçoivent pas le traitement que les recommandations prévoient.",
  "b-combination-space": "Il existe des milliers de paires et de séquences de médicaments possibles. Les essais peuvent en tester quelques dizaines par an.",
  "b-data-silos": "Dossiers, imageries, génomes et résultats sont stockés dans des systèmes séparés qui ne communiquent pas entre eux. L'expérience de chaque patient est perdue pour le suivant.",
  "b-dormancy-mrd": "Après un traitement « réussi », des cellules peuvent rester endormies pendant des années puis provoquer une rechute. Nous les détectons à peine et ne savons pas les cibler.",
  "b-dose-optimisation": "La plupart des doses de médicaments ont été choisies comme la plus forte qu'une personne peut tolérer, ce qui est souvent plus que nécessaire.",
  "b-drug-pricing": "Les nouveaux médicaments contre le cancer coûtent couramment plus de 150 000 dollars par an, souvent pour quelques mois de bénéfice. Les systèmes de santé ne peuvent pas les payer et les patients se ruinent.",
  "b-early-detection": "Le dépistage n'existe que pour quelques cancers. Les cancers du pancréas, de l'ovaire, du foie, de l'œsophage et la plupart des cancers du poumon sont découverts quand la guérison est peu probable.",
  "b-funding-allocation": "L'argent va aux cancers et aux questions faciles ou à la mode, pas à ceux qui pèsent le plus lourd ni là où chaque dollar ferait le plus de bien.",
  "b-generic-repurposing": "Les vieux médicaments bon marché qui montrent des signes d'activité anticancéreuse n'obtiennent jamais les essais dont ils ont besoin, parce que personne ne tire profit du résultat.",
  "b-global-access": "Sept décès par cancer sur dix surviennent dans des pays à revenu faible ou intermédiaire, où la radiothérapie, l'anatomopathologie, la chirurgie et les médicaments sont rares.",
  "b-hereditary-risk": "La plupart des personnes porteuses d'un gène de cancer à haut risque l'ignorent jusqu'à ce qu'elles-mêmes ou un proche développent un cancer.",
  "b-immunotherapy-response": "Les inhibiteurs de points de contrôle guérissent certains patients et ne font rien pour la plupart. Nous ne savons toujours pas distinguer les uns des autres avant de traiter.",
  "b-incentive-misalignment": "Le système paie autant pour un médicament qui apporte deux mois que pour une guérison, alors les entreprises se précipitent pour copier plutôt que pour guérir.",
  "b-ip-collaboration": "Les entreprises qui possèdent des médicaments complémentaires les testent rarement ensemble, et les données qui pourraient répondre à des questions restent sous clé.",
  "b-knowledge-diffusion": "La diffusion des connaissances est lente : il faut des années pour qu'un résultat prouvé change ce que reçoivent la plupart des patients, et personne ne parvient à suivre la littérature scientifique.",
  "b-manufacturing-cell-therapy": "Les thérapies cellulaires demandent des semaines de fabrication pour un seul patient et coûtent des centaines de milliers de dollars. Les isotopes viennent à manquer.",
  "b-metastasis-biology": "Les métastases causent environ neuf décès par cancer sur dix, mais ne reçoivent qu'une petite fraction des fonds de recherche et presque aucun essai qui leur soit propre.",
  "b-misinformation": "On vend aux patients des traitements non prouvés et on les détourne, par la peur, des traitements qui ont fait leurs preuves.",
  "b-negative-results": "Les essais négatifs, les médicaments qui ont échoué et les programmes abandonnés sont rarement publiés, si bien que les mêmes erreurs se répètent.",
  "b-overdiagnosis": "Détecter plus de cancers n'est pas la même chose que sauver des vies. Le dépistage trouve aussi des cancers qui n'auraient jamais fait de mal à personne, et les traite.",
  "b-palliative": "La plupart des personnes qui meurent d'un cancer dans le monde meurent sans soulagement adéquat de la douleur.",
  "b-patient-voice": "La plupart des patients ne peuvent pas comprendre leurs options, trouver des essais ni faire entendre leur désaccord, si bien que les décisions sont prises à leur place.",
  "b-preclinical-models": "Neuf médicaments anticancéreux sur dix qui fonctionnent chez la souris échouent chez l'humain. Nos modèles en sont la raison.",
  "b-prevention-adoption": "Environ quatre cancers sur dix sont évitables avec des outils que nous possédons déjà : vaccins, lutte contre le tabac, poids, alcool, protection solaire et contrôle des infections.",
  "b-rare-cancers": "Pris ensemble, les cancers rares représentent un cinquième de tous les cancers, mais chacun d'eux, pris isolément, est trop petit pour qu'une entreprise y investisse.",
  "b-real-world-evidence": "Nous ne savons pas de manière fiable ce qui arrive aux patients après l'autorisation, et nous ne pouvons donc pas dire quels médicaments tiennent leurs promesses en pratique.",
  "b-regulatory-fragmentation": "La divergence réglementaire fait qu'un médicament approuvé dans un pays peut mettre des années à en atteindre un autre, ou ne jamais y arriver.",
  "b-reproducibility": "Moins de la moitié des découvertes majeures en biologie du cancer se reproduisent lorsque quelqu'un d'autre essaie.",
  "b-resistance": "Presque toutes les thérapies ciblées cessent de fonctionner en quelques mois à quelques années, à mesure que la tumeur s'adapte.",
  "b-surgery-radiation-innovation": "La chirurgie et la radiothérapie guérissent plus de personnes que les médicaments, mais n'attirent qu'une fraction des investissements en recherche.",
  "b-survivorship": "Des dizaines de millions de personnes vivent après un cancer avec des lésions cardiaques, une infertilité, des seconds cancers et de la peur, et peu de services pour les aider.",
  "b-tme-immunosuppression": "La plupart des tumeurs tiennent le système immunitaire à l'écart ou l'endorment, si bien que l'immunothérapie n'aide qu'une minorité de patients.",
  "b-toxicity-qol": "Les essais mesurent combien de temps les gens vivent, pas comment ils vivent. Les effets secondaires sont sous-déclarés et sous-traités.",
  "b-translational-valley": "La plupart des découvertes académiques meurent avant que quiconque les teste chez l'humain, parce que personne ne finance l'étape intermédiaire.",
  "b-trial-design": "Un essai de phase 3 prend des années et coûte des centaines de millions de dollars, et répond souvent à une question déjà dépassée.",
  "b-trial-diversity": "Les patients âgés, noirs, hispaniques, asiatiques, ruraux, pauvres et atteints de plusieurs maladies sont sous-représentés, si bien que les résultats peuvent ne pas s'appliquer à eux.",
  "b-trial-enrolment": "Moins d'un adulte atteint de cancer sur dix participe à un essai. Les essais ferment par manque de patients, pas par manque d'idées.",
  "b-tumor-heterogeneity": "Une tumeur est en réalité plusieurs tumeurs. Les traitements qui tuent la plupart des cellules laissent les autres repousser, transformées.",
  "b-undruggable-targets": "Les protéines qui alimentent la plupart des cancers, comme MYC, p53 mutée et la plupart des variants de RAS, n'ont toujours pas de bon médicament.",
  "b-workforce": "Le nombre de personnes atteintes de cancer augmente plus vite que les effectifs formés pour les soigner.",
  b7h3: "B7-H3 est une protéine qui freine le système immunitaire, présente sur de nombreuses tumeurs solides et aujourd'hui utilisée comme cible d'adressage pour les ADC, notamment dans le cancer du poumon à petites cellules et le cancer de la prostate.",
  "barts-cancer-institute": "Le plus ancien hôpital de Londres, associé à l'institut du cancer de Queen Mary, connu pour ses recherches sur le cancer du pancréas, les cancers du sang et le microenvironnement tumoral.",
  "base-excision-repair-parp": "Des dizaines de milliers de fois par jour, une seule lettre de l'ADN est oxydée ou chimiquement abîmée. Une petite équipe la découpe et PARP marque l'entaille pour qu'elle soit refermée. Les inhibiteurs de PARP ne se contentent pas d'éteindre PARP ; ils le piègent sur l'ADN, transformant une entaille sans danger en une cassure mortelle lorsque la cellule copie son ADN.",
  "cancer-registries-surveillance": "Les systèmes publics qui recensent chaque diagnostic et chaque décès par cancer dans un pays, et qui nous indiquent si l'incidence et la survie s'améliorent.",
  "cancer-stem-cells-plasticity": "Certaines cellules cancéreuses se comportent comme des cellules souches : elles peuvent reformer toute la tumeur, résister au traitement et changer d'identité. Cette plasticité explique pourquoi les tumeurs récidivent et pourquoi certains cancers du poumon et de la prostate se transforment en un autre type de cancer sous traitement.",
  capivasertib: "Le capivasertib (Truqap) est le premier inhibiteur d'AKT, indiqué dans le cancer du sein avec mutations de la voie PI3K et, depuis 2026, dans le cancer de la prostate avec perte de PTEN.",
  capox: "CAPOX associe la capecitabine orale à l'oxaliplatin comme alternative sous forme de comprimés au FOLFOX. Trois mois de ce traitement après la chirurgie suffisent pour de nombreux cancers du côlon de stade III.",
  "car-nk-macrophage": "Placer le récepteur qui cible le cancer sur des cellules tueuses naturelles ou des macrophages plutôt que sur des lymphocytes T, ce qui pourrait être plus sûr et prêt à l'emploi.",
  "car-t": "Les lymphocytes T du patient sont prélevés, dotés d'un récepteur synthétique qui reconnaît le cancer, multipliés, puis réinjectés comme un médicament vivant.",
  "carbon-ion": "Des particules chargées plus lourdes qui détruisent même les tumeurs résistantes aux radiations, disponibles dans seulement une poignée de centres dans le monde.",
  carboplatin: "Le carboplatin est une chimiothérapie à base de platine qui crée des liaisons croisées dans le DNA ; il fait partie du protocole standard avant chirurgie pour le cancer du sein triple négatif.",
  "cardio-oncology": "Protéger le cœur des traitements contre le cancer, ce qui devient de plus en plus important à mesure que les patients vivent plus longtemps.",
  ccss: "La plus grande étude sur ce qui arrive aux enfants une fois le cancer guéri. En suivant des dizaines de milliers de survivants pendant des décennies, elle a montré que les atteintes cardiaques, les seconds cancers et d'autres effets tardifs étaient fréquents après les traitements anciens, et que les protocoles modernes, plus doux, ont déjà réduit de moitié les décès tardifs.",
  cd19: "CD19 est un marqueur présent sur les lymphocytes B et les cancers des lymphocytes B, et il a été la cible des toutes premières thérapies CAR-T approuvées.",
  cd20: "CD20 est un marqueur des lymphocytes B ; le rituximab dirigé contre lui a été le premier anticorps approuvé contre le cancer, en 1997.",
  cd3: "CD3 est l'interrupteur présent sur chaque lymphocyte T. Les médicaments bispécifiques le saisissent d'un bras et la tumeur de l'autre, forçant le lymphocyte T à attaquer.",
  cd47: "Le signal « ne me mange pas » que les cellules cancéreuses présentent aux macrophages. Le bloquer semblait prometteur, mais le médicament le plus avancé a échoué.",
  "cdk4-6": "CDK4/6 est le moteur qui pousse une cellule à copier son DNA. Le bloquer en plus de l'hormonothérapie a à peu près doublé la durée pendant laquelle le cancer du sein hormonodépendant reste contrôlé.",
  "cdk46-inhibitor": "Des comprimés qui arrêtent le moteur de la division cellulaire, ajoutés à l'hormonothérapie pour le type de cancer du sein le plus fréquent.",
  "cell-cycle-engine-cdks": "La division cellulaire fonctionne selon une horloge faite de cyclines et de leurs kinases (CDKs), chaque paire s'activant dans l'ordre : D-CDK4/6 pour sortir du repos, E-CDK2 pour commencer à copier le DNA, A-CDK2 pour terminer, B-CDK1 pour se diviser. Les cancers accélèrent l'horloge ; les inhibiteurs de CDK la ralentissent.",
  "cell-therapy": "Prélever des cellules immunitaires, les modifier ou les multiplier, puis les réinjecter comme un médicament vivant.",
  "cell-therapy-roadmap": "De la guérison de certaines leucémies en 2017 à la première CAR-T contre les tumeurs solides, jusqu'à la perspective de fabriquer des CAR-T directement dans le corps par une injection.",
  cemiplimab: "Un bloqueur de PD-1 qui est le traitement standard du carcinome épidermoïde cutané avancé et qui, en 2025, est devenu la première immunothérapie adjuvante pour ce cancer.",
  cetuximab: "Un anticorps qui bloque le récepteur de croissance EGFR. Il est efficace dans les cancers de l'intestin dont le gène RAS est normal, surtout ceux du côté gauche, et il est un partenaire clé de l'association ciblant BRAF.",
  "cgas-sting": "cGAS-STING est l'alarme de la cellule face à du DNA qui se trouve au mauvais endroit. La radiothérapie, la chimiothérapie et les ADC répandent du DNA dans le cytoplasme ; cGAS le détecte, STING déclenche l'alarme et l'interféron appelle le système immunitaire.",
  cgp: "Séquencer des centaines de gènes du cancer en une seule fois à partir d'une biopsie pour trouver les mutations qu'un médicament peut cibler.",
  "checkmate-067": "L'essai avec le plus long suivi en immunothérapie : environ la moitié des patients sous l'association sont en vie à 10 ans.",
  "checkpoint-inhibitor": "Des anticorps qui relâchent les freins des cellules immunitaires pour qu'elles puissent attaquer le cancer. Ils guérissent une minorité de patients dans de nombreux cancers, ce que la chimiothérapie fait rarement.",
  chemoprevention: "Des médicaments ou une chirurgie pour les personnes présentant un risque hérité élevé, avant l'apparition de tout cancer.",
  chemoradiation: "Une radiothérapie administrée en même temps que la chimiothérapie, ce qui rend la radiothérapie plus efficace. C'est le traitement curatif de nombreux cancers qui ne peuvent pas ou ne doivent pas être opérés.",
  chemotherapy: "Des médicaments qui tuent les cellules qui se divisent rapidement. Toujours la colonne vertébrale de nombreuses guérisons, et désormais l'ogive placée à l'intérieur de médicaments plus intelligents.",
  "childrens-oncology-group": "Le Children's Oncology Group est la plus grande organisation d'essais cliniques en cancérologie pédiatrique au monde ; la plupart des enfants atteints de cancer en Amérique du Nord sont traités dans le cadre d'un protocole du COG ou selon celui-ci.",
  chop: "L'hôpital pour enfants où la thérapie CAR-T a guéri pour la première fois la leucémie d'un enfant (Emily Whitehead, 2012) et où la génomique du neuroblastome a identifié ALK.",
  "basket-umbrella-platform": "Des schémas d'essais qui testent un médicament dans de nombreux cancers (basket), plusieurs médicaments dans un seul cancer (umbrella), ou qui ajoutent des bras au fil du temps (plateforme).",
  "bbb-focused-ultrasound": "Des ondes sonores associées à des microbulles ouvrent brièvement la barrière protectrice du cerveau pour que la chimiothérapie ou les anticorps puissent atteindre la tumeur.",
  "bcg-and-intravesical-therapy": "Traiter le cancer de la vessie à un stade précoce en introduisant le médicament directement dans la vessie par une sonde, ce qui épargne le reste du corps.",
  bcl2: "Une protéine qui empêche les cellules de s'autodétruire. Le venetoclax supprime cette protection et a transformé le traitement de la leucémie.",
  bcma: "BCMA est un récepteur de survie présent sur les plasmocytes, et la cible qui a permis aux CAR-T et aux anticorps bispécifiques de fonctionner dans le myélome multiple.",
  "bcr-abl": "La fusion qui définit la leucémie myéloïde chronique et un quart des leucémies aiguës lymphoblastiques de l'adulte ; le premier moteur du cancer jamais éteint par un comprimé.",
  belzutifan: "Le belzutifan est le premier inhibiteur de HIF-2α, issu d'une biologie récompensée par un prix Nobel, et il est désormais approuvé après une chirurgie du cancer du rein en association avec le pembrolizumab.",
  bevacizumab: "Le premier médicament à priver les tumeurs de vaisseaux sanguins. Approuvé en 2004 pour le cancer de l'intestin, il reste un partenaire standard de la chimiothérapie dans de nombreux cancers et c'est l'ajout qui rend les comprimés des lignes tardives plus efficaces.",
  "bispecific-adc": "Un ADC bispécifique est un ADC dont l'anticorps s'accroche à deux protéines différentes de la cellule cancéreuse, ce qui lui permet de mieux se fixer à la tumeur et moins aux tissus sains.",
  "bispecific-antibody": "Un anticorps bispécifique est un seul anticorps doté de deux bras de préhension différents, ce qui lui permet de bloquer deux cibles à la fois ou d'attirer une cellule immunitaire sur une cellule cancéreuse.",
  blinatumomab: "Le blinatumomab a été le premier engageur de lymphocytes T (2014), et il est désormais administré aux enfants et aux adultes atteints de leucémie même en rémission, parce qu'il améliore la survie.",
  "blood-brain-barrier": "Le joint étanche qui entoure les vaisseaux sanguins du cerveau et tient la plupart des médicaments à l'écart, l'une des deux principales raisons pour lesquelles le cancer du cerveau est si difficile à traiter.",
  "blood-brain-barrier-metastasis": "Les vaisseaux sanguins du cerveau sont hermétiquement fermés et équipés de pompes qui expulsent la plupart des médicaments. Cela protège le cerveau des poisons, mais aussi de la chimiothérapie et des anticorps. Les cellules cancéreuses qui parviennent tout de même à se faufiler recrutent les propres cellules de soutien du cerveau, les astrocytes, pour les nourrir et les protéger.",
  bms: "Pionnier des inhibiteurs de points de contrôle (Opdivo, Yervoy), qui mise aujourd'hui sur le premier ADC bispécifique réussi et sur les radiopharmaceutiques alpha.",
  bortezomib: "Le bortezomib a été le premier inhibiteur du protéasome : il bloque la machine de recyclage des protéines de la cellule, ce que les plasmocytes, véritables usines à anticorps, ne peuvent pas tolérer.",
  brachytherapy: "La curiethérapie place une source radioactive directement à l'intérieur de la tumeur ou juste à côté.",
  braf: "BRAF est une kinase de signalisation mutée dans la moitié des mélanomes ; son blocage par deux médicaments à la fois est devenu un modèle pour la thérapie ciblée.",
  brca: "Des gènes de réparation de l'ADN. Hériter d'une copie défectueuse augmente le risque de cancer du sein et de l'ovaire, mais les tumeurs qui les perdent deviennent particulièrement vulnérables aux inhibiteurs de PARP et au platine.",
  "brentuximab-vedotin": "L'ADC qui a donné sa crédibilité au domaine moderne (2011), pour le lymphome de Hodgkin et les lymphomes CD30+.",
  "broad-institute": "Le Broad Institute est la puissance de la génomique derrière DepMap, le co-développement de cBioPortal et la Cancer Cell Line Encyclopedia.",
  btk: "L'enzyme de signalisation que les cancers des lymphocytes B utilisent pour survivre. Son blocage a transformé la leucémie lymphoïde chronique en une maladie contrôlée par un comprimé quotidien.",
  "burkitt-lymphoma": "Le lymphome de Burkitt est la tumeur humaine à la croissance la plus rapide, entraînée par un seul réarrangement qui active le gène MYC. Cette vitesse le rend extrêmement sensible à la chimiothérapie : des cures courtes et intensives, désormais avec l'anticorps rituximab, guérissent la grande majorité des enfants dans les pays bien dotés en ressources. Il reste à apporter la même guérison aux enfants africains, qui représentent la majorité des cas.",
  cabozantinib: "Un comprimé qui bloque à la fois la croissance des vaisseaux sanguins et la voie d'échappement MET, utilisé dans les cancers du rein, du foie, de la thyroïde et, depuis 2025, les cancers neuroendocrines.",
  cachexia: "Une perte sévère de poids et de muscle dans le cancer avancé que le simple fait de manger davantage ne peut pas inverser. Elle touche jusqu'à 8 patients sur 10 atteints d'une maladie avancée et contribue à un cinquième des décès par cancer.",
  "cachexia-appetite-pharmacotherapy": "La pharmacothérapie de la cachexie regroupe trois approches médicamenteuses de la fonte liée au cancer : un nouvel anticorps qui bloque l'hormone supprimant l'appétit, un imitateur de l'hormone de l'appétit approuvé uniquement au Japon, et un vieux comprimé très bon marché. Aucun n'est encore le standard partout ; tous font mieux que ce qui existait avant.",
  "caf-activation-desmoplasia": "Les tumeurs recrutent les cellules de réparation de l'organisme, les fibroblastes, et les maintiennent pour toujours en mode cicatrisation. Le tissu cicatriciel qu'ils déposent (desmoplasie) écrase les vaisseaux sanguins jusqu'à les fermer, tient les cellules immunitaires à l'écart, rigidifie le tissu d'une manière qui, en elle-même, incite les cellules cancéreuses à croître, et c'est la raison pour laquelle le cancer du pancréas est si difficile à traiter.",
  camrelizumab: "L'un des bloqueurs de PD-1 les plus utilisés en Chine, approuvé là-bas pour les cancers de l'œsophage, du foie, du poumon et d'autres cancers ; non approuvé aux États-Unis.",
  "cams-cancer-hospital": "Le CAMS Cancer Hospital est le centre national du cancer de la Chine, qui mène des essais de niveau réglementaire sur des ADC et des anticorps PD-1 produits localement.",
  "cancer-immunity-cycle": "Sept étapes que le système immunitaire doit accomplir pour tuer une tumeur : libération des antigènes, capture par les cellules dendritiques, activation des lymphocytes T dans les ganglions lymphatiques, déplacement, entrée dans la tumeur, reconnaissance et destruction. Chaque immunothérapie agit sur une étape ; chaque échappement en bloque une.",
  "cancer-metabolism": "Les cellules cancéreuses reprogramment leur façon de se nourrir. Elles brûlent le glucose de manière inefficace mais rapide (l'effet Warburg), se gavent de glutamine et de graisses, et fabriquent les nucléotides et les lipides nécessaires pour se diviser. C'est pour cela que l'examen FDG PET fonctionne, et que le métabolisme est une cible thérapeutique.",
  chordoma: "Le chordome est un cancer des os à croissance lente de la base du crâne et de la colonne vertébrale, issu de cellules embryonnaires résiduelles de la notochorde. Une chirurgie complète suivie d'une radiothérapie à haute dose par protons ou ions carbone contrôle la plupart des tumeurs, et toute la maladie dépend d'un seul facteur de transcription, brachyury, que des vaccins et des dégradeurs tentent aujourd'hui de cibler.",
  "chromosomal-instability": "La plupart des cancers ont un nombre anormal de chromosomes et continuent de les remanier à chaque division. Ce chaos alimente l'évolution et la résistance aux médicaments, mais il met aussi la cellule sous tension et peut déclencher des alertes immunitaires, une arme à double tranchant que les chercheurs tentent d'exploiter.",
  "ciltacabtagene-autoleucel": "Ciltacabtagene autoleucel est une thérapie CAR-T anti-BCMA administrée en une seule fois pour le myélome qui, dans l'essai CARTITUDE-4, a réduit le risque de décès d'environ 45 % par rapport aux traitements standard.",
  "circulate-japan": "Le programme national du Japon évalue si une analyse de sang après la chirurgie devrait décider qui reçoit une chimiothérapie, et si traiter tôt un test positif est bénéfique.",
  cisplatin: "Cisplatin est la chimiothérapie au platine d'origine, découverte par hasard en 1965 ; elle guérit le cancer du testicule et rend la radiothérapie plus efficace dans le cancer du col de l'utérus et les cancers de la tête et du cou.",
  "city-of-hope": "Centre de cancérologie de Los Angeles où ont été mis au point l'insuline synthétique et les anticorps humanisés ; un leader de la fabrication de CAR-T.",
  "cldn18-2": "Une protéine des jonctions serrées, normalement cachée dans la paroi de l'estomac, qui devient exposée dans les cancers de l'estomac et du pancréas.",
  "clinicaltrials-gov": "ClinicalTrials.gov est le registre de référence des essais cliniques. Chaque essai présenté sur ce site renvoie à sa fiche.",
  "clonal-evolution": "Une tumeur est une population qui évolue par sélection naturelle. Le traitement tue les cellules sensibles et sélectionne les autres, c'est pourquoi la résistance est la règle ; mesurer la population survivante (MRD) et adapter le traitement est la contre-stratégie.",
  cmml: "Ce sont des cancers de la moelle osseuse qui se comportent en partie comme une myélodysplasie (cellules sanguines mal fabriquées) et en partie comme une maladie proliférative (trop de monocytes ou de plaquettes). Les médicaments qui reprogramment le contrôle des gènes de la moelle (agents hypométhylants) aident de nombreux patients, une greffe de cellules souches peut guérir les personnes en assez bonne forme, et les mutations motrices que l'on cartographie aujourd'hui orientent vers des médicaments ciblés.",
  "cold-spring-harbor": "Centre de recherche fondamentale sur le cancer où la biologie de RAS, les suppresseurs de tumeurs et les modèles d'organoïdes ont progressé.",
  "cold-vs-hot": "Les tumeurs « chaudes » sont remplies de cellules immunitaires et répondent à l'immunothérapie ; les tumeurs « froides » ont tenu le système immunitaire à l'écart.",
  "colorectal-screening": "Trouver et retirer les polypes avant qu'ils ne deviennent un cancer. La coloscopie prévient le cancer ; les tests sur les selles et le sang le détectent tôt et permettent de dépister davantage de personnes.",
  "companion-diagnostic": "Le test qui détermine si un médicament précis vous convient, approuvé en même temps que le médicament.",
  "complement-in-cancer": "Le complément est une cascade de protéines du sang qui perce des trous dans ce que les anticorps ont marqué et appelle des cellules inflammatoires. Les anticorps thérapeutiques comme le rituximab s'en servent pour tuer les cellules cancéreuses ; les tumeurs se défendent avec des boucliers (CD46, CD55, CD59), et les sous-produits de la cascade elle-même (C5a) peuvent recruter les cellules myéloïdes qui protègent la tumeur.",
  cps: "Un score PD-L1 qui compte ensemble les cellules tumorales et les cellules immunitaires marquées.",
  craniopharyngioma: "Le craniopharyngiome est une tumeur bénigne mais destructrice qui se développe à partir de vestiges embryonnaires à côté de l'hypophyse et de l'hypothalamus. La chirurgie, ou une chirurgie limitée associée à une radiothérapie, guérit la plupart des personnes, mais le prix peut être un déficit hormonal à vie et une obésité sévère. La forme de l'adulte (papillaire) porte une mutation de BRAF et régresse de façon spectaculaire sous inhibiteurs de BRAF et de MEK, son premier traitement médicamenteux.",
  "crispr-screens": "Inactiver chaque gène, un par un, dans des cellules cancéreuses pour découvrir ceux dont elles ne peuvent pas se passer.",
  crs: "Un déferlement de signaux inflammatoires lorsque les cellules immunitaires sont activées en masse, provoquant de la fièvre, une baisse de la tension artérielle et parfois une défaillance d'organes.",
  cruk: "Cancer Research UK est la plus grande association caritative indépendante de recherche sur le cancer au monde ; elle finance le Crick, l'ICR, Manchester, Cambridge, ainsi que les essais STAMPEDE et TRACERx.",
  "cruk-cambridge-centre": "Le partenariat de Cambridge contre le cancer entre l'université et Addenbrooke's, célèbre pour la génomique du cancer du sein, la biopsie liquide et la détection précoce du cancer de l'œsophage.",
  csf1r: "Le récepteur dont dépendent les macrophages ; le bloquer fait régresser la tumeur ténosynoviale à cellules géantes (une tumeur dépendante de CSF1) et élimine les macrophages qui soutiennent la tumeur, même si ce dernier effet n'a pas encore aidé les patients atteints de cancers courants.",
  ct: "Un scanner (CT) est une radiographie 3D rapide qui montre la taille et la forme des tumeurs et si elles se sont propagées.",
  ctdna: "L'ADN tumoral circulant (ctDNA) est constitué de fragments d'ADN libérés par les cellules tumorales dans le sang, détectables par un séquençage sensible.",
  ctla4: "Le premier frein immunitaire jamais ciblé contre le cancer ; le relâcher a valu un prix Nobel et guérit une fraction des mélanomes.",
  "cure-paths": "Trois façons différentes pour qu'un cancer cesse de tuer quelqu'un : l'arrêter avant qu'il ne commence, éliminer jusqu'à la dernière cellule, ou le tenir en échec toute la vie. Chacune nécessite une technologie différente.",
  "curie-nki-eortc": "L'EORTC est l'organisation académique européenne des essais cliniques en cancérologie et mène des essais qui changent la pratique depuis 1962.",
  cyclophosphamide: "L'un des médicaments de chimiothérapie les plus utilisés : il fait partie du CHOP pour le lymphome, de l'AC pour le cancer du sein, du VAC pour les sarcomes de l'enfant, et sert à préparer les patients aux CAR-T et à la greffe.",
  "cytokine-therapy": "La thérapie par cytokines administre comme médicaments des protéines de signalisation immunitaire. L'interleukine-2 à haute dose a été la première immunothérapie à guérir certains mélanomes, au prix d'une grande toxicité.",
  "cytotoxic-chemotherapy": "Les médicaments de chimiothérapie cytotoxique tuent les cellules qui se divisent rapidement. Ils restent curatifs dans le cancer du testicule, le lymphome, la leucémie et de nombreux cancers à un stade précoce, et ils constituent l'ogive contenue dans les ADC.",
  "early-detection-roadmap": "Des mammographies et coloscopies à une simple prise de sang qui pourrait dépister des dizaines de cancers, avec une première décision de la FDA imminente.",
  "ecog-acrin": "Groupe coopératif américain qui associe un groupe de thérapie à un groupe d'imagerie ; son essai E1910 a fait entrer le blinatumomab dans le traitement de première ligne de la leucémie.",
  "efflux-pump": "Pompes moléculaires présentes sur les cellules cancéreuses qui expulsent la chimiothérapie et les charges utiles des ADC avant qu'elles ne puissent agir.",
  efs: "Dans le cancer à un stade précoce : combien de temps les patients restent sans récidive, sans progression ni décès.",
  egfr: "Un récepteur de croissance muté dans certains cancers du poumon et surproduit dans d'autres ; le premier grand succès des comprimés ciblés.",
  "eli-lilly": "Eli Lilly fabrique Verzenio et Retevmo, ainsi que le SERD oral imlunestrant et l'inhibiteur de BTK pirtobrutinib.",
  ema: "L'agence de l'Union européenne dont le Comité des médicaments à usage humain recommande les autorisations de mise sur le marché des médicaments contre le cancer dans tous les États membres.",
  emt: "Comment une cellule cancéreuse change de forme pour migrer et résister aux médicaments. Des facteurs de transcription comme ZEB1 et SNAIL relâchent la cellule, activent des pompes qui expulsent la chimiothérapie et la dissimulent au système immunitaire.",
  encorafenib: "Encorafenib est un inhibiteur de BRAF qui, avec le cetuximab et la chimiothérapie, est devenu en 2026 le traitement standard de première ligne du cancer colorectal avec mutation BRAF.",
  "endocrine-therapy": "Des comprimés qui bloquent ou suppriment la signalisation des œstrogènes, pilier du traitement du cancer du sein hormonodépendant depuis 50 ans.",
  "endoscopic-resection": "Retirer des cancers très précoces de l'œsophage ou de l'estomac par l'intérieur, à l'aide d'un endoscope, de façon à conserver l'organe intact.",
  "energy-balance": "Le terme générique que les chercheurs utilisent pour l'effet combiné de ce que vous mangez, de votre niveau d'activité physique et de votre quantité de graisse corporelle. C'est le cadre qui relie la recherche sur l'alimentation, l'exercice et l'obésité au cancer.",
  "enfortumab-vedotin": "Enfortumab vedotin est un ADC dirigé contre Nectin-4 qui, associé au pembrolizumab, a presque doublé la survie dans le cancer de la vessie avancé.",
  enzalutamide: "Le bloqueur du récepteur des androgènes le plus utilisé, approuvé à tous les stades du cancer de la prostate avancé, y compris en cas de PSA en hausse après la chirurgie.",
  epcoritamab: "Epcoritamab est une injection sous la peau qui attire les cellules T vers les cellules du lymphome ; il est approuvé pour le lymphome à grandes cellules B et le lymphome folliculaire en rechute, et progresse vers la première ligne.",
  ependymoma: "Les épendymomes se développent à partir des cellules qui tapissent les espaces remplis de liquide du cerveau et de la moelle épinière. L'ablation complète de la tumeur, suivie d'une radiothérapie ciblée avec précision, guérit de nombreux enfants ; la tumeur a été classée en groupes moléculaires qui se comportent très différemment, et le travail du domaine consiste à adapter l'intensité du traitement à chaque groupe et à trouver les premiers médicaments efficaces.",
  "epigenetic-drugs": "Des médicaments qui modifient la façon dont les gènes sont activés et désactivés, sans modifier le DNA lui-même.",
  "epigenetic-reprogramming": "Le cancer ne modifie pas seulement ses gènes, mais aussi la façon dont ils sont lus : des marques chimiques sur le DNA et les histones font taire les gardiens et réveillent des programmes de croissance. Contrairement aux mutations, ces changements sont réversibles, et c'est là tout l'espoir des médicaments épigénétiques.",
  "epithelioid-sarcoma": "Le sarcome épithélioïde est un cancer rare des tissus mous qui a perdu un gène frein appelé SMARCB1, ce qui le rend dépendant de l'enzyme EZH2. La chirurgie guérit les tumeurs localisées, et l'inhibiteur d'EZH2 tazemetostat, premier médicament épigénétique approuvé pour une tumeur solide, permet un contrôle durable de la maladie dans certains cas avancés.",
  "er-signaling": "Dans le cancer du sein hormonopositif, l'œstrogène se fixe à son récepteur, qui active des gènes faisant se diviser la cellule. Chaque traitement endocrinien coupe cette chaîne à un endroit ou à un autre.",
  "erasmus-mc": "Le centre anticancéreux intégré de Rotterdam, accrédité par l'OECI, où la thérapie par radionucléides ciblant les récepteurs peptidiques au lutétium-177 a été mise au point pour la première fois et où les plus grands essais de dépistage d'Europe ont été dirigés.",
  esmo: "L'ESMO est la société européenne d'oncologie, connue pour son Congrès chaque automne et pour l'échelle ESMO-MCBS qui évalue la valeur des nouveaux médicaments.",
  "essen-wtz": "L'un des centres anticancéreux les plus anciens et les plus grands d'Allemagne, qui abrite le Centre de protonthérapie d'Allemagne de l'Ouest et un programme de premier plan en mélanome et en théranostique.",
  estro: "La société européenne de radiothérapie oncologique, qui organise le congrès ESTRO, dirige une école formant une grande partie du personnel de radiothérapie dans le monde et établit les normes qui sous-tendent la curiethérapie et la radiothérapie adaptative.",
  "estrogen-receptor": "L'interrupteur hormonal qui alimente la plupart des cancers du sein. Le bloquer ou le détruire est la thérapie ciblée la plus ancienne et la plus efficace.",
  etoposide: "Etoposide est une chimiothérapie issue de la plante podophylle, essentielle pour guérir le cancer du testicule (BEP), traiter le cancer du poumon à petites cellules, les lymphomes, les sarcomes de l'enfant et les leucémies, et utilisée dans le conditionnement avant greffe.",
  everolimus: "Un comprimé qui bloque mTOR, qui a doublé le temps sans progression avec exemestane en 2012 et qui est aujourd'hui associé au SERD oral giredestrant.",
  "exercise-oncology": "Un exercice physique structuré pendant et après le traitement, dont l'essai CHALLENGE a montré qu'il améliore la survie dans le cancer du côlon.",
  ezh2: "EZH2 est une enzyme qui fait taire des gènes. Le premier médicament dirigé contre elle a traité un sarcome rare et certains lymphomes jusqu'à son retrait en 2026 pour avoir provoqué des seconds cancers du sang.",
  fap: "FAP est une protéine présente sur les cellules de soutien qui entourent de nombreuses tumeurs, ce qui fait qu'elle révèle presque n'importe quel cancer solide sur un PET scan.",
  "fapi-pet": "La TEP FAPI est un examen TEP qui fait ressortir l'échafaudage qui entoure presque toutes les tumeurs solides, y compris des cancers que l'examen standard au sucre ne détecte pas.",
  "fda-oce": "Le pôle d'oncologie du régulateur américain, qui approuve les médicaments contre le cancer, gère l'approbation accélérée et le Project Orbis, et pousse à une meilleure recherche de dose via le Project Optimus.",
  "fdg-pet": "La TEP au FDG est l'examen TEP standard. Un sucre radioactif montre quels tissus consomment rapidement du glucose, ce que font la plupart des cancers.",
  fgfr2: "FGFR2 est un récepteur de croissance qui est fusionné dans le cancer des voies biliaires et surproduit dans le cancer de l'estomac.",
  "first-line": "La première ligne est le premier traitement d'un cancer avancé ; la deuxième ligne est celui qui vient après son échec, et ainsi de suite.",
  flt3: "FLT3 est une kinase mutée dans environ un tiers des leucémies aiguës myéloïdes, où l'ajout d'un inhibiteur à la chimiothérapie améliore la survie.",
  "fluorescence-guided-surgery": "Injecter un colorant qui fait briller la tumeur pour que le chirurgien voie exactement où couper.",
  fluorouracil: "La chimiothérapie de 1957 qui reste le pilier du traitement des cancers de l'intestin, de l'estomac, du pancréas, de l'anus, de la tête et du cou et du sein, et qui s'utilise en crème pour les lésions précancéreuses de la peau.",
  folfox: "FOLFOX est la combinaison de chimiothérapie de référence pour le cancer de l'intestin, utilisée après la chirurgie dans un but curatif et, dans la maladie avancée, comme socle auquel on ajoute les traitements ciblés.",
  folr1: "Le récepteur alpha du folate est un récepteur de vitamine que les cellules du cancer de l'ovaire portent en grand nombre, utilisé comme point d'ancrage pour l'ADC mirvetuximab.",
  "francis-crick": "Le Francis Crick Institute est le plus grand institut de recherche biomédicale d'Europe et le foyer des études TRACERx sur l'évolution des tumeurs (Swanton).",
  "fred-hutch": "Berceau de la greffe de moelle osseuse (Thomas, Nobel 1990) et pionnier des CAR-T (Riddell).",
  "frontier-2035": "L'oncologie radicale est une carte d'horizon des idées les plus audacieuses en cancérologie, classées selon leur proximité d'un impact réel, avec la raison pour laquelle chacune pourrait ne jamais aboutir.",
  "functional-drug-testing": "Cultiver les propres cellules cancéreuses d'un patient dans une boîte et tester directement les médicaments sur elles, au lieu de deviner à partir de la génétique.",
  gallbladder: "Le cancer de la vésicule biliaire est un cancer de la poche qui stocke la bile sous le foie, le plus souvent découvert par hasard lorsque la vésicule est retirée pour des calculs. Détecté tôt, une seconde opération pour nettoyer le lit hépatique et les ganglions peut le guérir ; dans la maladie avancée, la chimiothérapie s'accompagne désormais d'une immunothérapie, et les anticorps dirigés contre HER2 aident le sous-groupe dont les tumeurs surexpriment HER2.",
  galleri: "Un test sanguin de dépistage de plus de 50 cancers à la fois, soumis à la FDA en septembre 2026.",
  "gardasil-9": "Un vaccin contre neuf types de HPV qui prévient environ 90 % des cancers du col de l'utérus, et qui fonctionne désormais avec une seule dose.",
  gd2: "GD2 est une molécule de sucre et de graisse présente à la surface des cellules de neuroblastome (et de certaines autres tumeurs de l'enfant et de l'adulte), quasiment absente des tissus normaux à l'exception des nerfs, ce qui explique pourquoi les médicaments anti-GD2 provoquent des douleurs.",
  "gemcitabine-cisplatin": "Gemcitabine plus cisplatin est le socle de la chimiothérapie du cancer des voies biliaires depuis 2010 et s'administre désormais avec une immunothérapie.",
  "gene-fusion": "Une fusion de gènes, c'est deux gènes cassés puis soudés ensemble, créant une protéine hybride capable de provoquer un cancer. Les cancers dus à une fusion sont souvent extrêmement sensibles aux médicaments.",
  "geriatric-assessment": "L'évaluation gériatrique est un bilan structuré de la forme physique, de la mémoire et du soutien dont dispose un patient âgé, qui prédit la tolérance au traitement mieux que l'âge.",
  "germline-testing": "Un test de l'ADN avec lequel vous êtes né, pour rechercher des gènes de risque hérités tels que BRCA ou le syndrome de Lynch.",
  "germline-vs-somatic": "Les mutations germinales sont héritées et présentes dans toutes les cellules ; les mutations somatiques apparaissent uniquement dans la tumeur.",
  gilead: "Gilead détient Trodelvy (via le rachat d'Immunomedics pour 21 milliards de dollars) et la franchise CAR-T de Kite.",
  "glioma-car-t": "Des cellules immunitaires modifiées, administrées directement dans le cerveau ou le liquide céphalo-rachidien. Certains enfants atteints de gliome diffus de la ligne médiane, une tumeur du tronc cérébral sans traitement curatif, ont eu des réponses spectaculaires, bien que temporaires.",
  "global-oncology-access": "Soixante-dix pour cent des décès par cancer surviennent dans les pays à revenu faible ou intermédiaire, où les appareils de radiothérapie, les pathologistes, les médicaments essentiels et les soins palliatifs sont rares. L'oncologie mondiale travaille à des soins abordables et adaptés, ainsi qu'aux systèmes pour les délivrer.",
  glofitamab: "Glofitamab est un anticorps bispécifique à durée fixe pour le lymphome à grandes cellules B, avec un bénéfice de survie globale (OS) lorsqu'il est associé à la chimiothérapie.",
  "glp1-agonists-cancer-risk": "Les agonistes du GLP-1, les nouvelles injections amaigrissantes, réduisent le poids de 15 à 20 %. Les premières données observationnelles suggèrent moins de cancers liés à l'obésité chez les personnes qui les prennent, mais aucun essai n'a encore évalué le cancer comme critère de jugement.",
  "glutamine-metabolism": "Après le glucose, la glutamine est l'aliment préféré de la tumeur. Elle alimente le cycle énergétique, fournit l'azote nécessaire à la fabrication des lettres de l'ADN et produit l'antioxydant glutathion. Les cancers pilotés par MYC et KRAS en consomment tellement qu'ils affament les cellules T voisines.",
  "gog-foundation": "L'organisation américaine d'essais cliniques en oncologie gynécologique dont les essais de la série GOG-3000, menés avec l'industrie, ont fait entrer l'immunothérapie dans le cancer de l'endomètre et du col de l'utérus.",
  "guardant-health": "Leader de la biopsie liquide : Guardant360 pour le génotypage, Reveal pour la MRD et Shield pour le dépistage.",
  "guardant360-cdx": "Un test sanguin qui lit les mutations d'une tumeur sans biopsie tissulaire et qui constitue la porte d'entrée approuvée par la FDA vers plusieurs traitements ciblés.",
  "gustave-roussy": "Gustave Roussy est le premier centre de lutte contre le cancer en Europe, berceau de l'échelle ESMO-MCBS et à la tête de grands essais sur les ADC et l'immunothérapie.",
  "hazard-ratio": "Un hazard ratio (rapport de risques) est un nombre qui compare la fréquence des événements indésirables dans deux groupes. Un HR de 0,5 signifie que le risque est divisé par deux à tout moment.",
  "heidelberg-nct": "Heidelberg est la capitale allemande de la recherche sur le cancer, siège du DKFZ (le plus grand institut de recherche sur le cancer d'Allemagne) et du NCT, et berceau du FAPI PET et du classificateur de méthylation des tumeurs cérébrales.",
  hengrui: "Jiangsu Hengrui est le plus grand laboratoire pharmaceutique d'oncologie de Chine, fabricant du pyrotinib et de l'ADC anti-HER2 trastuzumab rezetecan, et l'un des plus grands concédants de licences d'actifs chinois à l'étranger.",
  her2: "Un récepteur de signaux de croissance. Certains cancers en produisent beaucoup trop, et les médicaments qui le bloquent ou s'en servent comme point d'ancrage ont changé la donne pour ces cancers.",
  "her2-low": "Des tumeurs qui présentent un peu de HER2 (IHC 1+ ou 2+ sans amplification), ou seulement une trace (ultralow), que les anciens médicaments anti-HER2 ignoraient mais qu'Enhertu peut attaquer.",
  her3: "HER3 est un cousin de HER2 que les cancers utilisent comme voie de secours lorsque HER2 ou EGFR sont bloqués.",
  "hereditary-cancer-syndromes": "Environ 5 à 10 % des cancers sont dus à une anomalie génétique héréditaire. Reconnaître ces syndromes (BRCA, Lynch, Li-Fraumeni, VHL, MEN, FAP, rétinoblastome et des dizaines d'autres) change le dépistage, la chirurgie et le traitement pour le patient et ses proches.",
  "hif-vhl": "La voie VHL/HIF est le mécanisme par lequel les cellules détectent l'oxygène (prix Nobel 2019). VHL détruit HIF lorsque l'oxygène est présent. Les cancers du rein perdent VHL, si bien que HIF-2α reste allumé en permanence et stimule la formation de vaisseaux sanguins et la prolifération.",
  hif2a: "Un interrupteur central que les cellules du cancer du rein laissent allumé en permanence lorsqu'elles perdent le gène VHL ; le belzutifan le bloque.",
  "hifu-histotripsy": "Détruire des tumeurs depuis l'extérieur du corps grâce à des ondes sonores très finement focalisées, en utilisant soit la chaleur, soit des bulles microscopiques.",
  hipec: "Rincer la cavité abdominale avec une chimiothérapie chauffée pendant l'opération afin de tuer les dépôts péritonéaux microscopiques.",
  histiocytoses: "Les histiocytoses sont des maladies dans lesquelles des cellules immunitaires chargées du nettoyage s'accumulent dans les os, le cœur, le cerveau, les reins et la peau. On les traitait autrefois comme des maladies inflammatoires, avec des corticoïdes et de l'interféron. La découverte que la plupart portent des mutations dans la même voie de croissance que le mélanome en a fait des cancers ciblables : les comprimés inhibiteurs de BRAF et de MEK produisent aujourd'hui une réponse chez presque tous les patients traités.",
  "histopathology-ihc": "L'histopathologie consiste à examiner les cellules cancéreuses au microscope, et l'immunohistochimie les colore pour révéler des protéines spécifiques. Ensemble, elles restent le fondement de tout diagnostic.",
  "hiv-associated-lymphoma": "Les personnes vivant avec le HIV ont un risque accru de lymphomes agressifs, favorisés par l'immunosuppression et par des virus tels que le virus d'Epstein-Barr. La transformation des deux dernières décennies est que, en poursuivant le traitement antirétroviral pendant la prise en charge, ces lymphomes sont traités avec les mêmes protocoles de chimiothérapie à pleine dose et d'anticorps que chez n'importe qui d'autre, avec des chances de guérison similaires.",
  "homologous-recombination-repair": "Une cassure des deux brins de l'ADN est la lésion la plus dangereuse à laquelle une cellule est confrontée. Deux équipes se disputent la réparation : la recombinaison homologue copie la bonne réponse sur le chromosome sœur (précise, mais nécessite BRCA), tandis que la jonction des extrémités recolle simplement les bouts (rapide, mais bâclée). L'équipe qui l'emporte détermine si les inhibiteurs de PARP et la radiothérapie tuent la cellule.",
  hormonal: "Couper l'apport des hormones dont certains cancers, en particulier ceux du sein et de la prostate, ont besoin pour se développer.",
  "hospital-clinic-barcelona": "L'hôpital universitaire de Barcelone, berceau du système de stadification BCLC du cancer du foie et du premier CAR-T académique européen, et à la pointe de la génomique du cancer du sein et des lymphomes.",
  "hpv-testing": "Un prélèvement par écouvillon analysé pour détecter le virus responsable du cancer du col de l'utérus, plus précis que le frottis et réalisable à domicile.",
  "hpv-vaccine": "Des vaccins qui préviennent les infections virales à l'origine des cancers du col de l'utérus, de la gorge, de l'anus et du foie. L'intervention anticancéreuse la plus efficace jamais créée.",
  hrd: "Une tumeur incapable de réparer correctement les cassures double brin de l'ADN, généralement à cause de la perte de BRCA ou d'un gène apparenté.",
  iarc: "L'IARC est l'agence de la WHO consacrée au cancer, chargée des statistiques mondiales sur le cancer (GLOBOCAN), de la classification des cancérogènes et de la recherche en prévention.",
  ibrutinib: "Le comprimé qui a mis fin à la chimiothérapie pour la plupart des CLL. Il bloque le signal de survie dont dépendent les lymphocytes B, et il a été le premier médicament à surpasser la chimio-immunothérapie dans presque toutes les situations de CLL.",
  icans: "L'ICANS désigne une confusion, des difficultés d'élocution et, rarement, des crises convulsives après un traitement par CAR-T ou par anticorps bispécifique.",
  "icr-london": "A découvert plus de médicaments anticancéreux que toute autre institution académique, dont l'abiraterone et l'utilisation clinique des inhibiteurs de PARP.",
  idh: "Une enzyme du métabolisme dont la forme mutée produit une molécule qui brouille la lecture des gènes ; la bloquer ralentit les tumeurs cérébrales et les leucémies.",
  ifosfamide: "Ifosfamide est une chimiothérapie alkylante associée à la doxorubicin dans les sarcomes et à l'etoposide dans le sarcome d'Ewing, administrée avec un médicament qui protège la vessie.",
  imaging: "L'imagerie regroupe les moyens de voir le cancer à l'intérieur du corps sans ouvrir, des radiographies aux traceurs qui font s'illuminer une seule protéine.",
  imatinib: "Le médicament qui a ouvert l'ère des thérapies ciblées en 2001, faisant de la leucémie myéloïde chronique une maladie gérable avec une espérance de vie proche de la normale.",
  "immune-desert-exclusion": "Les tumeurs présentent trois 'climats' immunitaires : enflammé (lymphocytes T à l'intérieur, les médicaments anti-points de contrôle fonctionnent), exclu (lymphocytes T bloqués en périphérie) et désert (aucun lymphocyte T). La plupart des cancers fréquents sont exclus ou déserts, et les rendre 'chauds' est le problème central de l'immunothérapie.",
  "immuno-pet": "Des examens PET réalisés avec des anticorps radiomarqués ou leurs fragments, pour visualiser toute protéine qu'un anticorps peut atteindre, y compris les cellules immunitaires à l'intérieur des tumeurs.",
  immunotherapy: "L'immunothérapie aide le système immunitaire du patient lui-même à reconnaître et à détruire le cancer.",
  "immunotherapy-roadmap": "La feuille de route de l'immunothérapie est un arc de 130 ans, de l'injection de bactéries dans les tumeurs à la levée des freins immunitaires, et aujourd'hui à la conception de la réponse immunitaire elle-même avec des vaccins, des anticorps engageurs et des cellules.",
  "imrt-igrt": "Une radiothérapie modelée avec précision sur la tumeur et contrôlée par une imagerie quotidienne, pour épargner les organes voisins.",
  imvigor011: "Le premier essai à utiliser un test sanguin de détection du cancer résiduel pour décider qui reçoit une immunothérapie, et cela a fonctionné.",
  "in-vivo-car-t": "Au lieu de modifier les lymphocytes T en usine, une injection les reprogramme directement dans le corps du patient.",
  "inflammation-nfkb": "L'inflammation chronique est un terreau pour le cancer : elle alimente les signaux de croissance, les dommages à l'ADN et la suppression immunitaire. L'interrupteur NF-κB à l'intérieur des cellules en est le relais principal, et la colite, l'hépatite et la gastrite à H. pylori en sont la preuve clinique.",
  "inflammatory-myofibroblastic-tumour": "L'IMT est une tumeur rare faite de cellules fusiformes mêlées à des cellules inflammatoires, le plus souvent dans le poumon ou l'abdomen d'enfants et de jeunes adultes. La chirurgie guérit la plupart des cas, et environ la moitié portent une fusion du gène ALK, de sorte que le comprimé bloquant ALK, le crizotinib, est approuvé pour les tumeurs qui ne peuvent pas être retirées, l'une des premières approbations de thérapie ciblée pour une tumeur solide de l'enfant.",
  "integrative-oncology": "Utiliser des approches complémentaires fondées sur des preuves réelles, comme l'acupuncture contre les nausées et la douleur, le yoga et la pleine conscience contre l'anxiété et la fatigue, en complément du traitement standard, tout en éloignant les patients des thérapies 'alternatives' non prouvées qui peuvent raccourcir la vie.",
  "intismeran-autogene": "Un vaccin mRNA sur mesure codant jusqu'à 34 mutations propres à la tumeur du patient. En août 2026, il est devenu le premier vaccin anticancéreux personnalisé à remporter un essai de phase 3.",
  "intravasation-ctc-survival": "Entrer dans la circulation sanguine et y survivre est brutal : les cellules sont arrachées à leurs voisines, malmenées par le flux et traquées par les cellules NK. Moins d'une sur mille survit. Celles qui y parviennent voyagent en grappes, se couvrent d'un manteau de plaquettes ou s'accrochent aux neutrophiles. Les biopsies liquides capturent ce qui reste.",
  "invasion-ecm-degradation": "Pour envahir, une cellule cancéreuse doit s'agripper à l'échafaudage qui l'entoure, se frayer un chemin avec des enzymes et se tirer vers l'avant, seule ou en file menée par une cellule éclaireuse. Les fibroblastes ouvrent souvent la voie en premier. Les bloqueurs d'enzymes des années 1990 ont échoué ; les cibles d'aujourd'hui sont l'accroche (intégrines, FAK) et les ouvreurs de voie.",
  ipilimumab: "Ipilimumab a été le premier inhibiteur de point de contrôle (2011) et a prouvé que le système immunitaire pouvait être libéré contre le cancer.",
  irae: "Les effets indésirables d'origine immunitaire (irAEs) sont les effets secondaires auto-immuns des inhibiteurs de points de contrôle : colite, troubles de la thyroïde, éruption cutanée, hépatite, pneumopathie inflammatoire.",
  irinotecan: "Irinotecan est une chimiothérapie bloquant la topoisomérase, au cœur des protocoles contre les cancers de l'intestin et du pancréas (FOLFIRI, FOLFIRINOX, NALIRIFOX) et du traitement de rattrapage des sarcomes de l'enfant ; il porte la même 'ogive' que les charges des ADC au deruxtecan.",
  ivonescimab: "Un anticorps bispécifique chinois qui a battu Keytruda en comparaison directe sur la survie sans progression dans le cancer du poumon, le premier médicament à y parvenir.",
  ivosidenib: "Ivosidenib est un comprimé qui bloque l'enzyme IDH1 mutée, approuvé dans le cancer des voies biliaires et dans la leucémie.",
  "izalontamab-brengitecan": "Izalontamab brengitecan est le premier ADC bispécifique à réussir un essai de phase 3, en frappant deux récepteurs de croissance à la fois dans le cancer du sein triple négatif.",
  "johns-hopkins": "Johns Hopkins est le berceau de la génomique du cancer (Vogelstein), de l'immunothérapie des tumeurs MSI-high (Le, Diaz) et de la science de la biopsie liquide et du MCED (CancerSEEK).",
  "johnson-johnson": "Johnson & Johnson est en tête dans le myélome multiple (Darzalex, Carvykti, Tecvayli, Talvey) et dans les anticorps bispécifiques contre le cancer du poumon (Rybrevant).",
  karolinska: "Le principal hôpital de cancérologie de Suède, lié au Karolinska Institutet et à l'Assemblée Nobel, avec une solide recherche fondée sur les registres.",
  "keynote-522": "L'essai qui a ajouté l'immunothérapie à la chimiothérapie préopératoire du cancer du sein triple négatif et qui, fait unique, a amélioré la survie.",
  kinase: "Une enzyme qui active d'autres protéines en leur accrochant un groupe phosphate. La signalisation du cancer fonctionne grâce aux kinases, et les inhibiteurs de kinases constituent la plus grande classe de médicaments ciblés.",
  "kinase-inhibitors": "Des comprimés qui bloquent l'enzyme précise dont un cancer dépend. Imatinib a prouvé en 2001 qu'un cancer pouvait être éteint de manière délibérée.",
  kit: "La mutation de KIT est le moteur de la plupart des tumeurs stromales gastro-intestinales, et la raison pour laquelle imatinib a transformé un sarcome dont la survie médiane était d'environ un an en une maladie chronique.",
  kras: "KRAS est le gène du cancer le plus fréquemment muté, qualifié de 'non ciblable' pendant 40 ans, jusqu'en 2021.",
  "kras-inhibitors": "Des médicaments contre le gène du cancer le plus fréquent, jugé impossible à cibler jusqu'à sotorasib en 2021.",
  lag3: "LAG-3 est le troisième frein immunitaire à obtenir une approbation, en association avec le blocage de PD-1 dans le mélanome.",
  "rare-childhood-cancers": "Certains cancers de l'enfant sont si rares qu'aucun hôpital n'en voit assez, à lui seul, pour en tirer des enseignements. Le NCI les regroupe : tumeurs du cœur, papillomes des voies respiratoires, cancers de la thyroïde, des surrénales, du nez et de la gorge, mélanome et carcinomes plus typiques de l'adulte. La réponse a été la création de registres internationaux et de réseaux d'experts qui rassemblent chaque cas, de sorte qu'il existe des recommandations de traitement même sans essais cliniques.",
  "ras-mapk": "La voie RAS-MAPK est le relais qui donne à la cellule l'ordre de se diviser. Un signal reçu à la surface active RAS, qui transmet le message à RAF, MEK puis ERK, lesquels indiquent au noyau de faire se diviser la cellule. Les mutations de KRAS et de BRAF la bloquent en position « allumée ».",
  "real-world-evidence": "Données issues des soins courants plutôt que des essais cliniques, utilisées pour vérifier si les résultats se confirment en dehors de la population des essais.",
  recist: "RECIST est le règlement qui sert à mesurer, sur les examens d'imagerie, si les tumeurs ont grossi ou diminué.",
  "replication-stress": "Les cancers copient leur ADN trop vite et avec des points de contrôle défaillants, si bien que les fourches de réplication se bloquent et s'effondrent. Ils ne survivent qu'en s'appuyant sur des kinases de réparation d'urgence comme ATR, CHK1 et WEE1, c'est pourquoi bloquer ces kinases peut être létal de façon sélective.",
  resistance: "Pourquoi les médicaments anticancéreux cessent d'agir : soit la tumeur n'a jamais dépendu de la cible, soit elle évolue pour contourner le blocage.",
  "resistance-routes-map": "Quand un médicament bloque le moteur d'un cancer, celui-ci dispose de cinq voies de retour : modifier la pièce à laquelle le médicament se fixe, en produire davantage, emprunter une route parallèle, passer à un tout autre moteur, ou cesser de laisser entrer le médicament. Savoir quelle voie la tumeur a empruntée détermine le médicament suivant.",
  ret: "RET est une kinase altérée dans le cancer de la thyroïde et dans une petite fraction des cancers du poumon, que l'on peut traiter avec un seul comprimé sélectif, quel que soit l'endroit où se trouve la tumeur.",
  revumenib: "Revumenib (Revuforj) est le premier inhibiteur de la ménine (2024), destiné aux leucémies aiguës présentant un réarrangement de KMT2A ou une mutation de NPM1.",
  ribociclib: "Ribociclib est l'inhibiteur de CDK4/6 dont le bénéfice sur la survie est le plus constant, approuvé depuis 2024 pour une large population de patients atteints d'un cancer du sein précoce.",
  rituximab: "Rituximab a été le premier anticorps jamais approuvé contre le cancer (1997). Il a fait de la chimio-immunothérapie le traitement standard de la CLL pendant une décennie, et les biosimilaires le maintiennent bon marché et disponible partout.",
  "rna-seq": "Mesurer quels gènes une tumeur utilise activement, ce qui révèle son sous-type et permet de trouver des fusions de gènes.",
  "robotic-surgery": "Les chirurgiens opèrent par de petites incisions à l'aide de bras robotisés, avec une précision sans tremblement et une vision en 3D.",
  "roche-genentech": "Créatrice d'Herceptin, d'Avastin et de Rituxan, et propriétaire de Foundation Medicine ; l'entreprise qui a défini l'oncologie par anticorps.",
  "royal-marsden": "The Royal Marsden a été le premier hôpital du monde consacré au cancer (1851) et travaille en tandem avec l'Institute of Cancer Research.",
  "rtk-activation": "Les récepteurs des facteurs de croissance sont des antennes à la surface de la cellule qui s'apparient quand un signal arrive et allument les relais de croissance à l'intérieur. Les cancers mutent, multiplient ou fusionnent ces antennes pour qu'elles diffusent l'ordre « croître » sans aucun signal. La plupart des médicaments ciblés, des anticorps et des ADC commencent ici.",
  "sacituzumab-govitecan": "Le premier ADC ciblant TROP2. Il délivre une chimiothérapie puissante directement aux cellules des cancers du sein et de la vessie, et constitue désormais une option de première ligne dans le cancer du sein triple négatif.",
  "sacituzumab-tirumotecan": "Sacituzumab tirumotecan est un troisième ADC anti-TROP2 venu de Chine, dont la licence a été cédée à Merck pour un très vaste programme mondial. Il est approuvé en Chine ; aux États-Unis, il bénéficie d'un bon d'examen prioritaire mais n'est pas encore approuvé.",
  sanofi: "Sanofi fabrique Sarclisa (isatuximab), désormais disponible sous une forme sous-cutanée approuvée en juillet 2026.",
  sbrt: "Des doses de radiothérapie très élevées et très précises, délivrées en 1 à 5 séances, capables de détruire une tumeur comme le ferait la chirurgie.",
  "scalp-cooling": "Un bonnet bien ajusté, refroidi à quelques degrés au-dessus de zéro et porté avant, pendant et après chaque perfusion de chimiothérapie, resserre les vaisseaux sanguins du cuir chevelu afin que moins de médicament atteigne les racines des cheveux. Dans un essai randomisé, environ la moitié des femmes sous chimiothérapie à base de taxanes ont gardé la plupart de leurs cheveux, contre aucune parmi celles qui n'en portaient pas.",
  screening: "Tester des personnes sans symptômes pour repérer un cancer, ou ses lésions précurseurs, assez tôt pour le guérir. Son efficacité est prouvée pour les cancers du sein, du col de l'utérus, colorectal et (chez les fumeurs) du poumon ; chaque test détecte aussi certains cancers qui n'auraient jamais causé de tort.",
  seer: "SEER enregistre combien de personnes aux États-Unis développent chaque cancer et combien de temps elles vivent, selon le stade, l'âge, l'origine ethnique et l'année.",
  selpercatinib: "Selpercatinib est un inhibiteur sélectif de RET approuvé pour toute tumeur porteuse d'une fusion RET, avec une nouvelle mise à jour de son indication en juillet 2026.",
  "sentinel-node": "Retirer seulement le premier ganglion lymphatique vers lequel la tumeur se draine, plutôt que tous, pour vérifier s'il y a propagation.",
  sgo: "La société américaine des oncologues gynécologues, dont l'Annual Meeting on Women's Cancer est le congrès où sont présentés les essais d'inhibiteurs de PARP et d'immunothérapie dans les cancers de l'ovaire, de l'endomètre et du col de l'utérus.",
  "shared-antigen-vaccine": "Des vaccins dirigés contre des mutations ou des protéines communes à de nombreux patients, ce qui permet de les fabriquer à l'avance.",
  sheba: "Le plus grand hôpital d'Israël, dont le centre de cancérologie a dirigé l'essai POLO sur l'olaparib dans le cancer du pancréas et qui gère l'un des rares programmes de thérapie par TIL au monde.",
  signatera: "Le test sanguin le plus utilisé pour détecter un reliquat de cancer après la chirurgie, personnalisé selon les mutations tumorales de chaque patient.",
  "single-cell-spatial": "Lire les gènes de chaque cellule individuellement et cartographier la position de chaque cellule dans la tumeur.",
  "targeted-therapy": "Les thérapies ciblées sont des médicaments conçus pour désactiver une protéine défectueuse précise dont le cancer dépend.",
  tarlatamab: "Le premier engageur de lymphocytes T à améliorer la survie dans une tumeur solide fréquente, le cancer du poumon à petites cellules.",
  "tata-memorial": "Le plus grand centre de cancérologie d'Inde, pionnier des essais à faible coût et à fort impact, comme l'immunothérapie à faible dose et la chimiothérapie métronomique orale.",
  "tcr-t": "Des lymphocytes T dotés par ingénierie d'un récepteur qui reconnaît des fragments de protéines situées à l'intérieur de la cellule cancéreuse, atteignant ainsi des cibles inaccessibles aux CAR-T.",
  tebentafusp: "Le premier médicament à améliorer la survie dans le mélanome uvéal métastatique, et le premier bispécifique fondé sur un TCR.",
  teclistamab: "Teclistamab a été le premier bispécifique prêt à l'emploi pour le myélome multiple, et il est désormais approuvé après une seule ligne de traitement antérieure.",
  temozolomide: "La seule chimiothérapie dont il est prouvé qu'elle prolonge la vie dans le glioblastome, administrée pendant et après la radiothérapie. Elle est plus efficace lorsque la tumeur a désactivé un gène de réparation appelé MGMT.",
  tempus: "Des tests génomiques associés à l'un des plus grands ensembles de données cliniques multimodales, utilisés pour des modèles d'IA et l'appariement aux essais cliniques.",
  "tenosynovial-giant-cell-tumour": "La TGCT est une tumeur bénigne mais destructrice de la membrane qui tapisse l'articulation, dans laquelle quelques cellules porteuses d'une fusion du gène CSF1 recrutent une foule de cellules immunitaires normales qui rongent l'articulation. La chirurgie guérit la plupart des formes localisées, et dans la maladie diffuse ou récidivante, deux comprimés qui bloquent le récepteur du CSF1, le pexidartinib et le vimseltinib, font régresser les tumeurs et rétablissent la fonction de l'articulation.",
  theranostics: "Utiliser la même molécule de ciblage pour un examen d'imagerie diagnostique et pour un traitement, afin de traiter exactement ce que l'on voit.",
  "therascreen-cdx": "Une famille de tests rapides portant sur un seul gène, qui déterminent qui peut recevoir plusieurs médicaments contre les cancers de l'intestin, du poumon, du sein et de la vessie.",
  "thermal-ablation": "L'ablation thermique détruit une tumeur par la chaleur ou le froid délivrés à travers une aiguille, sans aucune incision.",
  "thomas-powles": "A dirigé EV-302, NIAGARA et IMvigor011, les essais qui ont fait passer le cancer de la vessie d'une prise en charge fondée uniquement sur la chimiothérapie à des soins par ADC, immunothérapie et guidés par le ctDNA.",
  "til-therapy": "Des cellules immunitaires qui ont déjà pénétré dans la tumeur sont prélevées, multipliées jusqu'à plusieurs milliards, puis réinjectées.",
  tils: "Des cellules immunitaires qui ont pénétré à l'intérieur de la tumeur. Plus elles sont nombreuses, meilleurs sont les résultats dans le cancer du sein triple négatif.",
  tisagenlecleucel: "Tisagenlecleucel a été la toute première thérapie CAR-T approuvée (2017), pour les enfants et les jeunes adultes dont la leucémie était revenue après tous les autres traitements.",
  tislelizumab: "Un bloqueur de PD-1 développé en Chine, conçu pour éviter une voie parallèle qui peut atténuer l'effet d'autres médicaments anti-PD-1, désormais approuvé aux États-Unis et dans l'UE pour le cancer de l'œsophage et de l'estomac.",
  tmb: "Le nombre de mutations que porte une tumeur. Plus il y a de mutations, plus le système immunitaire a de cibles.",
  "tnbc-history": "Comment le cancer du sein triple négatif est passé, en six ans, du sous-type sans aucune thérapie ciblée à un sous-type disposant d'une immunothérapie, d'inhibiteurs de PARP, de trois ADC et d'un ADC bispécifique aux résultats positifs.",
  "topoisomerase-inhibitors": "Les inhibiteurs de la topoisomérase I agissent en bloquant l'enzyme qui démêle l'ADN pendant sa copie. Ils sont peu efficaces sous forme libre dans de nombreux cancers, mais redoutables lorsqu'ils sont délivrés par un ADC.",
  tp53: "TP53 est le « gardien du génome », défectueux dans la moitié de tous les cancers. Le réparer directement a jusqu'ici fait échouer toutes les tentatives, alors les médicaments exploitent ce dont sa perte rend les cancers dépendants.",
  "transcription-addiction": "Les cellules cancéreuses font tourner quelques gènes (MYC, leurs facteurs de lignée, leurs oncogènes de fusion) à un volume extrême à partir de régions de contrôle géantes appelées super-enhancers. Les amplificateurs, BRD4, CDK7, CDK9 et Mediator, sont les mêmes dans toutes les cellules, mais les cancers en dépendent de façon inhabituelle, et cette dépendance peut être ciblée par des médicaments.",
  trastuzumab: "Le premier anticorps ciblé pour une tumeur solide (1998), qui a fait passer le cancer du sein HER2 positif du pire sous-type à l'un des plus faciles à traiter.",
  "trastuzumab-deruxtecan": "Trastuzumab deruxtecan (Enhertu) est l'ADC le plus réussi de tous les temps. Il a redéfini HER2 en agissant sur des tumeurs ne portant que d'infimes quantités de la protéine, et en 2026 il a fait son entrée dans le cancer du sein à un stade précoce.",
  "trastuzumab-emtansine": "Trastuzumab emtansine (Kadcyla, T-DM1) a été le premier ADC pour une tumeur solide (2013). Il reste le traitement standard après la chirurgie chez les patientes atteintes d'un cancer du sein HER2+ dont la tumeur n'a pas complètement répondu au traitement préopératoire.",
  trop2: "Une protéine présente à la surface de nombreuses cellules cancéreuses en bien plus grande quantité que sur les cellules normales, ce qui en fait une bonne adresse pour y acheminer des médicaments.",
  "trop2-adc-roadmap": "Une cible, trois médicaments approuvés ou presque, et une quatrième vague. Comment TROP2 est passé d'un obscur antigène du trophoblaste au cœur du traitement des cancers du sein et du poumon.",
  "trop2-pet": "Un examen PET expérimental qui montre si une tumeur porte la protéine TROP2, afin que les médecins puissent choisir le bon ADC avant de l'administrer.",
  tucatinib: "Un comprimé sélectif de HER2 qui agit dans le cerveau, pour le cancer du sein HER2 positif avec métastases cérébrales.",
  "tumor-dormancy": "Les cellules cancéreuses peuvent se cacher dans la moelle osseuse, le poumon ou le cerveau pendant des années ou des décennies, endormies et invisibles aux examens d'imagerie comme à la chimiothérapie, puis se réveiller. La rechute tardive dans le cancer du sein et de la prostate correspond à la fin de cette dormance.",
  "dabrafenib-trametinib": "Dabrafenib plus trametinib est l'association en comprimés BRAF plus MEK, approuvée pour le cancer du poumon BRAF V600E et, depuis 2022, pour toute tumeur solide porteuse de cette mutation.",
  dactinomycin: "Le premier antibiotique utilisé comme médicament anticancéreux (1954), toujours au cœur de la chimiothérapie de la tumeur de Wilms, du rhabdomyosarcome et de la maladie trophoblastique gestationnelle.",
  "daiichi-sankyo": "Daiichi Sankyo est l'entreprise japonaise dont la technologie de charge utile DXd a créé la meilleure plateforme d'ADC du secteur.",
  "dana-farber": "Là où la chimiothérapie est née (Farber, 1948) et où une grande partie de l'oncologie moderne du sein, du poumon et du myélome a été définie.",
  daratumumab: "L'anticorps anti-CD38 qui a transformé les triplets en quadruplets : l'ajouter à l'induction standard divise à peu près par deux le risque de progression du myélome.",
  daraxonrasib: "Le premier médicament qui bloque toutes les formes actives de RAS, approuvé par la FDA en août 2026 pour le cancer du pancréas métastatique, où KRAS est le moteur de 90 % des tumeurs.",
  "datopotamab-deruxtecan": "Datopotamab deruxtecan (Datroway) est le deuxième ADC ciblant TROP2 et partage la charge utile d'Enhertu. En 2026, il est devenu une option de première ligne pour les patientes atteintes d'un cancer du sein triple négatif qui ne peuvent pas recevoir d'immunothérapie.",
  ddr: "La réponse aux dommages de l'ADN est l'ensemble des équipes de réparation de la cellule. Les cassures simple brin sont réparées par PARP ; les cassures double brin par la recombinaison homologue, qui dépend de BRCA. Si une équipe manque, la cellule survit ; si les deux manquent, elle meurt. C'est ainsi que fonctionnent les inhibiteurs de PARP.",
  "desmoid-tumour": "Les tumeurs desmoïdes sont des proliférations localement agressives de cellules semblables aux fibroblastes qui ne se propagent jamais à des organes distants mais peuvent envahir les nerfs, l'intestin et les muscles. Beaucoup cessent de grossir ou régressent d'elles-mêmes, si bien que la surveillance initiale est désormais la norme, et pour celles qui progressent, le premier médicament conçu pour cette maladie, l'inhibiteur de la gamma-sécrétase nirogacestat, réduit les tumeurs et soulage la douleur.",
  devices: "Les dispositifs et les thérapies physiques traitent le cancer avec des champs électriques, de la chaleur ou des sons plutôt qu'avec des produits chimiques.",
  diagnostics: "Des tests sur les tissus et le sang qui indiquent de quel type de cancer il s'agit, ce qui le fait progresser et quels médicaments pourraient être efficaces.",
  "dietary-fibre-microbiome-io": "Les patients qui consomment beaucoup de fibres et évitent les comprimés de probiotiques semblent mieux répondre à l'immunothérapie du mélanome, probablement parce que les fibres nourrissent les bonnes bactéries intestinales. Un véritable essai clinique est en cours.",
  "dietary-supplements-treatment-interactions": "La plupart des personnes traitées pour un cancer prennent des compléments, souvent sans en informer leur équipe soignante. Les antioxydants, le millepertuis, les vitamines à forte dose et certaines plantes peuvent atténuer l'effet de la chimiothérapie ou de la radiothérapie, ou interagir avec les thérapies ciblées.",
  "dietitian-led-weight-loss-breast": "Le surpoids après un cancer du sein est associé à davantage de récidives ; un essai portant sur 3 000 femmes a donc testé un programme téléphonique de perte de poids de deux ans. Les femmes ont perdu du poids, mais l'essai n'a pas clairement montré moins de récidives.",
  "digital-pathology-ai": "Numériser les lames de microscope et laisser un logiciel mesurer ce qu'un pathologiste ne peut pas voir, y compris prédire qui bénéficiera d'un traitement.",
  "dipg-dmg": "Le gliome diffus de la ligne médiane se développe à travers le tronc cérébral et ne peut pas être retiré chirurgicalement. Un seul changement dans une protéine histone (H3 K27M) modifie la façon dont la tumeur lit son ADN. La radiothérapie a longtemps été la seule aide ; en 2025, le premier médicament visant cette tumeur, dordaviprone (ONC201), a été approuvé après une réduction durable chez certains patients, et les cellules CAR-T anti-GD2 ont produit des réponses précoces remarquables.",
  dkfz: "Le DKFZ est le plus grand institut de recherche sur le cancer d'Allemagne ; c'est là que Harald zur Hausen a établi le lien entre le HPV et le cancer du col de l'utérus (Nobel 2008).",
  dll3: "Une protéine présente à la surface des cellules du cancer du poumon à petites cellules, désormais ciblée par un médicament qui attire les lymphocytes T vers elles.",
  "dna-replication-licensing": "Avant de se diviser, une cellule doit copier trois milliards de lettres d'ADN exactement une fois. Pour cela, elle « autorise » à l'avance des milliers de points de départ, puis les déclenche par vagues. Les cancers en déclenchent trop et trop vite, et de nombreuses chimiothérapies agissent en affamant ou en bloquant la machinerie de copie.",
  docetaxel: "La première chimiothérapie à prolonger la vie dans le cancer de la prostate (2004), aujourd'hui intégrée au traitement triple dès le diagnostic initial de la maladie métastatique.",
  dosimetry: "Mesurer la dose de rayonnement que chaque organe et chaque tumeur ont réellement reçue d'un médicament radioactif.",
  dostarlimab: "Dostarlimab est un bloqueur de PD-1 célèbre pour avoir fait disparaître le cancer du rectum sans chirurgie chez tous les patients dont la tumeur présentait un déficit de réparation des mésappariements.",
  doxorubicin: "Le médicament de chimiothérapie rouge issu d'une bactérie du sol qui reste le pilier du traitement du sarcome, du lymphome et du cancer du sein, limité par les dommages cardiaques cumulatifs.",
  "drug-discovery": "Les plateformes de découverte de médicaments sont les outils utilisés pour trouver le prochain médicament : criblages génétiques, organoïdes, modèles chez la souris et IA.",
  "drug-efflux-pumps": "Les cellules cancéreuses peuvent installer dans leur membrane externe des pompes qui rejettent la chimiothérapie aussi vite qu'elle entre. Ces mêmes pompes protègent l'intestin, le cerveau et la moelle osseuse dans les tissus sains, ce qui explique pourquoi les bloquer a échoué comme stratégie et pourquoi les concepteurs de médicaments choisissent désormais des charges utiles que les pompes ne peuvent pas saisir.",
  "drug-tolerant-persisters": "Même lorsqu'un médicament élimine 99 % d'une tumeur, quelques cellules survivent sans aucune mutation de résistance : elles se mettent en veille, cessent de se diviser et attendent. Ces cellules persistantes sont le germe de la rechute. Elles sont difficiles à tuer précisément parce qu'elles ne font pas grand-chose, mais elles ont leurs propres faiblesses.",
  "ductal-carcinoma-in-situ": "Le DCIS correspond à des cellules anormales confinées aux canaux galactophores ; ce n'est pas encore un cancer invasif et il ne peut pas se propager, mais une partie deviendrait invasive si on la laissait évoluer. Le traitement, généralement une tumorectomie avec radiothérapie ou une mastectomie, est très efficace, si bien que la vraie question est de savoir quels DCIS à faible risque peuvent être surveillés en toute sécurité. Le premier essai randomisé de surveillance active (2024) a montré qu'elle n'était pas moins bonne à deux ans.",
  durvalumab: "Un bloqueur de PD-L1 devenu le standard après chimioradiothérapie dans le cancer du poumon de stade III, et désormais utilisé aussi dans les cancers de la vessie, des voies biliaires et de l'estomac.",
  dynamic: "A montré qu'un test sanguin peut réduire de moitié, en toute sécurité, le nombre de patients atteints d'un cancer du côlon recevant une chimiothérapie après la chirurgie.",
  "early-detection": "La détection précoce et le dépistage consistent à trouver le cancer avant qu'il ne provoque des symptômes, au moment où il est le plus curable.",
  lancet: "The Lancet est la principale revue médicale généraliste britannique et l'autre grand lieu de publication des essais en cancérologie qui changent la pratique, avec une voix plus forte que le NEJM sur la santé mondiale et les politiques de santé.",
  "langerhans-cell-histiocytosis": "L'histiocytose à cellules de Langerhans est une maladie dans laquelle un petit groupe de cellules immunitaires porteuses d'un signal de croissance défectueux (le plus souvent une mutation de BRAF) s'accumule dans les os, la peau, l'hypophyse ou les organes. Elle va d'une lésion osseuse unique qui guérit après la biopsie à une maladie menaçant la vie chez le nourrisson. Une année de chimiothérapie douce guérit la plupart des enfants, et les inhibiteurs de BRAF ou de MEK sauvent ceux dont la maladie résiste.",
  larotrectinib: "Le premier médicament approuvé pour une fusion de gènes quel que soit l'organe d'origine du cancer ; il agit dans environ 75 % des cancers avec fusion NTRK, du fibrosarcome du nourrisson aux cancers des glandes salivaires et de la thyroïde.",
  "late-effects": "Problèmes de santé qui apparaissent des mois ou des décennies après la fin du traitement : atteinte cardiaque, infertilité, seconds cancers, lymphœdème, sécheresse buccale, troubles de la mémoire, fragilité osseuse. Ils comptent surtout pour les enfants et les jeunes adultes, qui vivent le plus longtemps avec eux.",
  lenalidomide: "Un descendant du thalidomide qui active le système d'élimination des protéines de la cellule contre deux facteurs de survie du myélome, et qui constitue le pilier du traitement d'entretien du myélome et de nombreux protocoles contre les lymphomes.",
  lenvatinib: "Un comprimé oral anti-angiogénique qui a égalé le sorafenib dans le cancer du foie avec des taux de réponse plus élevés, et qui s'associe au pembrolizumab dans le cancer du rein et de l'endomètre.",
  letrozole: "Des comprimés quotidiens qui empêchent le corps de fabriquer des œstrogènes après la ménopause, pilier de l'hormonothérapie pour la plupart des cancers du sein.",
  lifileucel: "Lifileucel a été la première thérapie TIL approuvée : les propres cellules immunitaires du patient qui combattent la tumeur sont multipliées jusqu'à atteindre des milliards, puis lui sont réinjectées.",
  "limb-salvage-surgery": "Retirer un sarcome de l'os ou des tissus mous en conservant le bras ou la jambe, puis reconstruire avec des implants métalliques, des greffes osseuses ou, chez l'enfant, des prothèses de croissance.",
  "lineage-plasticity-neuroendocrine": "Sous la pression d'un médicament qui bloque son identité (le récepteur des androgènes dans le cancer de la prostate, l'EGFR dans le cancer du poumon), une tumeur peut changer de type cellulaire et devenir un cancer neuroendocrine à petites cellules qui n'a plus besoin du signal bloqué. C'est l'échappement ultime : non pas une nouvelle mutation dans le moteur, mais un nouveau moteur.",
  "lipid-metabolism-cancer": "Les cellules qui se divisent ont besoin de membranes, et les membranes sont faites de graisse. Les cancers activent les enzymes de fabrication des graisses que la plupart des tissus adultes gardent éteintes, et dans les environnements gras (sein, épiploon, moelle osseuse) ils volent aussi des lipides aux cellules graisseuses voisines. Cela relie l'obésité au cancer et offre de nouvelles cibles thérapeutiques.",
  "liquid-biopsy": "Un test sanguin qui lit les fragments d'ADN libérés par la tumeur, ce qui permet de génotyper ou de surveiller le cancer sans piquer la tumeur avec une aiguille.",
  "liver-transplant-oncology": "Remplacer la totalité du foie malade guérit à la fois le cancer et la cirrhose sous-jacente, chez les patients dont les tumeurs sont suffisamment petites.",
  lorlatinib: "Un inhibiteur d'ALK offrant le contrôle de la maladie le plus long jamais enregistré pour un comprimé ciblé contre le cancer du poumon : 60 % sans progression à cinq ans.",
  "low-dose-ct-screening": "Un scanner annuel à faible dose de rayonnement, destiné aux gros fumeurs actuels et anciens, qui détecte le cancer du poumon assez tôt pour le guérir.",
  lutathera: "Lutetium-177 dotatate a été la première thérapie moderne par radioligand (2018), pour les tumeurs neuroendocrines, et est désormais utilisé en première ligne.",
  "male-breast-cancer": "Les hommes aussi ont des cancers du sein, généralement d'un type hormonosensible découvert sous la forme d'une boule près du mamelon. Le traitement ressemble beaucoup à celui des femmes, avec chirurgie, radiothérapie et tamoxifen, et les mutations héréditaires de BRCA2 sont assez fréquentes pour qu'un test génétique soit proposé à tout homme diagnostiqué. La principale amélioration en cours consiste à inclure les hommes dans les essais cliniques, afin que leur prise en charge cesse d'être empruntée à celle des femmes.",
  mammography: "Radiographie du sein à faible dose utilisée pour le dépistage. Les versions 3D plus récentes détectent davantage de cancers avec moins de fausses alertes.",
  "mayo-clinic": "Régulièrement classé premier hôpital des États-Unis toutes spécialités confondues, avec une solide activité de protonthérapie et le premier centre d'ions carbone des États-Unis en construction.",
  mced: "Un test sanguin unique conçu pour dépister des dizaines de cancers à la fois, y compris ceux pour lesquels il n'existe aucun dépistage aujourd'hui.",
  "md-anderson": "MD Anderson est le plus grand centre de cancérologie du monde en volume de patients, avec le plus important programme de phase 1 et un effort de premier plan sur les CAR-NK.",
  "mediterranean-plant-forward-diet": "Les régimes fondés sur les légumes, les céréales complètes, les légumineuses, les noix, le poisson et l'huile d'olive, avec peu de viande rouge ou transformée, sont associés à un risque de cancer plus faible et à une meilleure survie après le diagnostic. Les preuves sont solides pour le régime dans son ensemble, faibles pour un aliment pris isolément.",
  menin: "Une protéine d'échafaudage dont certaines leucémies ont besoin pour maintenir leurs gènes activés ; le premier médicament dirigé contre elle a été approuvé en 2024.",
  merck: "Merck & Co. (MSD) fabrique Keytruda, le médicament anticancéreux le plus vendu au monde, et prépare aujourd'hui son prochain acte autour des ADC ciblant TROP2 et des vaccins personnalisés.",
  met: "Un récepteur qui est soit muté dans certains cancers du poumon, soit amplifié comme voie d'échappement lorsque d'autres médicaments contre le cancer du poumon cessent d'agir.",
  "metastatic-cascade": "Comment le cancer se propage : les cellules quittent la tumeur, se glissent dans les vaisseaux sanguins ou lymphatiques, survivent au voyage, sortent dans un nouvel organe, y restent souvent endormies pendant des années, puis finissent par se développer. Les métastases causent environ 90 % des décès par cancer.",
  methotrexate: "L'antifolate de 1948 qui a produit les premières rémissions par chimiothérapie dans la leucémie de l'enfant et la première guérison d'une tumeur solide ; il reste essentiel dans l'ALL, le lymphome, l'ostéosarcome et le lymphome du système nerveux central.",
  "methylation-profiling": "Lecture des marques chimiques portées par l'ADN qui révèlent l'identité d'une cellule, utilisée pour classer les tumeurs cérébrales et pour détecter le cancer dans le sang.",
  mgh: "Le plus grand hôpital de Harvard ; des leaders de la thérapie ciblée du cancer du poumon, de la protonthérapie et de la recherche sur le ctDNA.",
  "mismatch-repair-msi": "Une fois l'ADN copié, une équipe de relecture corrige les lettres que la polymérase a mal recopiées. Si elle disparaît, le génome se remplit de milliers de petites erreurs, surtout dans les séquences répétitives (microsatellites). Ces erreurs produisent des protéines anormales que le système immunitaire peut voir, ce qui explique pourquoi l'immunothérapie fonctionne si bien dans ces cancers.",
  "paediatric-low-grade-glioma": "Les gliomes de bas grade de l'enfant sont des tumeurs cérébrales à croissance lente, presque toujours entraînées par un seul signal hyperactif, la voie MAPK, le plus souvent à cause d'une modification du gène BRAF. Comme l'interrupteur est connu, les comprimés qui le bloquent (dabrafenib avec trametinib, et tovorafenib) font aujourd'hui régresser les tumeurs bien plus souvent que la chimiothérapie, et de plus en plus d'enfants échappent à une irradiation du cerveau en développement.",
  palbociclib: "Palbociclib a été le premier inhibiteur de CDK4/6 (2015) et, en 2026, il est devenu le premier approuvé comme traitement d'entretien dans le cancer du sein HER2-positif et hormono-positif.",
  "palliative-care": "Des soins spécialisés pour les symptômes, la prise de décision et la qualité de vie, proposés en parallèle du traitement du cancer dès le diagnostic, et pas seulement en fin de vie. Les essais montrent qu'ils améliorent la qualité de vie et l'humeur et pourraient prolonger la survie.",
  "paper-ascent-nejm-2021": "Dans le cancer du sein triple négatif ayant déjà reçu au moins deux traitements, le conjugué anticorps-médicament ciblant TROP2 sacituzumab govitecan a à peu près doublé la durée de vie des patientes par rapport à la chimiothérapie standard.",
  "paper-breakwater-nejm-2025": "L'ajout d'un inhibiteur de BRAF et d'un anticorps anti-EGFR à la chimiothérapie de première ligne a à peu près doublé la survie dans le cancer de l'intestin métastatique porteur de la mutation BRAF V600E, l'un des sous-types de plus mauvais pronostic.",
  "paper-destiny-breast03-nejm-2022": "Un conjugué anticorps-médicament plus récent, le trastuzumab deruxtecan, a maintenu le cancer du sein métastatique HER2-positif sous contrôle environ quatre fois plus longtemps que l'ancien standard, le T-DM1, et a ensuite prolongé la survie.",
  "paper-destiny-breast04-nejm-2022": "Les cancers du sein n'ayant qu'un peu de HER2 à leur surface, longtemps qualifiés de HER2-négatifs, ont répondu au trastuzumab deruxtecan et les patientes ont vécu environ six mois de plus qu'avec la chimiothérapie. Cela a créé la catégorie HER2-faible.",
  "paper-ev-302-nejm-2024": "L'association du conjugué anticorps-médicament ciblant Nectin-4 enfortumab vedotin au pembrolizumab a presque doublé la survie par rapport à la chimiothérapie à base de platine dans le cancer urothélial avancé, la plus grande avancée dans cette maladie depuis 40 ans.",
  "paper-flaura-nejm-2018": "Commencer par l'osimertinib, un médicament anti-EGFR de troisième génération, plutôt que de le garder pour plus tard, a maintenu le cancer du poumon avec mutation de l'EGFR sous contrôle presque deux fois plus longtemps et a ensuite aidé les patients à vivre plus longtemps.",
  "paper-keynote-522-nejm-2022": "L'ajout de l'immunothérapie pembrolizumab à la chimiothérapie avant la chirurgie, puis sa poursuite après, a réduit d'environ un tiers le risque de rechute ou de décès dans le cancer du sein triple négatif de stade II-III et a ensuite amélioré la survie.",
  "paper-mariposa-nejm-2024": "L'association d'un anticorps bispécifique EGFR-MET à un comprimé anti-EGFR de troisième génération a fait mieux que l'osimertinib seul, retardant la progression d'environ sept mois et améliorant ensuite la survie, au prix de davantage d'effets secondaires.",
  "paper-olympia-nejm-2021": "Chez les femmes nées avec une mutation de BRCA1 ou BRCA2 dont le cancer du sein précoce était à haut risque, un an d'olaparib, un inhibiteur de PARP, après le traitement standard a réduit les rechutes de plus de 40% et a ensuite amélioré la survie.",
  parp: "PARP est une enzyme de réparation de l'ADN. Les cancers qui ont déjà perdu un système de réparation (BRCA) meurent quand ce second système est bloqué ; les cellules saines survivent.",
  "parp-inhibitor": "Des comprimés qui bloquent un système de secours de réparation de l'ADN, tuant les cellules cancéreuses qui ont déjà perdu leur système de réparation principal (BRCA).",
  "pathology-foundation-model": "De très grands modèles d'IA entraînés sur des millions de lames ou d'images médicales, qui peuvent être adaptés à presque n'importe quelle question diagnostique.",
  payload: "La charge utile est le poison transporté par un ADC, généralement une chimiothérapie bien trop toxique pour être administrée seule.",
  pcr: "Aucun cancer invasif restant dans le sein et les ganglions lymphatiques lorsque le chirurgien retire les tissus après le traitement préopératoire.",
  pd1: "PD-1 est un frein sur les cellules T. Le bloquer libère le système immunitaire contre la tumeur et a permis de guérir certains cancers auparavant incurables.",
  "pd1-checkpoint": "Comment les cellules T décident d'attaquer. Une cellule T doit voir sa cible (TCR-MHC) et recevoir un signal « feu vert » (CD28). PD-1 et CTLA-4 sont des signaux « stop » ; les tumeurs les exploitent. Les inhibiteurs de points de contrôle suppriment ce stop.",
  pdl1: "PD-L1 est le versant tumoral du frein PD-1, et aussi le biomarqueur qui décide qui reçoit une immunothérapie.",
  "pdx-models": "Une xénogreffe dérivée de patient est la tumeur d'un patient cultivée chez une souris, utilisée pour tester des médicaments avant qu'ils n'arrivent chez l'humain.",
  "pediatric-match": "Pediatric MATCH a été le premier essai national de médecine de précision pour les enfants : tout enfant avec une tumeur solide en rechute pouvait faire séquencer sa tumeur et, si un médicament correspondant existait, rejoindre le bras d'essai prévu pour lui. Il a prouvé que le mécanisme fonctionne, même si la plupart des médicaments donnés seuls ont eu peu d'effet.",
  pembrolizumab: "L'immunothérapie anticancéreuse la plus utilisée, approuvée dans plus de 40 indications, y compris avant et après la chirurgie du cancer du sein triple négatif.",
  penile: "Le cancer du pénis est un cancer de type cutané (épidermoïde), dont environ la moitié des cas sont dus au HPV, le même virus responsable du cancer du col de l'utérus. Il est très souvent guérissable quand il est détecté tôt, la chirurgie est devenue beaucoup moins mutilante, et la maladie peut être prévenue par la vaccination contre le HPV et l'hygiène. Les cas difficiles sont ceux avec atteinte des ganglions lymphatiques, pour lesquels la chimiothérapie associée à la chirurgie et, désormais, l'immunothérapie sont à l'essai.",
  "penn-abramson": "Là où la CAR-T est devenue un médicament (June, Levine ; Emily Whitehead), où le mRNA a été rendu utilisable comme médicament (Karikó, Weissman) et où la PET PARP a été inventée.",
  pertuzumab: "Un second anticorps anti-HER2 qui se fixe à un endroit différent du trastuzumab, empêchant HER2 de s'associer à HER3 ; ensemble, ils ont prolongé la survie de 16 mois dans CLEOPATRA.",
  pet: "Un examen d'imagerie qui montre où s'accumule un traceur radioactif, et qui visualise donc ce que font les tumeurs plutôt que leur apparence.",
  "pet-ct": "La PET et le CT dans une seule machine, de sorte que les zones actives sur la PET sont localisées avec précision sur le CT.",
  "peter-mac": "Peter Mac est le seul hôpital d'Australie entièrement dédié au cancer et un leader en théranostique, en CAR-T et en radiothérapie oncologique.",
  pfizer: "A acheté Seagen pour 43 milliards de dollars afin de devenir un leader des ADC ; fabrique aussi Ibrance, Lorbrena, Braftovi et le premier PROTAC.",
  pfs: "La survie sans progression (PFS) est la durée pendant laquelle les patients vivent sans que leur cancer ne progresse.",
  "pheochromocytoma-paraganglioma": "Les phéochromocytomes et les paragangliomes sont des tumeurs du tissu producteur d'adrénaline qui provoquent des poussées dangereuses de tension artérielle. La chirurgie, après un blocage soigneux de la tension artérielle, guérit la plupart des patients ; les tests génétiques trouvent une cause héréditaire dans près de la moitié des cas, et pour la minorité qui se propage, il existe désormais des médicaments radioactifs qui se fixent sur la tumeur et, depuis 2025, le premier comprimé ciblé par voie orale, le belzutifan.",
  "pi3k-akt-mtor": "Le circuit « croître et survivre » de la cellule. Les signaux de croissance venus de la surface activent PI3K, qui active AKT, qui active mTOR, lequel fabrique des protéines et bloque l'autodestruction.",
  pik3ca: "PIK3CA est le gène le plus souvent muté dans le cancer du sein hormonodépendant. Les médicaments qui le ciblent fonctionnent, mais il a fallu des années pour l'atteindre proprement sans faire monter la glycémie.",
  pirtobrutinib: "Un bloqueur de BTK qui fonctionne après que les plus anciens ont cessé d'agir, parce qu'il s'accroche à une autre partie de l'enzyme. Pleinement approuvé pour la CLL en décembre 2025.",
  "pituitary-tumours": "Les tumeurs hypophysaires sont généralement des excroissances bénignes de la glande hormonale située à la base du cerveau, qui posent problème en produisant trop d'hormones ou en comprimant les nerfs optiques. Les tumeurs productrices de prolactine fondent avec un comprimé, la plupart des autres sont guéries par une chirurgie passant par le nez, et les rares formes agressives répondent au médicament de chimiothérapie temozolomide.",
  "pku-cancer-hospital": "L'hôpital de Pékin dédié au cancer et le premier centre chinois pour les essais sur le cancer gastrique, où les CAR-T contre claudin 18.2 et les associations avec PD-1 ont été testées pour la première fois dans la maladie gastrique.",
  platinum: "Les agents à base de platine, comme le cisplatin et le carboplatin, agissent en créant des pontages dans l'ADN. Ils sont curatifs dans le cancer du testicule et occupent une place centrale dans le traitement des cancers du poumon, de l'ovaire, de la vessie, de la tête et du cou, et du TNBC.",
  "pleuropulmonary-blastoma": "Les tumeurs pulmonaires primitives de l'enfant sont rares et différentes du cancer du poumon de l'adulte. La plus importante, le blastome pleuropulmonaire, commence par un kyste pulmonaire chez le nourrisson et est due à un gène DICER1 défectueux, qui prédispose aussi aux tumeurs de la thyroïde, de l'ovaire et du rein. Repérer et retirer les kystes tôt, avec l'aide d'un registre international et de tests génétiques familiaux, empêche l'évolution vers les formes solides agressives.",
  pluvicto: "Un médicament radioactif qui va chercher PSMA sur les cellules du cancer de la prostate ; le radiopharmaceutique le plus vendu de tous les temps.",
  "post-transplant-lymphoproliferative-disorder": "Après une greffe d'organe ou de cellules souches, les médicaments qui empêchent le rejet empêchent aussi le système immunitaire de surveiller le virus d'Epstein-Barr, et les cellules B infectées peuvent se transformer en lymphome. La première mesure consiste à alléger l'immunosuppression ; viennent ensuite l'anticorps rituximab, une chimiothérapie si nécessaire et, plus récent encore, des lymphocytes T spécifiques du virus prêts à l'emploi qui rétablissent le contrôle immunitaire manquant.",
  ppv: "La valeur prédictive positive (PPV) est la probabilité qu'un test qui dit « cancer » ait raison.",
  "pre-metastatic-niche": "Avant même l'arrivée d'une seule cellule cancéreuse, la tumeur primitive envoie des colis en avance : de minuscules vésicules (exosomes) et des hormones qui recrutent des cellules de la moelle osseuse vers un organe distant et le transforment en terreau fertile. Quand la graine se pose, le lit est déjà fait.",
  prevention: "Empêcher le cancer d'apparaître : vaccins, tests génétiques germinaux, mode de vie, et médicaments ou chirurgie préventifs.",
  "princess-margaret": "Princess Margaret est le premier centre de cancérologie du Canada et un pionnier de l'immunothérapie et de la recherche sur les cellules souches cancéreuses.",
  "protac-degrader": "Au lieu de bloquer une protéine, ces médicaments l'étiquettent pour le système d'élimination des déchets de la cellule, qui la fait disparaître entièrement.",
  proteomics: "Mesurer les protéines d'une tumeur, qui sont ce que les médicaments atteignent réellement, plutôt que les gènes qui les codent.",
  "proton-therapy": "Une radiothérapie utilisant des protons, qui s'arrêtent dans la tumeur au lieu de la traverser, si bien que les tissus situés derrière ne reçoivent aucune dose.",
  prrt: "Une version radioactive de l'imitateur d'hormone utilisé pour l'examen d'imagerie ; elle se fixe sur les cellules de tumeur neuroendocrine et les irradie de l'intérieur.",
  psma: "Une protéine présente sur les cellules du cancer de la prostate qui permet aux médecins à la fois de voir le cancer sur un PET scan et de le frapper avec un médicament radioactif.",
  "psma-pet": "Un PET scan spécifique du cancer de la prostate qui détecte la propagation bien plus tôt que le CT ou la scintigraphie osseuse, et qui indique si un médicament radioactif correspondant sera efficace.",
  "race-for-children-act": "Une loi américaine qui oblige les laboratoires pharmaceutiques à tester les nouveaux médicaments anticancéreux ciblés chez les enfants dès que la cible du médicament joue un rôle dans un cancer de l'enfant, au lieu de les laisser ignorer les enfants parce que leurs cancers sont rares.",
  radiation: "Utiliser des faisceaux focalisés ou des particules radioactives pour tuer les cellules tumorales tout en épargnant les tissus sains.",
  "radioembolisation-tare": "Des millions de minuscules billes radioactives de verre ou de résine sont injectées dans l'artère du foie ; elles se logent dans la tumeur et l'irradient de l'intérieur.",
  radioimmunotherapy: "Fixer un atome radioactif à un anticorps, de sorte que le ciblage d'un ADC serve à délivrer une irradiation plutôt qu'une chimiothérapie.",
  "radioligand-therapy": "Un médicament qui trouve les cellules tumorales et transporte un atome radioactif qui les irradie depuis l'intérieur du corps.",
  "radiology-ai-screening": "Un logiciel qui lit les examens d'imagerie aux côtés des radiologues, détectant les cancers plus tôt et prédisant qui est à risque.",
  radiopharma: "Une molécule qui se fixe sur la tumeur transporte un atome radioactif. La même molécule avec un atome différent permet d'abord de voir la tumeur.",
  "radiopharma-roadmap": "La feuille de route des radiopharmaceutiques s'étend sur quatre-vingts ans, de l'iode radioactif pour le cancer de la thyroïde aux médicaments émetteurs alpha pour les cancers de la prostate et neuroendocrines, l'approvisionnement en isotopes étant le facteur limitant.",
  "rare-cancers": "Les cancers rares sont ceux qui comptent moins d'environ 6 nouveaux cas pour 100 000 personnes par an. Rares pris un par un, ils représentent ensemble un quart de tous les cancers et ont une survie moins bonne à cause du diagnostic tardif, du faible nombre d'essais et de l'expertise dispersée.",
  "mitotic-spindle-checkpoint": "Lorsqu'une cellule se divise, un échafaudage de microtubules (le fuseau) tire une copie de chaque chromosome vers chaque côté. Un point de contrôle retient la séparation jusqu'à ce que chaque chromosome soit accroché. Les taxanes et les alcaloïdes de la pervenche figent le fuseau, de sorte que la cellule reste bloquée à ce point de contrôle jusqu'à sa mort.",
  moffitt: "Moffitt est le centre de cancérologie de la Floride et le premier site américain pour la thérapie par TIL et la recherche sur la thérapie évolutive (« adaptative »).",
  "molecular-imaging-roadmap": "D'un traceur à base de sucre qui fait ressortir la plupart des cancers à des traceurs qui montrent une seule protéine, un type de cellule du stroma ou les cellules immunitaires à l'intérieur d'une tumeur.",
  "monoclonal-antibody": "Des protéines immunitaires fabriquées en laboratoire qui se fixent sur une seule cible, soit pour la bloquer, soit pour marquer la cellule afin qu'elle soit détruite.",
  "mount-sinai": "Mount Sinai est un centre universitaire de New York particulièrement fort en myélome et en immunologie du cancer.",
  "mr-linac": "Le MR-linac est un appareil de radiothérapie qui intègre une IRM, de sorte que le plan de traitement est ajusté à l'emplacement exact de la tumeur ce jour-là.",
  mrd: "Un cancer encore présent après le traitement mais trop petit pour être visible à l'imagerie, détecté par des analyses de sang ou de moelle osseuse.",
  "mrd-negative-cr": "Une rémission complète MRD négative signifie non seulement qu'aucune leucémie n'est visible au microscope, mais qu'aucune n'est détectable avec des tests mille fois plus sensibles. C'est l'objectif du traitement moderne de la leucémie.",
  "mrd-testing": "Une analyse de sang ultrasensible réalisée après la chirurgie, qui détecte le cancer résiduel des mois avant qu'une imagerie ne le fasse.",
  mri: "Utilise des aimants et des ondes radio, sans rayonnement, pour fournir des images très détaillées des tissus mous tels que le cerveau, le sein, le foie et la prostate.",
  msi: "L'instabilité des microsatellites est la marque d'un correcteur orthographique de l'ADN défaillant qui crée des milliers de mutations, rendant la tumeur très visible pour l'immunothérapie.",
  mskcc: "L'hôpital de cancérologie le mieux classé au monde, berceau du séquençage MSK-IMPACT, de l'étude du dostarlimab dans le cancer du rectum et de pionniers des CAR-T.",
  "multiple-endocrine-neoplasia": "Les syndromes MEN sont des anomalies héréditaires d'un seul gène qui provoquent des tumeurs dans plusieurs glandes hormonales au cours de la vie. Comme le gène peut être détecté dès l'enfance, les proches à risque peuvent être testés, surveillés et, dans le MEN2, se faire retirer la thyroïde avant l'apparition du cancer ; et pour le cancer de la thyroïde du MEN2 qui se propage malgré tout, il existe désormais un comprimé de précision, le selpercatinib, qui bloque la protéine RET défectueuse.",
  "mutagenesis-signatures": "Chaque cause de dommage à l'ADN laisse sa propre empreinte dans le génome : la lumière du soleil, le tabac, une enzyme de réparation défectueuse, une bactérie intestinale. Lire ces empreintes indique ce qui a causé un cancer et quelles équipes de réparation lui manquent, ce qui permet à son tour de prédire quels médicaments seront efficaces.",
  "mutational-signature": "Un motif caractéristique de mutations qui révèle leur cause : le tabac, les UV, un gène de réparation défectueux.",
  myc: "MYC est le gène du cancer le plus souvent amplifié, un interrupteur principal qui active des milliers de gènes de croissance. Il n'a pas de poche où un médicament classique pourrait se loger, si bien qu'il est resté « inaccessible aux médicaments » pendant 40 ans ; les premiers médicaments ciblant directement MYC sont enfin entrés en essais cliniques dans les années 2020.",
  "myeloid-suppression-axis": "Les tumeurs recrutent les cellules de nettoyage de l'organisme (macrophages et cellules myéloïdes immatures) et les rééduquent pour en faire leurs gardes du corps. Celles-ci désactivent les lymphocytes T, construisent des vaisseaux et, lorsqu'un anticorps thérapeutique marque une cellule cancéreuse pour qu'elle soit dévorée, reçoivent du CD47 présent à sa surface le message « ne me mange pas ».",
  "national-cancer-grid": "Un réseau de plus de 360 centres de cancérologie indiens, piloté depuis le Tata Memorial, qui s'accorde sur des recommandations de traitement communes, achète les médicaments anticancéreux en commun à une fraction du prix catalogue et organise des réunions de concertation et des essais cliniques partagés.",
  "ncc-hospital-east": "Le campus de Kashiwa du National Cancer Center du Japon, une place forte de la protonthérapie et des essais de phase précoce qui dirige SCRUM-Japan et de nombreux essais internationaux sur les cancers digestifs.",
  "ncc-japan": "Le National Cancer Center Hospital est le centre national de cancérologie du Japon et le premier site pour les essais des ADC DXd de Daiichi Sankyo.",
  nci: "Le NCI est l'agence de recherche sur le cancer du gouvernement américain ; il dépense environ 7 milliards de dollars par an et dirige le Cancer Centers Program, le TCGA et le laboratoire de thérapie cellulaire de Rosenberg.",
  "nci-cancer-centers": "Les centres de cancérologie désignés par le NCI constituent la liste, établie par le gouvernement américain, des centres qui répondent à ses normes de recherche et de soins.",
  "nci-ccr": "Les propres laboratoires et la clinique du NCI au NIH Clinical Center, siège de la branche de thérapie cellulaire de Rosenberg, du vaccin contre le HPV et de la génomique des lymphomes.",
  nejm: "Le NEJM est la revue médicale la plus influente. Lorsqu'un essai sur un médicament anticancéreux change la façon de traiter les patients, l'article paraît généralement ici, souvent publié le jour même de sa présentation à l'ASCO, à l'ESMO ou à l'ASH.",
  "neoadjuvant-adjuvant": "Les traitements néoadjuvant, adjuvant et périopératoire désignent respectivement un traitement administré avant la chirurgie, après la chirurgie, ou les deux.",
  neoantigen: "Un fragment de protéine créé par une mutation tumorale, que le système immunitaire n'a jamais rencontré auparavant, de sorte qu'il peut l'attaquer sans nuire aux cellules normales.",
  "neoantigen-mrna-vaccine": "Un vaccin fabriqué pour un seul patient, qui code les mutations uniques de sa propre tumeur, afin d'entraîner le système immunitaire à la traquer.",
  "ngs-mrd-clonoseq": "Séquencer le code-barres génétique unique de la leucémie d'un patient pour retrouver une cellule cancéreuse sur un million.",
  nice: "L'organisme d'évaluation des technologies de santé de l'Angleterre, qui décide si le NHS doit payer chaque nouveau médicament anticancéreux sur la base du coût par année de vie ajustée sur la qualité et gère le Cancer Drugs Fund.",
  niraparib: "Le niraparib est un inhibiteur de PARP approuvé en traitement d'entretien du cancer de l'ovaire quel que soit le statut BRCA, et dans le cancer de la prostate en association avec l'abiraterone.",
  nivolumab: "Nivolumab a été le deuxième bloqueur de PD-1 et il est souvent associé à ipilimumab. Les données à long terme montrent qu'environ la moitié des patients atteints d'un mélanome avancé sont encore en vie à 10 ans avec cette association.",
  "nk-cell-recognition": "Les cellules tueuses naturelles patrouillent à la recherche de cellules qui ont perdu leurs papiers d'identité (MHC-I) ou qui affichent des signaux de stress. Les cancers qui se cachent des cellules T en abandonnant le MHC-I deviennent visibles pour les cellules NK, à moins qu'ils ne se débarrassent aussi des signaux de stress, ne s'enveloppent d'un second badge inhibiteur (HLA-E) ou n'inondent leur voisinage de TGF-β.",
  nki: "Centre national néerlandais de lutte contre le cancer, pionnier en Europe de l'immunothérapie néoadjuvante (NADINA, NICHE) et de la thérapie par TIL.",
  novartis: "L'entreprise qui a fait de la thérapie par radioligands un véritable marché, avec Pluvicto et Lutathera, et le fabricant de Kisqali et de Gleevec.",
  "nrg-oncology": "Groupe coopératif américain issu de la fusion des groupes d'essais en radiothérapie, en gynécologie et en cancer du sein ; il a codirigé OlympiA, l'essai qui a instauré un inhibiteur de PARP après la chirurgie chez les porteurs d'une mutation BRCA.",
  ntrk: "Fusions de gènes rares retrouvées dans des dizaines de types de cancer ; la première cible pour laquelle un médicament a été approuvé pour toute tumeur qui la porte.",
  "nutrient-competition-tme": "Les tumeurs et les cellules immunitaires mangent dans la même assiette. Les cellules cancéreuses accaparent le glucose et la glutamine, rejettent du lactate et de l'acide, et brûlent le tryptophane et l'arginine en sous-produits qui paralysent les cellules T. La tumeur gagne la bataille pour la nourriture, et le système immunitaire perd avant même d'avoir tiré un coup.",
  "nutrition-lifestyle": "Ce que les gens mangent, boivent, pèsent et font influence qui développe un cancer, comment se déroule le traitement et qui rechute. Ce front étudie tout cela avec la rigueur d'un essai de médicament.",
  "nutrition-screening-mnt": "Le dépistage nutritionnel consiste à peser chaque patient, à poser quelques questions de dépistage et à orienter les personnes à risque vers un diététicien. C'est simple, recommandé par les guides de pratique, et pourtant toujours pas fait de façon systématique.",
  "obesity-related-cancers": "L'excès de graisse corporelle est une cause établie d'au moins 13 cancers, dont ceux de l'utérus, de l'œsophage, du rein, du foie, de l'intestin, du pancréas et le cancer du sein après la ménopause. Dans de nombreux pays, c'est la deuxième cause évitable de cancer après le tabac.",
  obinutuzumab: "Obinutuzumab est un anticorps anti-CD20 renforcé qui, associé au venetoclax pendant un an, permet à de nombreux patients atteints de CLL de passer des années sans aucun traitement.",
  oeci: "Le réseau des centres européens de lutte contre le cancer qui gère le programme d'accréditation et de désignation attribuant le statut de « Comprehensive Cancer Centre ».",
  olaparib: "Olaparib a été le premier inhibiteur de PARP et a transformé la mutation BRCA héréditaire d'un facteur de risque en une cible médicamenteuse, y compris après la chirurgie dans le cancer du sein.",
  oligometastatic: "Cancer qui ne s'est propagé qu'à quelques endroits et qui peut encore être guérissable en traitant chaque foyer.",
  "oncogene-activation-two-hit": "Parmi les milliers de mutations présentes dans une tumeur, seule une poignée (généralement 2 à 8) la fait réellement avancer. Ces mutations « conductrices » soit bloquent un accélérateur en position enfoncée (oncogènes, un seul coup suffit), soit suppriment un frein (suppresseurs de tumeur, les deux copies doivent disparaître). Tout le reste n'est que passager embarqué pour le voyage.",
  "oncogene-addiction": "Lorsqu'un cancer dépend si complètement d'un seul gène muté que le bloquer fait s'effondrer la tumeur.",
  "oncogenic-viruses": "Environ un cancer sur huit dans le monde est causé par un virus. HPV, hépatites B et C, Epstein-Barr, HTLV-1, KSHV et polyomavirus des cellules de Merkel détournent chacun les mêmes freins que le cancer doit normalement faire muter, ce qui explique pourquoi les vaccins contre HPV et HBV figurent parmi les médicaments anticancéreux les plus efficaces jamais créés.",
  "oncology-real-world-data": "Bases de données constituées à partir de millions de dossiers de patients réels, utilisées pour voir comment les traitements fonctionnent en dehors des essais et pour mener des études sans lancer de nouveaux essais.",
  "oncolytic-virus": "Virus modifiés pour infecter et faire éclater les cellules cancéreuses tout en épargnant les cellules normales, et pour alerter le système immunitaire au passage.",
  "oncotype-dx": "Un test de 21 gènes qui indique à la plupart des femmes atteintes d'un cancer du sein précoce hormonosensible si elles peuvent se passer de chimiothérapie en toute sécurité.",
  optune: "Optune est un dispositif portable qui délivre des champs électriques perturbant la division cellulaire. Il est approuvé pour le glioblastome et, en 2026, pour le cancer du pancréas.",
  "organ-tropism-seed-soil": "Le cancer du sein va vers l'os, le poumon, le foie et le cerveau ; le cancer de la prostate vers l'os ; le cancer du côlon vers le foie ; le mélanome uvéal presque uniquement vers le foie. L'idée de Paget, formulée en 1889, reste valable : l'endroit où un cancer se propage dépend à la fois de la graine (le programme de la cellule) et du sol (l'accueil réservé par l'organe). Chaque sol a son propre cercle vicieux, et certains peuvent être ciblés par des médicaments.",
  organoids: "Les organoïdes dérivés de patients sont des versions miniatures en 3D de la tumeur d'un patient, cultivées en laboratoire.",
  orr: "Le taux de réponse objective (ORR) est le pourcentage de patients dont les tumeurs diminuent d'au moins 30 %.",
  os: "La survie globale (OS) mesure combien de temps les patients vivent, tout simplement. C'est le critère d'évaluation de référence.",
  osimertinib: "Osimertinib (Tagrisso) est le comprimé de référence pour le cancer du poumon avec mutation EGFR, désormais aussi donné après la chirurgie et avec une chimiothérapie ou après une chimioradiothérapie.",
  "p53-cell-cycle": "Les points de contrôle p53 et RB sont les freins de la cellule. p53 détecte les dommages et empêche la cellule de se copier ; RB retient la cellule à la porte G1 jusqu'à ce que CDK4/6 la déverrouille. Les cancers coupent ces freins.",
  "p53-mdm2-axis": "p53 est le coordinateur d'urgence de la cellule. Les dommages, le stress lié aux oncogènes ou le manque d'oxygène l'activent ; il met alors la division en pause, ordonne des réparations, ou déclenche le suicide cellulaire ou la retraite définitive. MDM2 le maintient éteint dans les cellules saines. La moitié de tous les cancers cassent p53 purement et simplement ; beaucoup des autres surproduisent MDM2.",
  paclitaxel: "Un poison des microtubules découvert dans l'if du Pacifique, l'une des chimiothérapies les plus utilisées dans les cancers du sein, du poumon et de l'ovaire.",
  "paediatric-germ-cell-tumours": "Les tumeurs germinales naissent des cellules destinées à devenir des ovules ou des spermatozoïdes et peuvent apparaître dans les gonades, le bas du dos, le thorax ou le cerveau. Elles comptent parmi les cancers de l'enfant les plus guérissables, car elles répondent à la chimiothérapie par cisplatin et libèrent des marqueurs sanguins qui facilitent la surveillance. Le travail consiste désormais à guérir avec moins : la chirurgie seule pour les tumeurs à faible risque, des dérivés du platine plus doux et la protection de l'audition.",
  sinonasal: "Les cancers du nez et des sinus forment un groupe hétérogène, allant du carcinome épidermoïde à l'esthésioneuroblastome, d'origine nerveuse, et au carcinome indifférencié agressif SNUC. La chirurgie par le nez à l'aide d'un endoscope suivie d'une radiothérapie précise a remplacé les opérations ouvertes défigurantes, et le fait de donner d'abord une chimiothérapie pour voir qui y répond guide désormais la façon de traiter le SNUC.",
  "siop-europe": "La société européenne d'oncologie pédiatrique et l'organisation faîtière des groupes européens d'essais cliniques qui traitent la plupart des enfants atteints de cancer selon des protocoles communs.",
  sitc: "La société des immunologistes du cancer et des immuno-oncologues, dont le congrès annuel, les recommandations et les ressources sur la prise en charge des effets indésirables d'origine immunitaire accompagnent l'ère de l'immunothérapie.",
  "site-specific-conjugation": "La conjugaison site-spécifique et la chimie des linkers déterminent exactement où et combien de charges actives se fixent sur l'anticorps, ce qui conditionne la sécurité et l'efficacité d'un ADC.",
  "small-bowel": "Les cancers de l'intestin grêle sont rares et souvent découverts tard, car l'intestin grêle est difficile à examiner et les symptômes sont vagues. La chirurgie guérit la maladie précoce, la chimiothérapie empruntée au cancer du côlon aide après la chirurgie et dans la maladie avancée, et une minorité importante de tumeurs présente un défaut de réparation de l'ADN qui les rend très sensibles à l'immunothérapie.",
  sorafenib: "Le tout premier médicament à avoir prolongé la vie dans le cancer du foie avancé (2007), aujourd'hui surtout utilisé comme bras de comparaison face auquel on mesure les combinaisons plus récentes.",
  sotorasib: "Sotorasib (Lumakras) a été le premier médicament à cibler KRAS, approuvé en 2021 après quatre décennies d'échecs.",
  sstr2: "Le récepteur de la somatostatine de type 2 est un récepteur hormonal très abondant à la surface des tumeurs neuroendocrines, et il a été la première cible théranostique à entrer dans les soins courants.",
  "st-jude": "Le seul centre de cancérologie complet reconnu par le NCI entièrement consacré aux enfants, où les protocoles Total Therapy ont rendu la leucémie de l'enfant guérissable ; les familles ne reçoivent jamais de facture pour les soins.",
  "stage-shift": "Le décalage de stade signifie détecter plus de cancers à un stade précoce et moins à un stade tardif ; c'est l'objectif mesurable du dépistage.",
  "standard-of-care": "Le standard de soins est le traitement que les recommandations et les experts considèrent actuellement comme l'option la mieux démontrée.",
  stanford: "Stanford est le berceau de l'innovation en CAR-T (Mackall, Majzner), de la découverte de CD47 (Weissman) et de l'intelligence artificielle en médecine.",
  sunitinib: "Sunitinib est un comprimé anti-angiogénique approuvé pour les tumeurs neuroendocrines du pancréas, le cancer du rein et les GIST.",
  "supportive-care": "Les soins de support et l'après-cancer recouvrent tout ce qui permet au patient d'être assez bien pour recevoir son traitement, et de rester bien ensuite.",
  surgery: "Retirer ou détruire physiquement les tumeurs, de plus en plus avec des robots, un guidage par l'image, et de la chaleur ou du froid à la place du bistouri.",
  "survivorship-care-plan": "Un suivi organisé pour les 18 millions de survivants du cancer aux États-Unis et les plus de 50 millions dans le monde : surveiller les récidives et les seconds cancers, prendre en charge les effets secondaires à long terme comme les atteintes cardiaques, l'infertilité, la neuropathie et la fatigue, et aider les personnes à reprendre le travail et leur vie.",
  swog: "SWOG est l'un des groupes coopératifs du US National Cancer Institute : des milliers de centres communautaires et universitaires menant des essais qui changent la pratique, dont le résultat de 2026 dans le lymphome de Hodgkin en première ligne.",
  "synthetic-lethality": "Deux gènes dont la perte de l'un ou de l'autre seul est sans conséquence, mais dont la perte des deux tue la cellule. Les cancers qui ont perdu l'un des deux deviennent vulnérables aux médicaments dirigés contre l'autre.",
  "synthetic-lethality-approaches": "Trouver un deuxième gène dont un cancer a besoin uniquement parce que son premier gène est défaillant, puis cibler ce deuxième gène.",
  "synthetic-lethality-map": "Deux gènes sont dits synthétiquement létaux lorsque la perte de l'un ou de l'autre seul est sans conséquence, mais que la perte des deux tue la cellule. Les cancers qui en ont déjà perdu un (un suppresseur de tumeur qu'on ne peut pas restaurer) deviennent particulièrement dépendants de l'autre, que l'on peut cibler par un médicament. BRCA et PARP en ont été la première preuve ; une douzaine d'autres paires sont aujourd'hui en essais cliniques.",
  "systemic-mastocytosis": "La mastocytose systémique est une maladie clonale des mastocytes, les cellules immunitaires qui libèrent l'histamine ; presque tous les cas sont dus à une seule mutation du gène KIT. Des comprimés qui bloquent précisément KIT réduisent désormais la masse de mastocytes, soulagent les symptômes et, dans les formes agressives, prolongent la vie. La plupart des patients ont la forme indolente, où l'objectif est de contrôler les symptômes et de prévenir l'anaphylaxie.",
  sysucc: "Sun Yat-sen University Cancer Center est l'un des plus grands centres de cancérologie de Chine, le leader mondial du carcinome du nasopharynx et l'un des principaux recruteurs pour les essais chinois d'ADC et de PD-1.",
  "t-cell": "Les tueurs entraînés du système immunitaire. Chaque lymphocyte T reconnaît une cible précise présentée à la surface d'une cellule et, si cette cellule est infectée ou cancéreuse, la tue. L'immunothérapie consiste en grande partie à les libérer.",
  "t-cell-engager": "Un médicament prêt à l'emploi qui relie physiquement un lymphocyte T tueur à une cellule cancéreuse, forçant l'attaque.",
  "t-cell-exhaustion": "Les lymphocytes T qui font face à leur cible pendant des semaines sans l'emporter s'éteignent progressivement : ils activent une série de freins (PD-1, LAG-3, TIM-3, TIGIT), perdent leur capacité à tuer et finissent par verrouiller cet état dans leur ADN. Les médicaments anti-checkpoint sauvent ceux qui ne sont que partiellement épuisés ; ceux qui sont épuisés de façon terminale sont hors de portée.",
  takeda: "Takeda codétient Adcetris en dehors des États-Unis et développe des conjugués agonistes de STING et des cellules CAR-NK.",
  talazoparib: "Talazoparib est le piégeur de PARP le plus puissant, approuvé dans le cancer du sein lié à BRCA et, en association avec enzalutamide, dans le cancer de la prostate.",
  "talicabtagene-autoleucel": "La première thérapie cellulaire CAR-T conçue en Inde même, approuvée en 2023 pour la leucémie et le lymphome en rechute, fabriquée à Mumbai pour environ un dixième de ce que coûte le même type de traitement aux États-Unis.",
  tamoxifen: "Le tout premier médicament anticancéreux ciblé (1977) : un comprimé qui bloque l'effet des œstrogènes sur le cancer du sein et réduit de moitié les récidives, toujours essentiel pour les femmes avant la ménopause.",
  "targeted-alpha-therapy": "Comme la thérapie par radioligand mais avec des particules alpha : bien plus destructrices sur une portée beaucoup plus courte, ce qui permet de tuer des cellules isolées avec moins de dommages collatéraux.",
  "tumor-microenvironment": "Une tumeur n'est pas seulement un amas de cellules cancéreuses. C'est un voisinage de fibroblastes, de cellules immunitaires, de vaisseaux sanguins, de nerfs et de tissu de soutien que le cancer recrute et corrompt, et qui décide si les médicaments et les cellules immunitaires peuvent y pénétrer.",
  "tumour-agnostic": "Une approbation agnostique de la tumeur permet d'utiliser un médicament pour tout cancer porteur d'une caractéristique moléculaire précise, quel que soit l'organe où il a débuté.",
  "ubiquitin-proteasome-system": "Les cellules marquent les protéines indésirables avec une petite étiquette appelée ubiquitine et les envoient dans un broyeur, le protéasome. Les cellules de myélome, qui fabriquent des anticorps en masse, meurent si le broyeur se bloque ; et les médicaments les plus récents détournent la machinerie d'étiquetage pour forcer le cancer à détruire ses propres oncoprotéines.",
  "uchicago-cancer": "C'est là que Charles Huggins a prouvé que les hormones alimentent le cancer de la prostate et que Janet Rowley a découvert les translocations chromosomiques à l'origine de la leucémie ; aujourd'hui, le centre est fort en immunologie des tumeurs.",
  "ucla-jonsson": "C'est là que trastuzumab (Slamon) et palbociclib ont été développés sur le plan clinique ; le centre est aussi un leader du PET PSMA et de l'immunothérapie du mélanome (Ribas).",
  uclh: "L'hôpital universitaire du centre de Londres et l'un des deux centres de protonthérapie du NHS, soutenu par l'institut du cancer de l'UCL et ses recherches sur les CAR-T et l'évolution du cancer du poumon.",
  "ucsd-moores": "Le centre de cancérologie intégré du NCI à San Diego, où ont été développés l'anticorps anti-GD2 dinutuximab et l'anticorps anti-ROR1 à l'origine de zilovertamab.",
  ucsf: "L'UCSF est le berceau de la biologie des oncogènes (Bishop, Varmus) et du ciblage médicamenteux de KRAS G12C (Shokat), et un leader des essais adaptatifs I-SPY dans le cancer du sein.",
  ultrasound: "L'échographie utilise des ondes sonores pour produire des images en direct ; elle est peu coûteuse, sûre et sert à guider les aiguilles jusque dans les masses.",
  unicancer: "UNICANCER est le réseau des centres de lutte contre le cancer français et le promoteur de leurs essais académiques.",
  "unproven-diet-claims": "Régimes vendus comme des remèdes ou des moyens de prévention contre le cancer sans aucune preuve à l'appui : régimes alcalins, cures de jus, thérapie Gerson, noyaux d'abricot et autres. Certains sont simplement inutiles ; plusieurs ont causé des dommages ou conduit des personnes à retarder un traitement efficace.",
  urethral: "Le cancer de l'urètre se développe dans le conduit qui évacue l'urine hors du corps. Il est très rare, si bien que les médecins le traitent en s'inspirant du cancer de la vessie, du cancer de l'anus et du cancer de la vulve selon le type de cellules et la localisation. Associer la chimiothérapie à la radiothérapie avant la chirurgie, ou à sa place, permet à davantage de patients de conserver leurs organes.",
  "uterine-sarcoma": "Les sarcomes utérins sont des cancers rares du muscle et du tissu de soutien de l'utérus, distincts du cancer de l'endomètre, bien plus fréquent. L'ablation de l'utérus en un seul bloc est le traitement principal et guérit de nombreuses tumeurs précoces ; les sarcomes du stroma de bas grade répondent aux comprimés bloquant les hormones, tandis que le léiomyosarcome avancé est traité par chimiothérapie, comme doxorubicin et trabectedin.",
  "uz-leuven": "Le plus grand hôpital universitaire de Belgique et un centre de cancérologie intégré accrédité par l'OECI, avec une recherche de classe mondiale en cancérologie digestive, gynécologique et sur l'angiogenèse.",
  vaginal: "Le cancer primitif du vagin est rare et le plus souvent causé par le HPV, le virus à l'origine du cancer du col de l'utérus. Il se traite comme le cancer du col, par une chimiothérapie associée à une radiothérapie externe et interne, ce qui guérit de nombreuses patientes tout en préservant l'organe. La vaccination contre le HPV et le dépistage du col de l'utérus, qui détecte aussi les lésions précancéreuses vaginales, le font régulièrement reculer.",
  "vascular-tumours": "Les tumeurs vasculaires vont de l'angiosarcome, un cancer agressif des cellules qui tapissent les vaisseaux sanguins, à l'EHE à croissance lente et au KHE, une tumeur du nourrisson. L'angiosarcome répond à la chimiothérapie par paclitaxel et, dans sa forme du cuir chevelu abîmé par le soleil, à l'immunothérapie ; l'EHE et le KHE sont entretenus par des signaux de croissance que le bloqueur de mTOR sirolimus peut calmer, et de nombreux cas d'EHE peuvent simplement être surveillés.",
  vegf: "Le signal que les tumeurs utilisent pour se fabriquer leur propre réseau sanguin. Le bloquer affame les tumeurs et, de façon surprenante, aide l'immunothérapie à agir.",
  "vegf-angiogenesis": "Comment les tumeurs se fabriquent leur propre réseau sanguin. Le manque d'oxygène pousse les cellules à libérer du VEGF, qui ordonne aux cellules des vaisseaux sanguins de bourgeonner vers la tumeur.",
  vemurafenib: "Vemurafenib a été le premier inhibiteur de BRAF (2011) ; il a fait régresser des mélanomes en quelques semaines et prouvé qu'une seule mutation pouvait être ciblée par un médicament dans une tumeur solide.",
  venetoclax: "Un comprimé qui retire aux cellules leucémiques leur bouclier de survie, permettant un traitement de la CLL sans chimiothérapie et de durée limitée.",
  vincristine: "Une chimiothérapie d'origine végétale, tirée de la pervenche de Madagascar, présente dans presque tous les protocoles de traitement des leucémies et lymphomes de l'enfant depuis les années 1960.",
  "virtual-cell": "La tentative de construire un modèle informatique d'une cellule assez fidèle pour prédire l'effet d'un médicament ou d'une mutation avant même que quiconque ne réalise l'expérience.",
  wee1: "Une kinase de point de contrôle qui laisse aux cellules le temps de réparer leur ADN avant de se diviser. La supprimer force les cellules cancéreuses endommagées à entrer dans une division qui leur est fatale.",
  "wellcome-sanger": "L'institut britannique de génomique dont le Cancer Genome Project a découvert la mutation de BRAF dans le mélanome, créé COSMIC et défini les signatures mutationnelles.",
  "wes-wgs": "Lire tous les gènes (exome) ou la totalité de l'ADN (génome) d'une tumeur, plutôt qu'un panel de gènes choisis.",
  wnt: "Wnt/β-catenin est une voie du développement détournée par le cancer colorectal. Normalement, un complexe de destruction maintient la β-catenin à un niveau bas ; la perte d'APC lui permet d'envahir le noyau et d'activer les gènes de croissance.",
  "y-combinator": "Y Combinator est l'accélérateur de start-up qui finance chaque année des centaines de nouvelles entreprises en échange d'une petite participation. Depuis 2014, il soutient un flux régulier d'entreprises qui s'attaquent au cancer, des tests sanguins aux virus modifiés.",
  zanidatamab: "Zanidatamab (Ziihera) est un anticorps qui s'accroche à HER2 en deux endroits différents, approuvé pour le cancer des voies biliaires HER2+.",
  zanubrutinib: "Zanubrutinib est le seul bloqueur de BTK à avoir surpassé ibrutinib à la fois en efficacité et en sécurité dans un essai comparatif direct. C'est aujourd'hui l'inhibiteur de BTK le plus prescrit dans la CLL.",
  ziftomenib: "Ziftomenib est le deuxième inhibiteur de menin pour la leucémie, approuvé en novembre 2025 sous forme de comprimé en une prise quotidienne pour l'AML en rechute avec mutation de NPM1.",
  // ---- second wave (2026-09) ----
  "12-de-octubre": "L'un des plus grands hôpitaux de Madrid, un site de premier plan pour les essais sur le cancer du poumon et le myélome et pour le développement académique de CAR-T.",
  aall1731: "Chez les enfants atteints d'une leucémie de risque moyen, l'ajout de blinatumomab a fait passer la survie sans maladie à trois ans de 88% à 96%, l'un des plus grands gains depuis des décennies.",
  "aarhus-university-hospital": "Le deuxième hôpital universitaire du Danemark, siège du centre national de protonthérapie et des essais DAHANCA de radiothérapie des cancers de la tête et du cou.",
  abcsg: "Le groupe académique autrichien d'essais sur les cancers du sein et colorectal, dont les essais sur les traitements ciblant l'os et l'hormonothérapie prolongée ont changé la pratique dans le cancer du sein.",
  "abscopal-effect": "Lorsque l'irradiation d'une tumeur fait régresser des tumeurs non traitées situées ailleurs, par l'intermédiaire du système immunitaire.",
  "ac225-psma": "Des médicaments PSMA émetteurs alpha qui produisent des réponses même après l'échec de Pluvicto, freinés surtout par l'approvisionnement en isotope.",
  "accelerate-platform": "Un forum basé à Bruxelles où médecins du cancer de l'enfant, laboratoires pharmaceutiques, régulateurs et parents s'accordent sur la manière de tester les nouveaux médicaments anticancéreux chez l'enfant, afin que moins de médicaments prometteurs laissent de côté les cancers pédiatriques.",
  "active-surveillance-term": "Ne pas traiter volontairement un cancer pour l'instant, mais le surveiller régulièrement par des analyses de sang, des examens d'imagerie ou des biopsies, et ne traiter que s'il montre des signes de progression. C'est la norme pour le cancer de la prostate à faible risque, les petites masses rénales et plusieurs autres affections d'évolution lente.",
  adaura: "A montré qu'un comprimé ciblé après une chirurgie du cancer du poumon divise par deux le risque de décès, le premier résultat de ce type pour une thérapie ciblée.",
  "adc-cdmo-manufacturing": "Relier une charge hautement toxique à un anticorps de façon sûre et à grande échelle. Peu de sous-traitants savent le faire, ce qui détermine qui peut développer des ADC.",
  adcc: "Dans l'ADCC, un anticorps marque une cellule, et les cellules NK reconnaissent ce marquage et la tuent.",
  "aditya-bardia": "A dirigé ASCENT, l'essai qui a fait du sacituzumab govitecan le premier ADC pour le cancer du sein triple négatif, et l'essai EMERALD de l'elacestrant.",
  "afamitresgene-autoleucel": "Afamitresgene autoleucel a été la première thérapie par récepteur de lymphocytes T modifié approuvée pour une tumeur solide, le sarcome synovial.",
  agitg: "Le groupe d'essais sur les cancers digestifs d'Australie et de Nouvelle-Zélande, qui mène des essais influençant la pratique dans les cancers de l'estomac, de l'œsophage, colorectal et du pancréas, y compris des études adjuvantes guidées par le ctDNA.",
  "aiims-delhi": "La première institution médicale publique de l'Inde, dont le Rotary Cancer Hospital et le nouveau campus du National Cancer Institute à Jhajjar sont les piliers de la recherche et des soins publics en cancérologie.",
  ak146d1: "AK146D1 est l'ADC bispécifique Nectin-4 × TROP2 d'Akeso, qui réunit les deux cibles d'ADC les plus validées en une seule molécule.",
  akeso: "Biotech chinoise dont l'ivonescimab a battu Keytruda en comparaison directe, et développeur de l'ADC Nectin-4×TROP2.",
  "alcohol-reduction-labelling": "L'alcool cause au moins sept cancers et il n'existe pas de seuil sans risque. Le prix, la disponibilité et les étiquettes d'avertissement sur le cancer sont les outils qui fonctionnent ; la plupart des gens ignorent encore que l'alcool cause le cancer.",
  "alliance-oncology": "Groupe coopératif américain né de la fusion de CALGB, ACOSOG et NCCTG ; il mène OptimICE-pCR, qui demande si les patientes atteintes de TNBC ayant obtenu une réponse complète ont encore besoin d'un an d'immunothérapie.",
  "alpha-vs-beta": "Les particules bêta (lutétium-177) parcourent quelques millimètres et conviennent aux maladies volumineuses ; les particules alpha (actinium-225) parcourent la largeur de quelques cellules et tuent avec une énergie bien plus élevée.",
  "alternative-medicine-instead-of-treatment": "Les approches complémentaires utilisées en parallèle du traitement peuvent aider à soulager les symptômes. Choisir une thérapie alternative à la place de la chirurgie, de la chimiothérapie, de la radiothérapie ou de l'hormonothérapie est une décision différente : dans une base de données nationale américaine, les personnes qui l'ont fait avaient deux fois et demie plus de risque de mourir pendant la période de l'étude, et plus de cinq fois plus en cas de cancer du sein.",
  amplify: "AMPLIFY est l'essai à l'origine du premier traitement de la CLL entièrement par voie orale et de durée fixe approuvé aux États-Unis (février 2026) : 14 cycles de deux comprimés, puis arrêt.",
  anlotinib: "Anlotinib est l'un des comprimés anticancéreux les plus utilisés en Chine, d'abord approuvé pour le cancer du poumon après échec d'autres traitements, puis pour plusieurs tumeurs plus rares.",
  anthracycline: "Une famille de médicaments de chimiothérapie de couleur rouge, dérivés d'une bactérie du sol, qui endommagent l'ADN du cancer. Piliers du traitement du cancer du sein, du lymphome, de la leucémie et du sarcome, mais ils affaiblissent le cœur de façon dose-dépendante, d'où une limite à vie.",
  antibody: "Une protéine en forme de Y que le système immunitaire fabrique pour s'accrocher à une cible précise. Les anticorps fabriqués sont aujourd'hui une pierre angulaire du traitement du cancer, soit en bloquant une protéine, soit en lui apportant une charge.",
  "antiemetic-therapy": "Les médicaments grâce auxquels la chimiothérapie ne rime plus avec des jours de vomissements : bloqueurs 5-HT3 (ondansetron, palonosetron), bloqueurs NK1 (aprepitant), dexaméthasone et olanzapine, administrés selon le risque émétique de chaque protocole.",
  antigen: "Tout ce qu'un anticorps ou une cellule immunitaire peut reconnaître, généralement une protéine à la surface d'une cellule. Dans le cancer, un antigène est le drapeau qui indique à un médicament ou à une cellule immunitaire « voici la cellule à attaquer ».",
  "arcagy-gineco": "Le groupe français d'essais en cancérologie gynécologique qui a mené PAOLA-1, l'essai ajoutant l'olaparib au bevacizumab en entretien dans le cancer de l'ovaire.",
  "aromatase-inhibitor": "Des comprimés qui empêchent le corps de produire des œstrogènes (après la ménopause, quand ils proviennent de la graisse et du muscle plutôt que des ovaires), privant ainsi le cancer du sein à récepteurs hormonaux positifs de son carburant. Pris pendant cinq à dix ans après la chirurgie, ils réduisent de moitié les récidives.",
  "artera-ai-prostate": "Le premier outil d'IA autorisé par la FDA pour prédire à la fois le pronostic et le bénéfice du traitement à partir d'une lame de biopsie de routine, dans le cancer de la prostate.",
  "asan-medical-center": "Asan Medical Center est le plus grand hôpital de Corée et un leader mondial de la transplantation hépatique et de la chirurgie du cancer de l'estomac.",
  asciminib: "Asciminib est un bloqueur de BCR::ABL1 qui se fixe sur une poche différente de celle de tous les autres TKI, approuvé en 2024 pour toute leucémie myéloïde chronique nouvellement diagnostiquée et désormais testé dans la ALL Ph positive.",
  ash: "La plus grande société d'hématologie au monde, dont le congrès annuel de décembre est le lieu où sont présentés pour la première fois les résultats décisifs dans la leucémie, le lymphome et le myélome.",
  astellas: "Astellas codétient Padcev et fabrique Vyloy, le premier médicament ciblant Claudin 18.2.",
  astro: "La plus grande société de radiothérapie oncologique, dont le congrès annuel, les recommandations et les listes Choosing Wisely favorisent l'adoption de l'hypofractionnement et de la radiothérapie stéréotaxique.",
  "augment-101": "L'essai qui a fait passer l'inhibition de la ménine du stade d'idée au premier médicament approuvé pour la leucémie avec réarrangement de KMT2A.",
  "auto-contouring-ai": "Un logiciel qui délimite automatiquement les organes et les tumeurs sur les images, faisant gagner des heures par patient et rendant l'adaptation quotidienne du plan réalisable en pratique.",
  "autogene-cevumeran": "Le vaccin personnalisé de BioNTech, remarqué pour une petite étude dans le cancer du pancréas où les patients ayant répondu au vaccin sont restés sans cancer pendant des années.",
  "autologous-transplant": "Une chimiothérapie à très forte dose qui détruirait la moelle osseuse, rendue supportable en réinjectant au patient ses propres cellules souches prélevées auparavant. Standard dans le myélome et le lymphome en rechute ; les cellules sauvent la moelle, elles ne combattent pas le cancer.",
  avapritinib: "Avapritinib est le premier médicament contre les GIST portés par la mutation PDGFRA D842V, qui résiste à tous les autres inhibiteurs de kinase ; il est aussi approuvé dans la mastocytose systémique.",
  avelumab: "Avelumab est un bloqueur de PD-L1 administré en entretien après la chimiothérapie dans le cancer de la vessie avancé, qui a prolongé la survie d'environ sept mois.",
  "avoiding-immune-destruction": "Les cancers se cachent du système immunitaire ou le désactivent, en perdant les molécules qui présentent leurs antigènes ou en renforçant les freins des points de contrôle.",
  axitinib: "Axitinib est un comprimé sélectif contre le récepteur du VEGF, désormais donné surtout avec pembrolizumab ou avelumab en traitement de première ligne du cancer du rein.",
  "aya-oncology": "Le cancer chez les personnes de 15 à 39 ans, environ 90 000 cas par an aux États-Unis, avec un éventail de cancers particulier, une amélioration de la survie plus lente que chez les enfants ou les adultes plus âgés, et des besoins spécifiques : fertilité, études et travail, soutien psychosocial et accès aux essais.",
  "b-cell": "Les cellules immunitaires qui fabriquent les anticorps. Elles comptent doublement dans le cancer : comme source de tout anticorps thérapeutique, et comme cellules qui déraillent dans la plupart des lymphomes, des leucémies et du myélome.",
  "bariatric-surgery-cancer-incidence": "Les personnes souffrant d'obésité sévère qui subissent une chirurgie de l'obésité développent environ un tiers de cancers en moins au cours de la décennie suivante, en particulier des cancers de l'utérus et d'autres cancers hormono-dépendants, par rapport à des personnes similaires non opérées.",
  "basement-membrane-tissue-barriers": "Chaque organe maintient ses cellules de revêtement derrière une fine et dense couche de protéines appelée membrane basale. Une tumeur qui ne l'a pas franchie est 'in situ' et essentiellement curable ; la franchir est le moment où le cancer devient invasif.",
  bayer: "Bayer détient Xofigo, le seul émetteur alpha approuvé, et développe des agents PSMA à l'actinium de nouvelle génération.",
  "bc-cancer": "L'agence provinciale du cancer de la Colombie-Britannique, leader mondial en génomique du cancer (Personalized OncoGenomics), en recherche sur le lymphome et en dépistage du col de l'utérus basé sur le HPV.",
  "bcg-intravesical": "Un vaccin atténué contre la tuberculose instillé directement dans la vessie. Depuis 1976, c'est le traitement le plus efficace du cancer précoce de la vessie, et il reste en pénurie chronique.",
  "bcg-unresponsive": "La définition par la FDA du cancer de la vessie précoce ayant échoué à un traitement adéquat par BCG, la population dans laquelle la plupart des nouveaux médicaments de la vessie sont d'abord approuvés.",
  "bclc-staging": "Le système de stadification du cancer du foie qui combine la taille de la tumeur, la fonction hépatique et l'état général pour recommander un traitement : ablation ou chirurgie, transplantation, TACE ou médicaments.",
  "bcr-abl1-signalling": "La leucémie myéloïde chronique est causée par un seul gène cassé : deux chromosomes échangent des morceaux et collent une kinase (ABL1) à une protéine qui la force à rester allumée en permanence. Imatinib, le premier médicament à la cibler, a transformé une maladie mortelle en maladie gérable, et des médicaments ultérieurs couvrent les mutations qui lui échappent.",
  "bcr-signalling": "Le récepteur des cellules B est l'interrupteur de survie des cellules B. Ses signaux passent par BTK pour libérer NF-kappa-B, qui maintient la cellule en vie. Les cancers des cellules B le gardent allumé ; les inhibiteurs de BTK, les inhibiteurs du protéasome et le lénalidomide coupent la ligne chacun à un point différent.",
  bcrf: "Le plus grand financeur privé de la recherche sur le cancer du sein au monde, qui accorde chaque année des subventions à plus de 250 chercheurs dans les principaux centres du domaine.",
  "beatson-glasgow": "Le plus grand centre de cancérologie d'Écosse, qui porte le nom du chirurgien ayant utilisé pour la première fois l'hormonothérapie contre le cancer du sein, à côté d'un institut de biologie du cancer de premier plan.",
  "belantamab-mafodotin": "Un ADC contre le myélome retiré du marché en 2022, puis revenu en 2025 après des essais solides dans des lignes de traitement plus précoces.",
  beone: "BeOne Medicines fabrique Brukinsa, le premier inhibiteur de BTK du marché, et tislelizumab, et est le partenaire asiatique pour zanidatamab.",
  "bgb-16673": "Au lieu de bloquer BTK, ce comprimé le détruit, de sorte qu'il agit même lorsque l'enzyme a muté pour échapper à tous les inhibiteurs.",
  "bh3-profiling": "Un test de laboratoire qui mesure à quel point une cellule leucémique est proche de s'autodétruire, et quelle protéine de survie la retient, afin de prédire la réponse aux médicaments de type venetoclax.",
  big: "Le Breast International Group est la structure qui fédère plus de 50 groupes académiques de recherche sur le cancer du sein dans le monde et le co-promoteur d'OlympiA, APHINITY et HERA.",
  biocon: "La plus grande entreprise biopharmaceutique d'Inde, fondée par Kiran Mazumdar-Shaw en 1978, et maison mère de Biocon Biologics, qui fabrique des copies à bas coût des anticorps trastuzumab et bevacizumab.",
  biomarker: "Tout ce qui est mesurable dans le corps ou la tumeur et qui apporte une information utile : de quel type de cancer il s'agit, comment il risque d'évoluer, ou quel médicament a des chances d'être efficace.",
  biontech: "Du vaccin contre la COVID à un large portefeuille en oncologie : vaccins personnalisés, ADC venus de Chine et un bispécifique PD-L1×VEGF vendu à BMS pour 11 milliards de dollars.",
  biosimilar: "Un biosimilaire est une copie d'un médicament biologique comme le trastuzumab, dont il a été démontré qu'il est aussi sûr et efficace que l'original une fois son brevet expiré, généralement à un prix inférieur.",
  "birmingham-cancer-centre": "Le centre anticancéreux de la deuxième ville d'Angleterre, siège de l'une des plus grandes unités universitaires d'essais en cancérologie du Royaume-Uni et de grands essais sur les cancers de la vessie, colorectaux et pédiatriques.",
  bleomycin: "Bleomycin est le « B » de BEP pour le cancer du testicule et d'ABVD pour le lymphome de Hodgkin ; son danger propre est la fibrose des poumons, on surveille donc la fonction pulmonaire et on l'arrête souvent quand c'est possible sans risque.",
  "body-composition": "Ce dont est fait le poids d'une personne : muscle, graisse sous la peau, graisse autour des organes. Elle prédit l'évolution du cancer bien mieux que le poids ou le BMI, et peut être lue sur des scanners CT de routine.",
  "bone-modifying-agents": "Zoledronic acid et denosumab réduisent les fractures, la compression de la moelle épinière et les douleurs osseuses dues aux métastases osseuses et au myélome, préviennent la perte osseuse induite par les traitements et, dans le cancer du sein postménopausique, réduisent modestement les récidives osseuses.",
  "bracanalysis-cdx": "Le test BRCA hérité qui décide qui peut recevoir des comprimés d'inhibiteurs de PARP pour les cancers de l'ovaire, du sein, du pancréas et de la prostate.",
  "bradley-monk": "Oncologue gynécologue qui a codirigé KEYNOTE-826, innovaTV 301 et KEYNOTE-A18, les essais qui ont refondé le traitement du cancer du col de l'utérus.",
  breakwater: "A doublé la survie, d'environ 15 à environ 30 mois, dans le sous-type génétique de plus mauvais pronostic du cancer de l'intestin en ajoutant deux médicaments ciblés à la chimiothérapie de première ligne.",
  "breast-cancer-trials": "Le groupe d'essais sur le cancer du sein d'Australie et de Nouvelle-Zélande, partenaire du Breast International Group dans SOFT/TEXT, APHINITY, OlympiA et POSITIVE.",
  brenetafusp: "Le successeur du tebentafusp : un récepteur de lymphocyte T soluble qui reconnaît un fragment de PRAME, une protéine présente dans la plupart des mélanomes et de nombreux autres cancers, et attire les lymphocytes T sur la tumeur.",
  "brian-druker": "Il a fait passer un inhibiteur de kinase mis au placard du laboratoire à un essai clinique en 1998, alors que peu de gens croyaient qu'un comprimé ciblé puisse fonctionner. L'imatinib a fait de la leucémie myéloïde chronique une maladie avec laquelle on vit, et il est devenu le modèle de la thérapie ciblée.",
  "btki-plus-venetoclax-fixed-duration": "Bloquer le signal de survie et retirer le bouclier contre la mort cellulaire en même temps, pendant environ un an, puis arrêter et rester en rémission pendant des années.",
  bwel: "BWEL est un essai portant sur plus de 3 000 femmes, qui teste si perdre du poids après le traitement d'un cancer du sein réduit les récidives. Le programme a permis une perte de poids ; l'effet sur les récidives n'a pas été clairement démontré lors de la première analyse.",
  "bystander-effect": "Lorsque la charge libérée s'échappe de la cellule ciblée et tue ses voisines, y compris des cellules dépourvues de la cible.",
  "cachexia-biology": "Le syndrome de dénutrition qui tue jusqu'à un tiers des patients atteints de cancer : les tumeurs envoient des signaux hormonaux (GDF-15, IL-6) qui coupent l'appétit et brûlent muscle et graisse. Le premier médicament à l'inverser, ponsegromab, a montré une prise de poids en 2024.",
  "cachexia-therapy": "Traiter le dépérissement qui tue de nombreux patients atteints de cancer, en bloquant l'hormone qui supprime l'appétit.",
  camizestrant: "Camizestrant est un dégradeur oral du récepteur des œstrogènes approuvé en septembre 2026 pour un nouveau type de décision : changer de traitement lorsqu'un test sanguin montre qu'une résistance se développe, avant que le cancer ne grossisse visiblement.",
  "camrelizumab-rivoceranib": "Une association chinoise d'immunothérapie et d'un comprimé anti-angiogénique qui a clairement battu le sorafenib dans le cancer du foie, mais qui reste non approuvée aux États-Unis après trois refus liés à la fabrication.",
  "cancer-council-australia": "L'association caritative fédérée australienne contre le cancer, qui finance la recherche, rédige les recommandations cliniques nationales et mène les campagnes de prévention à l'origine de la baisse du tabagisme et du mélanome en Australie.",
  "cancer-health-disparities": "Des différences systématiques dans qui développe un cancer, à quel stade il est découvert et qui survit, liées à l'origine ethnique, aux revenus, à la géographie, à l'assurance et au racisme structurel plutôt qu'à la seule biologie.",
  "cancer-institute-adyar": "Le deuxième plus ancien hôpital anticancéreux de l'Inde (1954), fondé par Muthulakshmi Reddy et dirigé pendant des décennies par V. Shanta, et siège du premier registre du cancer en population de l'Inde.",
  "cancer-neuroscience": "La neuroscience du cancer étudie la façon dont les tumeurs dialoguent avec les nerfs. Les nerfs se développent dans les tumeurs et leur envoient des signaux ; les tumeurs cérébrales vont jusqu'à se brancher sur les circuits neuronaux. Couper cette conversation avec des médicaments courants comme les bêtabloquants est aujourd'hui à l'essai.",
  "cancer-stage": "L'étendue de la propagation d'un cancer, du stade I (petit et localisé) au stade IV (disséminé vers des organes distants). Le stade est, à lui seul, le guide le plus fiable pour le traitement et le pronostic.",
  candiolo: "L'institut du cancer du Piémont, près de Turin, une référence mondiale en génomique du cancer colorectal, en xénogreffes dérivées de patients et en biologie de MET.",
  "capstone-1": "L'essai qui a ajouté adebrelimab, l'anticorps anti-PD-L1 de Hengrui, à la chimiothérapie dans le cancer du poumon à petites cellules, avec l'un des plus grands gains de survie observés dans cette maladie.",
  cbioportal: "cBioPortal permet de parcourir les mutations, le nombre de copies et l'expression de dizaines de milliers de tumeurs sans écrire de code.",
  "ccc-tuebingen": "Le centre de cancérologie de Tübingen, berceau des vaccins peptidiques contre le cancer et des sociétés issues de ses laboratoires Immatics et CureVac, avec une solide tradition en mélanome et en PET/MRI.",
  "ccc-vienna": "Le principal centre universitaire de cancérologie d'Autriche, à l'Hôpital général de Vienne, connu pour les essais du sein de l'ABCSG, la recherche sur les métastases cérébrales et le centre de thérapie par ions MedAustron.",
  "ccc-wuerzburg": "L'université où Röntgen a découvert les rayons X, aujourd'hui un centre mondial des CAR-T et des anticorps bispécifiques dans le myélome multiple, sous la direction de Hermann Einsele.",
  cclg: "L'organisme professionnel et le réseau d'essais du cancer de l'enfant du Royaume-Uni et d'Irlande ; presque chaque enfant traité pour un cancer au Royaume-Uni est pris en charge dans un centre CCLG.",
  cctg: "Le groupe national d'essais académiques du Canada, qui a mené l'essai CHALLENGE sur l'exercice physique et codirigé l'essai SABR-COMET sur l'oligométastase.",
  cd38: "CD38 est une enzyme de surface des cellules du myélome et la cible du daratumumab, désormais administré par une injection rapide sous la peau.",
  cdisc: "L'organisation à but non lucratif qui rédige les normes de données des essais cliniques (SDTM, ADaM, CDASH) que la FDA, la PMDA et la NMPA exigent pour chaque dossier de médicament anticancéreux.",
  "cell-cycle": "La séquence ordonnée que suit une cellule pour copier son ADN et se diviser en deux, avec des points de contrôle en chemin où elle s'arrête pour vérifier l'absence de dommages. Les cellules cancéreuses passent outre ces points de contrôle.",
  "centre-leon-berard": "Le centre de lutte contre le cancer de Lyon, référence mondiale pour les sarcomes et les cancers rares, dirigé par Jean-Yves Blay, qui préside également UNICANCER.",
  cervavac: "Le premier vaccin anti-HPV fabriqué en Inde, qui protège contre les deux types de virus responsables de la plupart des cancers du col de l'utérus et les deux types responsables des verrues génitales, à un prix conçu pour un programme national.",
  cfdna: "De courts fragments d'ADN flottant dans le sang, libérés par les cellules qui meurent dans tout le corps. La plupart proviennent de cellules normales ; la petite fraction issue de la tumeur (ctDNA) est ce que les biopsies liquides vont pêcher.",
  challenge: "Le premier essai randomisé à montrer qu'un programme d'exercice encadré après le traitement d'un cancer réduit les récidives et les décès, dans le cancer du côlon.",
  champalimaud: "La fondation privée de recherche et clinique de Lisbonne, connue pour ses recommandations sur le cancer du sein avancé, la chirurgie des cancers digestifs et la recherche à la croisée du cancer et des neurosciences.",
  "charles-geyer": "Spécialiste des essais dans le cancer du sein, il a codirigé OlympiA, montrant que l'olaparib adjuvant améliore la survie chez les porteurs de BRCA.",
  "charles-swanton": "Il dirige TRACERx, l'étude qui suit l'évolution des cancers du poumon, et a montré comment la pollution de l'air peut déclencher un cancer du poumon sans nouvelles mutations.",
  "checkmate-214": "CheckMate 214 est l'essai qui a apporté la double immunothérapie au cancer du rein, avec un avantage de survie encore visible huit ans plus tard et un cinquième des patients en rémission à long terme.",
  "checkmate-649": "L'essai qui a ajouté l'immunothérapie à la chimiothérapie de première ligne du cancer de l'estomac ; à cinq ans, 16 % des patients dont la tumeur était riche en PD-L1 étaient en vie, contre 6 %.",
  "checkmate-8hw": "A montré qu'une association de deux immunothérapies contrôle le cancer colorectal avec déficience du système de réparation des mésappariements pendant plus de quatre ans en moyenne, et fait mieux que l'immunothérapie seule.",
  "chemotherapy-term": "Des médicaments qui tuent les cellules à division rapide en endommageant leur ADN ou la machinerie de la division. Comme les cellules cancéreuses se divisent vite, elles sont les plus touchées, mais c'est aussi le cas des cheveux, de la paroi intestinale et de la moelle osseuse, d'où viennent les effets secondaires.",
  "chulabhorn-hospital": "Un hôpital de cancérologie de fondation royale à Bangkok, spécialisé dans le diagnostic avancé et la médecine nucléaire, qui abrite le premier programme thaïlandais de TEP avec cyclotron et de thérapie par radioligands.",
  "chuv-lausanne": "L'hôpital universitaire de Lausanne et l'antenne lausannoise de l'Institut Ludwig, berceau de l'essai du temozolomide dans le glioblastome, de Solange Peters et d'un programme de pointe de thérapie personnalisée par cellules T.",
  "cin-hsil": "Des cellules anormales du col de l'utérus, causées par le HPV, qui peuvent se transformer en cancer en 10 à 20 ans. Le dépistage les détecte ; une intervention de cinq minutes les retire.",
  "cleveland-clinic": "La Cleveland Clinic est l'un des tout premiers hôpitaux américains, avec un Comprehensive Cancer Center (avec Case Western) et un programme de vaccin préventif contre le TNBC.",
  "cleveland-clinic-abu-dhabi": "L'hôpital universitaire privé le plus avancé du Golfe, dont le Fatima bint Mubarak Center a ouvert en 2023 comme premier centre intégré de cancérologie des Émirats arabes unis, avec une protonthérapie prévue.",
  "clinical-complete-response": "Aucun signe de tumeur à l'examen, à l'endoscopie et à l'IRM après le traitement, sans chirurgie pour le confirmer. C'est le fondement des stratégies de préservation d'organe.",
  "clinical-trial": "Une étude de recherche qui teste un traitement chez des volontaires selon des règles strictes, pour savoir s'il est sûr et s'il est efficace. Chaque médicament anticancéreux approuvé en a traversé plusieurs.",
  "cll13-gaia": "Chez les patients en bonne forme, un an de venetoclax plus obinutuzumab (avec ou sans ibrutinib) a nettement surpassé l'ancien standard de chimiothérapie.",
  cll14: "Un an de deux médicaments ciblés, puis plus rien : plus de la moitié des patients étaient encore sans progression six ans plus tard, sans aucun traitement.",
  "clonal-haematopoiesis": "Avec l'âge, des cellules souches du sang porteuses de mutations de type cancéreux se multiplient discrètement chez la plupart des gens. Ces clones augmentent le risque de leucémie et de maladie cardiaque, sont accélérés par la chimiothérapie et brouillent les tests sanguins recherchant l'ADN du cancer.",
  clonoseq: "Un test ADN qui compte les cellules résiduelles de leucémie, de myélome ou de lymphome jusqu'à une sur un million, utilisé pour décider si le traitement a vraiment fonctionné.",
  "closed-automated-cell-manufacturing": "Des machines fermées, pilotées par des robots, qui transforment les cellules sanguines d'un patient en produit CAR-T avec bien moins de mains, de salles blanches et d'erreurs.",
  cmg901: "Sonesitatug vedotin est un ADC ciblant Claudin 18.2, en phase 3 dans le cancer gastrique, dont AstraZeneca a acquis la licence auprès de KYM Biosciences.",
  cnio: "Le centre national espagnol de recherche sur le cancer, fondé par le pionnier de RAS Mariano Barbacid et connu pour la biologie des oncogènes, des télomères et de la sénescence.",
  cobimetinib: "Cobimetinib est le partenaire MEK du vemurafenib, et le premier médicament approuvé pour les néoplasies histiocytaires.",
  "colorado-cancer-center": "Le centre intégré du NCI de la région des Rocheuses et un leader mondial du cancer du poumon lié à des oncogènes, de ALK et ROS1 aux fusions NTRK.",
  "colposcopy-excision": "Examiner le col de l'utérus avec une loupe après un dépistage positif, puis retirer la zone anormale avec une anse de fil électrique lors d'une consultation en clinique.",
  columbus: "COLUMBUS a testé encorafenib-binimetinib, le troisième doublet BRAF/MEK, qui a la survie médiane la plus longue de la classe et moins de fièvre que dabrafenib-trametinib.",
  "community-oncology-networks": "Les cliniques où la plupart des patients atteints de cancer sont réellement traités, de plus en plus organisées en grands réseaux qui mènent aussi des essais.",
  "companion-diagnostic-term": "Un diagnostic compagnon est un test que la FDA exige avant qu'un médicament donné puisse être prescrit.",
  "conditioning-regimen": "La chimiothérapie (avec ou sans irradiation corporelle totale) administrée dans les jours précédant une greffe de cellules souches pour détruire la moelle malade et, pour les greffes de donneur, supprimer le système immunitaire du patient afin que le greffon ne soit pas rejeté.",
  "contract-research-organisations": "Des entreprises qui mènent les essais cliniques pour le compte des promoteurs : centres, suivi, données et dépôt réglementaire.",
  crizotinib: "Crizotinib a été le premier inhibiteur d'ALK, approuvé quatre ans après la découverte des fusions ALK dans le cancer du poumon ; il a aussi été le premier médicament contre le cancer du poumon ROS1 et contre le lymphome ALK-positif et la tumeur myofibroblastique inflammatoire chez l'enfant.",
  cross: "L'essai qui a fait de la chimiothérapie associée à la radiothérapie avant la chirurgie le standard du cancer de l'œsophage ; le gain de survie était toujours présent dix ans plus tard.",
  "cruk-manchester-institute": "L'institut de recherche sur le cancer de l'Université de Manchester, voisin de The Christie, leader mondial de la biopsie liquide et des modèles de cancer du poumon à petites cellules sous la direction de Caroline Dive.",
  "crystal-fire3": "Les essais qui ont établi les anticorps anti-EGFR dans le cancer de l'intestin et découvert qu'ils ne fonctionnent que lorsque le gène RAS est normal.",
  csco: "La société chinoise d'oncologie clinique, dont le congrès annuel et les recommandations par maladie servent de référence pour le traitement de la plus grande population de patients atteints de cancer au monde.",
  "csco-guidelines": "Les recommandations de la CSCO sont les recommandations nationales d'oncologie de la Chine ; elles se distinguent par le classement des recommandations à la fois selon les preuves et selon le coût, et par la prise en compte des médicaments développés en Chine (inhibiteurs de PD-1, ADC) et des cancers fréquents en Chine (nasopharynx, œsophage, foie, estomac) avant les recommandations occidentales.",
  "ctdna-lymphoma-monitoring": "Un test sanguin qui suit l'ADN du lymphome bien en dessous de ce qu'un PET-scan peut voir, afin que les médecins puissent dire tôt qui est guéri et qui va rechuter.",
  "cthpv-dna": "Un test sanguin qui détecte des fragments de l'ADN du virus libérés par les cancers de la gorge HPV-positifs, afin de confirmer le diagnostic, suivre la réponse et repérer tôt une récidive.",
  "cun-navarra": "Le centre de cancérologie de l'Université de Navarre à Pampelune et Madrid, connu pour le myélome, la recherche en immunothérapie et l'une des premières unités de protonthérapie d'Espagne.",
  "cytarabine-7-3": "La chimiothérapie intensive qui induit la rémission chez les patients atteints de AML en bon état général depuis 1973 : sept jours d'un médicament, trois d'un autre. Elle reste le socle auquel on ajoute les médicaments ciblés.",
  cytogenetics: "Observer les chromosomes d'un cancer au microscope pour repérer des morceaux manquants, en excès, cassés ou échangés. C'est depuis des décennies le principal outil de classification du risque dans la leucémie, le myélome et le lymphome.",
  "cytogenetics-fish": "Observer les chromosomes de la leucémie au microscope, ou faire ressortir des cassures géniques précises avec des sondes fluorescentes, pour classer le risque.",
  cytokine: "De petites protéines que les cellules immunitaires utilisent pour communiquer entre elles : alarmes, appels de renfort, ordres de croissance et signaux d'arrêt. Certaines sont des médicaments anticancéreux, et leur déferlement constitue le danger de certaines immunothérapies.",
  "dako-pd-l1-22c3-pharmdx": "Le test PD-L1 lié au pembrolizumab, et la source du score 'CPS' qui décide de l'immunothérapie dans de nombreux cancers.",
  dasatinib: "Dasatinib est un comprimé de deuxième génération contre BCR::ABL1 qui, associé à l'immunothérapie blinatumomab, peut amener la ALL Ph-positive en rémission profonde sans aucune chimiothérapie.",
  "dbt-india": "Le ministère qui finance les instituts de sciences de la vie de l'Inde et, par l'intermédiaire de BIRAC, les start-up à l'origine des thérapies CAR-T et du vaccin contre le HPV développés dans le pays.",
  "de-escalation": "Donner moins de traitement aux patients qui vont bien et davantage à ceux qui ne vont pas bien, en s'appuyant sur un marqueur tel que la réponse à l'imagerie, l'ctDNA ou la MRD pour décider. Le but est de guérir autant de personnes avec moins de dommages.",
  "de-novo-protein-design": "Concevoir une protéine de toutes pièces sur ordinateur pour qu'elle s'accroche à une cible choisie, au lieu d'en trouver une chez un animal ou dans une banque.",
  deauville: "Une échelle de 1 à 5 mesurant l'intensité avec laquelle un lymphome s'illumine sur un PET-scan, comparée au foie et au centre du thorax. Des scores de 1 à 3 après deux cycles signifient que le traitement fonctionne et permettent de le raccourcir ; 4 à 5 signifie qu'il faut intensifier.",
  "decitabine-cedazuridine": "Decitabine-cedazuridine par voie orale est une version en comprimé de la chimiothérapie hypométhylante qui, depuis mai 2026, permet aux patients âgés atteints d'AML de prendre l'ensemble de leur traitement par venetoclax à domicile.",
  "degrader-antibody-conjugate": "Un ADC qui délivre une molécule destructrice de protéines au lieu d'une chimiothérapie, atteignant des cibles à l'intérieur de la cellule jusque-là inaccessibles.",
  "del17p-tp53": "Une délétion del(17p) ou une mutation de TP53 signifie la perte ou l'endommagement du gène de sécurité p53 dans la CLL. Ces patients ne doivent jamais recevoir de chimiothérapie ; ils ont besoin d'inhibiteurs de BTK ou de venetoclax, généralement en continu.",
  depmap: "Les gènes dont chaque lignée cellulaire cancéreuse ne peut se passer. La carte des cibles de létalité synthétique.",
  "dermoscopy-ai": "Imagerie cutanée grossie et cartographie photographique du corps entier, de plus en plus interprétées par des algorithmes, pour détecter tôt le mélanome et éviter les biopsies inutiles.",
  desmoplasia: "Le tissu dense, semblable à une cicatrice, qui constitue l'essentiel d'une tumeur du pancréas et isole les cellules cancéreuses des médicaments et des cellules immunitaires.",
  "destiny-breast03": "L'essai comparatif direct entre ADC où Enhertu a largement surpassé Kadcyla, montrant que la charge utile et l'effet de voisinage comptent.",
  "destiny-breast04": "A créé une nouvelle catégorie de cancer du sein, HER2-low, en montrant qu'Enhertu agit dans des tumeurs jusque-là qualifiées de HER2-négatives.",
  "destiny-breast06": "A placé Enhertu avant la chimiothérapie dans le cancer du sein hormonodépendant et l'a étendu au HER2 « ultra-faible ».",
  "differentiation-syndrome": "Lorsqu'un médicament ciblé fait mûrir les cellules leucémiques toutes en même temps, provoquant fièvre, liquide dans les poumons et prise de poids. Traitable par stéroïdes si détecté tôt.",
  dinutuximab: "L'anticorps qui a augmenté d'environ 20 points les taux de guérison du neuroblastome de haut risque de l'enfant lorsqu'il est administré après la greffe avec des stimulants immunitaires et un rétinoïde.",
  "disitamab-vedotin": "Disitamab vedotin est un ADC chinois anti-HER2 approuvé dans le cancer gastrique et le cancer de la vessie, aujourd'hui en essais mondiaux avec Pfizer.",
  dordaviprone: "Dordaviprone est le tout premier médicament approuvé pour une tumeur cérébrale mortelle de l'enfant et du jeune adulte, le gliome diffus de la ligne médiane avec la mutation H3 K27M (août 2025).",
  "dose-modification": "Les outils du quotidien pour vivre avec les effets secondaires : suspendre un médicament jusqu'à ce qu'un problème se calme (interruption), le reprendre à une dose plus faible (réduction) ou l'arrêter définitivement (arrêt). La fréquence à laquelle les patients en ont besoin est une mesure clé pour savoir si la dose a été bien fixée.",
  "driver-mutation": "L'une des rares mutations d'une tumeur qui la font réellement grossir. Toutes les autres sont des passagères qui suivent le mouvement. Les mutations conductrices sont celles que visent les médicaments.",
  "driver-mutation-term": "Une altération génétique qui pousse réellement le cancer à croître, par opposition aux nombreuses mutations « passagères » inoffensives qui ne font que suivre. Lorsqu'il existe un médicament capable de la bloquer, cette altération motrice est dite actionnable.",
  "drug-repurposing": "Tester de vieux médicaments bon marché, aspirine, metformine, statines, bêtabloquants, comme traitements du cancer, parce qu'ils sont sûrs, disponibles et parfois efficaces.",
  "dual-payload-adc": "Un ADC à double charge est un ADC qui transporte deux poisons différents à la fois, de sorte que la tumeur ne peut pas s'échapper en devenant résistante à l'un d'eux.",
  dxd: "DXd est le poison de la topoisomérase contenu dans Enhertu et Dato-DXd : environ dix fois plus puissant que SN-38, il diffuse vers les cellules voisines et quitte rapidement l'organisme une fois libéré.",
  eanm: "La société européenne de médecine nucléaire, dont le congrès et les recommandations ont façonné l'adoption clinique de la TEP au PSMA et de la thérapie par radioligand au lutétium, qui a commencé dans des centres européens.",
  "ebv-term": "Le virus courant de la mononucléose, porté toute la vie par la plupart des adultes, qui chez une minorité de personnes provoque le cancer du nasopharynx, certains cancers de l'estomac et plusieurs lymphomes.",
  ecco: "La fédération basée à Bruxelles des sociétés européennes d'oncologie et des associations de patients qui porte la voix de toute la communauté du cancer sur les questions de politique.",
  "edinburgh-cancer-centre": "Le centre de cancérologie d'Édimbourg au Western General, soutenu par l'Institute of Genetics and Cancer de l'université et connu pour ses recherches sur le cancer du sein, la génétique du cancer colorectal et les tumeurs cérébrales.",
  "egfr-mutation-subtypes": "Les cancers du poumon porteurs d'une mutation du gène EGFR sont traités par des comprimés anti-EGFR, mais le choix du comprimé et son efficacité dépendent de l'emplacement exact de la mutation. Les délétions de l'exon 19 et L858R sont les mutations sensibles « classiques » ; les insertions de l'exon 20 résistent à la plupart des comprimés ; T790M et C797S apparaissent lorsque la résistance se développe.",
  eha: "La société européenne d'hématologie, dont le congrès de juin est la deuxième tribune mondiale pour les essais sur les cancers du sang et dont les recommandations et le programme de formation façonnent l'hématologie européenne.",
  eisai: "Laboratoire pharmaceutique japonais qui fabrique lenvatinib (Lenvima), une option de première ligne dans le cancer du foie et un partenaire du pembrolizumab dans plusieurs tumeurs.",
  elacestrant: "Elacestrant a été le premier dégradeur oral du récepteur des œstrogènes (2023), pour le cancer du sein avec mutation ESR1 détectée par test sanguin.",
  elekta: "Elekta est l'entreprise suédoise de radiothérapie à l'origine d'Unity, le principal MR-linac, et du Gamma Knife.",
  "eln-risk": "Le système à trois niveaux (favorable, intermédiaire, défavorable) qui détermine l'intensité du traitement d'un adulte atteint d'AML et si une greffe est recommandée.",
  elranatamab: "Elranatamab est l'anticorps bispécifique anti-BCMA de Pfizer, administré sous la peau chaque semaine puis toutes les deux semaines, pour le myélome après quatre lignes de traitement antérieures.",
  "embl-ebi": "L'institut public européen de données pour la biologie moléculaire, qui gère Ensembl, ChEMBL, Europe PMC, l'European Genome-phenome Archive et Open Targets.",
  "emil-frei": "Avec Emil Freireich, il a montré que des associations de médicaments pouvaient guérir la leucémie de l'enfant, puis a étendu l'idée au lymphome de Hodgkin et au traitement adjuvant après la chirurgie.",
  "emil-freireich": "Au NCI, au début des années 1960, lui et Emil Frei ont donné aux enfants quatre médicaments à la fois, le VAMP, malgré une opposition féroce, et ont transformé une leucémie toujours mortelle en une maladie curable. Il a aussi mis au point la transfusion de plaquettes.",
  "emory-winship": "Le seul centre de cancérologie complet du NCI en Géorgie, leader des essais sur le myélome multiple et le cancer du poumon avec mutation EGFR.",
  "endometrial-molecular-classes": "Quatre groupes définis par quelques tests qui prédisent l'évolution mieux que le microscope : POLE muté (excellent), déficient en réparation des mésappariements, p53 anormal (le pire) et 'sans profil moléculaire spécifique'.",
  endoscopy: "Regarder à l'intérieur d'un organe creux avec une caméra fixée sur un tube souple, prélever des biopsies et parfois traiter sur place.",
  endpoint: "Le résultat précis qu'un essai est conçu pour mesurer, fixé à l'avance : par exemple la durée de survie des patients, ou le délai avant que leur cancer progresse. Un essai « atteint son critère principal » lorsque le nouveau traitement bat le traitement de comparaison sur cette mesure.",
  "enteral-parenteral-nutrition": "Le soutien nutritionnel consiste à alimenter par sonde dans l'intestin, ou par voie veineuse quand l'intestin ne peut pas être utilisé. Il sauve la vie chez le bon patient, et il est nuisible ou inutile chez le mauvais.",
  entrectinib: "Entrectinib (Rozlytrek) est un comprimé pour les cancers à fusion NTRK et le cancer du poumon ROS1 qui atteint les métastases cérébrales.",
  epigenetics: "La thérapie épigénétique et transcriptionnelle modifie la façon dont les gènes sont lus, plutôt que les gènes eux-mêmes.",
  "epro-symptom-monitoring": "Les patients signalent leurs symptômes chaque semaine via une application ou un formulaire web, et des infirmières répondent aux alertes. Des essais randomisés ont montré que ce système simple améliorait la qualité de vie, réduisait les passages aux urgences et, dans un essai, prolongeait la survie de cinq mois.",
  "eras-perioperative-nutrition": "Au lieu de laisser les patients à jeun avant et après une opération, les parcours chirurgicaux modernes les alimentent tôt, leur donnent des boissons glucidiques la veille et les font marcher dès le lendemain. Les complications et la durée d'hospitalisation diminuent.",
  erdafitinib: "Le premier comprimé de thérapie ciblée pour le cancer de la vessie, destiné aux quelque 20 % de tumeurs porteuses d'altérations de FGFR3, utilisé après l'immunothérapie.",
  esgo: "La société européenne d'oncologie gynécologique, dont les recommandations communes avec l'ESTRO et l'ESP et le programme d'accréditation des centres fixent les normes européennes de prise en charge des cancers de l'ovaire, du col de l'utérus et de l'endomètre.",
  "esmo-guidelines": "Les recommandations de l'ESMO sont les algorithmes de traitement de l'Europe, et l'ESMO-MCBS note à quel point chaque nouveau médicament aide réellement.",
  "esr1-mutation": "Une modification du gène du récepteur des œstrogènes qui permet au cancer de croître sans œstrogènes, de sorte que les inhibiteurs de l'aromatase cessent d'agir. Elle est retrouvée dans le sang chez environ un tiers des patientes après hormonothérapie.",
  esso: "La société européenne d'oncologie chirurgicale, qui organise le congrès et les cours de l'ESSO et définit le cursus et l'examen européens des chirurgiens oncologues.",
  "etop-ibcsg": "La fondation basée à Berne qui réunit l'International Breast Cancer Study Group (SOFT, TEXT, POSITIVE) et l'European Thoracic Oncology Platform.",
  "euramos-1": "Le plus grand essai jamais mené sur l'ostéosarcome, à travers quatre groupes coopérateurs sur deux continents. Ni l'ajout d'interféron chez les bons répondeurs ni l'ajout d'ifosfamide et d'étoposide chez les mauvais répondeurs n'a amélioré les résultats, de sorte que la chimiothérapie MAP à trois médicaments est restée la norme et que le domaine s'est tourné vers une nouvelle biologie.",
  "ev-302": "A presque doublé la survie dans le cancer de la vessie avancé, mettant fin à 40 ans de chimiothérapie à base de platine comme traitement de référence.",
  "exact-sciences": "Exact Sciences fabrique Cologuard et Oncotype DX et lance Cancerguard MCED et Oncodetect MRD ; elle est en cours d'acquisition par Abbott pour 21 milliards de dollars.",
  "exercise-during-chemotherapy": "Une activité physique modérée pendant la chimiothérapie est sans danger et réduit la fatigue, aide les patients à recevoir toutes les doses prévues et pourrait protéger le cœur et les nerfs.",
  "extrinsic-apoptosis-death-receptors": "Les cellules immunitaires tuent par contact : elles présentent le ligand de FAS ou TRAIL à une cellule cible, dont les récepteurs de mort déclenchent alors l'autodestruction de l'extérieur vers l'intérieur. Les tumeurs coupent ce fil en supprimant les récepteurs ou en surproduisant des leurres et des bloqueurs.",
  "fap-2286": "Un couple théranostique ciblant FAP : une version permet d'imager presque n'importe quelle tumeur solide, l'autre la traite par irradiation.",
  "fda-approvals": "Les notifications d'approbation en oncologie de la FDA constituent le registre officiel de ce qui est approuvé, et pour quoi.",
  "ferroptosis-cell-death": "Les cellules peuvent mourir de plusieurs façons programmées. Au-delà de l'apoptose classique, la ferroptose tue par oxydation des graisses entraînée par le fer, et les cellules cancéreuses mésenchymateuses résistantes aux médicaments s'avèrent y être particulièrement sensibles.",
  "fertility-preservation": "Préserver la capacité d'avoir des enfants avant un traitement anticancéreux qui endommage les ovules, les spermatozoïdes ou l'utérus : congélation de sperme et d'ovocytes ou d'embryons, congélation de tissu ovarien, protection des ovaires et, pour certains cancers du sein, suppression ovarienne temporaire.",
  "fgfr-signalling": "Les récepteurs du facteur de croissance des fibroblastes sont des antennes de croissance à la surface des cellules. Le cancer de la vessie mute FGFR3, le cancer des voies biliaires fusionne FGFR2 à d'autres gènes et le cancer de l'estomac surproduit FGFR2b ; chacun a son propre médicament, et chacun s'accompagne d'un effet secondaire révélateur (phosphate élevé) parce que les mêmes récepteurs contrôlent le phosphate dans le rein.",
  "field-cancerisation": "Le cancer naît souvent de toute une région de tissu déjà porteuse de mutations, et non d'une seule cellule déviante. La peau exposée au soleil, les voies respiratoires des fumeurs et l'œsophage de Barrett sont des mosaïques de clones mutants en compétition bien avant l'apparition d'une tumeur.",
  "financial-toxicity": "Le préjudice causé aux patients par le coût des soins contre le cancer : épargne épuisée, dettes, médicaments non pris et survie moins bonne. Il se mesure comme n'importe quel autre effet secondaire et, de plus en plus, se traite comme tel.",
  "flash-rt": "Délivrer la dose entière en moins d'une seconde, ce qui, chez l'animal, épargne les tissus sains tout en tuant la tumeur.",
  flaura2: "L'ajout d'une chimiothérapie à l'osimertinib a prolongé à la fois la survie sans progression et, en 2025, la survie globale.",
  flot: "FLOT est la chimiothérapie à quatre médicaments administrée avant et après la chirurgie du cancer de l'estomac en Occident ; depuis 2025, on y ajoute une immunothérapie.",
  "flow-cytometry-mrd": "La MRD par cytométrie en flux compte les cellules leucémiques de la moelle osseuse une par une d'après leurs protéines de surface, jusqu'à une sur dix mille.",
  "fmt-checkpoint-nonresponders": "Transplanter les bactéries intestinales de patients ayant répondu à l'immunothérapie chez ceux qui n'ont pas répondu. Dans de petites études, une minorité de mélanomes résistants a commencé à répondre. Des essais randomisés sont en cours.",
  "fmt-pd1-refractory-melanoma-pitt": "Quinze patients atteints de mélanome dont l'immunothérapie avait échoué ont reçu une transplantation de selles provenant d'une personne chez qui l'immunothérapie avait fonctionné, puis ont repris le médicament. Six d'entre eux en ont bénéficié, dont trois avec des réponses durables.",
  folfiri: "FOLFIRI est l'autre chimiothérapie de base du cancer de l'intestin, remplaçant l'oxaliplatine par l'irinotécan. Utilisée en première ou en deuxième ligne et, depuis 2026, avec la combinaison BRAF.",
  folfirinox: "FOLFIRINOX est une association de chimiothérapie à quatre médicaments qui, en 2011, est devenue le premier traitement à prolonger réellement la vie dans le cancer du pancréas métastatique ; c'est aujourd'hui le standard avant et après la chirurgie.",
  "folfox-family": "Les recettes standard de chimiothérapie pour les cancers de l'intestin et du pancréas, nommées d'après leurs ingrédients : FOL (acide folinique) + F (5-fluorouracile) + OX (oxaliplatine), IRI (irinotécan), ou les deux (FOLFIRINOX). CAPOX remplace la perfusion de 5-FU par des comprimés de capécitabine.",
  "foundation-medicine": "Fabricant du test génomique FoundationOne CDx, approuvé par la FDA et utilisé dans des dizaines de notices de médicaments.",
  fruquintinib: "Un comprimé découvert en Chine qui bloque les récepteurs des vaisseaux sanguins, approuvé en 2023 pour le cancer de l'intestin après tous les traitements standards.",
  fulvestrant: "Fulvestrant est une injection mensuelle qui détruit le récepteur des œstrogènes ; c'est le partenaire standard de nombreux médicaments ciblés lorsque l'hormonothérapie cesse de fonctionner.",
  fuscc: "Le Fudan University Shanghai Cancer Center est le premier centre du cancer du sein en Chine et le lieu de la première imagerie PET de TROP2 chez l'humain.",
  "g-ba-iqwig": "L'organe décisionnel allemand qui détermine ce que l'assurance maladie obligatoire prend en charge (G-BA) et l'institut qui évalue le bénéfice ajouté des nouveaux médicaments (IQWiG), qui fixent ensemble les prix des médicaments anticancéreux dans le cadre du processus AMNOG.",
  "g-csf-growth-factors": "Des injections de filgrastim ou de sa forme à action prolongée, le pegfilgrastim, après la chimiothérapie accélèrent la récupération des globules blancs, réduisant le risque d'infections potentiellement mortelles et permettant de donner la chimiothérapie à la date prévue.",
  "garvan-institute": "L'un des principaux instituts de génomique d'Australie, dont le Kinghorn Cancer Centre, avec le St Vincent's, a été pionnier du traitement guidé par la génomique du cancer du pancréas et des tumeurs rares.",
  "gates-foundation": "La plus grande fondation privée du monde ; son action contre le cancer se concentre sur la vaccination contre le HPV et l'élimination du cancer du col de l'utérus dans les pays à revenu faible et intermédiaire.",
  "gbrca-mutation": "Une anomalie héréditaire du gène BRCA1 ou BRCA2, présente dans chaque cellule dès la naissance, qui augmente fortement le risque de cancer du sein, de l'ovaire, de la prostate et du pancréas et rend ces cancers sensibles aux inhibiteurs de PARP et au platine.",
  "gefitinib-chemo-tmh": "Un essai indien a montré que l'ajout d'une chimiothérapie standard au comprimé bon marché de première génération gefitinib doublait la durée pendant laquelle le cancer du poumon restait contrôlé et réduisait les décès de plus de moitié.",
  gemcitabine: "Une chimiothérapie polyvalente utilisée dans les cancers du pancréas, de la vessie, du poumon, de l'ovaire, du sein et des voies biliaires, dans le cancer du nasopharynx, et en instillation vésicale.",
  "gemtuzumab-ozogamicin": "Gemtuzumab ozogamicin (Mylotarg) fut le tout premier ADC : approuvé en 2000, retiré en 2010 pour toxicité, puis réapprouvé en 2017 à une dose fractionnée plus faible. Son histoire est à la fois un avertissement et une leçon.",
  genie: "AACR Project GENIE rassemble des données de séquençage tumoral en vie réelle partagées par de grands centres de cancérologie.",
  genmab: "Genmab est l'entreprise danoise d'ingénierie des anticorps à l'origine de la plateforme DuoBody, de Tivdak, d'Epkinly et (via ProfoundBio) de rinatabart sesutecan.",
  "genome-instability-mutation": "Les cancers mutent plus vite que les cellules normales parce que leur réparation du DNA et leur ségrégation des chromosomes sont défaillantes. Cela alimente toutes les autres caractéristiques du cancer.",
  "genomic-profiling": "Lire l'ADN (et parfois l'ARN) d'une tumeur pour dresser la liste des mutations qu'elle porte et les associer à des médicaments. C'est désormais la routine dans les cancers du poumon, colorectal, du sein, de la prostate et bien d'autres.",
  gilteritinib: "Un simple comprimé qui fait mieux que la chimiothérapie de rattrapage dans la LAM en rechute avec mutation de FLT3, et l'ossature des trithérapies actuellement testées en première ligne.",
  gimema: "Le groupe italien d'essais en hématologie de l'adulte, célèbre pour avoir rendu la leucémie aiguë promyélocytaire curable sans chimiothérapie et pour la LAL Philadelphie-positive sans chimiothérapie.",
  giredestrant: "Giredestrant est le SERD oral de Roche : il n'a pas réussi à battre un inhibiteur de l'aromatase en première ligne de la maladie métastatique, mais a réussi après la chirurgie et après l'échec des CDK4/6.",
  glenmark: "L'entreprise indienne dont l'anticorps trispécifique ISB 2001 contre le myélome multiple a été licencié à AbbVie en 2025 pour 700 millions de dollars d'avance, le plus gros accord pour un médicament anticancéreux découvert en Inde.",
  globocan: "GLOBOCAN, ce sont les chiffres mondiaux du cancer : des estimations d'incidence et de mortalité pour 185 pays et 36 cancers.",
  "glycaemic-index": "La vitesse à laquelle un aliment fait monter la glycémie (index) et de combien, selon la portion (charge). Les régimes à charge glycémique élevée sont faiblement associés à certains cancers, en grande partie via l'obésité et l'insuline.",
  "great-ormond-street": "L'hôpital pour enfants de Londres, où des cellules CAR-T « universelles » génétiquement modifiées ont été administrées pour la première fois à un enfant atteint de leucémie.",
  "growth-signal": "L'instruction qu'une cellule reçoit pour croître et se diviser. Les cellules normales l'attendent ; les cellules cancéreuses la simulent, si bien qu'elles continuent à se diviser que le corps en veuille davantage ou non.",
  gsk: "GSK fabrique Jemperli, Zejula et Blenrep, l'ADC contre le myélome approuvé à deux reprises.",
  "guangdong-provincial-peoples-hospital": "Siège du Guangdong Lung Cancer Institute, où le groupe de Yi-Long Wu a mené les essais qui ont fait du cancer du poumon avec mutation d'EGFR une maladie relevant de la thérapie ciblée en Asie.",
  "gut-microbiome-diversity": "Combien de types différents de bactéries vivent dans l'intestin et lesquelles dominent. Une plus grande diversité et certaines espèces sont associées à une meilleure réponse à l'immunothérapie ; les antibiotiques et une mauvaise alimentation réduisent les deux.",
  "guys-st-thomas": "Le centre de cancérologie du sud de Londres, avec le King's College London, fort en cancer du sein et de la prostate, en radiothérapie et dans de grands essais de dépistage tels que NHS-Galleri.",
  h3k27m: "Une seule modification d'une protéine histone qui définit le gliome diffus de la ligne médiane, la tumeur cérébrale de l'enfant offrant le moins d'options thérapeutiques, et désormais la cible du premier médicament approuvé contre elle.",
  hadassah: "L'hôpital universitaire de Jérusalem et son Institut d'oncologie Sharett, connus pour leur CAR-T produit en interne, la recherche sur les mutations fondatrices de BRCA et l'immunothérapie du mélanome.",
  "hallmarks-of-cancer": "Les Hallmarks of Cancer sont le cadre le plus cité en biologie du cancer : une courte liste des capacités que tout cancer doit acquérir, de la croissance illimitée à la dissimulation face au système immunitaire. La mise à jour de 2022 recense huit caractéristiques, deux caractéristiques facilitatrices et quatre nouvelles dimensions.",
  "harald-zur-hausen": "À l'encontre du consensus qui accusait l'herpès, il a proposé en 1976 que les papillomavirus causent le cancer du col de l'utérus et a isolé HPV16 et HPV18 à partir de tumeurs en 1983-84, rendant possibles la vaccination et le dépistage par test HPV. Prix Nobel 2008.",
  "harmoni-a": "La première victoire de phase 3 de l'ivonescimab, dans le cancer du poumon qui ne répond plus aux comprimés anti-EGFR, et le fondement de sa première approbation en Chine.",
  "has-france": "L'autorité française d'évaluation des technologies de santé, dont la Commission de la Transparence évalue le bénéfice clinique ajouté de chaque nouveau médicament anticancéreux et fixe ainsi son prix et son remboursement.",
  "hcc-surveillance": "Les personnes atteintes de cirrhose ou d'hépatite B chronique passent une échographie du foie et une analyse de sang tous les six mois afin que le cancer soit détecté alors qu'il est encore curable.",
  "helsinki-hus": "Le plus grand centre de cancérologie de Finlande et un centre de cancérologie intégré accrédité par l'OECI, connu pour la génétique des cancers héréditaires et la médecine de précision fonctionnelle dans la leucémie.",
  "her2-brain-metastases": "Jusqu'à la moitié des femmes atteintes d'un cancer du sein métastatique HER2-positif développent des métastases cérébrales, parce que les anticorps contrôlent le corps mais, historiquement, pas le cerveau.",
  "her2-pet": "HER2 PET est un examen TEP utilisant du trastuzumab radiomarqué ou des ligands de HER2 plus petits pour cartographier HER2 dans toutes les métastases à la fois.",
  "her2-positive": "Un cancer présentant un excès de la protéine de signal de croissance HER2, soit avec un score de 3+ à la coloration, soit avec des copies supplémentaires du gène démontrées. Autrefois le sous-type de cancer du sein le plus agressif, il figure aujourd'hui parmi les plus traitables grâce aux médicaments anti-HER2.",
  "her2-testing-assays": "Les tests qui gradent le niveau de HER2 d'un cancer du sein ou de l'estomac, du test initial pour le trastuzumab en 1998 aux nouveaux seuils 'HER2-low' et 'ultralow'.",
  her2climb: "Le premier essai à prouver qu'un médicament aide dans les métastases cérébrales HER2-positives, en prolongeant la survie globale de quatre mois et demi.",
  "herizon-gea-01": "Un anticorps anti-HER2 à deux bras a battu Herceptin en comparaison directe comme traitement de première ligne du cancer de l'estomac HER2-positif, la première victoire de ce type depuis 2010.",
  hhmi: "L'organisation philanthropique américaine qui finance des scientifiques plutôt que des projets ; beaucoup des biologistes du cancer à l'origine des suppresseurs de tumeurs, de la détection de l'hypoxie et de CRISPR sont chercheurs HHMI.",
  "histologic-transformation": "Lorsqu'un adénocarcinome du poumon échappe à la thérapie ciblée en se transformant en un autre type cellulaire, généralement à petites cellules.",
  histology: "L'étude des tissus au microscope. L'histologie d'un cancer, c'est le type de cellules qui le composent et la façon dont elles sont organisées, ce qui permet au pathologiste de le nommer et de le grader.",
  "homi-bhabha-cancer-hospital-varanasi": "Les deux hôpitaux du Tata Memorial Centre à Varanasi apportent une prise en charge complète du cancer à la plaine du Gange, l'une des régions de l'Inde les moins desservies et les plus touchées par les cancers de la bouche, du col de l'utérus et de la vésicule biliaire.",
  "hormone-receptor-status": "Si les cellules d'un cancer du sein portent des récepteurs aux œstrogènes (ER) et à la progestérone (PR). Si oui, le cancer est nourri par ces hormones et peut être traité en les bloquant ; environ 70 % des cancers du sein sont positifs pour les récepteurs hormonaux.",
  "hormone-therapy": "Traitement qui affame les cancers qui grandissent en réponse à une hormone, principalement les œstrogènes dans le cancer du sein et la testostérone dans le cancer de la prostate, en abaissant l'hormone ou en bloquant son récepteur.",
  "hospital-del-mar": "L'hôpital universitaire de Barcelone en bord de mer, dont l'institut de recherche, dirigé par Joaquín Arribas, est à la pointe de la biologie de HER2 et des CAR-T contre le cancer du sein.",
  "hospital-information-systems-oncology": "Les systèmes de prescription et de dossiers que les oncologues utilisent chaque jour, y compris les parcours de traitement intégrés qui orientent le choix des médicaments.",
  hovon: "Le groupe néerlando-belge d'essais en hématologie de l'adulte, l'un des plus grands moteurs européens d'essais de phase 3 dans la leucémie, le myélome et le lymphome.",
  "hpv-p16": "Cancers de la gorge causés par le papillomavirus humain, identifiés par un marquage p16. Ils touchent des non-fumeurs plus jeunes et sont bien plus curables que les cancers liés au tabac.",
  "hpv-status": "Le fait qu'un cancer soit ou non causé par le papillomavirus humain. Les cancers de la gorge HPV-positifs sont une maladie différente, bien plus curable que ceux liés au tabac, et l'ADN du virus dans le sang permet de suivre le cancer.",
  "hrd-testing": "Des tests qui révèlent si une tumeur a un système de réparation de l'ADN défaillant, ce qui prédit la réponse aux inhibiteurs de PARP et au platine.",
  "hug-geneva": "L'hôpital universitaire de Genève, partenaire du Swiss Cancer Center Léman et l'un des premiers centres européens de CAR-T dans les tumeurs cérébrales.",
  humanitas: "Un hôpital de recherche milanais connu pour les travaux d'Alberto Mantovani sur les macrophages associés aux tumeurs et pour ses essais de radiothérapie stéréotaxique et de cancer du foie.",
  huntsman: "Le centre complet du NCI de la région des montagnes de l'Ouest américain, bâti sur la base de données de population de l'Utah reliée aux généalogies, qui a aidé à découvrir BRCA1 et d'autres gènes de cancer héréditaire.",
  hyperthermia: "L'hyperthermie chauffe les tumeurs à 40-43 °C pour que la radiothérapie et la chimiothérapie agissent mieux.",
  hypofractionation: "Administrer la radiothérapie en un nombre réduit de séances quotidiennes plus fortes (fractions), de sorte qu'un traitement dure une à trois semaines au lieu de cinq à sept, avec une guérison et des effets secondaires équivalents pour de nombreux cancers. Le confort, le coût et la capacité des machines s'en trouvent tous améliorés.",
  iaea: "Le programme de l'agence nucléaire de l'ONU pour apporter la radiothérapie et la médecine nucléaire aux dizaines de pays qui n'ont pas ou trop peu d'appareils de traitement.",
  "iarc-india-hpv-dose-study": "Lorsqu'un essai vaccinal indien a été interrompu à mi-parcours, des milliers de filles n'avaient reçu qu'une seule dose ; leur suivi pendant dix ans a montré qu'une dose protégeait aussi bien que trois, ce qui a changé la politique vaccinale mondiale.",
  iaslc: "La seule société mondiale consacrée aux cancers du poumon et du thorax, dont la World Conference on Lung Cancer et le projet de stadification TNM définissent le domaine.",
  "icmr-ncrp": "Le programme qui recense le cancer en Inde : des registres de population et hospitaliers dont les rapports fournissent au pays ses estimations officielles de nouveaux cas, des cancers les plus fréquents et du stade au diagnostic.",
  "idea-ai-her2-low-scoring": "Les pathologistes ne s'accordent pas sur le marquage faible de HER2, et pourtant cette décision ouvre l'accès à Enhertu. Laissons un algorithme validé faire le comptage.",
  "idea-bio2-antigen-presentation-triage": "Certaines tumeurs ont détruit la machinerie qui affiche leur identité aux cellules immunitaires. Ces patients ne peuvent pas bénéficier de la plupart des immunothérapies et devraient être orientés vers d'autres options.",
  "idea-bio2-brain-met-prevention-trials": "Certains cancers atteignent le cerveau chez jusqu'à un quart des patients. Des essais de prévention pourraient viser spécifiquement à empêcher cela, plutôt que de le traiter une fois survenu.",
  "idea-bio2-ctdna-six-week-io-switch": "Les examens d'imagerie à trois mois ne permettent souvent pas de savoir si l'immunothérapie fonctionne. Un test sanguin à six semaines pourrait donner une réponse plus claire et plus précoce.",
  "idea-bio2-epigenetic-priming-cold-tumours": "De faibles doses de médicaments qui modifient la façon dont l'ADN est compacté peuvent amener les cellules cancéreuses à afficher davantage ce qui les signale comme anormales, ce qui pourrait réveiller l'immunothérapie dans les tumeurs froides.",
  "idea-bio2-io-biomarker-data-commons": "Des dizaines d'essais ont recueilli des données immunitaires, génomiques et d'imagerie sur les mêmes médicaments. Personne ne peut les analyser ensemble, et la réponse reste donc cachée en fragments.",
  "idea-bio2-localise-the-mrd": "Un test sanguin positif indique que le cancer est revenu, mais pas où. Associer l'IRM du corps entier aux traceurs PET modernes pourrait révéler un foyer unique que l'on peut détruire.",
  "idea-bio2-mechanism-defined-baskets": "Les cancers rares partagent souvent la même machinerie cellulaire défaillante, même lorsqu'ils naissent dans des organes différents. Regrouper les patients selon ce défaut commun rend les essais possibles.",
  "idea-bio2-mrd-triggered-neoantigen-vaccine": "Les vaccins anticancéreux personnalisés demandent des semaines de fabrication et marchent mieux quand il reste très peu de maladie. En fabriquer un au moment de la chirurgie et l'administrer quand un test sanguin devient positif répond à ces deux réalités.",
  "idea-bio2-neoadjuvant-biomarker-engine": "Administrer une immunothérapie pendant quelques semaines avant la chirurgie fournit un échantillon tumoral qui montre exactement ce que le médicament a fait. C'est le moyen le plus rapide d'apprendre qui répond.",
  "idea-bio2-oncolytic-regulated-il12": "L'interleukine-12 est l'un des stimulants immunitaires les plus puissants, mais elle est trop toxique pour être injectée dans la circulation sanguine. Un virus peut être conçu pour la produire uniquement à l'intérieur d'une tumeur.",
  "idea-bio2-paediatric-first-development": "Les enfants attendent des années pour obtenir des médicaments parce que les essais chez l'adulte passent d'abord, même lorsque la cible relève d'un cancer de l'enfant. Certains médicaments devraient commencer par les enfants.",
  "idea-bio2-rare-cancer-umbrella-platform": "Les cancers rares représentent ensemble un cinquième de tous les cancers, mais chacun est trop petit pour avoir son propre essai. Un essai permanent à plusieurs bras leur donnerait à tous une voie d'accès.",
  "idea-bio2-spatial-signature-cdx": "Le fait que les cellules immunitaires soient à côté des cellules cancéreuses compte plus que leur nombre. Transformer cette image spatiale en un test fiable et standardisé permettrait de mieux prédire la réponse.",
  "idea-bio2-transferrin-shuttle-adc": "Le cerveau possède des portes de transport naturelles pour le fer. Y attacher une clé qui s'adapte à ces portes permet de faire passer en douce de grosses molécules de médicament, une astuce qui fonctionne désormais dans des traitements de la maladie d'Alzheimer.",
  "idea-bio2-whole-genome-mrd-depth": "Les tests sanguins actuels manquent le cancer résiduel chez de nombreux patients. Lire des milliers de mutations à la fois, plutôt que quelques dizaines, permet de détecter des quantités bien plus faibles.",
  "idea-ctdna-switch-generalised": "SERENA-6 a montré que l'on peut agir sur un test sanguin avant que l'imagerie ne change. La même logique pourrait s'appliquer aux mutations de PIK3CA, AKT1 ou HER2 qui apparaissent sous traitement.",
  "idea-data-computable-living-guidelines": "Les recommandations de traitement du cancer seraient mises à jour en continu et publiées dans un format lisible par les ordinateurs, afin que les systèmes hospitaliers, les applications et les outils d'aide à la décision se mettent à jour d'eux-mêmes le jour où les preuves changent.",
  "idea-data-structured-genomic-reports": "Les résultats des tests génétiques des tumeurs sont pour la plupart des PDF. Obliger les laboratoires à envoyer aussi une version lisible par ordinateur à un dépôt national, afin de relier les variants aux traitements qui ont fonctionné.",
  "idea-exercise-as-adjuvant": "L'essai CHALLENGE a montré qu'un programme d'exercice supervisé améliore la survie dans le cancer du côlon. L'étendre aux cancers du sein, de la prostate et du poumon avec la même rigueur.",
  "idea-ferroptosis-persisters": "Les cellules qui survivent à la thérapie ciblée changent de forme et deviennent anormalement dépendantes d'une enzyme antioxydante, GPX4. Les frapper dans cette fenêtre pourrait stopper la résistance avant qu'elle n'évolue.",
  "idea-fund-academic-radiopharma-pipeline": "La plupart des nouveaux agents d'imagerie du cancer et des médicaments radioactifs naissent dans les hôpitaux universitaires. Un réseau partageant la production, les dossiers qualité et les démarches réglementaires les amènerait aux essais multicentriques des années plus tôt.",
  "idea-fund-adaptive-radiotherapy-evidence": "Les appareils de radiothérapie qui s'adaptent chaque jour à la tumeur coûtent bien plus cher que les appareils standard et leur bénéfice n'est pas prouvé. Les payeurs ne les financeraient que dans le cadre de registres et d'essais mesurant s'ils aident réellement.",
  "idea-fund-burden-weighted-portfolio": "Les financeurs publieraient la comparaison entre leurs dépenses et les décès et années de vie perdues pour chaque cancer, et s'engageraient à déplacer chaque année une part fixe de l'argent vers les plus grands écarts.",
  "idea-fund-device-technique-registry": "Les nouvelles opérations et les dispositifs chirurgicaux se répandent par enthousiasme, pas par les preuves. Chaque nouvelle technique devrait être inscrite dans un registre qui suit les patients à travers des étapes définies avant de pouvoir être largement utilisée et remboursée.",
  "idea-fund-lmic-burden-match": "Sept décès par cancer sur dix surviennent dans les pays les plus pauvres, mais presque tous les essais ont lieu dans les pays riches. Les financeurs s'engageraient à consacrer une part des fonds à des essais conçus et dirigés là où se trouve le fardeau.",
  "idea-fund-metastasis-moonshot": "Les métastases causent environ neuf décès par cancer sur dix mais ne reçoivent qu'une petite part des fonds de recherche. Cette proposition réserverait un dixième des budgets nationaux de recherche sur le cancer à la biologie et aux essais portant sur la dissémination elle-même.",
  "idea-fund-nonprofit-pharma": "Créer une société pharmaceutique qui n'a pas besoin de profits, sur le modèle de celles qui ont développé de nouveaux médicaments contre la tuberculose et la maladie du sommeil, pour s'attaquer aux cancers rares, pédiatriques et sans cible médicamenteuse.",
  "idea-fund-organ-preservation-programme": "Pour certains cancers, les médicaments et la radiothérapie peuvent désormais guérir sans enlever l'organe, épargnant aux patients une stomie, la perte de la voix ou l'ablation de la vessie. Un programme dédié mènerait les essais pour prouver où cela est sûr.",
  "idea-fund-payer-funded-pragmatic-trials": "Les assureurs santé et les systèmes de santé nationaux ont toutes les raisons de savoir si la moitié de la dose ou la moitié de la durée d'un médicament coûteux marche aussi bien. Ils financeraient directement ces essais et garderaient les économies.",
  "idea-fund-precompetitive-undruggable-consortium": "Les entreprises et les financeurs publics mettraient en commun argent et scientifiques pour percer les protéines cancéreuses les plus difficiles, comme MYC et p53 mutée, en partageant tout ouvertement jusqu'à l'obtention d'un véritable candidat médicament, puis en se faisant concurrence sur le produit final.",
  "idea-fund-proton-coverage-with-evidence": "La protonthérapie coûte bien plus cher que la radiothérapie standard et, pour la plupart des cancers de l'adulte, personne ne sait si elle est meilleure. Les payeurs ne la couvriraient qu'au sein d'essais ou de registres qui répondent à cette question, dans tous les centres à la fois.",
  "idea-fund-public-car-t-manufacturing": "Les hôpitaux universitaires peuvent déjà fabriquer des cellules CAR-T pour une fraction du prix commercial. Un réseau public étendrait cela pour que davantage de patients puissent être traités pour moins cher.",
  "idea-fund-radiotherapy-trials-infrastructure": "Les essais de radiothérapie ont besoin de physiciens pour vérifier chaque plan et d'une relecture centralisée de chaque volume cible contouré, ce que personne ne finance. Financer cette infrastructure de façon permanente pour que les essais soient plus rapides et les résultats fiables.",
  "idea-fund-rt-io-platform": "La radiothérapie pourrait rendre l'immunothérapie plus efficace, mais les essais pour le vérifier sont dispersés et souvent de petite taille. Une plateforme commune, gérée par des groupes de radiothérapie avec des médicaments fournis par plusieurs entreprises, trancherait la question plus vite.",
  "idea-fund-surgical-trials-network": "La chirurgie guérit plus de cancers que n'importe quel médicament, et pourtant la plupart des opérations n'ont jamais été comparées dans un essai en bonne et due forme. Un réseau permanent d'hôpitaux, doté d'un financement de base, mènerait ces essais en continu.",
  "idea-fund-translational-institutes-gmp": "Construire une poignée de centres financés par des fonds publics où les découvertes académiques peuvent être fabriquées à un niveau clinique et documentées pour les régulateurs, afin que les bonnes idées ne meurent pas faute d'usine et de dossier.",
  "idea-fund-trial-data-trust": "Les données anonymisées au niveau des patients de chaque essai sur le cancer iraient dans un dépôt de confiance unique dans les dix-huit mois suivant la fin de l'essai, avec un seul comité d'accès, afin que les chercheurs puissent réanalyser, regrouper et tirer des enseignements d'essais qui restent aujourd'hui sous clé.",
  "idea-immune-exclusion-drivers": "Dans de nombreuses tumeurs, les cellules immunitaires sont présentes mais ne peuvent pas entrer. Si nous connaissions la barrière dominante, nous pourrions ouvrir la porte et faire marcher l'immunothérapie chez plus de gens.",
  "idea-multimodal-foundation-model": "Entraîner une seule IA sur les imageries, les lames, la génomique et les résultats de nombreux patients pour qu'elle puisse prédire, pour un nouveau patient, quel traitement fonctionnera.",
  "idea-nl-alcohol-minimum-pricing-cancer-endpoints": "L'Écosse et le pays de Galles ont fixé un prix plancher pour l'alcool. Les décès par maladie du foie ont déjà baissé. Le cancer met plus de temps à se manifester, il faut donc que quelqu'un continue de mesurer pendant une décennie.",
  "idea-nl-antioxidant-supplement-harm-confirmation": "La moitié des patients prennent des vitamines antioxydantes pendant la chimiothérapie. Une bonne étude observationnelle suggère qu'elles augmentent les récidives de 40%. Les patients méritent une réponse définitive, et on peut l'obtenir à peu de frais en ajoutant le suivi des compléments aux essais déjà en cours.",
  "idea-nl-bariatric-cancer-registry-linkage": "Des millions de personnes ont subi une chirurgie de l'obésité ou prennent aujourd'hui des médicaments amaigrissants. Relier ces dossiers aux registres du cancer montrerait, cancer par cancer, dans quelle mesure inverser l'obésité protège, pour un coût quasi nul.",
  "idea-nl-diet-covariates-io-trials": "Les bactéries intestinales semblent influencer l'efficacité de l'immunothérapie, et l'alimentation et les antibiotiques façonnent ces bactéries. Pourtant, presque aucun essai de médicament ne consigne ce que les patients ont mangé ni quels antibiotiques ils ont pris. Le consigner ne coûterait presque rien.",
  "idea-nl-dietitian-in-every-mdt": "La dénutrition est la complication non traitée la plus fréquente dans les cancers de l'intestin, de la gorge et du pancréas. Mettre un diététicien dans la réunion où le traitement est décidé permet de la repérer et de la traiter avant le début de la chimiothérapie, et non après que le poids a été perdu.",
  "idea-nl-exercise-dose-finding": "CHALLENGE a prouvé que l'exercice fonctionne dans le cancer du côlon, mais pas quelle quantité est nécessaire. Un essai comparant des doses, comme on le ferait pour un médicament, dirait aux systèmes de santé ce qu'il faut financer.",
  "idea-nl-glp1-adjuvant-hr-breast": "La perte de poids par accompagnement n'a pas clairement réduit les récidives de cancer du sein dans BWEL, peut-être parce que la perte de poids était trop faible. Des médicaments produisant trois fois plus de perte de poids pourraient trancher la question de savoir si le poids lui-même compte.",
  "idea-nl-ketogenic-gbm-definitive-trial": "On vend aux patients atteints de tumeurs cérébrales des régimes cétogènes sur la foi de données chez la souris et de petites études de faisabilité. Un seul essai de puissance statistique suffisante, avec l'appui de diététiciens, le prouverait ou permettrait aux cliniciens de dire clairement que cela ne fonctionne pas.",
  "idea-payload-switching": "Quand un ADC échoue, le suivant devrait porter un poison d'un type différent, et pas seulement viser une autre protéine.",
  "idea-tr2-neoadjuvant-combo-platform": "Donner des combinaisons avant la chirurgie et regarder combien de tumeur il reste au moment de l'ablation. Cette réponse arrive en quelques mois, si bien que de nombreuses paires peuvent être testées rapidement.",
  "idea-tr2-smart-sequencing-adc": "Les patients sont randomisés à chaque point de décision, et pas seulement au départ, de sorte qu'un seul essai peut comparer des séquences de traitement entières plutôt que des médicaments isolés.",
  "idea-trop2-pet-selection": "Utiliser un examen TROP2 du corps entier plutôt qu'une seule coloration tissulaire pour décider quels patients reçoivent un ADC anti-TROP2, lequel, et quand changer.",
  "ieo-milan": "Fondé par Umberto Veronesi, pionnier de la chirurgie conservatrice du sein et de la biopsie du ganglion sentinelle.",
  ifct: "L'intergroupe français d'oncologie thoracique, qui a mené le programme national Biomarkers France montrant que le dépistage moléculaire systématique du cancer du poumon améliore la survie.",
  "ifinatamab-deruxtecan": "Ifinatamab deruxtecan est un ADC ciblant B7-H3 qui montre certains des meilleurs taux de réponse jamais observés dans le cancer du poumon à petites cellules en rechute.",
  ihc: "Colorer une coupe de tissu avec des anticorps pour qu'une protéine apparaisse en couleur au microscope.",
  "iit-bombay": "L'institut d'ingénierie dont le département de biosciences, avec le Tata Memorial, a mis au point la première thérapie cellulaire CAR-T conçue en Inde et l'a essaimée sous le nom d'ImmunoACT.",
  ild: "La pneumopathie interstitielle (ILD) est une inflammation du poumon, un effet secondaire grave de certains ADC (en particulier Enhertu) et de l'immunothérapie.",
  "imaging-core-labs": "Des radiologues indépendants qui relisent chaque examen d'imagerie d'un essai de la même manière, afin que les taux de réponse signifient la même chose d'un hôpital à l'autre.",
  "immune-checkpoint": "Des freins du système immunitaire qui empêchent les lymphocytes T d'attaquer les tissus sains. Les tumeurs actionnent ces freins pour se protéger ; les inhibiteurs de points de contrôle les relâchent pour que les lymphocytes T puissent attaquer le cancer.",
  "immune-system": "Le réseau de défense du corps, fait de cellules et de molécules, qui reconnaît et détruit les cellules infectées, étrangères et anormales. Il élimine la plupart des cancers en devenir avant même qu'on les remarque ; ceux qui survivent ont appris à s'en cacher.",
  "immuno-oncology": "Des traitements qui lèvent les freins du système immunitaire du patient pour qu'il attaque le cancer, principalement des anticorps contre PD-1, PD-L1 et CTLA-4. \"IO\" est le raccourci de l'industrie ; \"chimio-IO\" désigne la chimiothérapie associée à un inhibiteur de point de contrôle, l'association de première ligne la plus courante.",
  immunoact: "La spin-off de l'IIT Bombay qui a obtenu la première approbation d'une CAR-T en Inde en 2023 avec NexCAR19 et a traité plus de 600 patients au dixième des prix occidentaux.",
  "immunogenic-cell-death": "La mort cellulaire immunogène est une façon de mourir qui alerte le système immunitaire, contrairement à l'apoptose silencieuse.",
  "immunonutrition-perioperative": "Des boissons enrichies en arginine, en acides gras oméga-3 et en nucléotides, prises pendant une semaine avant une opération lourde, semblent réduire les infections postopératoires, même si les essais sont anciens et pour la plupart financés par l'industrie.",
  "immunotherapy-term": "Tout traitement qui agit en amenant le propre système immunitaire du patient à attaquer le cancer, plutôt qu'en attaquant directement le cancer. Il peut produire des réponses qui durent des années, mais seulement chez certains patients.",
  inavolisib: "Inavolisib est un médicament anti-PI3K qui détruit aussi la protéine mutante, approuvé en 2024 avec palbociclib et fulvestrant pour le cancer du sein porteur d'une mutation PIK3CA.",
  inca: "L'agence nationale du cancer de la France, qui pilote la stratégie nationale de lutte contre le cancer et finance et labellise la recherche, les réseaux d'essais et les unités de phase précoce.",
  "inca-brazil": "L'institut national du cancer du Brésil, organisme du ministère de la Santé qui gère la lutte contre le cancer, les registres et le dépistage pour le pays et soigne des patients dans ses hôpitaux de Rio.",
  "incan-mexico": "L'institut national du cancer du Mexique, hôpital fédéral de recours pour les patients atteints de cancer sans assurance et principal centre de recherche et de formation en oncologie du pays.",
  "incliva-valencia": "L'hôpital universitaire et institut de recherche de Valence, base de l'ancien président de l'ESMO Andrés Cervantes et d'un groupe de premier plan en oncologie digestive et mammaire.",
  incyte: "Incyte fabrique pemigatinib, le premier médicament ciblé approuvé pour le cancer des voies biliaires (2020), et l'inhibiteur de JAK ruxolitinib.",
  inhibitor: "Un médicament qui empêche une protéine précise de faire son travail, généralement en se logeant dans la poche dont la protéine a besoin pour fonctionner. La plupart des médicaments anticancéreux ciblés tirent leur nom de ce qu'ils inhibent.",
  innovent: "Innovent fabrique sintilimab, l'anticorps PD-1 le plus vendu de Chine, et est devenu une source d'actifs de nouvelle génération pour Roche et Takeda.",
  "inotuzumab-ozogamicin": "Inotuzumab ozogamicin est un anticorps qui transporte une toxine coupant l'ADN jusqu'à CD22 sur les cellules leucémiques. Il met en rémission bien plus de patients atteints d'ALL en rechute que la chimiothérapie et leur sert de passerelle vers la greffe.",
  "inselspital-bern": "L'hôpital universitaire de Berne, un centre à haut volume de thérapie par radioligands et siège du Bern Center for Precision Medicine et du groupe d'essais SAKK.",
  "institut-curie": "Fondé par Marie Curie ; un leader du cancer du sein, de la radiothérapie et de la protonthérapie.",
  "institut-jules-bordet": "Le seul hôpital de Belgique entièrement consacré au cancer, berceau du Breast International Group et centre mondial des essais sur le cancer du sein.",
  "instituto-alexander-fleming": "Le principal institut privé du cancer d'Argentine, un site clé pour les essais internationaux dans les cancers du sein, du poumon et du tube digestif, et le berceau de la tradition argentine des groupes coopératifs.",
  "inter-b-nhl-ritux-2010": "L'ajout de l'anticorps rituximab à une chimiothérapie intensive chez les enfants atteints d'un lymphome de Burkitt à haut risque ou de lymphomes apparentés a réduit les échecs thérapeutiques d'environ deux tiers, rendant encore plus curable une maladie qui l'était déjà. C'est le modèle d'un essai conjoint européen et nord-américain sur les cancers de l'enfant.",
  "interpath-001": "INTerpath-001 a été le premier essai de phase 3 positif d'un vaccin anticancéreux personnalisé, annoncé le 19 août 2026.",
  "io-plus-vegf": "Normaliser les vaisseaux sanguins de la tumeur laisse entrer les cellules immunitaires, et le blocage de VEGF supprime un signal immunosuppresseur.",
  "iov-veneto": "Le centre de lutte contre le cancer de la région de Vénétie, accrédité par l'OECI et situé à Padoue, reconnu pour ses essais sur le cancer du sein, le mélanome et l'immunologie des tumeurs.",
  "ipo-lisboa": "Le premier institut du cancer du Portugal, fondé en 1923 par Francisco Gentil, et l'hôpital de référence national en cancérologie pour la région de Lisbonne.",
  "ipo-porto": "L'hôpital dédié au cancer du nord du Portugal, un centre de cancérologie complet accrédité par l'OECI, connu pour la génétique des cancers héréditaires et les biomarqueurs épigénétiques.",
  ipsen: "Ipsen est le laboratoire pharmaceutique français à l'origine d'Onivyde (irinotécan liposomal) et du protocole NALIRIFOX, et il commercialise le tovorafenib en Europe.",
  "irst-meldola": "L'institut du cancer de Romagne, connu pour la thérapie par radioligands, la médecine nucléaire et les essais en cancérologie génito-urinaire et dans les sarcomes.",
  ispor: "La société des économistes de la santé et des chercheurs en résultats de santé, dont les méthodes et les rapports de bonnes pratiques sous-tendent la façon dont les organismes d'HTA et les payeurs évaluent la valeur des médicaments anticancéreux.",
  itcc: "Le réseau européen d'hôpitaux pédiatriques qui mènent les premiers essais de nouveaux médicaments anticancéreux chez l'enfant, afin que les enfants européens puissent accéder aux médicaments expérimentaux près de chez eux.",
  "iuct-oncopole": "Le campus cancérologique de Toulouse, réunissant l'Institut Claudius Regaud et le centre hospitalier universitaire, et un leader mondial de la recherche sur le myélome multiple.",
  "jak-stat": "Le relais qui transforme les signaux des cytokines en modifications des gènes. Hyperactif dans les cancers du sang (JAK2 dans la myélofibrose), c'est aussi le fil qui transporte le message anticancéreux de l'interféron, si bien que les tumeurs le coupent pour échapper à l'immunothérapie.",
  jak2: "L'enzyme de signalisation qui dit aux cellules de la moelle de fabriquer des globules rouges et des plaquettes ; une seule mutation (V617F) la laisse allumée dans la plupart des néoplasies myéloprolifératives.",
  "james-allison": "A découvert que le blocage de CTLA-4 libère les cellules T contre le cancer, le travail à l'origine de l'ipilimumab et du prix Nobel 2018.",
  jazz: "Jazz Pharmaceuticals commercialise le zanidatamab (Ziihera) en dehors de l'Asie.",
  jcog: "JCOG est le groupe coopératif national du Japon et définit les standards chirurgicaux et périopératoires dans les cancers de l'estomac et de l'œsophage.",
  jsmo: "La société japonaise d'oncologie médicale, qui certifie les oncologues médicaux du Japon, tient un grand congrès annuel et publie des recommandations cliniques avec la Japan Society of Clinical Oncology.",
  juravinski: "Le centre régional de cancérologie de Hamilton, lié à l'Université McMaster, berceau des essais qui ont fait de la radiothérapie mammaire hypofractionnée le standard et de la recherche sur les cellules souches des tumeurs cérébrales.",
  "kaiser-permanente-research": "La branche recherche du plus grand système de santé intégré des États-Unis, dont les cohortes et les programmes de dépistage produisent une grande partie des données en vie réelle sur le dépistage et la prévention du cancer.",
  "kathleen-moore": "A dirigé SOLO-1 et MIRASOL, qui ont donné au cancer de l'ovaire un inhibiteur de PARP en maintenance et son premier ADC avec un bénéfice de survie.",
  kcsg: "Le groupe coopératif multicentrique d'essais de Corée du Sud, qui relie les méga-hôpitaux de Séoul et les centres régionaux dans des essais à l'initiative des investigateurs sur les cancers de l'estomac, du poumon, du foie et du sein.",
  "ken-herrmann": "Figure de la médecine nucléaire qui a codirigé VISION et dirige l'un des plus grands programmes de théranostique au monde.",
  "kenyatta-national-hospital": "L'hôpital national de référence du Kenya et le plus grand d'Afrique de l'Est, avec le centre public de radiothérapie et de traitement du cancer le plus fréquenté de la région.",
  "ketogenic-diet-glioblastoma": "Un régime cétogène est un régime très pauvre en glucides et riche en graisses qui fait fonctionner le corps avec des cétones. L'idée est de priver les tumeurs cérébrales de glucose. Il est sûr et faisable pendant quelques mois, mais aucun essai n'a montré qu'il fait vivre plus longtemps.",
  "keynote-826": "A ajouté près de dix mois de vie aux femmes atteintes d'un cancer du col de l'utérus avancé et a fait de l'immunothérapie une composante du traitement de première ligne.",
  "keynote-a18": "Ajouter une immunothérapie à la chimioradiothérapie curative du cancer du col de l'utérus localement avancé a amélioré à la fois le contrôle de la maladie et la survie, la première avancée de ce type en vingt ans.",
  kfshrc: "L'hôpital tertiaire phare de l'Arabie saoudite, dont le Centre d'oncologie gère les plus grands programmes de transplantation, de CAR-T et de protonthérapie du Golfe.",
  khcc: "L'hôpital jordanien exclusivement consacré au cancer et le principal centre de cancérologie intégré du monde arabe, le premier hors des États-Unis accrédité comme centre de cancérologie par la Joint Commission International.",
  kmt2a: "Une fusion de gènes qui entraîne une leucémie agressive chez les nourrissons et les adultes. Elle ne peut pas être bloquée directement, mais la protéine d'échafaudage dont elle dépend (menin) le peut.",
  "korle-bu-teaching-hospital": "Le premier hôpital universitaire du Ghana et le plus grand d'Afrique de l'Ouest, qui abrite le National Radiotherapy, Oncology and Nuclear Medicine Centre et mène la recherche africaine sur le cancer du sein.",
  "kras-mutation-subtypes": "KRAS, le gène du cancer le plus fréquemment muté, existe en plusieurs variantes nommées d'après le changement exact d'acide aminé. G12C (fréquente dans le cancer du poumon des fumeurs) a été la première à obtenir un médicament ; G12D domine dans les cancers du pancréas et colorectal et ses inhibiteurs arrivent maintenant.",
  "kras-roadmap": "Le gène du cancer le plus important a été déclaré impossible à cibler par un médicament pendant 40 ans. Puis une poche a été trouvée, et aujourd'hui un médicament pan-RAS est en phase 3 dans le cancer du pancréas.",
  "kyoto-university-hospital": "L'université où Tasuku Honjo a découvert PD-1 et Shinya Yamanaka a créé les cellules iPS ; son hôpital est à la pointe de la recherche japonaise en immunothérapie et en thérapie cellulaire.",
  "late-recurrence": "Le cancer du sein hormonodépendant peut revenir 10, voire 20 ans après le traitement, contrairement à la plupart des cancers, ce qui explique pourquoi l'hormonothérapie dure si longtemps.",
  "leeds-cancer-centre": "L'un des plus grands centres de cancérologie du Royaume-Uni, connu pour la pathologie et les essais dans le cancer colorectal, la recherche sur le mélanome, le myélome et la radiothérapie guidée par MR.",
  "leukaemia-type": "Cancer des cellules productrices de sang dans la moelle osseuse, qui inondent le sang de globules blancs immatures ou anormaux et évincent la production normale de sang. Il n'y a pas de masse unique à retirer.",
  "li-fraumeni": "Le syndrome de Li-Fraumeni est une anomalie héréditaire du gène TP53 qui donne un risque de cancer au cours de la vie proche de 100% chez les femmes et de ~75% chez les hommes, avec des sarcomes, des cancers du sein, des tumeurs cérébrales, des cancers des surrénales et des leucémies, souvent dès l'enfance. La surveillance par MRI du corps entier sauve des vies.",
  "libretto-531": "A montré qu'un médicament conçu spécifiquement pour la mutation de RET surpasse les anciens comprimés multicibles dans le cancer médullaire de la thyroïde, avec beaucoup moins d'effets secondaires.",
  linker: "Le linker est l'attache chimique entre l'anticorps et la charge utile. Il doit tenir dans le sang et se détacher à l'intérieur de la tumeur.",
  "lisocabtagene-maraleucel": "Lisocabtagene maraleucel est la seule CAR-T approuvée dans la leucémie lymphoïde chronique, pour les patients dont la maladie a échappé à la fois aux inhibiteurs de BTK et de BCL-2.",
  "liver-directed-therapy": "L'ensemble des traitements visant uniquement les tumeurs du foie, administrés par son artère ou par aiguille, utilisés lorsque le foie est le site principal ou unique de la maladie : chimioembolisation, microsphères radioactives, ablation et pompes de perfusion.",
  "lmu-munich": "Le LMU Klinikum est le centre universitaire de cancérologie de Munich, avec des points forts en théranostique PSMA et en hématologie.",
  lonza: "Lonza est le plus grand fabricant sous contrat de produits biologiques, d'ADC et de thérapies cellulaires, et détient la technologie de linkers pour ADC Synaffix et la plateforme de fabrication cellulaire Cocoon.",
  "low-dose-nivolumab-tmh": "Un essai de Mumbai qui a ajouté environ un vingtième de la dose habituelle de l'immunothérapie nivolumab à une chimiothérapie orale bon marché et a presque triplé la proportion de patients en vie à un an.",
  lucence: "Lucence propose des tests sanguins qui lisent à la fois le DNA et le RNA tumoraux à partir d'un seul échantillon pour aider les médecins à choisir des traitements ciblés, et développe un test de dépistage multi-cancers.",
  "lumc-leiden": "L'hôpital universitaire de Leyde, berceau des vaccins thérapeutiques contre le cancer et de l'immunologie des tumeurs, et base de l'essai néerlandais TME sur le cancer du rectum.",
  "lund-skane": "L'hôpital universitaire du sud de la Suède et le centre de cancérologie de l'université de Lund, connus pour le projet SCAN-B de séquençage du cancer du sein à l'échelle de la population.",
  lunit: "Société coréenne d'IA couvrant la lecture des mammographies (INSIGHT MMG), le risque lié à la densité mammaire (Volpara) et la pathologie par IA pour les biomarqueurs d'immunothérapie.",
  lurbinectedin: "Une chimiothérapie d'origine marine qui bloque la machinerie de lecture des gènes du cancer, approuvée pour le cancer du poumon à petites cellules en rechute et, depuis 2025, en maintenance de première ligne avec atezolizumab.",
  luspatercept: "Une injection qui aide la moelle à achever la fabrication des globules rouges, réduisant ou supprimant le besoin de transfusions dans les SMD de faible risque et la bêta-thalassémie.",
  "lustgarten-foundation": "Le plus grand financeur privé de la recherche sur le cancer du pancréas, qui finance des laboratoires dédiés à Cold Spring Harbor, Johns Hopkins, Dana-Farber et au MIT.",
  "luth-lagos": "Le principal hôpital universitaire du Nigeria, dans sa plus grande ville, qui abrite le NSIA-LUTH Cancer Centre, l'installation de radiothérapie la plus avancée du pays.",
  lymphadenectomy: "Retirer chirurgicalement les ganglions lymphatiques qui drainent une tumeur, à la fois pour déterminer le stade du cancer et pour éliminer toute propagation.",
  "lymphoma-type": "Cancer des lymphocytes, les globules blancs du système immunitaire, qui se développe généralement sous forme de masses dans les ganglions lymphatiques, la rate ou d'autres organes. On le divise en Hodgkin et en nombreux types non hodgkiniens.",
  "lynch-syndrome": "Le syndrome de Lynch est le syndrome de cancer héréditaire le plus fréquent : un gène défectueux de réparation des mésappariements porte le risque de cancer de l'intestin au cours de la vie à 40-80 % et augmente aussi le risque de cancer de l'endomètre et d'autres cancers.",
  lysa: "Le groupe franco-belge du lymphome, successeur du GELA, dont l'essai LNH-98.5 a fait du R-CHOP le standard du lymphome diffus à grandes cellules B.",
  "macmillan-cancer-support": "L'association caritative britannique qui finance les infirmières et les travailleurs d'accompagnement Macmillan au sein du NHS et apporte information, soutien financier et soutien émotionnel aux personnes vivant avec un cancer.",
  magrolimab: "Le premier bloqueur du signal « ne me mange pas ». Gilead l'a payé 4,9 milliards de dollars ; il a été arrêté en 2024 après que les essais ont montré plus de décès, et non moins.",
  "maintenance-therapy-term": "Un traitement plus doux et continu, administré après le traitement principal pour empêcher le cancer de revenir, parfois pendant des années ou jusqu'à la progression. Sa valeur se juge au regard du fardeau de ne jamais s'arrêter.",
  "malnutrition-screening": "Des questionnaires rapides qui repèrent les personnes à risque de dénutrition : perte de poids récente, BMI bas, manque d'appétit, gravité de la maladie. Toute personne repérée devrait voir un diététicien.",
  mariposa: "Le premier traitement à surpasser osimertinib dans le cancer du poumon avec mutation d'EGFR, avec un bénéfice de survie dépassant un an.",
  mascc: "La société internationale des soins de support en cancérologie, dont les recommandations sur les antiémétiques, la mucite, la neutropénie fébrile et la toxicité des immunothérapies sont utilisées dans le monde entier.",
  "mcgill-goodman": "L'institut de recherche sur le cancer de McGill, héritier de la découverte du CEA, le premier marqueur tumoral, et un leader dans les métastases, le métabolisme et les modèles murins de cancer du sein.",
  "mcrpc-mhspc": "Le cancer de la prostate est d'abord nourri par la testostérone (hormonosensible) et régresse quand on la supprime. Lorsqu'il apprend à croître malgré des taux de testostérone de castration, on le dit résistant à la castration, un stade plus tardif et plus dangereux qui a ses propres traitements.",
  "mdc-berlin": "L'institut Helmholtz de médecine moléculaire de Berlin, dont la recherche sur le cancer couvre les thérapies par récepteurs de cellules T, la biologie de la cellule unique et la médecine des systèmes.",
  mdm2: "MDM2 est la protéine qui dégrade p53 ; la bloquer réactive p53 dans les tumeurs où le gène est intact, en particulier les liposarcomes qui portent des copies supplémentaires de MDM2.",
  melphalan: "La chimiothérapie du myélome qui est aussi le conditionnement standard à haute dose avant autogreffe et qui, délivrée directement dans la circulation sanguine du foie ou dans l'œil, traite les métastases du mélanome uvéal et le rétinoblastome.",
  "metabolic-syndrome": "Le syndrome métabolique est un ensemble associant obésité abdominale, hypertension artérielle, glycémie élevée et anomalies des graisses sanguines. Il augmente le risque de plusieurs cancers et aggrave les résultats après le diagnostic, en grande partie par des taux élevés d'insuline.",
  "metabolic-therapy": "Priver la tumeur d'un acide aminé ou d'un nutriment que certaines tumeurs ne peuvent pas fabriquer elles-mêmes, alors que les cellules normales le peuvent.",
  metastasis: "Cancer qui s'est propagé de son point de départ vers des parties éloignées du corps, en voyageant par le sang ou la lymphe. Les métastases sont la raison pour laquelle les examens de stadification regardent tout le corps, et le cadre dans lequel la plupart des nouveaux médicaments anticancéreux sont d'abord approuvés.",
  mgmt: "Un interrupteur chimique qui éteint un gène de réparation du DNA. Lorsqu'il est éteint, temozolomide fonctionne beaucoup mieux.",
  mhra: "L'autorité britannique de régulation des médicaments et des dispositifs médicaux, qui depuis le Brexit gère ses propres autorisations, participe au Project Orbis et utilise des voies de reconnaissance internationale pour accélérer l'accès aux médicaments anticancéreux.",
  "mibg-theranostics": "Un sosie de la noradrénaline que les cellules de neuroblastome absorbent : marqué avec une petite quantité de radioactivité, il montre la tumeur à l'imagerie ; avec une grande quantité, il la traite.",
  "michigan-rogel": "Le Rogel Cancer Center du Michigan est le lieu de la découverte de TMPRSS2-ERG, de MI-ONCOSEQ et d'une chimie pionnière des dégradeurs (Wang).",
  "microbiome-modulation-io": "Modifier les bactéries intestinales d'un patient dont l'immunothérapie a cessé de fonctionner, dans l'espoir de relancer la réponse.",
  "microbiome-tumour": "Les bactéries de l'intestin, et même celles présentes à l'intérieur des tumeurs, influencent l'apparition du cancer et l'efficacité de l'immunothérapie. La transplantation de selles de patients répondeurs a permis à certains non-répondeurs de répondre.",
  midostaurin: "Le premier médicament à améliorer la survie dans la AML avec mutation de FLT3, ajouté à la chimiothérapie standard : la survie médiane est passée d'environ deux ans à plus de six.",
  "minoxidil-chemotherapy-alopecia": "La plupart des cheveux repoussent après la chimiothérapie, mais une minorité de patients, surtout après docetaxel, gardent des cheveux clairsemés, et le tamoxifène et les inhibiteurs de l'aromatase provoquent un amincissement progressif. La lotion de minoxidil ou les comprimés à faible dose, le même traitement que pour la calvitie commune, ont amélioré la repousse chez la plupart des patients dans des séries dermatologiques et raccourci le délai de repousse dans un premier essai randomisé.",
  "mirvetuximab-soravtansine": "Mirvetuximab soravtansine (Elahere) est le premier ADC pour le cancer de l'ovaire, destiné aux tumeurs à forte expression du récepteur alpha des folates.",
  "mit-koch": "L'institut de recherche sur le cancer du MIT, où le premier oncogène humain et RB ont été découverts et où la biologie rencontre l'ingénierie ; la racine académique de Moderna.",
  mitomycin: "La chimiothérapie donnée avec la radiothérapie pour guérir le cancer de l'anus sans chirurgie, utilisée en instillation vésicale après résection de la tumeur et, depuis 2020-25, sous forme de gel pour les cancers des voies urinaires supérieures et de la vessie récidivants.",
  mmae: "MMAE est la charge cytotoxique d'ADC bloquant la tubuline la plus utilisée : elle empêche les cellules de se diviser et diffuse dans les cellules voisines. L'atteinte des nerfs est son effet secondaire caractéristique.",
  moderna: "Moderna est la société d'ARNm dont le vaccin personnalisé contre le cancer, intismeran, a remporté le premier essai de phase 3 de sa classe (août 2026).",
  monarche: "Le premier inhibiteur de CDK4/6 à réduire les récidives après chirurgie dans le cancer du sein hormono-positif à haut risque.",
  mosunetuzumab: "Mosunetuzumab est un anticorps bispécifique anti-CD20 de durée fixe approuvé dans le lymphome folliculaire et étudié avec le polatuzumab dans le lymphome B à grandes cellules.",
  "mou-brno": "Le seul centre de cancérologie complet dédié de la République tchèque, accrédité par l'OECI et connu pour son centre de recherche translationnelle RECAMO.",
  "mp-mri": "Une MRI avant biopsie qui trouve les cancers qui comptent et permet à de nombreux hommes de se passer complètement de biopsie.",
  "mrd-negativity-myeloma": "La négativité de la MRD signifie qu'aucune cellule de myélome n'est détectable parmi 100 000 ou un million de cellules de la moelle. C'est le meilleur prédicteur d'une survie longue et, depuis 2024, un critère d'évaluation accepté pour l'approbation accélérée.",
  "msi-mmr-testing": "Des tests qui montrent si une tumeur a perdu son correcteur orthographique de l'ADN ; si c'est le cas, l'immunothérapie fonctionne exceptionnellement bien et un syndrome héréditaire peut être présent.",
  "myriad-genetics": "L'entreprise qui a fait du test BRCA un business, qui vend aujourd'hui des panels héréditaires et les tests tumoraux myChoice, EndoPredict et Prolaris.",
  nadina: "Administrer la bithérapie d'immunothérapie avant la chirurgie, plutôt que nivolumab après, a réduit le risque de récidive d'environ deux tiers et a permis à la plupart des patients d'éviter tout traitement supplémentaire.",
  "narayana-health": "Le réseau hospitalier à bas coût de Devi Shetty, dont le centre de cancérologie Mazumdar Shaw à Bengaluru applique au cancer la chirurgie et la greffe à haut volume et à bas prix, et héberge le deuxième développeur de CAR-T de l'Inde.",
  natera: "Natera fabrique Signatera, le principal test de MRD informé par la tumeur.",
  "ncc-korea": "Le centre gouvernemental de lutte contre le cancer de la Corée, siège du registre national du cancer et du programme de dépistage, et de la première installation de protonthérapie du pays.",
  nccn: "Les algorithmes que suivent les oncologues américains. Si un médicament figure dans le NCCN, les assureurs paient généralement.",
  nccs: "Le centre national du cancer de Singapour et le plus grand établissement de cancérologie du pays, doté d'un centre de protonthérapie et d'une recherche de premier plan en Asie sur la génomique des cancers du foie et du poumon.",
  "nct-dresden": "Le deuxième site du Centre national des maladies tumorales, connu pour la recherche en protonthérapie à OncoRay et pour l'IA en pathologie et en chirurgie.",
  nectin4: "Nectin-4 est une protéine d'adhésion abondante sur les cellules du cancer de la vessie, utilisée comme site d'amarrage pour l'ADC enfortumab vedotin.",
  "newcastle-cancer-centre": "Le centre de cancérologie du nord-est de l'Angleterre et le berceau du premier inhibiteur de PARP à atteindre les patients, le rucaparib.",
  ngs: "Lire des millions de fragments de DNA en parallèle, le moteur de tout test génomique moderne.",
  "ngs-bioinformatics-software": "Un logiciel qui transforme la sortie brute du séquenceur en un rapport indiquant quelles mutations comptent et vers quels médicaments elles orientent.",
  "nhs-galleri": "Le plus grand essai de dépistage du cancer jamais mené, qui teste si un test sanguin multi-cancers réduit les diagnostics à un stade avancé.",
  nilotinib: "Nilotinib est un comprimé de deuxième génération contre la CML qui produit des réponses plus profondes et plus rapides que l'imatinib, au prix d'effets secondaires cardiovasculaires et métaboliques.",
  "nio-warsaw": "L'institut national du cancer de Pologne, fondé en 1932 à l'initiative de Marie Curie, avec des antennes à Gliwice et Cracovie et le registre national du cancer.",
  nirogacestat: "Nirogacestat est le premier médicament approuvé pour les tumeurs desmoïdes, des proliférations localement invasives qui ne se disséminent pas mais peuvent être invalidantes ; il agit en bloquant la signalisation Notch.",
  "nlst-nelson": "Les deux essais qui ont prouvé qu'un scanner CT annuel à faible dose réduit les décès par cancer du poumon chez les gros fumeurs.",
  "nmpa-cde": "Le régulateur des médicaments de la Chine et son centre d'évaluation, dont les réformes depuis 2015 ont fait de la Chine la deuxième source mondiale de nouveaux médicaments anticancéreux et un leader des ADC et des bispécifiques.",
  "nogapendekin-alfa": "Nogapendekin alfa inbakicept est une version modifiée de la protéine immunostimulante IL-15, administrée avec le BCG dans la vessie, approuvée en 2024 pour le cancer de la vessie précoce que le BCG seul ne contrôle plus.",
  "northwestern-lurie": "Le centre de cancérologie de Northwestern à Chicago, leader mondial du traitement des tumeurs cérébrales, des Tumour Treating Fields à l'ouverture de la barrière hémato-encéphalique par ultrasons.",
  notch: "Un signal de contact entre cellules qui décide du destin cellulaire. Il entraîne la leucémie à cellules T lorsqu'une mutation le maintient activé, agit comme suppresseur de tumeur dans certains cancers épidermoïdes lorsqu'il est perdu, et son ligand DLL3 est devenu une cible thérapeutique dans le cancer du poumon à petites cellules.",
  npm1: "NPM1 est la mutation la plus fréquente de la leucémie de l'adulte. Elle déplace une protéine nucléaire vers le cytoplasme et, il s'avère, rend la leucémie dépendante de menin.",
  "nsabp-foundation": "Le groupe historique américain d'essais sur le traitement adjuvant chirurgical qui a prouvé que la tumorectomie équivaut à la mastectomie, que tamoxifen prévient le cancer du sein et que trastuzumab guérit davantage de maladies HER2-positives.",
  ntuh: "Le premier hôpital universitaire de Taïwan et le berceau du programme de vaccination contre l'hépatite B qui a fait reculer le cancer du foie chez l'enfant, avec un nouveau centre dédié au cancer.",
  "nuh-ncis": "L'institut du cancer de l'hôpital universitaire de Singapour, associé au Cancer Science Institute of Singapore et connu pour ses recherches sur le cancer gastrique, l'hématologie et le développement de médicaments.",
  "nut-carcinoma": "Le carcinome NUT est un cancer à croissance rapide de la ligne médiane du corps, provoqué par un seul gène fusionné, BRD4-NUTM1, qui bloque les cellules dans un état immature. La chimiothérapie et la chirurgie le contrôlent rarement longtemps, mais les médicaments qui bloquent les protéines BET dont dépend la fusion ont produit des réponses et sont au centre des essais.",
  "nutrition-impact-symptoms": "Les effets secondaires du cancer et de son traitement qui empêchent les gens de manger : nausées, douleurs buccales, altérations du goût, difficultés à avaler, satiété précoce, constipation, douleur et moral bas. Les traiter est souvent l'intervention nutritionnelle la plus efficace.",
  "nyu-perlmutter": "Le centre de cancérologie de NYU, « comprehensive » depuis 2019, connu pour l'immunothérapie du mélanome, la biologie de RAS et SHP2 et les premiers travaux de pathologie par apprentissage profond.",
  "octreotide-lanreotide": "Des injections mensuelles d'une hormone de synthèse qui à la fois apaise les symptômes hormonaux de la tumeur et ralentit sa croissance, le premier traitement pour la plupart des tumeurs neuroendocrines.",
  "ohsu-knight": "L'institut de Brian Druker, où l'imatinib a fait ses preuves dans la LMC et où l'oncologie de précision est née ; aujourd'hui centré sur la détection précoce et la génomique fonctionnelle.",
  "olanzapine-appetite-tmh": "Un essai randomisé en Inde d'une dose de 2.5 mg d'un comprimé très bon marché et vieux de plusieurs décennies. Six patients sur dix ont pris plus de 5 % de leur poids, contre un sur dix sous placebo.",
  olympia: "A montré qu'un an d'inhibiteur de PARP après le traitement standard améliore la survie des femmes porteuses de mutations héréditaires de BRCA.",
  oncogene: "Un gène qui, lorsqu'il est suractivé par une mutation ou des copies supplémentaires, pousse la cellule à croître et à se diviser. Imaginez une pédale d'accélérateur bloquée au plancher.",
  "oncology-nutrition": "Dépistage de la dénutrition, conseils dirigés par des diététiciens, compléments et alimentation par sonde ou intraveineuse lorsqu'elle est indiquée, ainsi que traitement de la cachexie cancéreuse, le syndrome de fonte musculaire qui touche jusqu'à 80% des patients à un stade avancé.",
  "oncomine-dx-target-test": "Le premier panel génétique approuvé par la FDA capable d'associer une seule biopsie à plusieurs médicaments différents contre le cancer du poumon en même temps.",
  "onkoloski-institut-ljubljana": "Le centre national de lutte contre le cancer de la Slovénie, accrédité par l'OECI, siège de l'un des plus anciens registres du cancer d'Europe et pionnier de l'électrochimiothérapie.",
  "optical-imaging": "Des colorants qui brillent sous une lumière spéciale, pour que les chirurgiens puissent voir les bords de la tumeur et les nerfs au bloc opératoire.",
  "organ-preservation": "Guérir un cancer par les médicaments et la radiothérapie afin que l'organe (rectum, vessie, larynx, membre) n'ait pas à être retiré, en gardant la chirurgie en réserve pour la minorité dont le cancer repousse.",
  "oslo-radium-hospital": "L'hôpital national du cancer et institut de recherche de la Norvège, où sont nés l'émetteur alpha radium-223 (Xofigo) et l'agent d'imagerie de la vessie de Photocure.",
  outcomes4me: "Outcomes4Me est une application gratuite qui transforme les recommandations officielles de traitement du cancer en options en langage clair pour chaque patient, et qui suit aussi les symptômes, explique les tests génétiques et trouve des essais cliniques.",
  owkin: "Biotech française d'IA utilisant l'apprentissage fédéré entre hôpitaux ; première IA marquée CE pour prédire le MSI à partir de lames H&E.",
  "oxford-cancer": "Le partenariat oxonien contre le cancer, qui associe le Churchill Hospital aux instituts de radiothérapie oncologique, Ludwig et de détection précoce de l'université, avec une longue tradition de spin-outs dans les médicaments et le diagnostic.",
  paige: "Société issue du MSK, dotée du premier produit de pathologie par IA autorisé par la FDA et du modèle de fondation Virchow.",
  "pain-management": "Traitement systématique de la douleur cancéreuse par opioïdes, médicaments adjuvants, radiothérapie et procédures telles que les blocs nerveux et les pompes intrathécales. La plupart des douleurs peuvent être contrôlées, mais le sous-traitement reste fréquent, surtout là où les opioïdes ne sont pas disponibles.",
  "palliative-radiotherapy": "De courtes séries de radiothérapie, souvent une seule séance, pour soulager la douleur des métastases osseuses, arrêter un saignement, dégager des voies respiratoires obstruées ou protéger la moelle épinière. C'est l'un des traitements les plus rentables en cancérologie.",
  "pancreatic-surveillance": "Une IRM ou une échographie endoscopique annuelle pour les personnes présentant un risque hérité, qui dépiste les cancers du pancréas alors qu'ils sont encore opérables.",
  panitumumab: "Panitumumab est un anticorps anti-EGFR entièrement humain, le partenaire privilégié de la chimiothérapie en première ligne dans le cancer de l'intestin du côté gauche avec RAS normal depuis l'essai PARADIGM.",
  "paola-1": "L'ajout d'olaparib au traitement d'entretien par bevacizumab a à peu près doublé le temps sans progression dans les tumeurs à réparation de l'ADN défaillante, et a amélioré la survie dans ce groupe.",
  "paper-aall1731-blinatumomab-children-nejm-2025": "Deux cures de blinatumomab ajoutées à la chimiothérapie standard ont réduit les rechutes chez les enfants atteints d'une leucémie de risque standard de niveau moyen ou plus élevé, faisant passer la survie sans maladie à trois ans de 88% à 96%.",
  "paper-adaura-nejm-2020": "Après chirurgie d'un cancer du poumon à un stade précoce avec mutation de l'EGFR, trois ans d'osimertinib ont réduit les récidives d'environ 80% et, plus tard, ont diminué les décès de moitié.",
  "paper-adriatic-nejm-2024": "Dans le cancer du poumon à petites cellules limité au thorax, l'ajout de deux ans de durvalumab après la chimioradiothérapie a fait passer la survie médiane de moins de trois ans à plus de quatre ans et demi, la première avancée dans cette situation depuis des décennies.",
  "paper-alcohol-cancer-burden-lancet-oncol-2021": "S'appuyant sur le classement de l'alcool par le IARC comme cancérogène du Groupe 1, cette étude de modélisation mondiale a attribué 4,1% de tous les nouveaux cancers de 2020 à la consommation d'alcool, dont les trois quarts chez les hommes, les effectifs les plus élevés concernant les cancers de l'oesophage, du foie et du sein.",
  "paper-amplify-acalabrutinib-venetoclax-nejm-2025": "Dans AMPLIFY, un traitement entièrement oral de 14 mois associant acalabrutinib et venetoclax a fait mieux que la chimio-immunothérapie FCR ou BR chez des patients atteints de CLL en bonne forme, offrant une alternative de durée limitée aux comprimés pris indéfiniment.",
  "paper-asco-irae-guideline-jco-2021": "La recommandation ASCO 2021 est le règlement consensuel de la toxicité des inhibiteurs de points de contrôle : graduer le problème, suspendre ou arrêter le médicament, donner des stéroïdes tôt, passer à d'autres immunosuppresseurs s'ils échouent et faire appel à des spécialistes.",
  "paper-augment-101-revumenib-menin-nature-2023": "Bloquer la ménine, une protéine d'échafaudage dont dépend la leucémie, a produit des rémissions chez des patients lourdement prétraités atteints de leucémie aiguë avec réarrangement de KMT2A ou mutation de NPM1.",
  "paper-basu-single-dose-hpv-lancet-oncol-2021": "Dix ans après la vaccination, les jeunes filles indiennes ayant reçu une seule dose de vaccin contre le HPV étaient aussi bien protégées contre les types de HPV cancérogènes que celles qui en avaient reçu deux ou trois, ce qui a permis au monde de passer à des programmes à dose unique.",
  "paper-body-fatness-iarc-nejm-2016": "Un groupe de travail du IARC a passé en revue plus de 1 000 études et conclu qu'il existe des preuves suffisantes que l'absence d'excès de graisse corporelle réduit le risque de 13 cancers, contre 5 lors de l'évaluation de 2002.",
  "paper-brca-risk-reducing-surgery-jama-2010": "Parmi 2 482 femmes porteuses de mutations BRCA1 ou BRCA2, l'ablation des ovaires et des trompes de Fallope a été associée à une mortalité toutes causes réduite de 60%, et aucun cancer du sein n'est survenu chez les femmes ayant subi une mastectomie préventive.",
  "paper-c-144-01-lifileucel-melanoma-jco-2021": "Des cellules immunitaires prélevées dans la tumeur d'un patient, multipliées en laboratoire et réinjectées ont fait régresser le mélanome chez 36% des patients dont la maladie avait progressé sous blocage de PD-1, avec des réponses qui ont le plus souvent duré.",
  "paper-capp2-aspirin-lynch-lancet-2020": "Chez les porteurs du syndrome de Lynch, 600 mg d'aspirin par jour pendant environ deux ans ont réduit le cancer colorectal au cours de la décennie suivante (HR 0.65 en intention de traiter ; 0.56 chez ceux qui l'ont prise au moins deux ans).",
  "paper-cartitude-1-cilta-cel-lancet-2021": "Une seule perfusion de cellules CAR-T dirigées contre BCMA a produit des réponses chez 97% des patients dont le myélome avait résisté à une médiane de six lignes antérieures, et deux tiers ont atteint une réponse complète stricte.",
  "paper-cartitude-4-cilta-cel-nejm-2023": "Avancer le CAR-T anti-BCMA en deuxième ligne a réduit le risque de progression ou de décès de 74% par rapport aux triplettes standard, et a ensuite amélioré la survie globale.",
  "paper-cepheus-dara-vrd-natmed-2025": "Chez les patients non éligibles à la greffe ou l'ayant différée, la quadrithérapie à base de daratumumab a fait passer les taux de rémission profonde d'environ 39% à 61% et a réduit le risque de progression de 43%.",
  "paper-cercek-dmmr-rectal-nejm-2022": "Six mois de l'anticorps anti-PD-1 dostarlimab ont fait disparaître toutes les tumeurs chez un petit groupe de patients atteints d'un cancer du rectum avec déficience de la réparation des mésappariements, leur permettant d'éviter la chimiothérapie, la radiothérapie et la chirurgie.",
  "paper-cercek-dostarlimab-rectal-nejm-2022": "Les 12 patients atteints d'un cancer du rectum dMMR localement avancé ont tous eu une réponse clinique complète à un anticorps PD-1 seul, évitant la chimiothérapie, la radiothérapie et la chirurgie.",
  "paper-challenge-exercise-nejm-2025": "Dans CHALLENGE, trois ans d'exercice physique encadré et fondé sur des objectifs après la chimiothérapie adjuvante d'un cancer du côlon ont réduit les récidives ou décès de 28% et les décès de 37%, la première preuve randomisée que l'exercice en lui-même améliore la survie dans le cancer.",
  "paper-checkmate-067-10-year-nejm-2025": "Dix ans après le début du traitement, environ la moitié des patients atteints de mélanome avancé traités par nivolumab plus ipilimumab étaient toujours en vie, la plupart sans aucun traitement supplémentaire, ce qui montre que l'immunothérapie peut guérir une maladie qui tuait autrefois la plupart des patients en moins d'un an.",
  "paper-checkmate-067-ten-year-nejm-2025": "Le suivi à dix ans de l'essai qui a établi le blocage combiné des points de contrôle immunitaire montre une survie médiane de plus de six ans avec nivolumab plus ipilimumab et un plateau de la courbe de survie compatible avec une guérison.",
  "paper-checkmate-649-lancet-2021": "L'ajout de l'immunothérapie nivolumab à la chimiothérapie de première ligne a permis aux patients atteints d'un adénocarcinome avancé de l'estomac et de l'œsophage de vivre plus longtemps, surtout lorsque la tumeur exprimait PD-L1, faisant de la chimio-immunothérapie le nouveau standard.",
  "paper-checkmate-816-nejm-2022": "Seulement trois cycles de chimiothérapie avec l'immunothérapie nivolumab avant la chirurgie ont éliminé toute tumeur viable chez un quart des patients et réduit la rechute ou le décès d'environ un tiers, sans rendre la chirurgie plus difficile.",
  "paper-clear-nejm-2021": "L'association de l'inhibiteur multikinase lenvatinib et du pembrolizumab a plus que doublé le délai avant progression par rapport au sunitinib dans le cancer du rein à cellules claires avancé et a amélioré la survie, avec une réponse chez 71% des patients.",
  "paper-cll14-venetoclax-obinutuzumab-nejm-2019": "Un traitement fixe d'un an par deux médicaments ciblés a maintenu la CLL sous contrôle bien plus longtemps que la chimio-immunothérapie, et la plupart des patients n'avaient plus de maladie détectable à l'arrêt du traitement.",
  "paper-codebreak-200-lancet-2023": "Le premier médicament à bloquer directement le KRAS muté a fait mieux que la chimiothérapie par docetaxel pour retarder la progression dans le cancer du poumon KRAS G12C, mais seulement d'environ un mois, et n'a pas amélioré la survie.",
  "paper-codebreak-300-nejm-2023": "L'association d'un inhibiteur de KRAS G12C et d'un anticorps anti-EGFR a produit des réponses chez environ un quart des patients atteints d'un cancer de l'intestin KRAS G12C lourdement prétraité, contre aucune avec la chimiothérapie standard, et a plus que doublé le délai avant progression.",
  "paper-crown-nejm-2020": "L'inhibiteur d'ALK de troisième génération lorlatinib a maintenu le cancer du poumon ALK-positif sous contrôle des années de plus que le crizotinib et a largement prévenu les métastases cérébrales ; à cinq ans, la plupart des patients sous lorlatinib n'avaient toujours pas progressé.",
  "paper-dellphi-301-nejm-2023": "Un anticorps bispécifique qui attire les lymphocytes T sur les cellules du cancer du poumon à petites cellules a produit des réponses chez 40% des patients dont le cancer était revenu après chimiothérapie, avec une durée bien supérieure à celle de tout médicament antérieur dans cette situation.",
  "paper-depmap-tsherniak-cell-2017": "Des criblages RNAi à l'échelle du génome sur 501 lignées cellulaires cancéreuses, analysés avec l'algorithme DEMETER pour éliminer le bruit hors cible, ont identifié 769 gènes dont dépendent des sous-ensembles de cancers et ont montré que la plupart des dépendances peuvent être prédites à partir des caractéristiques moléculaires de la cellule.",
  "paper-destiny-breast06-nejm-2024": "Administré comme premier traitement de type chimiothérapie après l'échec de l'hormonothérapie, trastuzumab deruxtecan a retardé la progression d'environ cinq mois par rapport à la chimiothérapie standard, y compris dans les tumeurs où HER2 était à peine détectable.",
  "paper-detect-a-science-2020": "La première étude interventionnelle prospective d'un test sanguin multi-analytes (CancerSEEK) chez des personnes sans symptômes : 26 cancers ont d'abord été détectés par le test sanguin, la plupart localisés, et le test a à peu près doublé le nombre de cancers repérés par le dépistage standard.",
  "paper-doll-peto-50-year-doctors-bmj-2004": "Après avoir suivi 34 439 médecins hommes pendant 50 ans, les fumeurs de toute une vie sont morts en moyenne environ 10 ans plus tôt que les personnes n'ayant jamais fumé, et arrêter à 60, 50, 40 ou 30 ans permettait de récupérer environ 3, 6, 9 ans ou la totalité des 10 ans.",
  "paper-drug-dosing-conundrum-nejm-2021": "Les responsables de l'oncologie de la FDA ont soutenu que le paradigme de la dose maximale tolérée hérité de la chimiothérapie aboutit à des thérapies ciblées et des immunothérapies dosées bien au-delà du nécessaire, en prenant le sotorasib (960 mg contre 240 mg) comme cas d'étude, et ont lancé Project Optimus pour exiger l'optimisation de la dose avant l'approbation.",
  "paper-dynamic-nejm-2022": "Donner la chimiothérapie uniquement aux patients présentant de l'ADN tumoral dans le sang après la chirurgie a réduit le recours à la chimiothérapie de 28% à 15%, sans perte de survie sans récidive à deux ans.",
  "paper-e1910-blinatumomab-mrd-negative-all-nejm-2024": "Administrer le bispécifique blinatumomab à des adultes dont la leucémie était déjà indétectable après la chimiothérapie a fait passer la survie à trois ans de 68% à 85%.",
  "paper-echelon-1-brentuximab-avd-nejm-2018": "Remplacer la bléomycine par le conjugué anticorps-médicament anti-CD30 brentuximab vedotin a modestement amélioré le contrôle de la maladie dans le lymphome de Hodgkin avancé et, à six ans, a amélioré la survie.",
  "paper-elevate-tn-acalabrutinib-lancet-2020": "Dans ELEVATE-TN, l'acalabrutinib, un inhibiteur de BTK de deuxième génération, avec ou sans anticorps, a réduit le risque de progression de 80-90% par rapport à chlorambucil-obinutuzumab chez des patients âgés ou fragiles atteints de CLL.",
  "paper-eliana-tisagenlecleucel-nejm-2018": "Dans 25 centres, 81% des enfants et jeunes adultes atteints de ALL en rechute ou réfractaire sont entrés en rémission après une seule perfusion de tisagenlecleucel, et la moitié étaient encore sans événement un an plus tard.",
  "paper-epcore-nhl-1-epcoritamab-jco-2023": "Dans EPCORE NHL-1, l'anticorps bispécifique prêt à l'emploi epcoritamab a produit des réponses chez 63% des patients atteints de lymphome agressif en rechute, dont beaucoup chez qui la CAR-T avait échoué.",
  "paper-galaxy-signatera-nat-med-2023": "Chez 1 039 patients japonais opérés d'un cancer colorectal, un test Signatera positif à la semaine 4 s'accompagnait d'un risque de récidive dix fois plus élevé, et seuls les patients ctDNA positifs semblaient tirer bénéfice de la chimiothérapie adjuvante.",
  "paper-gerlinger-intratumour-heterogeneity-nejm-2012": "Le séquençage de plusieurs régions de quatre cancers du rein et de leurs métastases a montré qu'environ deux tiers des mutations n'étaient pas partagées par l'ensemble de la tumeur, que des signatures génétiques de bon et de mauvais pronostic coexistaient dans la même tumeur, et que des régions différentes avaient touché indépendamment les mêmes gènes.",
  "paper-hallmarks-new-dimensions-cancer-discov-2022": "Le troisième article sur les hallmarks a proposé deux nouvelles caractéristiques (le déverrouillage de la plasticité phénotypique, les cellules sénescentes) et deux nouvelles caractéristiques facilitatrices (la reprogrammation épigénétique non mutationnelle, les microbiomes polymorphes), portant le cadre à quatorze éléments.",
  "paper-hallmarks-of-cancer-cell-2000": "Hanahan et Weinberg ont condensé des décennies de biologie du cancer en six capacités acquises communes à tous les cancers, offrant au domaine un cadre organisateur commun qui a été cité plus que tout autre article sur le cancer.",
  "paper-harmoni-2-lancet-2025": "Dans le premier essai randomisé à battre directement le pembrolizumab, un seul anticorps bloquant à la fois PD-1 et VEGF a presque doublé le délai avant progression dans le cancer du poumon PD-L1 positif, même si les données de survie étaient encore immatures.",
  "paper-hodi-ipilimumab-melanoma-nejm-2010": "Bloquer le frein immunitaire CTLA-4 a été le premier traitement de l'histoire à prolonger la vie dans le mélanome métastatique, avec environ un patient sur cinq en vie à deux ans et une nouvelle classe d'effets secondaires auto-immuns.",
  "paper-hpv-vaccine-sweden-nejm-2020": "Parmi 1.7 million de filles et de femmes suédoises, la vaccination quadrivalente contre le HPV a réduit le cancer invasif du col de l'utérus de 88% lorsqu'elle était administrée avant 17 ans et d'environ la moitié entre 17 et 30 ans.",
  "paper-imbrave150-nejm-2020": "L'association de l'immunothérapie atezolizumab et de l'anticorps anti-vaisseaux sanguins bevacizumab a permis aux patients atteints de carcinome hépatocellulaire avancé de vivre plus longtemps qu'avec le sorafenib, mettant fin à une décennie pendant laquelle rien n'avait fait mieux que ce médicament.",
  "paper-imvigor011-nejm-2025": "Les patients dont le sang est devenu positif pour l'ADN tumoral après cystectomie ont vécu plus longtemps avec l'atezolizumab qu'avec le placebo ; les patients restés ctDNA-négatifs ont bien évolué sans aucun traitement. C'est le premier essai adjuvant guidé par le ctDNA à améliorer la survie.",
  "paper-ino-vate-inotuzumab-all-nejm-2016": "Un conjugué anticorps-médicament ciblant CD22 a produit une rémission complète chez 81% des adultes atteints de ALL en rechute contre 29% sous chimiothérapie, au prix d'une toxicité hépatique chez environ un patient sur dix.",
  "paper-iris-imatinib-nejm-2003": "L'imatinib a largement surpassé le traitement standard précédent dans la CML nouvellement diagnostiquée, et le suivi à long terme a montré que la plupart des patients étaient en vie à dix ans.",
  "paper-iwai-pdl1-tumour-escape-pnas-2002": "Une décennie après le clonage de PD-1 par le groupe de Honjo (1992), cette étude a montré que les cellules tumorales exprimant PD-L1 résistent à la destruction par les lymphocytes T cytotoxiques chez la souris, et qu'un anticorps anti-PD-L1 ou l'absence de PD-1 rétablit le rejet de la tumeur, fondement de la thérapie PD-1/PD-L1.",
  "paper-jain-talicabtagene-lancet-haem-2025": "Le rapport de l'essai à l'origine de la première thérapie CAR-T de l'Inde : environ trois patients sur quatre atteints de lymphome ou de leucémie, lourdement prétraités, ont répondu à des cellules conçues et fabriquées à Mumbai.",
  "paper-jaiswal-chip-nejm-2014": "L'ADN sanguin de 17 182 personnes a montré que des clones porteurs de mutations associées à la leucémie (surtout DNMT3A, TET2, ASXL1) sont présents chez environ 10% des personnes de plus de 70 ans, multipliant par 11 le risque de cancer du sang et, de façon inattendue, celui d'infarctus et d'accident vasculaire cérébral.",
  "paper-juliet-tisagenlecleucel-dlbcl-nejm-2019": "Chez des adultes atteints d'un lymphome agressif après au moins deux traitements antérieurs, le tisagenlecleucel a produit des réponses chez 52% et des réponses complètes chez 40%, dont la plupart se sont maintenues.",
  "paper-karmma-3-ide-cel-nejm-2023": "Le premier essai randomisé de CAR-T dans le myélome a triplé la survie médiane sans progression (13.3 contre 4.4 mois) par rapport aux combinaisons standard après deux à quatre lignes antérieures.",
  "paper-katherine-nejm-2019": "Les femmes dont le cancer du sein HER2 positif était encore présent à la chirurgie après chimiothérapie et trastuzumab avaient deux fois moins de risque de rechute si leur traitement post-opératoire était remplacé par l'anticorps conjugué T-DM1 au lieu de poursuivre le trastuzumab.",
  "paper-keynote-048-lancet-2019": "Le pembrolizumab, seul dans les tumeurs PD-L1-positives ou associé à la chimiothérapie, a permis aux patients atteints d'un cancer épidermoïde de la tête et du cou récidivant ou métastatique de vivre plus longtemps qu'avec l'ancien standard à base de cetuximab.",
  "paper-keynote-177-nejm-2020": "Pour les environ 5% de cancers de l'intestin métastatiques présentant un défaut de réparation des mésappariements de l'ADN, le pembrolizumab seul a doublé le temps sans progression par rapport à la chimiothérapie, avec beaucoup moins d'effets secondaires et de nombreuses rémissions durables.",
  "paper-keynote-189-nejm-2018": "L'ajout du pembrolizumab à la chimiothérapie standard a réduit d'environ moitié le risque de décès dans le cancer du poumon non épidermoïde nouvellement diagnostiqué, quel que soit le niveau de PD-L1, faisant de la chimio-immunothérapie le premier traitement par défaut.",
  "paper-keynote-564-nejm-2021": "Un an de pembrolizumab après chirurgie d'un cancer du rein à haut risque a réduit les récidives d'environ un tiers et, lors du suivi ultérieur, est devenu le premier traitement adjuvant à prolonger la vie des patients atteints d'un cancer du rein.",
  "paper-keynote-942-lancet-2024": "Un vaccin fabriqué sur mesure à partir des mutations de la tumeur de chaque patient, administré avec le pembrolizumab après une chirurgie pour mélanome à haut risque, a réduit les récidives d'environ 44 % par rapport au pembrolizumab seul dans un essai randomisé de taille moyenne, premier signe que les vaccins personnalisés contre le cancer peuvent fonctionner.",
  "paper-keynote-a18-lancet-2024": "L'ajout du pembrolizumab à la chimioradiothérapie standard du cancer du col de l'utérus localement avancé à haut risque a réduit la progression de 30 % et a ensuite amélioré la survie, première avancée systémique dans ce contexte depuis l'ajout du cisplatin à la radiothérapie en 1999.",
  "paper-le-mmr-deficiency-pd1-nejm-2015": "Pembrolizumab a fait régresser les tumeurs chez 40% des cancers colorectaux et 71% des autres cancers présentant un défaut de réparation des mésappariements de l'ADN, mais chez aucun de ceux dont la réparation était intacte, reliant la réponse à l'immunothérapie à la charge mutationnelle.",
  "paper-le-mmr-deficiency-science-2017": "Chez 86 patients atteints de 12 cancers dMMR différents, pembrolizumab a produit des réponses chez 53% et des réponses complètes chez 21%, ce qui a conduit à la première approbation d'un médicament anticancéreux fondée sur un marqueur génétique plutôt que sur la localisation de la tumeur.",
  "paper-leach-allison-ctla4-blockade-science-1996": "L'injection à des souris d'un anticorps bloquant le récepteur inhibiteur des lymphocytes T CTLA-4 a provoqué le rejet de carcinomes du côlon et de fibrosarcomes établis et protégé contre une nouvelle exposition, l'expérience fondatrice de l'immunothérapie par blocage des points de contrôle.",
  "paper-lynch-frameshift-vaccine-ccr-2020": "Un vaccin composé de trois peptides issus de décalages du cadre de lecture, communs à presque toutes les tumeurs à instabilité des microsatellites, s'est révélé sûr et a induit des réponses immunitaires chez tous les patients atteints d'un cancer colorectal MSI, ouvrant la voie à des vaccins d'interception du cancer pour le syndrome de Lynch.",
  "paper-magnetismm-3-elranatamab-natmed-2023": "Elranatamab a produit des réponses chez 61% des patients atteints de myélome lourdement prétraités et a montré que l'administration peut être espacée à toutes les deux semaines une fois que les patients répondent.",
  "paper-maia-daratumumab-rd-nejm-2019": "L'ajout de l'anticorps anti-CD38 daratumumab au traitement standard lenalidomide-dexamethasone a réduit le risque de progression ou de décès d'environ 44% chez des patients âgés atteints de myélome, et a par la suite prolongé la survie.",
  "paper-majestec-1-teclistamab-nejm-2022": "Un anticorps prêt à l'emploi qui attire les lymphocytes T sur les cellules de myélome a produit des réponses chez 63% des patients après une médiane de cinq traitements antérieurs, sans l'attente liée à la fabrication de cellules.",
  "paper-martincorena-somatic-mutations-normal-skin-science-2015": "Le séquençage profond de 234 minuscules biopsies de peau normale de paupière chez quatre personnes a révélé des milliers de clones porteurs de mutations motrices du cancer, avec environ un cinquième à un tiers des cellules porteuses de mutations de NOTCH1, montrant que les mutations motrices sont fréquentes dans les tissus sains.",
  "paper-masai-lancet-oncol-2023": "Dans le premier essai randomisé de l'IA en mammographie de dépistage en population, la lecture assistée par IA a détecté 20% de cancers de plus que la double lecture standard sans augmenter les faux positifs, et a réduit le travail de lecture de 44%.",
  "paper-mathur-ncrp-cancer-statistics-2020": "Le décompte officiel des cancers en Inde : environ 1,39 million de nouveaux cancers en 2020, dominés par le sein, le poumon, la bouche, le col de l'utérus et la langue, la plupart des cancers du sein, du col et de la tête et du cou n'étant découverts qu'au stade localement avancé.",
  "paper-maude-ctl019-all-nejm-2014": "La première série de taille notable de thérapie CAR-T anti-CD19 a montré une rémission complète chez 90% des patients atteints d'une leucémie résistante à tous les autres traitements, avec des cellules modifiées persistantes et une toxicité nouvelle mais traitable.",
  "paper-monarche-jco-2020": "L'ajout de deux ans de l'inhibiteur de CDK4/6 abemaciclib à l'hormonothérapie standard après la chirurgie a réduit d'un quart le risque de récidive du cancer chez les femmes atteintes d'une maladie à haut risque avec atteinte ganglionnaire.",
  "paper-murano-venetoclax-rituximab-nejm-2018": "Dans la CLL en rechute, une cure de durée limitée de venetoclax et rituximab a réduit le risque de progression de plus de 80% par rapport à bendamustine et rituximab, et a ensuite amélioré la survie.",
  "paper-nadina-nejm-2024": "Administrer seulement deux cycles d'immunothérapie combinée avant l'ablation des ganglions lymphatiques du mélanome a réduit les rechutes de plus des deux tiers par rapport à un an d'immunothérapie standard après la chirurgie, et la plupart des patients n'ont eu besoin d'aucun traitement supplémentaire.",
  "paper-napoli-3-lancet-2023": "Une chimiothérapie à quatre médicaments construite autour de l'irinotécan liposomal a prolongé la survie dans le cancer du pancréas métastatique d'environ deux mois par rapport au doublet le plus utilisé, le premier essai de première ligne positif depuis dix ans.",
  "paper-natalee-nejm-2024": "Trois ans de l'inhibiteur de CDK4/6 ribociclib ajouté à l'hormonothérapie ont réduit les rechutes dans le cancer du sein à récepteurs hormonaux positifs de stade II-III, y compris chez certaines patientes sans atteinte ganglionnaire.",
  "paper-netter-2-lancet-2024": "Utiliser le médicament radioactif lutétium dotatate en premier traitement des tumeurs neuroendocrines à croissance plus rapide, plutôt que de le garder pour plus tard, a presque triplé le temps sans progression par rapport à l'octréotide à forte dose.",
  "paper-nhs-galleri-design-cancers-2022": "L'article de conception de NHS-Galleri est le protocole d'un essai randomisé de 140,000 personnes en Angleterre qui teste si trois tests sanguins Galleri annuels réduisent les diagnostics de cancer à un stade avancé (III-IV) ; c'est le premier essai MCED dimensionné pour un critère de déplacement de stade.",
  "paper-niagara-nejm-2024": "Ajouter l'immunothérapie durvalumab à la chimiothérapie avant l'ablation de la vessie, puis la poursuivre ensuite, a réduit les rechutes et les décès dans le cancer de la vessie infiltrant le muscle, la première amélioration par rapport à la chimiothérapie néoadjuvante en vingt ans.",
  "paper-niche-2-nejm-2024": "Deux doses d'immunothérapie sur quatre semaines avant la chirurgie n'ont laissé que peu ou pas de tumeur vivante chez 95% des patients atteints d'un cancer du côlon avec déficience de la réparation des mésappariements, et aucun n'avait rechuté à trois ans.",
  "paper-niche-2-neoadjuvant-colon-nejm-2024": "Dans NICHE-2, quatre semaines de blocage des points de contrôle avant la chirurgie ont éliminé la quasi-totalité de la tumeur chez 95% des patients atteints d'un cancer du côlon déficient en réparation des mésappariements, et aucun n'avait rechuté à trois ans.",
  "paper-nlst-nejm-2011": "Trois scanners annuels à faible dose ont réduit d'un cinquième les décès par cancer du poumon par rapport aux radiographies thoraciques chez les gros fumeurs actuels et anciens.",
  "paper-ostrem-kras-g12c-nature-2013": "Grâce à des criblages par ancrage disulfure, le laboratoire de Shokat a trouvé de petites molécules qui se lient de façon covalente à la cystéine mutante de KRAS G12C dans une poche jusque-là inconnue sous le switch II, verrouillant l'oncoprotéine dans son état inactif lié au GDP.",
  "paper-pacific-nejm-2017": "Administrer l'immunothérapie durvalumab pendant un an après la chimioradiothérapie d'un cancer du poumon de stade III non résécable a triplé le délai avant progression et a fait passer la survie à cinq ans d'environ un tiers à plus de 40%.",
  "paper-paola-1-nejm-2019": "L'ajout de l'inhibiteur de PARP olaparib au bevacizumab après la chimiothérapie de première ligne du cancer de l'ovaire avancé a à peu près doublé le temps sans progression chez les femmes dont la tumeur présentait une réparation de l'ADN défectueuse, mais n'a rien apporté à celles qui n'en avaient pas.",
  "paper-pathfinder-lancet-2023": "Chez 6,621 adultes de plus de 50 ans, le test Galleri a signalé un signal de cancer chez 1.4 % d'entre eux, dont 38 % avaient effectivement un cancer ; le bilan diagnostique a pris environ deux mois pour les vrais positifs et plus de cinq mois pour les faux positifs.",
  "paper-perseus-dara-vrd-transplant-nejm-2024": "L'ajout de daratumumab à l'induction standard à trois médicaments, à la greffe et à l'entretien a réduit la progression ou le décès de 58% et a porté la négativité de la MRD à trois quarts des patients.",
  "paper-polarix-polatuzumab-rchp-nejm-2022": "Remplacer un médicament de chimiothérapie du R-CHOP par un conjugué anticorps-médicament ciblant CD79b a modestement réduit la progression (PFS à 2 ans de 76,7% contre 70,2%) sans modifier la survie ni les effets secondaires.",
  "paper-prasad-surrogate-endpoints-jama-im-2015": "Une revue systématique de 36 méta-analyses au niveau des essais a constaté que dans plus de la moitié des cas le critère de substitution (taux de réponse, survie sans progression) était faiblement corrélé à la survie globale, et qu'environ un quart seulement montrait une corrélation forte.",
  "paper-quantum-first-quizartinib-lancet-2023": "Ajouter l'inhibiteur de FLT3 quizartinib à la chimiothérapie standard, et le poursuivre jusqu'à trois ans, a environ doublé la survie médiane dans la leucémie aiguë myéloïde avec FLT3-ITD.",
  "paper-relativity-047-nejm-2022": "L'ajout au nivolumab d'un anticorps contre un second frein immunitaire, LAG-3, a retardé la progression du mélanome avancé par rapport au nivolumab seul, avec bien moins d'effets secondaires graves que l'association avec l'ipilimumab.",
  "paper-rohaas-til-vs-ipilimumab-nejm-2022": "Dans un essai en face à face, la thérapie par lymphocytes infiltrant la tumeur a réduit de moitié le risque de progression par rapport à l'ipilimumab dans des mélanomes qui, pour la plupart, avaient déjà échappé au blocage de PD-1.",
  "paper-rojas-mrna-neoantigen-vaccine-pancreatic-nature-2023": "Des vaccins à mRNA individualisés codant jusqu'à 20 des mutations tumorales de chaque patient ont généré de fortes réponses des cellules T chez la moitié des patients atteints d'un cancer du pancréas après chirurgie, et ces répondeurs ont eu beaucoup moins de rechutes.",
  "paper-ruby-nejm-2023": "Ajouter l'anticorps anti-PD-1 dostarlimab à la chimiothérapie de première ligne du cancer de l'endomètre avancé a réduit la progression de 72% dans les tumeurs avec déficit de réparation des mésappariements et d'environ un tiers dans l'ensemble, puis a amélioré la survie.",
  "paper-solo-1-nejm-2018": "Chez les femmes atteintes d'un cancer de l'ovaire avancé avec mutation BRCA, deux ans d'inhibiteur de PARP olaparib après la chimiothérapie ont réduit le risque de progression ou de décès de 70%, et des années plus tard beaucoup plus d'entre elles étaient encore en vie.",
  "paper-spotlight-lancet-2023": "Dans les cancers de l'estomac exprimant la protéine Claudin 18.2, l'ajout de l'anticorps zolbetuximab à la chimiothérapie a prolongé la survie de près de trois mois, faisant de Claudin 18.2 un nouveau biomarqueur à rechercher.",
  "paper-stampede-abiraterone-nejm-2017": "Donner dès le départ l'abiraterone, un médicament agissant sur la voie hormonale, en plus de la suppression standard de la testostérone, a réduit les décès de plus d'un tiers chez les hommes nouvellement diagnostiqués d'un cancer de la prostate à haut risque ou métastatique.",
  "paper-stupp-temozolomide-nejm-2005": "Ajouter la chimiothérapie orale témozolomide pendant et après la radiothérapie a prolongé la survie médiane dans le glioblastome d'environ deux mois et demi et a plus que doublé le nombre de patients en vie à deux ans ; vingt ans plus tard, c'est toujours le standard.",
  "paper-swog-s1826-nivolumab-avd-nejm-2024": "L'ajout d'un anticorps anti-PD-1 à la chimiothérapie a surpassé le standard à base de brentuximab, avec 92 % des patients sans progression à deux ans et moins d'atteintes nerveuses.",
  "paper-tcga-pancancer-atlas-cell-2018": "Le point d'orgue de The Cancer Genome Atlas a intégré des données d'ADN, d'ARN, de protéines et de méthylation sur environ 10 000 tumeurs, montrant que la cellule d'origine domine la classification moléculaire mais que certains cancers se regroupent au-delà des organes.",
  "paper-topalian-anti-pd1-nejm-2012": "Nivolumab a fait régresser les tumeurs chez environ un cinquième à un quart des patients atteints de trois cancers avancés différents, avec des réponses ayant duré plus d'un an et un indice que le PD-L1 sur la tumeur prédisait le bénéfice.",
  "paper-tracerx-100-nejm-2017": "Le séquençage multirégional de 327 régions issues des 100 premiers cancers du poumon de TRACERx a montré que la plupart des mutations conductrices sont précoces et partagées tandis que le chaos du nombre de copies continue d'évoluer, et que les tumeurs à forte hétérogénéité du nombre de copies avaient près de cinq fois plus de risque de rechuter ou de tuer le patient.",
  "paper-tracerx-evolution-nature-2023": "L'analyse de 1 644 régions tumorales provenant de 421 patients a confirmé que les expansions sous-clonales et le doublement du génome entier prédisent la rechute, a cartographié quels gènes conducteurs sont sélectionnés tardivement et a montré que le sous-clone qui métastase est souvent une population minoritaire dans la tumeur primitive.",
  "paper-transform-liso-cel-lancet-2022": "Dans TRANSFORM, un second CAR-T anti-CD19, le lisocabtagene maraleucel, a lui aussi surpassé la chimiothérapie suivie de greffe en deuxième ligne, avec un faible taux d'effets secondaires sévères.",
  "paper-tropion-breast01-jco-2024": "Le conjugué anticorps-médicament dirigé contre TROP2 Dato-DXd a retardé la progression d'environ deux mois par rapport à la chimiothérapie, mais les patientes n'ont pas vécu plus longtemps, ce qui a bloqué son approbation dans le cancer du sein.",
  "paper-ucart19-allogeneic-car-t-lancet-2020": "Des cellules CAR-T prêtes à l'emploi, fabriquées à partir d'un donneur sain et modifiées génétiquement pour éviter le rejet et la maladie du greffon contre l'hôte, ont produit une rémission chez 14 des 21 patients atteints de ALL en rechute.",
  "paper-viale-a-venetoclax-azacitidine-nejm-2020": "L'ajout de l'inhibiteur de BCL-2 venetoclax à l'azacitidine a plus que doublé les taux de rémission et prolongé la survie médiane de 9.6 à 14.7 mois chez les patients atteints d'AML inaptes à un traitement intensif.",
  "paper-vision-nejm-2021": "Un médicament radioactif qui se fixe sur la protéine PSMA des cellules du cancer de la prostate a permis à des hommes atteints d'un cancer de la prostate métastatique lourdement prétraité de vivre environ quatre mois de plus, faisant de la thérapie par radioligands un traitement courant.",
  "paper-vogelstein-cancer-genome-landscapes-science-2013": "En synthétisant la première génération de séquençage des génomes du cancer, Vogelstein et ses collègues ont conclu qu'environ 140 gènes peuvent provoquer un cancer lorsqu'ils sont mutés, qu'une tumeur solide typique compte 2 à 8 mutations conductrices parmi des dizaines de mutations passagères, et que tous les gènes conducteurs agissent par une douzaine de voies de signalisation.",
  "paper-zuma-1-axi-cel-nejm-2017": "Dans le lymphome réfractaire à la chimiothérapie, où la survie attendue était d'environ six mois, une seule perfusion de CAR-T a produit des réponses chez 82% des patients et une rémission à long terme chez environ 40%.",
  "paper-zuma-2-brexu-cel-mantle-cell-nejm-2020": "Dans le lymphome à cellules du manteau ayant cessé de répondre aux inhibiteurs de BTK, une seule perfusion de CAR-T a produit des réponses chez 93% des patients et des rémissions complètes chez deux tiers.",
  "paper-zuma-7-axi-cel-second-line-nejm-2022": "Pour le lymphome revenu en moins d'un an, passer directement à la CAR-T a surpassé l'approche vieille de plusieurs décennies de chimiothérapie puis greffe, et a ensuite amélioré la survie.",
  paradigm: "A prouvé que, pour les tumeurs à RAS normal naissant du côté gauche du côlon, un anticorps anti-EGFR l'emporte sur l'anticorps anti-VEGF comme premier partenaire de la chimiothérapie.",
  "parker-institute": "L'institut fondé par Sean Parker en 2016, qui mène la recherche en immunothérapie du cancer comme un seul réseau réunissant une douzaine de grands centres de cancérologie, en partageant données, échantillons et propriété intellectuelle.",
  "pascale-naples": "L'institut national du cancer du sud de l'Italie, leader mondial des essais d'immunothérapie du mélanome sous la direction de Paolo Ascierto.",
  "pathfinder-2": "PATHFINDER 2 est l'étude en vie réelle du test Galleri aux États-Unis qui constitue le cœur de son dossier de soumission à la FDA.",
  "patritumab-deruxtecan": "Un ADC dirigé contre HER3 avec la charge d'Enhertu, actif dans le cancer du poumon et dans tous les sous-types de cancer du sein, mais au parcours réglementaire cahoteux.",
  pazopanib: "Pazopanib est le seul inhibiteur multikinase approuvé pour le sarcome des tissus mous (hors tumeurs d'origine graisseuse), utilisé après échec de la chimiothérapie.",
  "pd-l1-testing": "Une coloration réalisée sur la biopsie tumorale qui mesure la quantité de protéine PD-L1, le signal 'ne m'attaquez pas', présente. Des niveaux plus élevés signifient généralement que les inhibiteurs de points de contrôle fonctionnent mieux, et de nombreuses autorisations exigent un score minimal.",
  pdgfra: "PDGFRA est un récepteur de facteur de croissance muté dans environ 10% des GIST, dont la mutation D842V, qui résiste à l'imatinib mais répond à l'avapritinib.",
  pemetrexed: "Pemetrexed est la chimiothérapie qui, avec un sel de platine, est devenue le premier traitement approuvé du mésothéliome en 2004, et reste aujourd'hui la base du traitement.",
  "percutaneous-hepatic-perfusion": "Isoler la circulation du foie avec des cathéters et des ballonnets afin d'y faire circuler du melphalan à haute dose et de le filtrer avant qu'il n'atteigne le reste du corps ; approuvé en 2023 pour le mélanome de l'œil qui s'est propagé au foie.",
  "peripheral-neuropathy": "Atteinte des nerfs due à la chimiothérapie, qui provoque des engourdissements, des fourmillements et des douleurs dans les mains et les pieds, et parfois une faiblesse ou une perte d'audition. Elle s'accumule à chaque dose, peut être permanente et est la principale raison pour laquelle l'oxaliplatine, les taxanes et la vincristine doivent être arrêtés ou réduits.",
  peritoneum: "La fine membrane qui tapisse la cavité abdominale et recouvre l'intestin. Les cancers de l'ovaire, de l'estomac, du côlon, de l'appendice et du pancréas y sèment souvent de nombreux petits dépôts, difficiles à traiter par les seuls médicaments.",
  perseus: "L'ajout du daratumumab à l'induction standard à trois médicaments et au traitement d'entretien a réduit de plus de moitié le risque de progression dans le myélome éligible à la greffe.",
  "pet-adapted-therapy": "Faire une imagerie après deux cycles de chimiothérapie ; si la tumeur s'est éteinte, donner moins de traitement, et sinon, en donner plus. Le lymphome de Hodgkin a été le pionnier de cette approche.",
  "pet-tracer-manufacturing": "Fabriquer les traceurs PSMA, FDG et de nouveaux traceurs selon les règles de fabrication des médicaments, et les livrer chaque jour.",
  petosemtamab: "Un anticorps à deux bras qui bloque l'EGFR tout en s'accrochant à LGR5, un marqueur des cellules souches cancéreuses, de sorte qu'il frappe les cellules qui font repousser les tumeurs.",
  "pgimer-chandigarh": "Le premier hôpital public de recherche du nord de l'Inde, avec d'importants programmes de médecine nucléaire, de radiothérapie et d'hématologie et un centre régional de cancérologie pour le Pendjab et l'Haryana.",
  "ph-positive-all": "La ALL Ph-positive est une leucémie aiguë lymphoblastique porteuse du chromosome Philadelphie. Autrefois la forme la plus grave, elle est aujourd'hui souvent la mieux contrôlée, grâce aux TKI et au blinatumomab.",
  phergain: "L'utilisation d'un PET précoce pour repérer les patientes répondeuses a permis de guérir un tiers des femmes atteintes d'un cancer du sein HER2-positif sans aucune chimiothérapie.",
  "photobiomodulation-mucositis": "Éclairer l'intérieur de la bouche avec une lumière rouge ou proche infrarouge de faible puissance avant et pendant le traitement prévient les ulcérations buccales sévères chez les personnes recevant une radiothérapie de la tête et du cou ou une chimiothérapie à haute dose en vue d'une greffe. Les recommandations sur la mucite la préconisent, même si peu de centres disposent encore de l'équipement.",
  photoimmunotherapy: "Un anticorps transporte un colorant sensible à la lumière jusqu'à la tumeur ; l'éclairage en lumière proche infrarouge fait ensuite éclater les cellules.",
  placebo: "Un traitement inactif d'apparence identique donné au groupe de comparaison d'un essai, de sorte que ni les patients ni les médecins ne puissent savoir qui reçoit le vrai médicament. Dans les essais en cancérologie, il est ajouté au traitement standard, jamais donné à sa place.",
  "platinum-etoposide": "Le platine plus étoposide est le socle de la chimiothérapie du cancer du poumon à petites cellules depuis plus de 40 ans, et il est désormais administré avec l'immunothérapie.",
  "point-of-care-cell-manufacturing": "Fabriquer les cellules CAR-T à l'hôpital ou à proximité, au lieu d'expédier les cellules vers une usine centrale et de les faire revenir.",
  polarix: "L'essai qui a amélioré le R-CHOP pour la première fois en vingt ans, en remplaçant la vincristine par un ADC.",
  "polatuzumab-vedotin": "Polatuzumab vedotin est un ADC dirigé contre CD79b qui, intégré au schéma classique R-CHOP, est devenu la première amélioration du traitement de première ligne du lymphome en vingt ans.",
  pomalidomide: "L'analogue de troisième génération du thalidomide pour le myélome résistant au lénalidomide et, depuis 2020, le premier nouveau médicament contre le sarcome de Kaposi en vingt ans.",
  ponatinib: "Ponatinib est le seul inhibiteur de BCR::ABL1 qui couvre la mutation de résistance T315I. En 2024, il est devenu le comprimé privilégié pour la LAL Ph-positive nouvellement diagnostiquée.",
  "ponsegromab-phase-2": "Le premier médicament à cibler l'hormone responsable de la cachexie cancéreuse : les patients sous la dose la plus élevée ont pris près de 3 kg de plus que sous placebo en 12 semaines et ont rapporté un meilleur appétit et plus d'activité.",
  pralsetinib: "Pralsetinib est le deuxième comprimé sélectif anti-RET pour le cancer du poumon, moins utilisé que le selpercatinib après un changement de propriétaire et de notice.",
  prame: "Une protéine normalement confinée au testicule que la plupart des mélanomes et de nombreux autres cancers activent ; les médicaments à récepteur de cellules T peuvent en reconnaître des fragments.",
  "precancer-ablation": "Détruire les cellules précancéreuses du col de l'utérus avec une sonde chauffée ou congelée en moins d'une minute, l'outil qui rend possible le dépistage-traitement là où il n'y a pas de chirurgiens.",
  "prehab-trial": "PREHAB a montré que quatre semaines d'entraînement encadré, d'apport protéique et de soutien avant une chirurgie du cancer de l'intestin réduisaient les complications sévères et accéléraient la récupération, dans un essai randomisé international de 251 patients.",
  prehabilitation: "La préhabilitation consiste en quelques semaines d'exercice structuré, de nutrition et de préparation psychologique entre le diagnostic et la chirurgie, pour que les patients arrivent plus en forme à l'opération et récupèrent plus vite.",
  "prince-of-wales-hospital-cuhk": "L'hôpital où le groupe de Dennis Lo a inventé le dépistage du cancer du nasopharynx par l'ADN de l'EBV plasmatique et la détection du cancer par l'ADN libre circulant.",
  "princess-maxima": "Le centre national de cancérologie pédiatrique des Pays-Bas, qui concentre l'ensemble des soins et de la recherche en oncologie pédiatrique néerlandais sur un seul campus à Utrecht.",
  "prmt5-mtap": "Une enzyme dont les cancers dépourvus du gène MTAP (environ 10-15% de toutes les tumeurs) dépendent davantage que les cellules normales ; de nouveaux inhibiteurs conçus pour exploiter cette différence sont en essais avancés.",
  "probiotics-antibiotic-stewardship-io": "Les antibiotiques dans les semaines précédant l'immunothérapie sont associés à de moins bons résultats, et les probiotiques achetés en magasin pourraient ne pas aider et pourraient nuire. Éviter les deux quand c'est possible est une précaution peu coûteuse.",
  progression: "Le cancer grossit ou s'étend malgré le traitement, ou après celui-ci. La progression signifie généralement que le médicament en cours a cessé d'agir et qu'il est temps de passer à la ligne suivante.",
  "prophylactic-cranial-irradiation": "Le cancer du poumon à petites cellules se propage si souvent au cerveau que les médecins irradiaient autrefois tout le cerveau à titre préventif. Les IRM régulières remettent aujourd'hui cette pratique en question.",
  "prostate-screening-psa-mri": "La question de savoir si les hommes doivent être dépistés pour le cancer de la prostate reste débattue ; l'approche moderne utilise un dosage sanguin du PSA suivi d'une IRM, qui trouve les cancers qui comptent tout en laissant tranquilles ceux qui sont inoffensifs.",
  "psycho-oncology": "La psycho-oncologie reconnaît et traite l'anxiété, la dépression, la peur de la récidive et la détresse existentielle qui touchent un tiers des personnes atteintes de cancer, au moyen du dépistage, d'une psychothérapie adaptée au cancer et de médicaments.",
  "pubmed-europepmc": "PubMed et Europe PMC forment ensemble l'index consultable de la littérature biomédicale ; chaque affirmation ici devrait pouvoir être rattachée à quelque chose qui s'y trouve.",
  "quality-of-life": "La façon dont un patient se sent et fonctionne réellement au quotidien : symptômes, énergie, humeur, capacité à travailler et à vivre normalement. Mesurée par des questionnaires, c'est le critère qui compte le plus avec la survie, et celui que les essais ont historiquement négligé.",
  "r-chop": "Le traitement initial standard du lymphome diffus à grandes cellules B : rituximab (un anticorps contre CD20) plus quatre médicaments de chimiothérapie (cyclophosphamide, doxorubicin, vincristine, prednisone), administrés toutes les trois semaines pendant six cycles. Il guérit environ 60% des patients.",
  "radioactive-iodine": "La radiothérapie ciblée originelle : les cellules thyroïdiennes absorbent l'iode, si bien que l'iode radioactif détruit le tissu thyroïdien résiduel et les métastases en épargnant tout le reste.",
  "radioiodine-therapy": "Utiliser l'appétit naturel de la thyroïde pour l'iode afin d'imager et de traiter le cancer de la thyroïde avec une forme radioactive de celui-ci. Le plus ancien des théranostiques, aujourd'hui utilisé de façon plus sélective qu'autrefois.",
  "radiopharmacy-network": "Les usines et les circuits de livraison qui fabriquent des traceurs radioactifs à courte durée de vie et les acheminent aux hôpitaux en quelques heures.",
  "radium-223": "Radium-223 a été le premier médicament émetteur de particules alpha jamais approuvé (2013). Il se fixe sur l'os comme le calcium et traite le cancer de la prostate qui ne s'est propagé qu'aux os.",
  "raludotatug-deruxtecan": "Raludotatug deruxtecan est un ADC ciblant CDH6, en phase 3 dans le cancer de l'ovaire résistant au platine.",
  ramucirumab: "Un anticorps qui bloque le récepteur du VEGF, approuvé dans le cancer du foie uniquement pour les patients ayant un taux sanguin élevé d'AFP, le premier médicament du HCC sélectionné par biomarqueur.",
  "randomised-trial": "Un essai dans lequel un tirage au sort (fait par ordinateur) décide du traitement que reçoit chaque patient, de sorte que les groupes sont identiques en tout point sauf le traitement. C'est le seul moyen fiable de prouver qu'un traitement apporte un bénéfice.",
  receptor: "Une protéine, généralement à la surface de la cellule, qui capte une molécule signal précise venue de l'extérieur et relaie le message à l'intérieur, comme une sonnette reliée aux commandes de la cellule.",
  recursion: "Recursion est une biotech centrée sur l'IA (fusionnée avec Exscientia en 2024) dont le portefeuille clinique en oncologie comprend un dégradeur de RBM39 et un inhibiteur de MEK pour la polypose adénomateuse familiale.",
  "red-processed-meat-reduction": "La viande transformée (bacon, jambon, saucisses) cause certainement le cancer de l'intestin ; la viande rouge le cause probablement. Le risque par personne est modeste, mais comme tant de gens en mangent, l'impact sur la population est important.",
  "reference-laboratories": "Les grands laboratoires qui réalisent la plupart des tests de biomarqueurs, et les fabricants de réactifs dont les colorations décident qui reçoit un médicament.",
  regeneron: "Regeneron fabrique Libtayo et possède un large portefeuille de bispécifiques CD3 (odronextamab, linvoseltamab).",
  "regina-elena-rome": "L'institut national du cancer de Rome, qui coordonne le réseau de recherche italien Alliance Against Cancer.",
  regorafenib: "Un successeur du sorafenib devenu le premier médicament de deuxième ligne dont il est prouvé qu'il prolonge la vie dans le cancer du foie (2017).",
  "relatlimab-nivolumab": "Opdualag associe relatlimab, le premier médicament ciblant le frein immunitaire LAG-3, au nivolumab pour le mélanome.",
  repotrectinib: "Un comprimé anti-ROS1 et NTRK qui agit aussi après l'échec d'autres médicaments anti-ROS1, avec les vertiges comme effet indésirable caractéristique.",
  "resection-margins": "Indique si le bord du tissu retiré est exempt de cancer. R0 signifie sain au microscope, R1 signifie cancer microscopique au bord, R2 signifie tumeur visible laissée en place. R0 est ce que veut dire 'résection complète'.",
  "resistance-training-cachexia": "Soulever des poids et manger suffisamment de protéines est le seul traitement dont il est démontré qu'il reconstruit le muscle chez les personnes atteintes de cachexie cancéreuse, mais la plupart sont trop malades pour le faire seules et les essais sont de petite taille.",
  retifanlimab: "Retifanlimab est un anticorps anti-PD-1 approuvé pour le carcinome à cellules de Merkel et, associé à la chimiothérapie, comme premier standard d'immunothérapie du cancer anal avancé.",
  "richard-finn": "A dirigé PALOMA-2, qui a fait du palbociclib un médicament de première ligne du cancer du sein, et IMbrave150, qui a fait de l'immunothérapie le standard du cancer du foie.",
  rigshospitalet: "L'hôpital national de référence du Danemark, un centre nordique de premier plan en hématologie, en essais de phase 1 et, avec Herlev, en thérapie par lymphocytes infiltrant les tumeurs.",
  ripretinib: "Un médicament de quatrième ligne pour les GIST qui verrouille KIT en position éteinte, quelle que soit la mutation de résistance acquise par la tumeur.",
  "risk-reducing-salpingectomy": "Retirer les trompes de Fallope, où débute la plupart des cancers de l'ovaire, lors d'une autre chirurgie pelvienne ou chez les femmes présentant un risque hérité.",
  "rna-splicing": "Les gènes sont découpés et recollés en messages avant d'être utilisés. Les cancers du sang portent souvent des mutations de la machinerie d'épissage, et les erreurs créent des protéines anormales qui pourraient servir de cibles ou de signaux pour le système immunitaire.",
  "robert-motzer": "L'investigateur en cancer du rein derrière sunitinib, CheckMate 214 et CLEAR, trois changements du traitement standard de première ligne.",
  "romana-1-2": "ROMANA 1 et 2 étaient deux essais de phase 3 d'un mimétique de l'hormone de l'appétit chez des patients atteints de cancer du poumon avec cachexie. Les patients ont gagné du muscle mais pas de force de préhension, ce qui a divisé les régulateurs : approuvé au Japon, rejeté en Europe.",
  ros1: "Une fusion génique présente dans environ 1-2% des cancers du poumon qui répond pendant des années à des comprimés ciblés, aujourd'hui dans leur troisième génération.",
  "roswell-park": "Roswell Park est le premier centre anticancéreux des États-Unis (1898), avec des points forts en immunothérapie et en fabrication de thérapies cellulaires.",
  "ruijin-hospital": "L'hôpital où l'acide tout-trans rétinoïque et l'arsenic ont guéri la leucémie aiguë promyélocytaire, et qui reste le premier centre d'hématologie de Chine.",
  ruxolitinib: "Ruxolitinib a été le premier inhibiteur de JAK : il réduit la rate et soulage les symptômes dans la myélofibrose et contrôle les numérations sanguines dans la polyglobulie de Vaquez, sans éliminer le clone de la maladie.",
  ryz101: "Une version à particules alpha de Lutathera pour les tumeurs neuroendocrines qui ne répondent plus à la version bêta.",
  sahlgrenska: "L'hôpital universitaire de l'ouest de la Suède, avec un centre de recherche sur le cancer connu pour ses modèles de mélanome, la dosimétrie des radionucléides et le cancer de l'enfant.",
  "san-raffaele": "L'hôpital de recherche de Milan, connu pour ses thérapies par lymphocytes T modifiés, la thérapie génique, la chirurgie pancréatique à haut volume et les essais dans le cancer du sein HER2.",
  "sankaranarayanan-rengaswamy": "Il a mené les grands essais indiens montrant qu'un seul cycle de test HPV réduit de moitié les décès par cancer du col de l'utérus et que l'examen visuel de la bouche réduit les décès chez les consommateurs de tabac, et il a dirigé l'étude à l'origine de la vaccination HPV à dose unique.",
  sano: "Pour le tiers des patients dont la tumeur disparaît après la chimioradiothérapie, surveiller étroitement et n'opérer qu'en cas de récidive a donné la même survie que la chirurgie immédiate.",
  "sant-orsola-bologna": "L'hôpital universitaire de Bologne, siège de l'institut d'hématologie Seràgnoli et centre italien de premier plan pour le myélome, le lymphome et les CAR-T.",
  "sara-tolaney": "Dirige la division d'oncologie mammaire du Dana-Farber et nombre des essais qui ont fait entrer les ADC et la désescalade thérapeutique dans la prise en charge du cancer du sein.",
  sarcopenia: "La sarcopénie est la perte de masse et de force musculaires. Dans le cancer, elle prédit des effets secondaires de la chimiothérapie plus sévères, plus de complications chirurgicales et une survie plus courte, et elle peut passer inaperçue chez des personnes qui paraissent de poids normal ou en surpoids.",
  "satricabtagene-autoleucel": "Satricabtagene autoleucel (satri-cel) est la première thérapie CAR-T approuvée pour une tumeur solide (cancer gastrique), en Chine.",
  "sean-parker": "En 2016, il a fondé et financé un institut qui mène la recherche en immunothérapie du cancer comme un seul réseau réunissant une douzaine de grands centres de cancérologie, en partageant données, échantillons et brevets plutôt que de se les disputer.",
  senescence: "Les cellules endommagées peuvent cesser définitivement de se diviser au lieu de mourir. Cela protège d'abord contre le cancer, mais les cellules sénescentes persistent, sécrètent des signaux inflammatoires et, après la chimiothérapie, peuvent favoriser la rechute des tumeurs ; les éliminer (sénolytiques) est donc une nouvelle stratégie.",
  sequoia: "Zanubrutinib a surpassé la chimio-immunothérapie dans la CLL non traitée et a obtenu un taux de 72% de patients sans progression à cinq ans dans le sous-groupe génétique le plus difficile.",
  serd: "Des médicaments qui ne se contentent pas de bloquer le récepteur des oestrogènes mais le marquent pour destruction, de sorte que la cellule cancéreuse perd complètement le récepteur. Les nouvelles versions orales fonctionnent même lorsque le récepteur a muté (ESR1) pour échapper aux anciens comprimés hormonaux.",
  "serena-6": "Le premier essai à modifier le traitement sur la base d'une analyse de sang plutôt que d'une imagerie : passer au camizestrant dès l'apparition d'une mutation ESR1 dans le sang a retardé la progression de sept mois.",
  servier: "Servier est le laboratoire pharmaceutique français privé qui a mis sur le marché le vorasidenib, le premier médicament du gliome de bas grade.",
  "shaare-zedek": "L'hôpital universitaire de Jérusalem tourné vers la communauté, où exerce Nathan Cherny, architecte de l'ESMO-MCBS, et qui mène une recherche de premier plan sur le dépistage populationnel de BRCA.",
  "shanghai-chest-hospital": "L'un des hôpitaux d'oncologie thoracique au plus grand volume d'activité du monde, siège du Shanghai Lung Cancer Center et de nombreux essais chinois d'inhibiteurs d'EGFR et d'ALK.",
  shield: "Le premier test sanguin approuvé par la FDA pour le dépistage du cancer colorectal (2024), qui peut désormais aussi, en option, signaler d'autres cancers.",
  sickkids: "Le plus grand hôpital pour enfants du Canada, où les cellules souches de tumeurs cérébrales ont été isolées pour la première fois et où le protocole de surveillance de Li-Fraumeni a été mis au point.",
  "sidney-farber": "En 1947-48, il a montré que l'antagoniste des folates aminopterin pouvait mettre la leucémie de l'enfant en rémission, le premier médicament à y parvenir. Il a ensuite bâti le Dana-Farber et, avec Mary Lasker, obtenu le National Cancer Act de 1971.",
  "signalling-pathway": "Une chaîne de protéines qui transmet un message de la surface de la cellule jusqu'au noyau, chacune activant la suivante comme dans une course de relais. Les médicaments anticancéreux tentent de briser un maillon de la chaîne.",
  sintilimab: "Sintilimab est l'anticorps anti-PD-1 d'Innovent, l'une des immunothérapies anticancéreuses les plus utilisées en Chine, avec des approbations dans les cancers du poumon, du foie, de l'œsophage et de l'estomac fondées sur les essais ORIENT.",
  "sleep-circadian-interventions": "La moitié des personnes atteintes d'un cancer dorment mal, d'où l'importance des interventions sur le sommeil et l'horloge biologique. La thérapie par la parole contre l'insomnie fonctionne bien et est sous-utilisée ; il n'est pas prouvé que corriger le sommeil ou les perturbations de l'horloge biologique modifie le cancer lui-même.",
  "smoking-cessation-after-diagnosis": "Arrêter de fumer après un diagnostic de cancer améliore la survie, réduit les complications du traitement et les seconds cancers, et constitue l'intervention de soutien la plus efficace que les services d'oncologie continuent de ne pas proposer systématiquement.",
  smoothened: "L'interrupteur de la voie de développement hedgehog qui reste bloqué en position allumée dans le carcinome basocellulaire et certains médulloblastomes ; trois comprimés approuvés le bloquent.",
  snmmi: "La société américaine de médecine nucléaire, éditrice du Journal of Nuclear Medicine et foyer professionnel de l'essor de la théranostique PSMA et neuroendocrine.",
  "sodium-thiosulfate": "Un vieil antidote dont deux essais pédiatriques ont prouvé qu'il divise par deux la perte auditive permanente due au cisplatine, et approuvé en 2022 comme premier médicament destiné à prévenir un effet secondaire de la chimiothérapie chez l'enfant.",
  "soft-text": "Chez les femmes plus jeunes, la mise au repos des ovaires associée à un inhibiteur de l'aromatase prévient davantage de récidives que le tamoxifen seul, avec les gains les plus importants chez les femmes à plus haut risque.",
  solti: "Un groupe académique de recherche sur le cancer du sein basé à Barcelone, connu pour ses essais guidés par des biomarqueurs qui utilisent les sous-types intrinsèques PAM50 pour choisir le traitement.",
  sonrotoclax: "Sonrotoclax est un successeur du venetoclax plus puissant et d'action plus courte. Il a été approuvé pour le lymphome à cellules du manteau en mai 2026 et fait l'objet d'essais de phase avancée avec zanubrutinib dans la CLL.",
  "southampton-cancer": "L'hôpital universitaire de Southampton et le premier centre du Royaume-Uni construit spécialement pour l'immunologie du cancer, connu pour l'ingénierie des anticorps et les essais dans le lymphome.",
  "soy-breast-cancer": "Pendant des années, on a conseillé aux femmes atteintes d'un cancer du sein d'éviter le soja parce qu'il contient des oestrogènes végétaux. De grandes études montrent qu'une consommation modérée d'aliments à base de soja est sans danger et peut légèrement réduire les récidives, y compris sous tamoxifène.",
  spect: "La SPECT et la scintigraphie osseuse sont un type plus ancien d'examen nucléaire, encore utilisé pour les métastases osseuses et pour vérifier où un médicament radioactif est allé après le traitement.",
  sso: "La société internationale des chirurgiens du cancer, éditrice des Annals of Surgical Oncology et coautrice des recommandations sur les marges et la désescalade qui ont changé la chirurgie du sein et du mélanome.",
  "sstr-pet": "Une TEP utilisant un imitateur radioactif d'hormone qui fait ressortir les tumeurs neuroendocrines et montre si le traitement radioactif correspondant fonctionnera.",
  stampede: "STAMPEDE est l'essai plateforme le plus long en oncologie, et a montré que le docetaxel comme l'abiraterone prolongent la vie lorsqu'ils sont débutés dès le premier diagnostic de maladie métastatique.",
  "stand-up-to-cancer": "Une organisation caritative issue de l'industrie du divertissement qui finance des Dream Teams multi-institutionnelles, avec l'AACR comme partenaire scientifique, pour faire passer rapidement les découvertes en essais cliniques.",
  "sterile-fill-finish": "Le remplissage aseptique (fill-finish) consiste à mettre le médicament fini en flacons dans des conditions stériles. C'est une cause fréquente de pénuries lorsque les capacités sont limitées.",
  "sting-agonist": "Des médicaments qui déclenchent l'\"alarme antivirus\" intégrée de la cellule à l'intérieur des tumeurs pour appeler les cellules immunitaires.",
  "structured-exercise-survivorship": "Un programme d'exercice supervisé et encadré pendant trois ans après le traitement d'un cancer de l'intestin a réduit les récidives et les décès dans un grand essai randomisé. C'est la première intervention sur le mode de vie dont il est prouvé qu'elle agit comme un médicament adjuvant.",
  "sunnybrook-odette": "L'un des plus grands centres de cancérologie du Canada, où les ultrasons focalisés ont ouvert pour la première fois la barrière hémato-encéphalique chez un patient et où le premier MR-linac du Canada a été installé.",
  "sustaining-proliferative-signaling": "Les cellules cancéreuses ne cessent de se dire de se diviser, en fabriquant leurs propres signaux de croissance ou en bloquant les récepteurs en position allumée.",
  "swi-snf-chromatin": "Une machine qui ouvre et ferme l'ADN pour que les gènes puissent être lus. Un cancer sur cinq en a une pièce défectueuse (ARID1A, SMARCA4, PBRM1), et la perte d'une pièce crée souvent une dépendance à sa jumelle, ce qui est la base de nouveaux médicaments de létalité synthétique.",
  "swog-s1826": "L'immunothérapie associée à la chimiothérapie a surpassé le meilleur schéma précédent avec beaucoup moins d'atteintes nerveuses, dans le premier essai sur le lymphome de Hodgkin à inclure ensemble enfants et adultes ; approuvé en mars 2026.",
  "sydney-childrens-hospitals-network": "Le plus grand réseau d'hôpitaux pédiatriques d'Australie, qui, avec le Children's Cancer Institute, dirige ZERO Childhood Cancer, un programme national de médecine de précision pour chaque enfant atteint de cancer.",
  tace: "Un cathéter introduit dans l'artère qui alimente une tumeur du foie délivre la chimiothérapie puis bouche le vaisseau, affamant la tumeur de l'intérieur.",
  tafasitamab: "Un anticorps anti-CD19 administré avec le lénalidomide aux patients atteints de lymphome qui ne peuvent pas recevoir de greffe ; en 2026, il a montré le premier gain en première ligne par rapport au R-CHOP dans la maladie à haut risque.",
  "talicel-phase-1-2": "L'essai à l'origine de la première approbation d'un CAR-T en Inde : environ trois patients sur quatre atteints de lymphome ou de leucémie lourdement prétraités ont répondu à une thérapie fabriquée à Mumbai.",
  "talimogene-laherparepvec": "Talimogene laherparepvec (T-VEC, Imlygic) a été le premier virus oncolytique approuvé (2015), injecté dans les lésions cutanées du mélanome.",
  "targeted-therapy-term": "Des médicaments conçus pour frapper une molécule précise dont le cancer dépend, généralement une protéine produite par un gène muté ou amplifié, tout en épargnant relativement les cellules normales. La tumeur est d'abord testée pour vérifier qu'elle porte la cible.",
  tazemetostat: "Tazemetostat a été le premier inhibiteur d'EZH2, approuvé pour le sarcome épithélioïde et le lymphome folliculaire en 2020 et retiré du marché mondial en 2026 après des cancers du sang secondaires.",
  "telisotuzumab-vedotin": "Telisotuzumab vedotin (Emrelis) est le premier ADC dirigé contre c-MET, approuvé en 2025 pour le cancer du poumon avec un taux élevé de protéine c-MET.",
  "texas-childrens": "L'un des plus grands centres de cancérologie pédiatrique des États-Unis, l'hôpital pour enfants de Baylor et fondateur du programme Global HOPE pour le cancer de l'enfant en Afrique.",
  "tgf-beta": "Un signal qui empêche les cellules normales de se diviser mais qui, une fois le cancer installé, change de camp : il construit un stroma cicatriciel, tient les cellules immunitaires à l'écart et pousse les cellules vers un état migratoire.",
  "the-christie": "The Christie est le plus grand centre de cancérologie sur un seul site d'Europe et le premier centre de protonthérapie du NHS au Royaume-Uni.",
  "thyroid-fna-molecular": "La cytoponction thyroïdienne à l'aiguille fine prélève un échantillon d'un nodule de la thyroïde et le classe sur une échelle à six niveaux ; quand le résultat est incertain, un test génétique sur le même échantillon peut souvent écarter un cancer et éviter la chirurgie.",
  "time-restricted-eating": "L'alimentation à horaires restreints consiste à manger dans une fenêtre de 8-12 heures par jour et à jeûner la nuit. Elle améliore un peu la glycémie et le poids ; on ignore si elle modifie le risque de cancer ou de récidive.",
  "tisotumab-vedotin": "Tisotumab vedotin est un ADC dirigé contre le facteur tissulaire, le premier à montrer un bénéfice de survie dans le cancer du col de l'utérus récidivant.",
  "tki-term": "Des comprimés qui bloquent l'enzyme servant d'interrupteur (une kinase) dont dépend un cancer donné : imatinib pour la CML, osimertinib pour le cancer du poumon EGFR, ibrutinib pour la CLL. Ils se prennent généralement chaque jour à la maison et sont poursuivis tant qu'ils agissent.",
  "tongji-hospital-wuhan": "Le plus grand hôpital du centre de la Chine, avec un centre de cancérologie connu pour l'oncologie gynécologique, la recherche en immunothérapie et un très vaste portefeuille d'essais.",
  "topoisomerase-i-payloads": "Les charges inhibitrices de la topoisomérase I sont la classe de charge utile derrière Enhertu, Trodelvy et Dato-DXd : des poisons qui piègent l'enzyme qui déroule l'ADN, de sorte que les cellules en division cassent leur propre ADN.",
  topotecan: "Topotecan est la chimiothérapie de deuxième ligne de longue date du cancer du poumon à petites cellules en rechute, et désormais le comparateur que les nouveaux médicaments doivent battre.",
  toripalimab: "Un bloqueur de PD-1 développé en Chine, devenu la première immunothérapie approuvée aux États-Unis pour le cancer du nasopharynx.",
  tovorafenib: "Tovorafenib est un comprimé contre la tumeur cérébrale la plus fréquente de l'enfant, le gliome de bas grade lié à des altérations de BRAF, approuvé en 2024.",
  "transfusion-support": "Les transfusions de globules rouges et de plaquettes, le fer et les agents stimulant l'érythropoïèse protègent les patients pendant la chimiothérapie et l'insuffisance médullaire ; les seuils restrictifs et la prudence vis-à-vis des ESA reflètent des essais montrant que plus n'est pas mieux.",
  "treatment-planning-systems": "Le logiciel qui calcule précisément la forme que doivent prendre les faisceaux de rayonnement et vérifie que la machine les a bien délivrés.",
  trog: "Le groupe d'essais de radiothérapie oncologique d'Australie et de Nouvelle-Zélande, qui a mené des essais ayant changé la pratique en matière d'hypofractionnement, de radiothérapie stéréotaxique et d'associations radiothérapie-médicaments.",
  ttfields: "Des électrodes portables qui délivrent des champs électriques alternatifs perturbant la division des cellules cancéreuses.",
  "tubulin-inhibitor-payloads": "Les charges inhibitrices de la tubuline ont été la première génération de charges des ADC modernes : des médicaments qui bloquent l'échafaudage de la cellule pour qu'elle ne puisse pas se diviser. Les effets secondaires nerveux et oculaires sont typiques.",
  "tum-munich": "L'hôpital de l'université technique de Munich, l'une des deux moitiés du Comprehensive Cancer Center Munich et un leader de l'imagerie PSMA et de la chimie des radiopharmaceutiques.",
  "tumour-grade": "À quel point les cellules cancéreuses paraissent anormales au microscope, du grade 1 (proche de la normale, lent) au grade 3 ou 4 (très anormal, rapide). Le grade décrit le comportement ; le stade décrit l'étendue.",
  "tumour-suppressor-gene": "Un gène dont le rôle normal est d'empêcher les cellules de se diviser ou de faire mourir les cellules endommagées. Le perdre supprime un frein, si bien que la cellule peut croître sans contrôle même sans accélérateur bloqué.",
  "uct-frankfurt": "Le centre universitaire de cancérologie de Francfort, héritier de l'institut de la « balle magique » de Paul Ehrlich, avec des points forts en leucémie, neuro-oncologie et thérapie cellulaire.",
  "uct-mainz": "Le centre médical universitaire où Uğur Şahin et Özlem Türeci ont bâti la science à l'origine de BioNTech et des vaccins personnalisés à mRNA contre le cancer.",
  "uganda-cancer-institute": "Le plus ancien institut de recherche sur le cancer d'Afrique de l'Est, fondé en 1967 pour étudier le lymphome de Burkitt, et aujourd'hui un centre national de cancérologie doté d'un partenariat avec le Fred Hutch et du premier bâtiment d'Afrique construit spécialement pour la recherche sur le cancer.",
  "uk-duesseldorf": "L'hôpital universitaire de Düsseldorf, partenaire de l'alliance de centres de cancérologie CIO et site de premier plan pour l'imagerie FAPI et PSMA sous la direction de Frederik Giesel.",
  "ultra-processed-food-ssb": "Les régimes riches en aliments transformés industriellement et en boissons sucrées sont associés à davantage de cancers, principalement par le biais de l'obésité, mais peut-être aussi par les additifs et les substances chimiques des emballages. Le sucre en lui-même ne 'nourrit' pas une tumeur comme le prétendent les réseaux sociaux.",
  "umc-utrecht": "Le centre de cancérologie universitaire néerlandais qui a inventé le MR-linac et se trouve au cœur de l'écosystème des organoïdes d'Utrecht et d'Oncode.",
  umrd: "Le test de recherche de cellules cancéreuses résiduelles n'en a trouvé aucune, jusqu'à la limite de sensibilité de l'analyse (souvent une cellule sur 100 000 ou un million). C'est la rémission la plus profonde que nous puissions mesurer et elle devient un objectif de traitement et un critère d'évaluation des essais dans les cancers du sang.",
  "uniklinik-koeln": "L'Uniklinik Köln gère le Centre d'oncologie intégrée et mène la génomique du cancer du poumon via le Network Genomic Medicine.",
  "uppsala-akademiska": "Le plus ancien hôpital universitaire de Suède, voisin de la clinique nationale de protonthérapie Skandion et centre de référence mondial pour les tumeurs neuroendocrines.",
  "usb-basel": "L'hôpital universitaire de Bâle, dans la ville d'origine de Roche et Novartis, avec une forte recherche en immunologie des tumeurs, en radiopharmaceutiques et sur les métastases du cancer du sein.",
  "usz-zurich": "L'hôpital universitaire et centre du cancer de Zurich, référence mondiale en neuro-oncologie, mélanome et imagerie tumorale à l'échelle de la cellule unique.",
  vaf: "La fraction des lectures d'ADN portant une mutation. Elle indique quelle part de l'échantillon est mutée et à quel point elle est clonale.",
  "vall-dhebron": "Vall d'Hebron est le premier hôpital espagnol de recherche sur le cancer et un leader mondial des essais de phase 1 et des essais d'ADC dans le cancer du sein.",
  varian: "Varian est le plus grand fabricant d'équipements de radiothérapie et mène les premiers essais chez l'humain de protonthérapie FLASH.",
  "varnimcabtagene-autoleucel": "La deuxième thérapie CAR-T approuvée en Inde, une version fabriquée à Bengaluru de la thérapie cellulaire académique anti-CD19 d'un hôpital espagnol, pour le lymphome qui est revenu après d'autres traitements.",
  "ventana-pd-l1-sp142": "La coloration PD-L1 qui décide qui peut recevoir l'atezolizumab, évaluée sur les cellules immunitaires plutôt que sur les cellules tumorales dans le cancer du sein.",
  vepdegestrant: "Vepdegestrant est le tout premier PROTAC approuvé (2026) : un comprimé qui marque le récepteur des œstrogènes pour sa destruction, destiné aux cancers du sein porteurs de mutations d'ESR1.",
  vimseltinib: "Vimseltinib est un comprimé approuvé en février 2025 pour la tumeur ténosynoviale à cellules géantes, une tumeur articulaire bénigne mais destructrice, offrant une alternative aux chirurgies répétées.",
  vinblastine: "Vinblastine est l'alcaloïde de la pervenche de l'ABVD, le protocole standard du lymphome de Hodgkin, et faisait autrefois partie des combinaisons à base de cisplatine qui ont pour la première fois guéri le cancer du testicule.",
  "viral-vector-manufacturing": "Produire les virus modifiés qui transportent un gène CAR dans les cellules T. La fabrication de vecteurs viraux est depuis longtemps un goulot d'étranglement pour la thérapie cellulaire et génique.",
  vision: "VISION est l'essai qui a établi la thérapie par radioligand dans le cancer de la prostate.",
  "vitamin-d-omega3-supplementation": "Le plus grand essai sur les comprimés de vitamine D et d'huile de poisson a constaté qu'ils ne préviennent pas le cancer. Une possible réduction des décès par cancer, et des indices de bénéfice après un diagnostic de cancer digestif, maintiennent la question ouverte.",
  vorasidenib: "Le premier traitement ciblé des tumeurs cérébrales de bas grade, qui retarde de plusieurs années le recours à la radiothérapie et à la chimiothérapie.",
  "vusolimogene-oderparepvec": "Vusolimogene oderparepvec est un virus de l'herpès modifié injecté dans les tumeurs de mélanome, approuvé en août 2026 avec nivolumab après échec de l'immunothérapie.",
  "warburg-effect-diet-claims": "Parce que les cellules cancéreuses brûlent beaucoup de glucose, beaucoup de gens en concluent que supprimer le sucre affame les tumeurs. La biologie est réelle ; la conclusion ne l'est pas. La glycémie est étroitement régulée et aucun essai ne montre que la restriction du sucre améliore l'évolution du cancer.",
  wehi: "Le plus ancien institut de recherche médicale d'Australie, où la famille BCL-2 des protéines de la mort cellulaire a été découverte, ce qui a conduit au venetoclax.",
  weizmann: "L'institut de recherche fondamentale d'Israël, dont les découvertes sur les récepteurs HER, p53, l'immunologie en cellule unique et le microbiome ont façonné la biologie du cancer.",
  whipple: "La grande opération pour les cancers de la tête du pancréas : le chirurgien retire la tête du pancréas, le duodénum, la vésicule biliaire et une partie du canal biliaire, puis reconnecte le tout.",
  who: "L'agence de santé de l'ONU qui fixe la politique mondiale contre le cancer : la stratégie d'élimination du cancer du col de l'utérus, la liste des médicaments essentiels, l'initiative sur les cancers de l'enfant et la classification des tumeurs.",
  "who-essential-medicines": "La liste de l'Organisation mondiale de la Santé des médicaments que tout système de santé devrait fournir, qui compte désormais environ 60 médicaments anticancéreux, du cyclophosphamide et du cisplatine au trastuzumab, à l'imatinib et aux inhibiteurs de PD-1, et qui oriente les achats et les prix dans les pays à faible revenu.",
  "whole-body-mri": "L'IRM corps entier est une IRM de tout le corps sans rayonnement, utilisée pour rechercher l'extension du myélome et pour dépister les personnes à haut risque héréditaire de cancer.",
  "whole-slide-scanners": "Les scanners qui transforment les lames de verre en images de plusieurs gigapixels, et les logiciels qui les stockent et les diffusent, sans lesquels l'IA en pathologie ne peut pas fonctionner.",
  "wits-charlotte-maxeke": "L'hôpital universitaire phare de Johannesburg et le pôle d'oncologie de l'université de Wits, qui gère le plus grand service public de radiothérapie et d'oncologie médicale d'Afrique du Sud et ouvre la voie aux cohortes africaines de cancer.",
  wrn: "Une enzyme qui déroule l'ADN et dont les cancers déficients en réparation des mésappariements ne peuvent se passer ; les premiers inhibiteurs de WRN sont en essais comme option sans chimiothérapie pour les tumeurs MSI-high qui échappent à l'immunothérapie.",
  "wustl-siteman": "A séquencé le premier génome de cancer (2008) et fait figure de leader dans la science des vaccins néoantigéniques et dans CIViC.",
  "yoda-project": "Le programme de Yale qui agit comme gestionnaire indépendant des données d'essais cliniques de Johnson & Johnson et d'autres promoteurs, permettant à des chercheurs extérieurs de réanalyser des essais, y compris des études en oncologie.",
  zenocutuzumab: "Zenocutuzumab est le premier médicament pour les cancers portés par des fusions du gène NRG1 ; il agit en empêchant HER3 de recevoir son signal de croissance.",
  "zhongshan-hospital-fudan": "Le principal hôpital général de Shanghai et un centre mondial de chirurgie et de recherche sur le cancer du foie, siège du Liver Cancer Institute.",
  zolbetuximab: "Zolbetuximab est le premier médicament dirigé contre Claudin 18.2, une protéine exposée à la surface des cellules du cancer de l'estomac. Ajouté à la chimiothérapie, il prolonge la survie de deux à trois mois ; les nausées en sont le prix.",
  zoldonrasib: "Le premier médicament visant spécifiquement KRAS G12D, la mutation unique la plus fréquente dans le cancer du pancréas. Les premières données en association, en 2026, ont montré une réponse chez la moitié des patients déjà traités.",
  "zuma-7": "L'essai qui a placé le CAR-T devant la greffe comme traitement de deuxième ligne du lymphome B à grandes cellules en rechute précoce, avec un bénéfice de survie.",
  // ---- third wave (2026-09) ----
  aaml0531: "L'ajout du conjugué anticorps-médicament gemtuzumab ozogamicin à la chimiothérapie a réduit le risque de rechute chez les enfants atteints de leucémie myéloïde aiguë. Des années après le retrait du médicament du marché américain, cet essai a contribué à le rendre de nouveau disponible pour les enfants.",
  abbott: "Géant du diagnostic qui fabrique le test vésical UroVysion, commercialise le test sanguin de Freenome pour le cancer de l'intestin et est en train d'acquérir Exact Sciences.",
  "abvd-beacopp": "Les protocoles de chimiothérapie qui guérissent la plupart des lymphomes de Hodgkin : l'ABVD (quatre médicaments, le standard de longue date), le BEACOPP allemand plus intensif, et des versions plus récentes qui remplacent la bleomycin par le brentuximab vedotin (A+AVD) ou ajoutent le nivolumab (N-AVD).",
  "ac-camargo": "Le premier centre anticancéreux spécialisé d'Amérique latine, fondé en 1953, doté d'un grand institut de recherche et du plus important internat d'oncologie de la région.",
  acns0331: "Cet essai cherchait à savoir si les enfants atteints d'un médulloblastome de risque standard pouvaient recevoir moins de radiothérapie sans danger. Réduire le complément de dose sur le lit tumoral s'est avéré sûr ; diminuer la dose sur l'ensemble du cerveau et de la moelle épinière chez les jeunes enfants ne l'était pas, si bien que 23,4 Gy reste le minimum pour la plupart d'entre eux.",
  "activating-invasion-metastasis": "Les cellules cancéreuses se détachent, envahissent les tissus, voyagent et colonisent d'autres organes, le processus responsable de la plupart des décès par cancer.",
  "active-surveillance-thyroid": "Surveiller par échographie les très petits cancers papillaires de la thyroïde plutôt que d'opérer, car la plupart ne grossissent jamais et presque aucun ne fait de mal.",
  "acupuncture-aromatase-inhibitor-arthralgia": "Les douleurs et la raideur articulaires sont la principale raison pour laquelle les femmes arrêtent prématurément les comprimés d'inhibiteurs de l'aromatase. Dans un grand essai randomisé, douze semaines d'acupuncture ont réduit ces douleurs davantage qu'une acupuncture simulée ou l'absence de traitement, et le bénéfice a persisté après la fin des séances.",
  "acupuncture-chemotherapy-neuropathy": "Les engourdissements, fourmillements ou douleurs des mains et des pieds après des taxanes, des sels de platine ou du bortezomib n'ont aucun traitement préventif reconnu. De petits essais suggèrent que l'acupuncture peut soulager les symptômes, mais ils sont trop petits et trop hétérogènes pour en être sûr ; c'est donc une option à essayer dans le cadre d'un essai ou avec un suivi attentif, plutôt qu'un traitement établi.",
  "acupuncture-hot-flushes": "Les bouffées de chaleur sous tamoxifen ou inhibiteurs de l'aromatase sont fréquentes, et le traitement hormonal substitutif est exclu. L'acupuncture a réduit les bouffées de chaleur dans plusieurs essais randomisés, dans l'un d'eux à peu près aussi bien que le médicament gabapentin et avec moins d'effets secondaires, même si les résultats face à une acupuncture simulée sont contrastés.",
  "adaptive-biotechnologies": "Adaptive Biotechnologies fabrique clonoSEQ, le test de séquençage autorisé par la FDA qui détecte une cellule leucémique sur un million et guide désormais le traitement dans la LAL, le myélome et la LLC.",
  "adc-after-adc-caution": "Donner un second ADC portant le même type de charge cytotoxique juste après le premier fonctionne souvent mal.",
  "adc-plus-io": "Un ADC tue les cellules tumorales d'une manière qui alerte le système immunitaire ; un inhibiteur de point de contrôle laisse le système immunitaire finir le travail.",
  adcendo: "Adcendo est une société danoise qui développe des conjugués anticorps-médicament, des anticorps qui acheminent un médicament cytotoxique directement jusqu'aux cellules cancéreuses, contre des cibles que peu d'autres explorent. Ses premiers médicaments sont en essais précoces chez l'humain, dont un pour le sarcome des tissus mous.",
  "add-aspirin": "Add-Aspirin est un essai portant sur 11 000 patients atteints de quatre cancers fréquents, au Royaume-Uni, en Irlande et en Inde, qui cherche à savoir si une aspirine quotidienne bon marché, prise après un traitement curatif, empêche le cancer de revenir.",
  adebrelimab: "L'adebrelimab est l'anticorps anti-PD-L1 de Hengrui, approuvé en Chine en première ligne du cancer bronchique à petites cellules de stade étendu sur la base de l'essai CAPSTONE-1.",
  adenocarcinoma: "Un carcinome issu des cellules glandulaires, celles qui produisent du mucus, du lait, des sucs digestifs ou des hormones. C'est le type le plus fréquent de cancer du sein, du poumon, du côlon, de la prostate, du pancréas et de l'estomac.",
  "adenocarcinoma-term": "Cancer issu des cellules glandulaires, celles qui tapissent les organes et produisent du mucus ou d'autres sécrétions. C'est le type le plus fréquent de cancer du poumon, du côlon, du pancréas, de la prostate, de l'estomac et du sein.",
  adriatic: "ADRIATIC a apporté la première avancée en 30 ans dans le traitement à visée curative du cancer bronchique à petites cellules : un an ou deux d'immunothérapie après la chimioradiothérapie prolonge la vie.",
  adt: "Supprimer la testostérone, l'hormone qui nourrit le cancer de la prostate, par des injections (ou des comprimés) qui empêchent les testicules de la produire, ou en retirant ceux-ci. C'est le pilier du traitement du cancer de la prostate avancé depuis 1941.",
  "advanced-accelerator-applications": "L'entreprise issue du CERN que Novartis a rachetée en 2018 pour Lutathera, et qui fabrique aujourd'hui Pluvicto ainsi que les kits d'imagerie Locametz et Netspot.",
  afatinib: "L'afatinib (Gilotrif) est un comprimé inhibiteur irréversible de l'EGFR pour le cancer du poumon, remarquable par son activité contre les mutations rares de l'EGFR (G719X, L861Q, S768I).",
  afp: "Une protéine produite par le foie fœtal que de nombreux cancers du foie réactivent ; dosée dans le sang pour le dépistage, le pronostic et pour sélectionner les patients candidats au ramucirumab.",
  agile: "Dans la LAM avec mutation IDH1, l'ajout d'ivosidenib à l'azacitidine a triplé la survie, l'un des effets les plus importants jamais observés dans un essai randomisé de LAM.",
  "agonist-antagonist": "Un agoniste active un récepteur en imitant le signal naturel ; un antagoniste se loge dans le récepteur et le bloque sans l'activer. La médecine du cancer utilise les deux.",
  ahod2131: "Cherche à savoir si le lymphome de Hodgkin de stade précoce chez l'enfant et l'adulte peut être traité par immunothérapie à la place d'une partie de la chimiothérapie et de la radiothérapie.",
  "ai-compute-platforms": "Les plateformes de calcul pour l'IA sont les GPU, les bibliothèques de modèles et les services cloud sur lesquels tournent les IA de pathologie, de radiologie et de conception de médicaments.",
  "aichi-cancer-center": "Le centre anticancéreux préfectoral de Nagoya, doté d'un institut de recherche réputé pour l'épidémiologie du cancer, la cancérogenèse moléculaire et l'oncologie digestive.",
  airc: "Le principal financeur caritatif de la recherche sur le cancer en Italie, qui soutient des milliers de chercheurs à l'IEO, à l'Istituto Nazionale dei Tumori et dans les universités de tout le pays.",
  alascca: "Un essai nordique montrant que trois ans d'aspirine à faible dose réduisent environ de moitié les récidives des cancers de l'intestin porteurs d'un ensemble précis de mutations, un usage guidé par biomarqueur d'un médicament qui coûte quelques centimes.",
  "alcohol-attributable-cancer": "La part des cancers dus à la consommation d'alcool : environ 4 % de tous les nouveaux cancers dans le monde, soit à peu près 740 000 par an, dont une fraction non négligeable provient d'une consommation légère à modérée.",
  alectinib: "L'alectinib est un comprimé anti-ALK bien toléré, standard de première ligne depuis des années et, depuis 2024, la première thérapie ciblée administrée après chirurgie dans le cancer du poumon ALK-positif.",
  "alexs-lemonade-stand": "Une association de lutte contre le cancer de l'enfant née du stand de limonade d'une patiente de quatre ans, qui finance aujourd'hui des centaines de bourses de recherche et gère un laboratoire de données en science ouverte pour la génomique des cancers pédiatriques.",
  "alkylating-agent": "Les deux plus anciennes familles de chimiothérapie : les alkylants (cyclophosphamide, temozolomide, melphalan) soudent les brins d'ADN entre eux pour que les cellules ne puissent plus les copier ; les antimétabolites (5-FU, capecitabine, methotrexate, gemcitabine) sont de faux éléments de construction qui bloquent la synthèse de l'ADN.",
  "allogeneic-transplant": "Remplacer le système sanguin d'un patient par celui d'un donneur : la chimiothérapie détruit la moelle, les cellules souches du donneur la reconstruisent, et les cellules immunitaires du donneur traquent la leucémie résiduelle. La seule guérison possible pour de nombreux cancers du sang à haut risque, et le traitement le plus risqué de toute l'oncologie.",
  alpelisib: "L'alpelisib a été le premier inhibiteur de PI3K pour le cancer du sein avec mutation PIK3CA (2019). Il est efficace, mais l'hyperglycémie et les éruptions cutanées ont limité son usage, et des médicaments plus récents le supplantent.",
  "alpha-9-oncology": "Alpha-9 Oncology conçoit des molécules sur mesure qui acheminent des isotopes radioactifs jusqu'aux cellules cancéreuses, avec des essais précoces chez l'humain en cours dans le mélanome ainsi que dans le cancer du sein et d'autres tumeurs solides.",
  alphamedix: "Une version à particules alpha de la radiothérapie par ligands pour les tumeurs neuroendocrines, qui a produit des réponses chez plus de la moitié des patients n'ayant jamais reçu de PRRT, avec la désignation Breakthrough de la FDA.",
  alpine: "Le premier essai en face-à-face dans lequel un inhibiteur de BTK plus récent s'est montré à la fois plus sûr et plus efficace que l'ibrutinib.",
  "american-cancer-society": "L'American Cancer Society est la plus grande association américaine de lutte contre le cancer : elle publie les statistiques annuelles du cancer aux États-Unis, très largement citées, des recommandations de dépistage qui diffèrent par endroits de celles de l'USPSTF, et des guides pour les patients en langage clair pour chaque cancer.",
  "amivantamab-plus-lazertinib": "Bloquer l'EGFR de l'intérieur (un comprimé) et de l'extérieur (un anticorps qui bloque aussi MET) a surpassé l'osimertinib et ajouté plus d'un an de survie.",
  amplification: "Lorsqu'une cellule possède de nombreuses copies supplémentaires d'un gène au lieu des deux habituelles, et fabrique donc beaucoup trop de la protéine correspondante. Le cancer du sein HER2-positif en est l'exemple classique.",
  anbl1531: "COG ANBL1531 est l'essai nord-américain actuel pour le haut risque, qui ajoute une irradiation ciblée pendant l'induction et un comprimé anti-ALK pour les enfants dont la tumeur porte des mutations d'ALK.",
  "andrew-tutt": "A dirigé OlympiA, l'essai qui a montré qu'un an d'olaparib après la chirurgie améliore la survie dans le cancer du sein avec mutation BRCA.",
  "angelina-jolie": "Sa tribune de 2013 dans le New York Times, où elle racontait être porteuse d'une mutation BRCA1 et avoir choisi une mastectomie préventive, a environ doublé les demandes de tests de cancer héréditaire dans plusieurs pays : « l'effet Angelina Jolie ».",
  angiogenesis: "La croissance de nouveaux vaisseaux sanguins. Une tumeur plus grosse qu'une tête d'épingle a besoin de sa propre irrigation sanguine et envoie des signaux (surtout le VEGF) pour la recruter ; les médicaments anti-angiogéniques coupent cet approvisionnement.",
  "ann-lii-cheng": "Oncologue taïwanais qui a dirigé l'essai Asie-Pacifique du sorafenib et codirigé IMbrave150, la référence en immunothérapie du cancer du foie.",
  "anti-egfr-left-sided": "Dans les cancers de l'intestin qui naissent du côté gauche et dont les gènes RAS et BRAF sont normaux, l'ajout d'un anticorps anti-EGFR à la chimiothérapie donne la survie la plus longue observée dans les essais de première ligne.",
  "antiangiogenic-toxicities": "Les effets indésirables communs aux médicaments qui bloquent la croissance des vaisseaux sanguins (bevacizumab, ramucirumab et inhibiteurs de kinase du VEGFR) : hypertension artérielle, fuite de protéines dans les urines, saignements de nez et hémorragies plus graves, cicatrisation lente et, rarement, perforations de l'intestin.",
  "antigen-escape": "Lorsqu'un cancer traité par une thérapie ciblant un marqueur de surface (CD19, BCMA, HER2) survit en se débarrassant de ce marqueur, de sorte que le médicament n'a plus rien à quoi s'accrocher. Environ un tiers des rechutes après un CAR-T anti-CD19 sont antigène-négatives.",
  "antisense-sirna": "Les oligonucléotides thérapeutiques sont de courts brins synthétiques de code génétique qui font taire un gène cancéreux précis.",
  "apheresis-starting-material": "L'aphérèse consiste à prélever les globules blancs d'un patient à l'aide d'une machine pendant plusieurs heures. Tout CAR-T autologue commence ici, et la qualité de ces cellules conditionne le produit final.",
  aphinity: "L'ajout de pertuzumab après la chirurgie aide les femmes dont le cancer avait atteint les ganglions lymphatiques, de quelques points de pourcentage, et n'aide pas celles dont les ganglions sont indemnes.",
  apoptosis: "Le programme d'autodestruction intégré de la cellule, qui démonte proprement une cellule endommagée ou indésirable sans alarmer ses voisines. Les cellules cancéreuses le désactivent, et de nombreux médicaments tentent de le réenclencher.",
  "approval-withdrawal": "Lorsque l'autorisation d'un médicament pour un cancer donné est annulée, généralement parce que l'essai de confirmation n'a pas démontré de bénéfice, parfois pour des raisons de sécurité. Le médicament peut rester sur le marché pour ses autres usages, et il arrive qu'une indication soit réapprouvée plus tard sur la base de nouvelles données.",
  "arc-institute": "L'Arc Institute est un institut de recherche à but non lucratif, bien financé, qui construit des modèles d'IA de « cellule virtuelle » et les jeux de données pour les entraîner.",
  aren0533: "Un essai sur la tumeur de Wilms adapté au risque : les enfants dont les métastases pulmonaires avaient disparu après six semaines de chimiothérapie ont été dispensés de radiothérapie pulmonaire, tandis que ceux qui gardaient des nodules persistants ou présentaient un profil chromosomique à haut risque ont reçu une chimiothérapie plus intensive et s'en sont mieux sortis qu'auparavant.",
  "arpa-h": "L'agence américaine calquée sur la DARPA qui finance des programmes de santé à haut risque, pilotés par jalons, dont la thérapie adaptative du cancer, la chirurgie rapide d'ablation des tumeurs et le dépistage précoce.",
  arpi: "Les nouveaux comprimés hormonaux du cancer de la prostate (abiratérone, enzalutamide, apalutamide, darolutamide) qui bloquent le récepteur des androgènes ou les dernières étapes de la production d'androgènes, utilisés en plus de la suppression standard de la testostérone.",
  artera: "Première entreprise à disposer de tests de pathologie par IA autorisés par la FDA qui prédisent le bénéfice d'un traitement (prostate 2025, sein 2026).",
  "artera-ai-breast": "Un test d'IA autorisé par la FDA (mai 2026) qui lit les lames de cancer du sein pour estimer le risque de récidive dans les formes précoces hormonodépendantes.",
  "ascent-04": "A montré que l'association d'un ADC à l'immunothérapie surpasse la chimiothérapie plus immunothérapie dans le TNBC PD-L1 positif en première ligne.",
  autophagy: "L'autophagie est le programme de recyclage de la cellule. Les cellules cancéreuses, en particulier les tumeurs du pancréas et celles dépendantes de RAS, s'en servent pour survivre à la privation de nutriments et au stress des médicaments, ce qui explique pourquoi l'hydroxychloroquine, un vieil antipaludéen qui la bloque, revient sans cesse dans les essais.",
  "avutometinib-defactinib": "L'avutometinib associé au defactinib est le premier traitement approuvé spécifiquement pour le cancer de l'ovaire séreux de bas grade, une forme à croissance lente dépendante de la voie RAS.",
  "azur-1": "AZUR-1 est l'essai d'enregistrement de l'approche « ni chirurgie, ni radiothérapie, ni chimio » pour le cancer du rectum avec déficience du système de réparation des mésappariements, fondée sur l'étude du MSK dans laquelle tous les patients ont obtenu une réponse complète.",
  "barbara-bradfield": "En 1992, elle a été la première patiente atteinte d'un cancer du sein HER2 positif récidivant à recevoir l'anticorps qui allait devenir l'Herceptin, dans l'essai de Dennis Slamon à l'UCLA. Elle en est devenue la première survivante à long terme.",
  "barretts-esophagus": "Une modification de la muqueuse du bas œsophage causée par le reflux acide qui peut, chez une minorité de personnes, évoluer via une dysplasie vers un adénocarcinome. C'est la raison pour laquelle le cancer de l'œsophage en Occident est surtout un adénocarcinome.",
  "baylor-duncan": "Le centre intégré NCI de Baylor au Texas Medical Center, qui abrite le Center for Cell and Gene Therapy et a mené le premier essai de CAR-T anti-GD2 chez l'enfant.",
  beatcc: "Une deuxième immunothérapie a confirmé que l'ajout d'un inhibiteur de point de contrôle à la chimiothérapie plus bevacizumab prolonge la vie dans le cancer du col de l'utérus avancé.",
  bendamustine: "Une chimiothérapie est-allemande redécouverte dans les années 2000, devenue le partenaire de base du rituximab dans les lymphomes folliculaires, à cellules du manteau et de Waldenström.",
  "bernard-fisher": "Il a soutenu que le cancer du sein est une maladie systémique dès ses débuts, puis a prouvé par des essais randomisés que la tumorectomie avec radiothérapie équivaut à la mastectomie et que le tamoxifène après la chirurgie, et même avant l'apparition du cancer, sauve des vies.",
  "bert-vogelstein": "Bert Vogelstein est le scientifique le plus cité en génétique du cancer : il a cartographié le développement du cancer colorectal et fondé le domaine du séquençage du génome tumoral et de la détection par analyse sanguine.",
  "beta-then-alpha": "Lorsque le traitement au lutétium cesse d'agir, une version à l'actinium du même médicament peut encore produire des réponses.",
  "bevacizumab-glioma": "Un anticorps qui bloque les vaisseaux sanguins, réduit le glioblastome sur les images et diminue l'œdème, mais dont on n'a jamais démontré qu'il prolonge la vie des patients.",
  binimetinib: "Le binimetinib est l'inhibiteur de MEK associé à l'encorafenib ; bloquer l'étape suivante du même relais empêche la tumeur de contourner le blocage de BRAF.",
  biobanking: "Des congélateurs remplis d'échantillons tumoraux prélevés avec consentement et associés à des données cliniques, dont dépend tout programme de biomarqueurs ou de médicaments.",
  "biochemical-recurrence": "Une remontée du PSA après chirurgie ou radiothérapie, généralement des années avant que quoi que ce soit n'apparaisse à l'imagerie.",
  "biocon-biologics": "La branche biosimilaires de Biocon, l'une des rares entreprises hors États-Unis et Europe à disposer de biosimilaires d'anticorps anticancéreux approuvés par la FDA et l'EMA, et propriétaire depuis 2022 de l'activité biosimilaires de Viatris.",
  biopsy: "Prélever un petit fragment du tissu suspect pour qu'un pathologiste puisse l'examiner au microscope. C'est le seul moyen de confirmer un diagnostic de cancer et d'en connaître le type et les marqueurs.",
  "bla-nda": "La demande officielle de mise sur le marché d'un médicament : une New Drug Application pour les petites molécules, une Biologics License Application pour les anticorps et les thérapies cellulaires (États-Unis), ou une Marketing Authorisation Application (UE). La date PDUFA est l'échéance à laquelle la FDA s'est engagée à rendre sa décision.",
  bnct: "Dans la thérapie par capture de neutrons par le bore, un médicament au bore s'accumule dans les cellules tumorales, puis un faisceau de neutrons fait exploser uniquement ces cellules de l'intérieur.",
  "bone-marrow": "Le tissu mou à l'intérieur des os où toutes les cellules sanguines sont fabriquées. La chimiothérapie l'endommage, provoquant la baisse des numérations sanguines qui limite la quantité de traitement qu'un patient peut recevoir.",
  "bone-metastases": "Cancer qui s'est propagé aux os, le plus souvent dans les cancers de la prostate, du sein, du poumon, du rein et de la thyroïde et dans le myélome. Il provoque douleurs, fractures et hypercalcémie, et ses complications sont comptabilisées dans les essais comme « événements osseux ».",
  "braf-v600-mutation": "Un simple changement de lettre dans le gène BRAF qui bloque un interrupteur de croissance en position allumée. On le trouve dans la moitié des mélanomes et dans certaines tumeurs du côlon, de la thyroïde, du poumon et du cerveau, et il se traite par un comprimé anti-BRAF associé à un comprimé anti-MEK.",
  "brain-metastases": "Des foyers tumoraux qui ont migré vers le cerveau depuis un cancer situé ailleurs ; ils sont dix fois plus fréquents que les cancers qui naissent dans le cerveau. La capacité d'un médicament à les atteindre et à les faire régresser est désormais une propriété clé des nouveaux traitements anticancéreux.",
  "breakthrough-designation": "Breakthrough Therapy, Priority Review et le Priority Voucher sont des voies accélérées de la FDA pour les médicaments qui paraissent nettement supérieurs aux options existantes.",
  "breath-vocs": "Sentir le cancer : mesurer les traces de substances chimiques qu'une tumeur libère dans l'air expiré.",
  "brexucabtagene-autoleucel": "Le brexucabtagene autoleucel est la thérapie CAR-T du lymphome à cellules du manteau et de la leucémie aiguë lymphoblastique de l'adulte, qui procure des rémissions prolongées après l'échec des inhibiteurs de BTK.",
  "butaro-cancer-center": "Le premier centre de cancérologie du Rwanda, ouvert en 2012 dans un hôpital de district rural par Partners In Health et le gouvernement rwandais, qui a prouvé que des soins oncologiques complexes peuvent être dispensés dans des milieux à faibles revenus.",
  c797s: "Une mutation qui empêche l'osimertinib de se fixer à l'EGFR ; c'est le principal mécanisme d'échappement sur cible des cancers du poumon à ce traitement.",
  cabazitaxel: "Un deuxième taxane qui agit après le docétaxel et a battu un deuxième comprimé hormonal en comparaison directe (CARD).",
  "cadance-304": "CaDAnCe-304 est le premier essai de phase 3 d'un dégradeur de protéine dans la leucémie, qui oppose la destruction de BTK au meilleur inhibiteur de BTK disponible.",
  cadonilimab: "Un anticorps chinois à deux bras qui bloque à la fois PD-1 et CTLA-4, approuvé en Chine pour le cancer du col de l'utérus et qui prolonge la survie même dans les tumeurs PD-L1 négatives.",
  "caix-pet": "La TEP CAIX est un examen d'imagerie qui utilise un anticorps dirigé contre une protéine presque exclusive au cancer du rein à cellules claires, afin de distinguer un cancer d'une masse rénale bénigne sans biopsie.",
  "canadian-cancer-society": "L'organisme de bienfaisance national du Canada contre le cancer et le plus grand bailleur de fonds caritatif de la recherche sur le cancer, qui assure aussi le financement de base du Canadian Cancer Trials Group.",
  "cancer-grand-challenges": "Un partenariat entre Cancer Research UK et le National Cancer Institute américain qui accorde jusqu'à 20 millions de livres à des équipes internationales pour s'attaquer à un problème précis du cancer qu'aucun laboratoire ne pourrait résoudre seul.",
  "cancer-models": "Trouver un modèle murin ou en boîte de culture correspondant à un type de tumeur ou à une mutation.",
  "cannabinoids-pain-appetite": "Beaucoup de personnes atteintes de cancer utilisent le cannabis contre la douleur, pour l'appétit et le sommeil. Les essais randomisés d'un spray buccal de cannabis ajouté aux opioïdes n'ont pas fait mieux que le placebo contre la douleur cancéreuse, les essais sur l'appétit ont été négatifs, et rien ne prouve que le cannabis ou l'huile de CBD fassent régresser les tumeurs chez l'être humain. La recommandation de l'ASCO de 2024 déconseille de l'utiliser pour traiter le cancer en dehors d'un essai clinique.",
  capecitabine: "La capécitabine (Xeloda) est la forme en comprimés de la chimiothérapie fluorouracile. Elle est un pilier du traitement du cancer de l'intestin et une option standard dans le cancer du sein avancé.",
  captivate: "Quinze mois de deux comprimés, puis l'arrêt : trois quarts des patients n'avaient plus de leucémie détectable dans le sang, et la plupart étaient encore en rémission des années plus tard.",
  carcinoma: "Cancer de l'épithélium, le tissu de revêtement qui tapisse les surfaces et forme les glandes. Environ 85 % des cancers sont des carcinomes, dont les cancers du sein, du poumon, du côlon, de la prostate et de la peau.",
  "carcinoma-in-situ": "Cellules cancéreuses qui occupent la couche de revêtement où elles sont apparues, sans avoir franchi la membrane basale vers le tissu sous-jacent. Elles ne peuvent pas encore se propager, si bien que leur ablation est généralement curative ; c'est le « stade 0 ».",
  cardiotoxicity: "Atteinte du cœur due au traitement du cancer : les anthracyclines affaiblissent le muscle cardiaque de façon permanente et proportionnelle à la dose, le trastuzumab le fait de façon réversible, et certains inhibiteurs de kinases élèvent la tension artérielle ou perturbent le rythme. La fonction cardiaque (FEVG) est surveillée par échographie pendant le traitement.",
  "caris-mi-cancer-seek": "Le premier test approuvé par la FDA qui séquence en une seule fois l'ensemble des gènes d'une tumeur et leur activité, utilisé pour orienter les patients vers plusieurs médicaments ciblés.",
  "carl-june": "A mis au point la thérapie CAR-T anti-CD19 qui est devenue la première thérapie cellulaire génétiquement modifiée approuvée contre le cancer.",
  carmustine: "La carmustine est une chimiothérapie qui atteint le cerveau. Elle est administrée en perfusion pour les tumeurs cérébrales, le lymphome et le myélome, et sous forme d'implant à libération lente laissé dans la cavité après l'ablation d'une tumeur cérébrale.",
  "caroline-robert": "A dirigé KEYNOTE-006 et COMBI-v, les essais qui ont fait du pembrolizumab et de l'association dabrafénib-tramétinib des standards dans le mélanome.",
  carsgen: "CARsgen Therapeutics a développé le satri-cel, la première CAR-T approuvée pour une tumeur solide (cancer gastrique, Chine).",
  "cartitude-4": "Le premier essai randomisé à montrer qu'une CAR-T améliore la survie dans le myélome, dès la deuxième ligne.",
  "castration-resistance": "Cancer de la prostate qui continue de progresser alors que la testostérone a été abaissée à des taux de castration.",
  catumaxomab: "Le catumaxomab (Korjuny) est un anticorps perfusé dans la cavité abdominale pour contrôler l'ascite maligne, l'accumulation de liquide provoquée par des cancers comme ceux de l'ovaire et de l'estomac, chez des personnes qui ont épuisé les autres traitements.",
  "cbt-insomnia-cancer": "L'insomnie est l'un des problèmes les plus persistants après un traitement contre le cancer. Une thérapie par la parole courte et structurée, qui rééduque les habitudes de sommeil, agit mieux et plus longtemps que les somnifères, et les versions numériques la rendent accessible à ceux qui ne peuvent pas consulter un thérapeute.",
  "ccc-freiburg": "Le centre universitaire de cancérologie de Fribourg-en-Brisgau, réputé pour l'immunologie de la transplantation, la recherche sur la maladie du greffon contre l'hôte et la radiothérapie guidée par TEP-PSMA.",
  "cche-57357": "L'un des plus grands hôpitaux de cancérologie pédiatrique du monde, construit entièrement grâce aux dons du public et qui soigne gratuitement les enfants égyptiens atteints de cancer depuis 2007.",
  cd22: "CD22 est une protéine de surface des lymphocytes B et le site d'ancrage de l'ADC contre la leucémie, l'inotuzumab ozogamicine.",
  cd30: "CD30 est une protéine présente sur les cellules malignes de Reed-Sternberg du lymphome de Hodgkin et sur certains lymphomes T, et l'adresse de l'ADC brentuximab védotine.",
  "cd38-plus-triplet": "L'ajout d'un anticorps anti-CD38 à l'induction standard à trois médicaments réduit environ de moitié le risque de progression dans le myélome nouvellement diagnostiqué.",
  "cd47-sirpa": "Les macrophages dévorent les cellules qui paraissent anormales, sauf si la cellule affiche CD47, un badge « ne me mange pas ». De nombreux cancers surproduisent CD47 pour échapper à cette destruction. Des anticorps qui masquent ce badge devraient permettre aux macrophages d'éliminer la tumeur ; l'idée fonctionne en laboratoire, mais le médicament le plus avancé a échoué dans les cancers du sang, car les globules rouges portent le même badge.",
  "cd73-adenosine": "CD73 est une enzyme présente sur les cellules tumorales et immunitaires qui transforme les produits de dégradation de l'ATP en adénosine, un puissant immunosuppresseur ; la bloquer, ou bloquer les récepteurs de l'adénosine, a été un grand espoir de l'immunothérapie qui n'a pas encore tenu ses promesses.",
  "cdk46-plus-endocrine": "Couper le carburant (œstrogènes) et bloquer le moteur (CDK4/6) en même temps.",
  cdsco: "L'autorité nationale de régulation des médicaments de l'Inde, dirigée par le Drugs Controller General of India, qui approuve les nouveaux médicaments anticancéreux et supervise l'industrie des génériques et des biosimilaires qui approvisionne une grande partie du monde.",
  "cedars-sinai-cancer": "Le pôle de cancérologie du plus grand hôpital à but non lucratif de Los Angeles, connu pour la biologie du cancer de la vessie, l'immunothérapie des gliomes et le projet d'IA Molecular Twin.",
  "celestial-tncll": "CELESTIAL-TNCLL compare la bithérapie orale de nouvelle génération au standard actuel à durée fixe, avec des résultats attendus à partir de fin 2026.",
  "cell-line": "Une population de cellules, généralement prélevées sur une tumeur il y a des décennies, qui continue de se diviser indéfiniment en laboratoire. L'outil de base de la recherche sur le cancer : peu coûteuse, rapide et reproductible à l'infini, mais une cousine éloignée d'une vraie tumeur.",
  "cell-therapy-cold-chain": "Congeler les cellules à moins 150 degrés et les expédier dans des « conteneurs secs » à azote liquide avec suivi, pour qu'un médicament vivant arrive vivant et destiné au bon patient.",
  "centre-antoine-lacassagne": "Le centre de lutte contre le cancer de Nice et un pionnier de la protonthérapie en France, qui traite le mélanome de l'œil par protons depuis 1991.",
  "centre-oscar-lambret": "Le centre régional de lutte contre le cancer du nord de la France, réputé pour l'oncologie pédiatrique, les sarcomes, les cancers gynécologiques et la radiothérapie.",
  charite: "La Charité est le plus grand hôpital universitaire d'Europe, doté d'un Comprehensive Cancer Center et du Berlin Institute of Health.",
  "charles-sawyers": "A codéveloppé le dasatinib, successeur de l'imatinib, et l'enzalutamide, médicament contre le cancer de la prostate, et a expliqué comment les cancers résistent aux thérapies ciblées.",
  "checkmate-548": "CheckMate 548, 143 et 498 ont été trois grands essais, tous négatifs : l'immunothérapie qui a transformé le mélanome et le cancer du poumon n'a eu aucun effet dans le glioblastome.",
  "checkmate-577": "Un an d'immunothérapie après la chirurgie a doublé le délai avant la récidive du cancer chez les patients dont la tumeur n'avait pas complètement répondu à la chimioradiothérapie, même si le gain de survie n'a pas atteint la significativité.",
  "checkmate-648": "A démontré deux options d'immunothérapie pour le cancer épidermoïde de l'œsophage, dont une sans aucune chimiothérapie, toutes deux prolongeant la survie.",
  "checkmate-743": "CheckMate 743 a été le premier essai d'immunothérapie à prolonger la survie dans le mésothéliome, et a apporté la première nouvelle option de première ligne en 16 ans.",
  "checkmate-816": "CheckMate 816 a été le premier essai à montrer que l'immunothérapie avant la chirurgie du cancer du poumon améliore la survie.",
  "checkmate-9er": "Le nivolumab associé au cabozantinib a doublé la survie sans progression par rapport au sunitinib et a prolongé la vie, tout en préservant la qualité de vie.",
  "chemo-io-first-line-endometrial": "Trois essais avec trois anticorps différents s'accordent : l'ajout d'une immunothérapie à la première chimiothérapie du cancer de l'endomètre avancé triple environ le temps sans progression dans les tumeurs dMMR et aide modestement les autres.",
  "cho-byoung-chul": "A codirigé MARIPOSA, l'essai dans lequel l'amivantamab associé au lazertinib a surpassé l'osimertinib, et est une figure de premier plan du développement des médicaments contre le cancer du poumon en Asie.",
  "chris-obrien-lifehouse": "L'hôpital de cancérologie intégré à but non lucratif de Sydney, fondé à la mémoire du chirurgien de la tête et du cou Chris O'Brien et intégré au Royal Prince Alfred et à l'University of Sydney.",
  chronotherapy: "Administrer le même médicament à un autre moment de la journée, parce que l'horloge biologique modifie l'ampleur des dégâts qu'il cause et la qualité de la réponse du système immunitaire.",
  chum: "L'hôpital universitaire francophone de Montréal, dont les chercheurs ont montré que le microbiome intestinal influence la réponse à l'immunothérapie et qui dirigent de grands essais sur le cancer de la prostate.",
  "circadian-control": "Les cellules fonctionnent selon une horloge de 24 heures qui régule la division cellulaire, la réparation de l'ADN et le métabolisme des médicaments. Les cancers dérèglent souvent leur horloge, et le moment de la journée où un médicament ou une immunothérapie est administré peut modifier son efficacité.",
  cladribine: "Une perfusion d'une semaine qui met la plupart des personnes atteintes de leucémie à tricholeucocytes en rémission pendant des années ; elle est aussi utilisée sous forme de comprimés dans la sclérose en plaques.",
  "clarity-gastric01": "Le premier ADC dirigé contre la Claudine 18.2 à avoir prouvé qu'il prolonge la vie, annoncé en juillet 2026, offrant au cancer de l'estomac son premier ADC au-delà de HER2.",
  "cldn18-antibody-then-adc": "Cibler la Claudine 18.2 à deux reprises : d'abord avec un anticorps simple associé à une chimiothérapie, puis avec un ADC ou des cellules modifiées lorsque le cancer récidive.",
  cldn6: "Une protéine des jonctions serrées normalement présente uniquement chez l'embryon, qui réapparaît dans les cancers de l'ovaire, du testicule, de l'endomètre et du poumon, ce qui en fait une cible propre pour les ADC et les CAR-T.",
  clear: "L'association ayant la plus longue survie sans progression jamais rapportée dans le cancer du rein en première ligne, près de deux ans.",
  cleopatra: "L'ajout d'un second anticorps anti-HER2, le pertuzumab, a prolongé la survie de 16 mois, le gain le plus important jamais observé à l'époque dans le cancer du sein métastatique.",
  "clinical-trial-software": "Les logiciels d'essais cliniques sont l'ensemble des systèmes qui recueillent les données de l'essai, randomisent les patients et garantissent la traçabilité de chaque formulaire.",
  "cmc-vellore": "Un hôpital missionnaire et une faculté de médecine abritant le premier service d'hématologie d'Inde, connu pour ses greffes de moelle osseuse à bas coût, sa recherche en thérapie génique et la prise en charge des leucémies de l'enfant.",
  "cns-penetration": "La capacité d'un médicament à passer du sang vers le cerveau, dont la barrière hémato-encéphalique tient à l'écart la plupart des médicaments anticancéreux. Les comprimés qui pénètrent dans le cerveau peuvent traiter et prévenir les métastases cérébrales ; ceux qui n'y pénètrent pas laissent le cerveau devenir un sanctuaire où le cancer repousse.",
  "codebreak-300": "CodeBreaK 300 a montré qu'un médicament anti-KRAS a besoin d'être associé à un anticorps anti-EGFR pour être efficace dans le cancer colorectal.",
  "coffee-intake-cancer": "Le café ne provoque pas de cancer et protège probablement contre le cancer du foie et de l'utérus. Les boissons très chaudes, quelles qu'elles soient, peuvent augmenter le risque de cancer de l'œsophage.",
  cologuard: "Un test de selles à faire chez soi tous les trois ans, qui recherche de l'ADN tumoral et du sang occulte ; un résultat positif signifie qu'une coloscopie est nécessaire.",
  "cologuard-plus": "La version actualisée de Cologuard, approuvée en 2024, qui conserve le taux élevé de détection des cancers tout en provoquant moins de fausses alertes.",
  "columbia-hicc": "Le centre de cancérologie intégré du NCI de Columbia, réputé pour la génétique des lymphomes, la biologie des systèmes appliquée au cancer et la découverte de la ferroptose.",
  "combi-ad": "Un an de deux comprimés ciblés après la chirurgie réduit de moitié le risque de rechute dans le mélanome muté BRAF, et le bénéfice reste visible dix ans plus tard.",
  "compass-therapeutics": "Compass conçoit des anticorps qui frappent deux cibles à la fois pour remodeler la vascularisation et l'environnement immunitaire des tumeurs. Son médicament phare, le tovecimig, bloque deux signaux de croissance des vaisseaux sanguins et se dirige vers une possible demande d'approbation aux États-Unis dans le cancer des voies biliaires.",
  "compassion-16": "Un anticorps à deux têtes qui bloque deux freins immunitaires à la fois a prolongé la survie dans le cancer du col de l'utérus avancé, quel que soit le statut PD-L1.",
  compete: "Le premier essai comparant directement un radioligand à un comprimé ciblé dans les tumeurs neuroendocrines ; le radioligand l'a emporté sur la survie sans progression.",
  "complete-response": "Tous les signes détectables de la tumeur ont disparu à l'imagerie et à l'examen clinique après le traitement. C'est le meilleur résultat qu'un essai puisse enregistrer pour un patient donné, même si une maladie microscopique peut persister.",
  "complete-response-term": "Une réponse complète signifie que toute trace mesurable du cancer a disparu à l'imagerie ou dans la moelle ; une réponse partielle signifie qu'il a diminué d'au moins 30 % (RECIST) mais qu'il est toujours présent. Ni l'une ni l'autre n'équivaut à une guérison : une maladie microscopique peut persister.",
  "confirmatory-trial": "L'essai randomisé qu'une entreprise doit mener après une approbation accélérée pour prouver que le médicament aide réellement les patients à vivre plus longtemps ou mieux. S'il échoue ou n'aboutit jamais, l'approbation est censée être retirée.",
  "consolidation-therapy": "Traitement administré après une bonne réponse pour détruire les cellules cancéreuses qui restent probablement mais ne sont pas visibles, afin de faire durer la rémission. Le durvalumab après chimioradiothérapie dans le cancer du poumon en est l'exemple le plus connu.",
  "continuous-ctdna-monitoring": "Plutôt que d'analyser le sang tous les trois mois, prélever des échantillons en continu, afin de détecter une rechute la semaine même où elle commence.",
  "control-arm": "Le groupe d'un essai randomisé qui reçoit le traitement standard existant, et par rapport auquel le nouveau médicament est évalué. Selon que le contrôle est le véritable standard actuel, un standard dépassé ou un éventail d'options choisies par chaque médecin (« choix de l'investigateur »), la portée d'un résultat positif n'est pas la même.",
  "corinne-faivre-finn": "Elle a dirigé CONVERT, qui a établi le schéma de radiothérapie du cancer du poumon à petites cellules de stade limité.",
  "courtney-dinardo": "Elle a dirigé VIALE-A, qui a fait du vénétoclax associé à l'azacitidine le traitement standard des patients âgés atteints de leucémie myéloïde aiguë.",
  "cpx-351": "Les deux vieux médicaments de chimiothérapie enfermés ensemble dans de minuscules bulles de graisse à un rapport fixe, ce qui a doublé la survie à cinq ans des adultes âgés atteints de LAM à haut risque.",
  cretostimogene: "Le cretostimogene est un virus modifié pour se multiplier uniquement dans les cellules de cancer de la vessie dont la voie RB est défaillante, instillé directement dans la vessie. Il a fait disparaître le carcinome in situ chez 75 % des patients ne répondant pas au BCG.",
  "cross-then-nivolumab": "Chimiothérapie et radiothérapie, puis chirurgie, puis un an d'immunothérapie si l'opération révèle qu'il restait du cancer. C'est le parcours actuel à visée curative.",
  "crystal-mackall": "Crystal Mackall est une pionnière de la thérapie cellulaire dont l'équipe a apporté les CAR-T anti-GD2 aux enfants atteints de tumeurs cérébrales mortelles.",
  "ctdna-mrd-to-adjuvant": "Un test sanguin de MRD par ctDNA après la chirurgie détermine qui reçoit un traitement supplémentaire et qui en est dispensé.",
  curium: "Curium est l'une des plus grandes entreprises de médecine nucléaire et développe le 177Lu-PSMA-I&T (ECLIPSE) comme concurrent du Pluvicto.",
  cxcr4: "Un récepteur de chimiokine qui ancre les cellules sanguines dans la moelle et aide les cellules cancéreuses à s'y loger ; il est muté chez un tiers des patients atteints de maladie de Waldenström et ciblé par le plerixafor pour la mobilisation des cellules souches.",
  cystectomy: "Ablation de la vessie (et des organes voisins) pour un cancer de la vessie ayant envahi la paroi musculaire ; l'urine est ensuite dérivée par une stomie ou par une nouvelle vessie fabriquée à partir d'un segment d'intestin.",
  "cystoscopy-turbt": "La cystoscopie et la RTUV consistent à regarder l'intérieur de la vessie avec une caméra et à réséquer les tumeurs par l'urètre. Les colorants en lumière bleue rendent les tumeurs planes plus faciles à voir.",
  cytopenias: "Le terme générique désignant toute baisse des cellules sanguines (globules blancs, globules rouges, plaquettes) lorsque le traitement freine la moelle osseuse. La plupart des chimiothérapies en provoquent de façon passagère ; les radioligands, les CAR-T et certains comprimés en causent des formes plus durables.",
  "cz-biohub": "Le réseau d'instituts de recherche de la Chan Zuckerberg Initiative qui construit des atlas cellulaires, des outils d'imagerie et d'IA dont dépendent les chercheurs en cancérologie, dont l'atlas unicellulaire Tabula Sapiens.",
  "d-alba": "L'essai qui a montré que la LAL Ph-positive peut être traitée par un comprimé associé à une immunothérapie, sans chimiothérapie, avec 95 % des patients en vie à 18 mois.",
  "damon-runyon": "Une fondation new-yorkaise qui finance des chercheurs en cancérologie en début de carrière depuis 1946 ; parmi ses anciens boursiers figurent une douzaine de lauréats du prix Nobel.",
  "daniel-ludwig": "En 1971, il a placé la quasi-totalité de ses participations internationales dans un institut de recherche sur le cancer qui porte son nom à contrecœur ; celui-ci a depuis consacré plus de 1,8 milliard de dollars de ses propres fonds à la science du cancer.",
  darolutamide: "Le darolutamide est un bloqueur du récepteur aux androgènes qui pénètre à peine dans le cerveau, ce qui lui vaut de provoquer moins de chutes et d'effets secondaires cognitifs ; il est approuvé avec ou sans chimiothérapie.",
  "dartmouth-cancer-center": "Le centre de cancérologie intégré du NCI de la Nouvelle-Angleterre rurale, berceau académique de Medarex (ipilimumab et nivolumab) et pôle de recherche sur le surdiagnostic.",
  "deborah-james": "Diagnostiquée d'un cancer de l'intestin à 35 ans, elle a passé cinq ans à dire aux gens de surveiller leurs selles, a coanimé l'émission de la BBC You, Me and the Big C et a récolté plus de 11 millions de livres pour Cancer Research UK dans les semaines précédant sa mort en 2022.",
  debulking: "Chirurgie qui retire le plus de tumeur possible lorsqu'on ne peut pas tout enlever proprement; ce qui compte, c'est de ne rien laisser de visible.",
  "decentralised-clinical-trials": "Réaliser une partie d'un essai à domicile ou localement, grâce à la télémédecine, aux soins infirmiers à domicile et au suivi à distance, afin que les patients éloignés des grands centres puissent y participer.",
  "decipher-prostate": "Un test de 22 gènes réalisé sur la biopsie ou la pièce opératoire, qui prédit la dissémination et le décès, utilisé pour choisir entre la surveillance et l'ajout d'une hormonothérapie.",
  "decision-sorafenib": "Le premier médicament approuvé pour les cancers de la thyroïde qui ne répondaient plus à l'iode radioactif.",
  defi: "Le premier essai randomisé à montrer qu'un médicament contrôle les tumeurs desmoïdes, avec une amélioration de la douleur et de la fonction.",
  "dellphi-304": "DeLLphi-304 a été le premier essai dans lequel un engageur de lymphocytes T a amélioré la survie dans une tumeur solide fréquente.",
  "dennis-slamon": "Il a établi le lien entre l'amplification de HER2 et le cancer du sein agressif, et a mené le trastuzumab puis le palbociclib jusqu'à leur approbation.",
  denosumab: "Le denosumab est une injection sous-cutanée qui bloque le signal responsable de la destruction osseuse. Sous le nom de Xgeva, il prévient les fractures et d'autres complications osseuses chez les personnes dont le cancer s'est propagé aux os ou qui ont un myélome; sous le nom de Prolia, il traite l'ostéoporose, y compris la perte osseuse causée par l'hormonothérapie des cancers du sein et de la prostate.",
  "deregulating-cellular-energetics": "Les cellules cancéreuses reprogramment leur métabolisme pour produire rapidement de la biomasse, brûlant le glucose de façon inefficace et se gavant de glutamine et de lipides.",
  "destiny-breast09": "A montré qu'Enhertu associé au pertuzumab surpasse le standard de première ligne en place depuis dix ans dans le cancer du sein métastatique HER2-positif.",
  "destiny-breast11": "DESTINY-Breast11 a introduit Enhertu dans le traitement préopératoire du cancer du sein HER2-positif, en remplacement des anthracyclines.",
  "destiny-gastric04": "La première preuve randomisée qu'un médicament anti-HER2 fait mieux que la chimiothérapie standard dans le cancer de l'estomac en deuxième ligne: Enhertu a apporté environ trois mois de vie supplémentaires.",
  "destiny-pantumor02": "Enhertu a fait régresser les tumeurs dans de nombreux cancers HER2-positifs, le cancer de l'endomètre figurant parmi les meilleurs répondeurs, ce qui a conduit à la première approbation anti-HER2 indépendante du type de tumeur.",
  "deutsche-krebshilfe": "Le plus grand financeur privé de la lutte contre le cancer en Allemagne, qui finance le réseau des centres d'excellence en oncologie et la certification des centres de cancérologie intégrés sur lesquels repose la prise en charge du cancer en Allemagne.",
  "dharmais-cancer-hospital": "Le centre national du cancer et hôpital de référence de l'Indonésie, qui coordonne l'enregistrement des cancers, le dépistage et les normes de traitement pour le quatrième pays le plus peuplé du monde.",
  "dietary-pattern-scores": "Des scores qui évaluent l'alimentation dans son ensemble par rapport à un modèle sain, au lieu de compter des aliments isolés. Ils prédisent le risque de cancer et la survie mieux que n'importe quel nutriment pris individuellement.",
  differentiation: "Le degré de ressemblance qu'une cellule cancéreuse conserve avec le tissu mature et spécialisé dont elle provient. Les tumeurs bien différenciées ressemblent à leur tissu d'origine et ont tendance à mieux se comporter; les tumeurs peu différenciées ont un aspect primitif et grossissent plus vite.",
  "digital-twins-trials": "Utiliser un modèle de ce qui serait arrivé à un patient sous traitement standard, afin que moins de personnes aient à y être randomisées.",
  "disseminated-tumor-cells": "Des cellules cancéreuses isolées qui se sont déjà propagées à des organes distants, souvent retrouvées dans la moelle osseuse des années avant l'apparition de toute métastase.",
  "dna-term": "La longue molécule qui stocke les instructions nécessaires pour construire et faire fonctionner une cellule, écrites dans un alphabet chimique de quatre lettres. Le cancer est fondamentalement une maladie de l'ADN endommagé.",
  "domenica-lorusso": "Elle a dirigé KEYNOTE-A18, qui a montré que l'ajout du pembrolizumab à la chimioradiothérapie améliore la survie dans le cancer du col de l'utérus localement avancé.",
  donafenib: "Le donafenib est une version chinoise remaniée du sorafenib qui a permis une survie plus longue que l'original dans un essai comparatif direct dans le cancer du foie, et qui est approuvé en Chine comme option de première ligne.",
  "donald-pinkel": "Directeur fondateur du St. Jude Children's Research Hospital en 1962, il a conçu la Total Therapy, associant les médicaments au traitement du cerveau et du liquide céphalorachidien, et a fait passer les taux de guérison de la leucémie de l'enfant de presque zéro à environ la moitié en dix ans.",
  dose: "La quantité de médicament administrée, à quelle fréquence et pendant combien de temps. Les médicaments anticancéreux ont longtemps été donnés à la dose maximale que le patient peut supporter, et les autorités réglementaires poussent désormais vers des doses choisies pour leur bénéfice plutôt que pour leur tolérance.",
  "dose-limiting-toxicity": "Un effet indésirable survenant dans un essai précoce, assez sévère (généralement de grade 3 ou plus, ou imposant une longue interruption du traitement) pour que la dose ne puisse pas être augmentée davantage sans danger. Compter les DLT à chaque palier de dose est la façon dont les essais de phase 1 déterminent la dose maximale tolérée.",
  downstaging: "Utiliser des médicaments, la radiothérapie ou l'embolisation pour faire régresser un cancer d'un stade où un traitement curatif est impossible vers un stade où il devient possible: par exemple, réduire des métastases hépatiques jusqu'à pouvoir les retirer, ou un cancer du foie jusqu'à ce qu'il réponde aux critères de transplantation.",
  downstream: "La position dans une chaîne de signalisation: les protéines en amont envoient le message, les protéines en aval le reçoivent. Une mutation en aval de la cible d'un médicament peut rendre ce médicament inutile.",
  "dr-reddys": "Le fabricant de génériques d'Hyderabad qui a lancé le premier biosimilaire du rituximab au monde en 2007 et qui vend aujourd'hui des génériques et des biosimilaires d'oncologie en Inde, aux États-Unis et en Europe.",
  dreamseq: "A tranché la question de l'ordre: dans le mélanome muté BRAF, commencer par l'immunothérapie et garder les comprimés ciblés pour plus tard.",
  "drew-pardoll": "Immunologiste qui a contribué à définir le rôle de la voie PD-1 dans le cancer et a bâti l'un des plus grands instituts d'immunothérapie.",
  "drug-price-transparency": "Les nouveaux médicaments anticancéreux sont couramment lancés aux États-Unis à plus de $150,000-$250,000 par an, avec des prix fixés sans lien avec le bénéfice et masqués par des remises; d'autres pays négocient ou évaluent le rapport coût-efficacité. La politique de prix détermine qui est traité.",
  "duke-cancer-institute": "L'un des premiers centres intégrés du NCI (1973), célèbre pour ses recherches sur les tumeurs cérébrales, dont l'immunothérapie par virus de la polio contre le glioblastome.",
  "duo-e": "Une troisième immunothérapie a confirmé le bénéfice dans la maladie dMMR et a laissé entrevoir que l'ajout de l'olaparib aide la majorité des patientes dont la réparation des mésappariements est intacte.",
  dysphagia: "Des difficultés à avaler, soit parce qu'une tumeur rétrécit l'œsophage ou la gorge, soit parce que la radiothérapie et la chirurgie de la tête, du cou ou du thorax ont endommagé les muscles et les nerfs qui coordonnent la déglutition. Elle affecte la nutrition, la dignité et le risque de passage des aliments dans les poumons.",
  dysplasia: "Des cellules d'aspect anormal dans un revêtement de surface, qui ne sont pas encore cancéreuses mais en prennent le chemin. Trouver et retirer la dysplasie (frottis du col, surveillance de l'œsophage de Barrett, polypes du côlon) est la façon dont le dépistage prévient le cancer au lieu de se contenter de le détecter tôt.",
  e1910: "A prouvé que l'ajout de l'immunothérapie blinatumomab au traitement standard sauve des vies, même chez les patients dont la leucémie était déjà indétectable.",
  "early-detection-term": "Trouver un cancer alors qu'il est encore petit et localisé, au moment où il est le plus souvent curable. Pour la plupart des cancers, la survie à cinq ans est plusieurs fois plus élevée au stade I qu'au stade IV, ce qui explique pourquoi tant d'efforts sont consacrés à les détecter plus tôt.",
  "echelon-1": "Remplacer la bléomycine par l'ADC anti-CD30 dans la chimiothérapie de première ligne a amélioré la survie dans le lymphome de Hodgkin avancé, le premier gain de survie en première ligne depuis des décennies.",
  eflornithine: "L'éflornithine (DFMO) est un ancien médicament contre la maladie du sommeil, reconverti en premier traitement d'entretien oral du neuroblastome à haut risque, approuvé en décembre 2023 pour réduire les rechutes après immunothérapie.",
  "egfr-bispecific-plus-pd1-hnscc": "L'association d'un nouvel anticorps anti-EGFR à l'immunothérapie a triplé, dans les essais précoces, le taux de réponse observé avec l'immunothérapie seule.",
  "egfr-exon19-l858r": "La délétion de l'exon 19 et la mutation L858R sont les deux mutations EGFR les plus fréquentes, représentant ensemble ~85% des cancers du poumon mutés EGFR, et toutes deux répondent aux comprimés anti-EGFR.",
  egfrviii: "EGFRvIII est une version mutée du récepteur EGFR, présente uniquement dans la tumeur, retrouvée dans environ un tiers des glioblastomes. C'est une cible qui semble idéale, et pourtant tous les médicaments dirigés contre elle ont échoué jusqu'ici.",
  electrochemotherapy: "De brèves impulsions électriques appliquées à une tumeur ouvrent des pores dans les membranes cellulaires afin qu'une dose infime de bléomycine ou de cisplatine y pénètre massivement; utilisée pour les métastases cutanées et, de plus en plus, pour les tumeurs profondes.",
  "elevate-tn": "Six ans plus tard, la plupart des patients sous acalabrutinib n'ont toujours pas progressé, et l'ajout de l'obinutuzumab a également amélioré la survie.",
  "eli-002-7p": "Un vaccin prêt à l'emploi ciblant les sept mutations KRAS les plus fréquentes, administré après une chirurgie du cancer du pancréas. Sa phase 2 a manqué son objectif principal en 2026 mais a montré des signes d'activité.",
  eliana: "ELIANA a été l'essai mondial à l'origine de la première approbation d'une CAR-T: quatre enfants sur cinq sans autre option sont entrés en rémission, et beaucoup y sont restés pendant des années.",
  "elias-jabbour": "Spécialiste des leucémies qui a mis au point des protocoles allégés en chimiothérapie associant inotuzumab, blinatumomab et ponatinib pour la LAL de l'adulte.",
  "ember-3": "Un SERD oral efficace seul dans les tumeurs porteuses d'une mutation ESR1 et qui, associé à l'abemaciclib, double le temps sans progression chez toutes les patientes, quelle que soit la mutation.",
  emerald: "Le premier dégradeur oral du récepteur des œstrogènes à surpasser l'hormonothérapie standard, avec un bénéfice concentré dans les tumeurs porteuses de mutations ESR1.",
  "emily-whitehead": "La première enfant traitée par cellules CAR-T, en 2012. Sa guérison d'une leucémie en rechute a transformé une idée expérimentale en traitement approuvé.",
  enasidenib: "L'énasidénib est le pendant de l'ivosidénib pour IDH2 ; approuvé aux États-Unis dans la maladie en rechute, il n'a jamais été approuvé en Europe après avoir échoué à prolonger la survie dans un essai de confirmation.",
  "endocrine-resistance": "Lorsque l'hormonothérapie ne parvient plus à contrôler un cancer du sein hormonodépendant, soit rapidement (résistance primaire), soit après des années (résistance acquise).",
  "endoscopic-resection-term": "Retirer un cancer précoce de la paroi interne du tube digestif à l'aide d'un endoscope, sans incision externe et en laissant l'organe en place.",
  "enriqueta-felip": "Oncologue thoracique qui a dirigé IMpower010, établissant l'atezolizumab adjuvant dans le cancer du poumon.",
  "eortc-26981": "L'essai de 2005 qui a fixé le traitement que reçoit encore chaque patient atteint de glioblastome. Rien ne l'a remplacé en vingt ans.",
  epcam: "Une protéine d'adhésion présente sur presque toutes les cellules de carcinome et la molécule de capture des tests de cellules tumorales circulantes ; la cible du tout premier anticorps bispécifique approuvé (catumaxomab, 2009).",
  epirubicin: "L'épirubicine (Ellence) est un proche parent de la doxorubicine, utilisé surtout après une chirurgie du cancer du sein lorsque les ganglions sont atteints, ainsi que dans les protocoles du cancer de l'estomac ; il est un peu moins toxique pour le cœur.",
  "equecabtagene-autoleucel": "Eque-cel est une CAR-T chinoise destinée au myélome multiple ayant récidivé après au moins trois traitements, approuvée en 2023 et remarquée pour ses réponses durables dans un vaste essai à bras unique.",
  ergo2: "Le seul essai randomisé d'un régime cétogène dans les tumeurs cérébrales n'a montré aucun bénéfice. Les patients ont pu suivre le régime et leurs taux de cétones ont augmenté, mais la progression est survenue tout aussi vite.",
  "eric-klein": "Urologue qui a dirigé l'étude CCGA ayant validé Galleri, le test de détection multi-cancers fondé sur la méthylation.",
  "eric-van-cutsem": "Il a dirigé CRYSTAL, qui a établi le cetuximab dans le cancer colorectal RAS non muté, et façonne les recommandations digestives de l'ESMO depuis deux décennies.",
  erlotinib: "L'erlotinib a été l'un des premiers comprimés anti-EGFR contre le cancer du poumon ; il a été approuvé avant que l'on sache que les mutations d'EGFR prédisaient les répondeurs, puis redéfini par elles.",
  espen: "La société européenne de nutrition clinique dont les recommandations sur la nutrition des patients atteints de cancer définissent le dépistage de la dénutrition et le traitement de la cachexie en oncologie.",
  estimabl2: "A démontré que la plupart des personnes ayant un petit cancer de la thyroïde à faible risque peuvent se passer d'iode radioactif après la chirurgie sans aucune augmentation des récidives.",
  "eudract-ctis": "Le registre des essais cliniques de l'UE et le CTIS constituent le registre européen des essais, qui complète ClinicalTrials.gov pour les études menées uniquement dans l'UE.",
  "euro-ewing-2012": "Le protocole américain du sarcome d'Ewing a surpassé le protocole européen dans un essai comparatif direct, unifiant les pratiques.",
  "ev-pembro-continuum": "Le duo ADC-immunothérapie qui a doublé la survie dans la maladie avancée fonctionne désormais aussi autour de la chirurgie, chez les patients en bon état général comme chez les plus fragiles.",
  "evading-growth-suppressors": "Échapper aux suppresseurs de croissance, c'est couper les freins qui arrêtent normalement la division, p53 et RB avant tout.",
  evera: "Dans evERA, l'association d'un SERD oral à l'évérolimus après échec des inhibiteurs de CDK4/6 a retardé la progression de plus de trois mois, et de quatre mois et demi dans les tumeurs porteuses d'une mutation ESR1.",
  "ewsr1-fli1": "Le gène de fusion qui définit le sarcome d'Ewing : un facteur de transcription aberrant qui résiste depuis 30 ans aux efforts de conception de médicaments.",
  exatecan: "L'exatécan est une camptothécine très puissante, à l'origine de la plupart des charges cytotoxiques d'ADC de nouvelle génération, dont celles de l'iza-bren et de plusieurs ADC chinois.",
  exelixis: "Exelixis fabrique le cabozantinib (Cabometyx), utilisé dans les cancers du rein, du foie, de la thyroïde et, depuis 2025, les cancers neuroendocrines.",
  exemestane: "L'exémestane est un inhibiteur stéroïdien de l'aromatase, partenaire de l'évérolimus et agent testé avec la suppression ovarienne chez les femmes jeunes.",
  "eytan-stein": "Il a dirigé les essais de l'énasidénib et du revuménib qui ont fait entrer les inhibiteurs d'IDH2 et de la ménine dans le traitement des leucémies aiguës.",
  "f-stephen-hodi": "Premier auteur de l'essai sur l'ipilimumab de 2010 qui a prouvé que l'immunothérapie pouvait prolonger la survie dans le mélanome.",
  "falp-chile": "Le plus grand institut du Chili dédié au cancer, une fondation à but non lucratif créée en 1954 et le centre le plus actif du pays pour les essais en oncologie et la radiothérapie avancée.",
  "fasting-mimicking-diet": "Manger très peu pendant quelques jours autour de chaque cure de chimiothérapie pourrait protéger les cellules normales et sensibiliser la tumeur. Les premiers essais sont intrigants mais de petite taille, et ce n'est pas à tenter sans diététicien.",
  "fc-effector": "Modifier la queue de l'anticorps pour qu'il recrute les cellules immunitaires plus fortement, ou pas du tout.",
  "ferdinandos-skoulidis": "Il a dirigé CodeBreaK 100, l'essai qui a fait du sotorasib le premier inhibiteur de KRAS approuvé, et a montré que les co-mutations STK11/KEAP1 affaiblissent l'immunothérapie.",
  "fgfr2-fusion": "Un gène FGFR2 cassé puis ressoudé qui est le moteur d'environ un cancer des voies biliaires intrahépatiques sur huit et que des comprimés peuvent éteindre.",
  fianlimab: "Le fianlimab est l'anti-LAG-3 de Regeneron. Les données précoces prometteuses avec le cemiplimab ne se sont pas confirmées face au pembrolizumab dans un essai de phase 3 de première ligne en 2026.",
  "fianlimab-phase3-melanoma": "Un deuxième anti-LAG-3 n'a pas réussi à surpasser le pembrolizumab seul, un avertissement que le résultat d'Opdualag n'est pas automatiquement un effet de classe.",
  "firefly-1": "FIREFLY-1 a montré qu'un comprimé hebdomadaire, le tovorafenib, fait régresser la plupart des gliomes de bas grade de l'enfant en rechute liés à des altérations de BRAF, y compris la fréquente fusion KIAA1549-BRAF que les anciens anti-BRAF ne pouvaient pas traiter sans danger. Il a conduit à la première approbation d'un médicament pour cette maladie.",
  fish: "Un test qui utilise des sondes d'ADN fluorescentes sur une lame de tissu pour compter les copies d'un gène ou repérer des gènes réarrangés dans chaque cellule ; il sert à confirmer une amplification de HER2, MYCN dans le neuroblastome, ou des réarrangements d'ALK et de MYC.",
  "fit-test": "Un test des selles à la recherche de sang occulte, réalisé à domicile chaque année. Les résultats positifs sont suivis d'une coloscopie.",
  "fixed-duration": "Selon qu'un médicament est pris pendant une durée déterminée (par exemple 12 mois) puis arrêté même s'il agit encore, ou poursuivi indéfiniment jusqu'à ce qu'il cesse d'agir. La durée fixe offre aux patients des années sans traitement ; le traitement continu évite le risque de voir le cancer repousser.",
  "flot-term": "Quatre cycles de chimiothérapie avant la chirurgie et quatre après pour le cancer de l'estomac et de la jonction œsogastrique, avec fluorouracile, leucovorine, oxaliplatine et docétaxel. Il a remplacé l'ancien protocole ECF après l'essai FLOT4 et constitue aujourd'hui le standard occidental.",
  "flow-cytometry": "Un appareil qui fait défiler les cellules une à une devant des lasers et lit les protéines de surface (marqueurs CD) que chacune porte, afin d'identifier de quel type de cellule il s'agit. C'est ainsi que l'on classe les leucémies et les lymphomes et que l'on mesure la maladie résiduelle.",
  "flt3i-plus-7-3": "Ajouter un inhibiteur de FLT3 à la chimiothérapie standard est le moyen éprouvé d'améliorer la survie dans la LAM avec mutation de FLT3.",
  "foresight-diagnostics": "Société issue de Stanford dont la technologie ctDNA PhasED-Seq détecte le lymphome résiduel avec plus de précision que la TEP/TDM ; lancement clinique de CLARITY en 2026.",
  "fortifi-hn01": "Un anticorps bifonctionnel qui bloque l'EGFR et capte le TGF-bêta, dans le but de rendre les tumeurs de la tête et du cou HPV-négatives sensibles à l'immunothérapie.",
  "foundationone-cdx": "Les tests génomiques approuvés par la FDA sur tissu (324 gènes) et sur sang qui servent de diagnostics compagnons pour des dizaines de médicaments.",
  fragmentomics: "La fragmentomique analyse la taille et la position des fragments d'ADN dans le sang, et non les mutations. Les cellules cancéreuses meurent de façon désordonnée et laissent un schéma de fragmentation reconnaissable.",
  "frederick-national-lab": "Le seul laboratoire national américain consacré à la recherche biomédicale, géré pour le NCI ; il abrite la RAS Initiative et la fabrication de médicaments expérimentaux du NCI.",
  fulzerasib: "Fulzerasib a été le premier comprimé bloquant KRAS G12C approuvé en Chine, pour les cancers du poumon porteurs de cette mutation après un traitement antérieur.",
  furlong: "L'essai comparatif direct dans lequel le furmonertinib a presque doublé le délai avant progression du cancer du poumon par rapport au géfitinib, reproduisant FLAURA avec un médicament chinois.",
  futibatinib: "Le futibatinib est un inhibiteur covalent de FGFR pour le cancer des voies biliaires avec fusion de FGFR2, avec le taux de réponse le plus élevé des médicaments de première génération.",
  "ga68-dotatate": "La TEP des tumeurs neuroendocrines qui détecte beaucoup plus de lésions que les scintigraphies anciennes et confirme l'éligibilité à la radiothérapie par ligand au lutétium (le couple théranostique).",
  "gabriel-hortobagyi": "Oncologue spécialiste du sein qui a dirigé MONALEESA-2, le premier essai d'inhibiteur de CDK4/6 à montrer un gain de survie globale dans la maladie HR-positive en première ligne.",
  "gatekeeper-mutation": "Lorsqu'un cancer devient résistant à un comprimé ciblé, c'est souvent en modifiant l'endroit exact où le médicament se fixe : une mutation « gatekeeper » ou du « front de solvant ». Les médicaments de nouvelle génération sont conçus pour s'adapter à ces changements.",
  gbg: "Le groupe académique allemand dont les essais GeparX ont établi le carboplatine et les stratégies néoadjuvantes dans le cancer du sein triple négatif.",
  "gd2-cart01": "GD2-CART01 a été la première CAR-T à obtenir des rémissions complètes durables dans une tumeur solide de l'enfant : deux tiers des patients ont répondu et un tiers a atteint la rémission complète.",
  gedatolisib: "Un médicament intraveineux qui bloque l'ensemble de la voie PI3K/mTOR, approuvé en juillet 2026 pour le cancer du sein hormonodépendant.",
  gefitinib: "Le comprimé contre le cancer du poumon dont les réponses spectaculaires chez quelques patients ont conduit à la découverte des mutations de l'EGFR en 2004.",
  geicam: "Le groupe national espagnol de recherche sur le cancer du sein, qui mène des essais de chimiothérapie adjuvante, d'hormonothérapie et d'inhibiteurs de CDK4/6 dans plus de 200 hôpitaux.",
  "gemcitabine-nab-paclitaxel": "La gemcitabine associée au nab-paclitaxel est le plus doux des deux protocoles de chimiothérapie standard du cancer du pancréas, et la base sur laquelle la plupart des nouveaux médicaments sont testés.",
  gemelli: "Le Gemelli est l'hôpital universitaire catholique de Rome et une référence en oncologie gynécologique.",
  gene: "Un segment d'ADN qui contient la recette d'une protéine (ou d'un ARN fonctionnel). L'être humain en possède environ 20 000, et le cancer implique généralement qu'une poignée d'entre eux se dérèglent.",
  "gene-amplification": "Les cellules cancéreuses possèdent souvent des copies supplémentaires d'un gène de croissance (amplification) ou ont perdu des copies d'un gène protecteur (délétion), plutôt qu'une faute d'orthographe à l'intérieur du gène. Les copies supplémentaires de HER2 ou de MYCN sont des exemples classiques qui modifient le traitement.",
  "gene-expression": "Le degré d'activation d'un gène, et donc la quantité de sa protéine qu'une cellule fabrique. Les cellules cancéreuses expriment souvent les mauvais gènes aux mauvais niveaux.",
  "generate-biomedicines": "Société de conception de protéines par IA générative (issue de Flagship), entrée en bourse en 2026, qui teste un anticorps neutralisant la charge utile d'ADC libérée afin de réduire les effets secondaires.",
  "genomics-cloud-platforms": "Systèmes cloud où hôpitaux et chercheurs stockent et analysent des données génomiques de façon sécurisée à l'échelle du pétaoctet.",
  "georgetown-lombardi": "Le seul centre de cancérologie intégré du NCI à Washington, DC, connu pour sa recherche sur le cancer du sein, dont la direction de l'essai CLEOPATRA sur le pertuzumab.",
  "georgina-long": "Spécialiste des essais sur le mélanome qui a dirigé COMBI-d, COMBI-AD et NADINA, faisant passer l'immunothérapie avant la chirurgie dans la maladie de stade III.",
  "german-lymphoma-alliance": "Le groupe allemand d'essais sur les lymphomes agressifs, anciennement DSHNHL, dont les essais MInT, RICOVER-60 et FLYER ont fixé le nombre de cycles de R-CHOP dont les patients ont besoin.",
  "gerson-therapy-detox-regimens": "Le régime Gerson prescrit des jus toutes les heures, un régime végétarien strict pauvre en sel, des compléments et plusieurs lavements au café par jour, et il est vendu dans des cliniques au Mexique. Il n'a jamais montré de bénéfice dans aucune étude contrôlée, et les lavements au café ont provoqué des troubles électrolytiques mortels et des infections.",
  ggfg: "Le tétrapeptide GGFG est le lien de quatre acides aminés d'Enhertu et de Dato-DXd, coupé par des enzymes à l'intérieur de la cellule cancéreuse et très stable dans le sang.",
  "ghassan-abou-alfa": "A dirigé HIMALAYA et ClarIDHy, qui ont donné au cancer du foie une option de double immunothérapie et au cancer des voies biliaires son premier médicament ciblé.",
  ghsg: "Le groupe basé à Cologne dont les essais HD, de BEACOPP à BrECADD dans HD21, fixent la norme du traitement du lymphome de Hodgkin depuis quatre décennies.",
  "gilles-salles": "A dirigé PRIMA, qui a établi l'entretien par rituximab dans le lymphome folliculaire, et a coprésidé POLARIX dans le DLBCL.",
  "giuseppe-curigliano": "Oncologue spécialiste du sein et figure des essais de phase 1, qui a codirigé DESTINY-Breast06 et façonné le concept de HER2-low.",
  "glutamine-mucositis-neuropathy": "La glutamine orale, un acide aminé que les cellules de la muqueuse intestinale et buccale utilisent comme carburant, peut réduire la sévérité des aphtes pendant la chimioradiothérapie des cancers de la tête et du cou ; les recommandations sur la mucite la suggèrent pour cet usage. La glutamine intraveineuse chez les patients transplantés n'est pas recommandée, et les preuves pour prévenir les atteintes nerveuses sont minces.",
  "gog-0218-icon7": "L'ajout du bévacizumab, un bloqueur des vaisseaux sanguins, à la chimiothérapie de première ligne a retardé la rechute de quelques mois mais n'a pas prolongé la survie globale.",
  "google-deepmind": "Google DeepMind a créé AlphaFold, AlphaMissense, AlphaGenome et Med-Gemini, les modèles de référence pour la structure, les variants et le raisonnement médical multimodal.",
  goserelin: "Injections mensuelles ou trimestrielles qui mettent les ovaires au repos, permettant aux femmes non ménopausées d'utiliser des inhibiteurs de l'aromatase et réduisant les récidives dans les cas à plus haut risque.",
  gp100: "gp100 est une protéine des cellules pigmentaires, et la cible du premier médicament bispécifique à améliorer la survie dans une tumeur solide, le mélanome uvéal.",
  gprc5d: "GPRC5D est une deuxième cible dans le myélome, utilisée lorsque les médicaments dirigés contre BCMA cessent d'agir.",
  grail: "GRAIL a développé Galleri, le test sanguin multi-cancers en attente d'une décision de la FDA après un comité consultatif en septembre 2026.",
  "gray-unit": "L'unité de dose de rayonnement absorbée par les tissus : un gray correspond à un joule par kilogramme. Un traitement curatif totalise généralement 50-70 Gy ; une séance unique contre les douleurs osseuses est de 8 Gy. Les radiopharmaceutiques, eux, sont prescrits en activité, en becquerels (GBq).",
  "groote-schuur-uct": "L'hôpital universitaire le plus célèbre d'Afrique du Sud, lieu de la première transplantation cardiaque, et avec l'UCT un centre africain de premier plan pour la recherche sur le cancer, la radiothérapie oncologique et les études sur les cancers de l'œsophage et du col de l'utérus.",
  "growth-factor": "Une protéine libérée par une cellule qui indique aux cellules voisines de croître, de se diviser ou de survivre. Les cancers en fabriquent souvent eux-mêmes ou y deviennent hypersensibles.",
  "guardant-reveal": "Un test sanguin de détection du cancer résiduel après chirurgie qui ne nécessite aucun échantillon tumoral, ce qui rend les résultats plus rapides que ceux des tests guidés par la tumeur.",
  "gupta-sudeep": "Sudeep Gupta dirige le plus grand centre de cancérologie de l'Inde et son programme d'essais pragmatiques et abordables.",
  gvhd: "Après une greffe de donneur, les cellules immunitaires du donneur peuvent attaquer la peau, l'intestin et le foie du patient (maladie du greffon contre l'hôte) tout en traquant la leucémie résiduelle (effet du greffon contre la leucémie). Les deux effets sont liés, et les médecins cherchent donc à conserver assez du second sans trop du premier.",
  "hacettepe-cancer-institute": "L'institut universitaire du cancer pionnier de la Turquie, à Ankara, doté de solides programmes d'oncologie pédiatrique, de radiothérapie oncologique et d'oncologie préventive.",
  "hamad-medical-corporation": "Le système de santé public du Qatar, dont le National Center for Cancer Care and Research est le seul centre de cancérologie intégré du pays et le pivot de sa stratégie nationale contre le cancer.",
  "harmoni-2": "Le premier essai comparatif direct dans lequel un nouveau médicament a battu Keytruda, en Chine ; un bénéfice de survie a suivi en 2026.",
  "hbv-hcv": "Deux virus causent la majorité des cancers du foie dans le monde. L'un se prévient par un vaccin, l'autre se guérit avec des comprimés, ce qui fait du cancer du foie l'un des cancers les plus évitables.",
  hcg: "Le plus grand réseau privé d'hôpitaux de cancérologie d'Inde, avec des dizaines de centres en Asie du Sud et en Afrique et une avance précoce dans le CyberKnife, le PET-CT et le diagnostic moléculaire.",
  "hcmc-oncology-hospital": "Le principal hôpital de cancérologie du sud du Vietnam, l'un des plus fréquentés d'Asie du Sud-Est, avec un grand campus neuf à Thu Duc et le registre du cancer de Hô Chi Minh-Ville.",
  "hcpa-porto-alegre": "Le premier hôpital universitaire public du sud du Brésil, connu pour la génétique du cancer, la recherche sur le syndrome de Li-Fraumeni et l'un des programmes de recherche clinique les plus solides du Brésil.",
  hd21: "Un nouveau protocole intensif à base de brentuximab a égalé la chimiothérapie la plus efficace (et la plus toxique) d'Europe, avec beaucoup moins d'effets secondaires.",
  "health-canada": "Le ministère fédéral de la santé et l'autorité de régulation des médicaments du Canada, qui autorise les médicaments contre le cancer et travaille avec les provinces et l'Agence des médicaments du Canada sur le remboursement.",
  hedgehog: "Une voie du développement qui façonne les embryons et se réactive dans le carcinome basocellulaire de la peau et certaines tumeurs cérébrales. Son blocage guérit la plupart des carcinomes basocellulaires avancés, mais les tumeurs apprennent à la réactiver plus en aval.",
  hepatectomy: "Retirer la partie du foie qui contient la tumeur. Le foie se régénère, si bien que jusqu'à 70% peut être enlevé à condition que ce qui reste soit sain.",
  "her2-gastric-sequence": "Dans le cancer de l'estomac HER2 positif, d'abord un anticorps associé à une chimiothérapie, puis Enhertu en cas de progression. Les deux étapes reposent désormais sur des preuves de phase 3.",
  "hera-b31-n9831": "Trois essais publiés ensemble en 2005 ont montré qu'un an de trastuzumab après la chirurgie réduit d'environ un tiers le risque de mourir d'un cancer du sein HER2 positif.",
  hetero: "Un groupe privé de génériques basé à Hyderabad, premier fabricant mondial d'antirétroviraux contre le VIH, qui a lancé des biosimilaires indiens du rituximab en 2015 et du bevacizumab en 2016.",
  "high-potency-payload-synthesis": "Fabriquer les toxines actives au microgramme contenues dans les ADC, dans des installations conçues pour qu'un simple grain de poussière ne puisse pas nuire à un ouvrier.",
  "hipec-procedure": "Une fois que les chirurgiens ont retiré toute tumeur visible du péritoine, l'abdomen est baigné pendant 60-90 minutes dans une chimiothérapie chauffée afin de détruire les cellules microscopiques restantes.",
  "hippo-yap": "La voie qui indique aux organes quand cesser de grandir. Les cancers la désactivent pour que YAP et TAZ restent dans le noyau et stimulent la croissance; dans le mésothéliome, la perte de NF2 fait exactement cela, et les premiers médicaments dirigés contre l'interrupteur YAP-TEAD sont en essais.",
  "histology-directs-first-line-meso": "Il faut d'abord identifier le type de tumeur au microscope: les tumeurs non épithélioïdes doivent recevoir une immunothérapie d'emblée; les tumeurs épithélioïdes peuvent raisonnablement recevoir soit une immunothérapie, soit une chimio-immunothérapie.",
  "histotripsy-immune-priming": "Détruire une tumeur mécaniquement par les ondes sonores, plutôt que par la chaleur, laisse des débris suffisamment intacts pour que le système immunitaire puisse en tirer des enseignements.",
  hl7: "L'organisme de normalisation à l'origine de FHIR, l'interface de données de santé aujourd'hui utilisée pour intégrer les dossiers d'oncologie aux essais, aux registres et aux outils d'IA, et gardien du standard de données sur le cancer mCODE.",
  "hla-a02-restriction": "Certains médicaments à base de récepteurs de lymphocytes T ne fonctionnent que chez les personnes ayant un 'type tissulaire' immunitaire particulier. Environ la moitié des personnes d'ascendance européenne le possèdent; beaucoup moins dans certaines autres populations.",
  hma: "Une chimiothérapie de faible intensité qui retire de l'ADN les interrupteurs chimiques d'extinction (groupes méthyle) pour que les gènes mis en silence puissent de nouveau être lus. Le traitement de référence des patients âgés atteints de LAM et de SMD à haut risque, surtout en association avec le venetoclax.",
  "hofman-michael": "Il a dirigé proPSMA et TheraP, les essais qui ont prouvé que la TEP au PSMA surpasse l'imagerie conventionnelle et que le lutétium-PSMA surpasse la chimiothérapie.",
  "hope-rugo": "Oncologue spécialiste du sein qui a dirigé des essais majeurs sur les ADC et les inhibiteurs de CDK4/6 et qui a quitté l'UCSF pour City of Hope en 2024.",
  "hospice-end-of-life": "Des soins dans les derniers mois de la vie entièrement axés sur le confort, à domicile ou en unité de soins palliatifs, lorsque le traitement du cancer n'aide plus. Y entrer plus tôt que les deux à trois semaines habituelles apporte davantage de bénéfices aux patients et à leurs proches.",
  "hospital-de-amor-barretos": "Un hôpital de cancérologie philanthropique en zone rurale de l'État de São Paulo qui soigne exclusivement via le système public brésilien, célèbre pour ses unités mobiles de dépistage et son grand centre de recherche.",
  "hr-nbl1": "L'essai européen de longue haleine sur le neuroblastome à haut risque a établi busulfan-melphalan comme protocole de greffe et montré que l'ajout d'IL-2 au traitement anti-GD2 augmentait la toxicité sans apporter de bénéfice.",
  hta: "L'autorisation dit qu'un médicament fonctionne; le remboursement dit qui va payer. Les organismes d'évaluation des technologies de santé (NICE, G-BA, PBAC) jugent si le bénéfice vaut le prix, souvent par année de vie ajustée sur la qualité, et peuvent retarder l'accès de plusieurs années après l'autorisation.",
  "hussein-tawbi": "Il a dirigé RELATIVITY-047, qui a fait du relatlimab le premier inhibiteur de LAG-3 approuvé, ainsi que l'essai ayant montré que l'immunothérapie est efficace dans les métastases cérébrales du mélanome.",
  hydroxyurea: "L'hydroxyurée est un comprimé peu coûteux, utilisé depuis des décennies, qui abaisse les numérations sanguines trop élevées dans la polyglobulie de Vaquez et la thrombocytémie essentielle et qui est aussi le principal médicament de la drépanocytose.",
  "hyperbaric-oxygen-radiation-injury": "Respirer de l'oxygène pur dans un caisson pressurisé, sur 30 à 40 séances, aide à guérir les lésions radiques de la mâchoire, de la vessie et de l'intestin qui apparaissent des années après le traitement. Une revue Cochrane a trouvé des preuves de qualité modérée d'un bénéfice pour ces localisations, et peu pour les autres.",
  hypogammaglobulinaemia: "Un manque d'anticorps parce que le traitement a détruit les lymphocytes B ou les plasmocytes qui les produisent, comme le font délibérément les CAR-T anti-CD19, les anticorps anti-CD20 et les traitements anti-BCMA. Il rend les patients vulnérables aux infections, parfois pendant des années, et se traite par des perfusions d'immunoglobulines.",
  "hypoxia-activated-therapy": "Une molécule inoffensive qui ne se transforme en poison que là où il n'y a pas d'oxygène, ce qui, dans l'organisme, signifie à l'intérieur d'une tumeur.",
  "i131-mibg": "La MIBG radioactive à haute dose délivre le rayonnement depuis l'intérieur des cellules de neuroblastome qui captent la noradrénaline; elle est utilisée dans la maladie en rechute et a été testée en traitement de première intention.",
  "ian-frazer": "En 1991, avec Jian Zhou, il a fabriqué en laboratoire des pseudo-particules virales du HPV, base des vaccins qui pourraient éliminer le cancer du col de l'utérus. L'Australie, où le vaccin a été déployé en premier, est en bonne voie d'y parvenir.",
  iba: "IBA est le premier fournisseur d'équipements de protonthérapie.",
  icmr: "Le plus haut conseil de recherche médicale de l'Inde, qui gère le Programme national des registres du cancer, un institut de prévention du cancer et un réseau d'instituts de recherche, et fixe la politique nationale de recherche et d'éthique.",
  "icmr-nicpr": "L'institut de prévention du cancer de l'ICMR, près de Delhi, consacré aux cancers que l'Inde peut prévenir: le cancer du col de l'utérus par le dépistage et la vaccination contre le HPV, et le cancer de la bouche par la lutte antitabac.",
  "idea-acc-ai-first-pathology-common-cases": "Laisser une IA validée effectuer la première lecture des prélèvements de routine à fort volume, comme les frottis cervicaux et les colorations standard des biopsies mammaires, pour que les rares pathologistes consacrent leur temps aux cas difficiles.",
  "idea-alpha-after-adc": "Lorsque les ADC dirigés contre une protéine de surface cessent d'agir parce que leur charge utile ne tue plus, utiliser la même protéine pour délivrer à la place un rayonnement.",
  "idea-bio1-adaptive-car-antigen-switch": "Les thérapies cellulaires échouent quand la tumeur cesse d'afficher le marqueur qu'elles ont été conçues pour reconnaître. Préparer à l'avance un produit de remplacement permettrait aux médecins de changer rapidement.",
  "idea-bio1-antibody-degrader-conjugates": "Les médicaments qui détruisent des protéines peuvent aussi toucher les cellules saines. Les fixer à un anticorps qui ne s'arrime qu'aux cellules tumorales les maintiendrait là où on en a besoin.",
  "idea-bio1-antigen-mapping-at-progression": "Les médicaments à base d'anticorps ont besoin que leur cible soit toujours présente. Après l'échec de l'un d'eux, vérifier quels marqueurs de surface subsistent guiderait le choix du suivant au lieu de le deviner.",
  "idea-bio1-baseline-ultradeep-resistant-clones": "Les mutations de résistance existent souvent dans une infime fraction des cellules avant le début du traitement. Un test très sensible au diagnostic pourrait les détecter et justifier une association dès le premier jour.",
  "idea-bio1-cfrna-plasticity-tracking": "Certains cancers échappent au traitement en se transformant en un autre type de cellule que le médicament n'atteint plus. L'ARN tumoral dans le sang pourrait révéler ce changement des mois avant une biopsie.",
  "idea-bio1-immunopeptidome-timing": "Les thérapies ciblées rendent brièvement les cellules cancéreuses plus faciles à repérer par le système immunitaire. Administrer l'immunothérapie précisément dans cette fenêtre, plutôt qu'en même temps, pourrait être plus efficace.",
  "idea-bio1-pan-ras-covalent-g12d": "Une mutation de RAS peut désormais être ciblée par un médicament parce qu'elle offre une prise réactive. La plupart des mutations de RAS n'en offrent pas, il faut donc une nouvelle chimie pour accrocher d'autres acides aminés.",
  "idea-bio1-pmhc-bispecifics-public-drivers": "Les cellules découpent leurs protéines internes et en exposent les fragments à leur surface. Cela signifie que même les protéines inaccessibles aux médicaments à l'intérieur de la cellule peuvent être attaquées de l'extérieur par le système immunitaire.",
  "idea-bio1-rebiopsy-before-switch": "Le traitement est souvent choisi d'après une biopsie prélevée des années plus tôt sur la tumeur d'origine. La maladie disséminée peut aujourd'hui être différente. Il faut la réanalyser avant de changer de médicament.",
  "idea-bio1-upfront-bypass-combination": "Si la plupart des tumeurs échappent à un médicament par la même voie de secours, bloquer cette voie dès le départ pourrait prévenir la résistance au lieu de courir après.",
  "idea-bio2-autophagy-block-mrd": "Les cellules cancéreuses dormantes survivent en recyclant leur propre contenu. Un ancien médicament contre le paludisme bloque ce recyclage et est testé chez des personnes sans cancer visible mais avec des cellules résiduelles détectables.",
  "idea-bio2-brain-penetrant-glue-degraders": "Les nouveaux médicaments qui détruisent les protéines cancéreuses sont généralement trop gros pour pénétrer dans le cerveau. En concevoir des versions beaucoup plus petites pourrait étendre cette approche aux tumeurs cérébrales.",
  "idea-bio2-caf-subtype-assignment": "Les cellules de soutien qui bâtissent la charpente d'une tumeur existent en plusieurs types : certaines protègent la tumeur, d'autres la freinent. Les traiter toutes de la même façon explique les échecs passés.",
  "idea-bio2-csf-ctdna-monitoring": "Le liquide prélevé dans le bas du dos contient de l'ADN provenant des tumeurs cérébrales. Son analyse permet de diagnostiquer, de surveiller et de détecter une résistance sans chirurgie du cerveau.",
  "idea-bio2-ctc-clearance-go-nogo": "Les cellules cancéreuses qui circulent dans le sang peuvent être comptées. Si un médicament les élimine, c'est un signe précoce qu'il pourrait empêcher la dissémination, et le résultat s'obtient en quelques semaines plutôt qu'en plusieurs années.",
  "idea-bio2-ctc-culture-functional-testing": "Les tests de médicaments utilisent normalement des cellules de la tumeur d'origine. Cultiver les cellules plus rares présentes dans le sang permettrait de tester les médicaments sur les cellules qui sont réellement en train de circuler.",
  "idea-bio2-exercise-reimbursement": "Un vaste essai a montré qu'un programme d'exercice structuré améliorait la survie après un cancer de l'intestin. Presque aucun système de santé ne le prend en charge, donc presque aucun patient n'en bénéficie.",
  "idea-bio2-fmt-plus-checkpoint-phase3": "Transférer des bactéries intestinales de patients ayant répondu à l'immunothérapie a aidé certains patients qui avaient cessé de répondre. Il est temps de mener un véritable essai de grande ampleur.",
  "idea-bio2-functional-precision-rare": "Pour les cancers très rares, il n'y a souvent ni indice génétique ni essai clinique. Cultiver les cellules du patient et tester directement des médicaments sur elles peut suggérer ce qu'il faut essayer.",
  "idea-bio2-fus-for-cell-entry": "Les cellules immunitaires modifiées administrées par perfusion atteignent rarement les tumeurs cérébrales. Ouvrir brièvement la barrière par ultrasons focalisés au bon moment pourrait leur permettre d'entrer.",
  "idea-bio2-gdf15-plus-exercise": "Un nouvel anticorps bloque l'hormone qui fait perdre l'appétit et du poids aux personnes atteintes de cancer. Pour que le poids repris soit du muscle et non de la graisse, il faut y associer exercice et protéines.",
  "idea-bio2-histotripsy-immune-priming": "Les ultrasons focalisés peuvent fragmenter une tumeur sans chaleur ni incision, en laissant des débris dont le système immunitaire peut apprendre. Le faire sur une tumeur pourrait aider à traiter les autres.",
  "idea-bio2-hypoxia-guided-adenosine": "Les tumeurs privées d'oxygène produisent une substance qui désactive les cellules immunitaires. Une imagerie peut montrer quelles tumeurs manquent d'oxygène, et ce sont celles qu'il faut traiter avec des bloqueurs.",
  "idea-bio2-implantable-microdevice-screen": "Un implant de la taille d'un grain de riz peut libérer de petites doses de nombreux médicaments différents dans des zones distinctes d'une tumeur, puis être retiré pour que les médecins voient lequel a fonctionné chez cette personne.",
  "idea-bio2-in-situ-vaccination-solid": "Injecter des agents activant l'immunité dans une seule tumeur, associés à une faible dose de radiothérapie, peut apprendre au système immunitaire à attaquer les tumeurs situées ailleurs dans le corps.",
  "idea-bio2-intracavitary-immunotherapy": "L'immunothérapie intracavitaire cible le cancer qui tapisse la paroi de l'abdomen ou du thorax, que les médicaments administrés par perfusion atteignent à peine. L'administrer directement dans la cavité permet des doses locales bien plus élevées.",
  "idea-bio2-intraventricular-car-t": "Le cancer qui se propage le long des enveloppes du cerveau est presque impossible à traiter. Injecter des cellules immunitaires modifiées directement dans le liquide cérébral, par un petit réservoir, permet de l'atteindre.",
  "idea-bio2-lean-mass-dosing": "Les doses de chimiothérapie sont calculées à partir de la taille et du poids, selon une formule datant des années 1950. Des doses fondées sur la masse musculaire réelle pourraient causer moins d'effets secondaires graves.",
  "idea-bio2-low-dose-olanzapine-appetite": "Une faible dose d'un ancien comprimé peu coûteux a amélioré l'appétit et le poids dans un essai randomisé mené chez des personnes atteintes d'un cancer avancé. Il pourrait être utilisé presque partout dès demain.",
  "idea-bio2-lymph-node-immune-priming": "Le premier ganglion lymphatique atteint par le cancer est aussi celui où le système immunitaire apprend à le combattre. Injecter l'immunothérapie dans ce ganglion avant l'opération, plutôt que de le retirer à l'aveugle, pourrait mieux fonctionner.",
  "idea-bio2-mrd-guided-endocrine-duration": "Beaucoup de femmes prennent des comprimés bloquant les hormones pendant dix ans, avec de réels effets secondaires. Un test sanguin sensible pourrait montrer qui peut arrêter sans risque au bout de cinq ans.",
  "idea-bio2-mrd-reference-standards": "Les tests sanguins de détection du cancer résiduel proposés par différentes entreprises ne concordent pas, et il n'existe aucun étalon commun. Des échantillons de référence publics permettraient à chacun de vérifier quel test fonctionne vraiment.",
  "idea-bio2-myeloid-engager-bispecific": "Les médicaments qui capturent les cellules T et les amènent jusqu'aux tumeurs fonctionnent bien dans les cancers du sang. La même astuce, appliquée aux cellules qui dévorent les tumeurs, pourrait fonctionner là où les cellules T sont absentes.",
  "idea-bio2-national-mrd-platform": "Les tests sanguins peuvent désormais détecter un cancer résiduel des mois avant l'imagerie, mais la plupart des patients dont le test est positif n'ont aucun essai auquel s'inscrire. Un essai permanent par pays réglerait le problème.",
  "idea-bio2-nk-cells-for-mrd": "Des cellules immunitaires de donneur ne nécessitant aucune compatibilité pourraient être administrées en cures courtes pour éliminer les quelques cellules cancéreuses restant après l'opération, au moment où la cible est la plus petite.",
  "idea-bio2-oligometastatic-signature": "Certaines personnes n'ont que quelques foyers de dissémination et peuvent être guéries en traitant chacun d'eux. D'autres en ont de nombreux, pas encore visibles. Un test permettant de les distinguer éviterait des traitements inutiles et repérerait les patients guérissables.",
  "idea-bio2-organotropism-atlas": "Chaque cancer a ses organes de prédilection, et il en va de même d'un patient à l'autre. Un modèle capable de prédire quel organe est menacé pourrait cibler la surveillance et la prévention.",
  "idea-bio2-patient-partnered-rare-commons": "Pour les cancers très rares, les patients sont dispersés dans de nombreux pays. Des projets portés par les patients peuvent rassembler dossiers, salive et échantillons tumoraux par la poste et partager les données ouvertement.",
  "idea-bio2-platelet-cloak-aspirin-mrd": "Les cellules cancéreuses présentes dans le sang s'enveloppent de plaquettes pour se camoufler. L'aspirine pourrait leur retirer ce manteau, et le tester coûte le moins cher chez les patients les plus à risque de rechute.",
  "idea-bio2-prehabilitation-standard": "Être en meilleure forme et mieux nourri avant une opération réduit les complications et accélère la récupération. C'est peu coûteux, mais seuls quelques hôpitaux le proposent.",
  "idea-bio2-pro-dormancy-therapy": "Si nous ne pouvons pas tuer les cellules cancéreuses dormantes, nous pourrions essayer de les maintenir endormies à vie. Le cancer résiduel deviendrait alors un passager inoffensif.",
  "idea-bio2-radiotherapy-sting-fractionation": "La radiothérapie peut alerter le système immunitaire, mais une dose unique trop forte détruit le signal d'alarme même qu'elle a créé. Choisir la bonne dose et le bon rythme pourrait apporter un bénéfice supplémentaire gratuit.",
  "idea-bio2-rapid-autopsy-commons": "Presque tous les décès par cancer sont dus à la dissémination, et pourtant très peu de tissu métastatique est jamais étudié. Un réseau collectant des tissus donnés dans les heures suivant le décès changerait cela.",
  "idea-bio2-rare-cancer-telepathology-network": "Les cancers rares sont souvent mal diagnostiqués, ce qui engage les patients sur une mauvaise voie thérapeutique. Le partage de lames numérisées permettrait de soumettre chaque cas à un expert en quelques jours.",
  "idea-bio2-rare-tumour-model-bank": "On ne peut pas étudier un cancer sans en avoir un modèle de laboratoire, et la plupart des cancers rares n'en ont aucun. Une banque financée qui créerait et partagerait des modèles débloquerait la recherche.",
  "idea-bio2-registry-embedded-randomisation": "Les patients atteints de cancers rares sont déjà suivis dans des registres. Proposer la randomisation au sein même du registre rend les essais beaucoup moins coûteux et permet à presque tout le monde d'y participer.",
  "idea-bio2-robotic-convection-delivery": "Perfuser lentement des médicaments par de fins cathéters dans une tumeur cérébrale permet de contourner la barrière, mais le liquide s'échappe souvent. Une mise en place robotisée et une imagerie en temps réel montreraient où il va réellement.",
  "idea-bio2-survivor-plasma-biobank": "Pour prouver qu'un test de cancer résiduel fonctionne, il faut du sang prélevé des années avant la rechute. Collecter et congeler des échantillons annuels dès maintenant permettra d'évaluer tous les tests à venir.",
  "idea-bio2-tcr-repertoire-early-readout": "Quand l'immunothérapie fonctionne, certaines familles de cellules immunitaires se multiplient dans le sang en quelques semaines. Suivre ce phénomène pourrait indiquer tôt aux patients s'il faut continuer.",
  "idea-bio2-tertiary-lymphoid-induction": "Les tumeurs qui contiennent de petites structures immunitaires ressemblant à des ganglions lymphatiques répondent bien mieux à l'immunothérapie. Induire ces structures délibérément pourrait rendre les tumeurs froides sensibles au traitement.",
  "idea-bio2-til-reactivity-selection": "Cultiver les propres cellules antitumorales du patient ne fonctionne que si ces cellules sont présentes au départ. Un test permettant de les détecter éviterait des traitements inutiles.",
  "idea-bio2-trem2-myeloid-reprogramming": "Les tumeurs se remplissent de cellules immunitaires qui les protègent. Les premiers médicaments ont tenté d'éliminer ces cellules et ont échoué. Les plus récents visent à les faire passer du côté de l'attaque.",
  "idea-bio2-tumour-anchored-tgfbeta-trap": "Un puissant signal immunosuppresseur appelé TGF-beta empêche les cellules immunitaires d'entrer dans les tumeurs, mais le bloquer dans tout l'organisme provoque des problèmes cardiaques et cutanés. Ancrer le bloqueur à l'intérieur de la tumeur pourrait apporter le bénéfice sans les dégâts.",
  "idea-bio2-vascular-normalisation-window": "De faibles doses de médicaments antivasculaires font brièvement mieux fonctionner les vaisseaux de la tumeur, ce qui aide les cellules immunitaires et d'autres médicaments à y pénétrer. L'imagerie peut repérer cette fenêtre chez chaque patient.",
  "idea-biomarker-quadruplet-gastric": "Le cancer de l'estomac dispose désormais de trois biomarqueurs complémentaires (HER2, PD-L1, Claudin 18.2) qui se chevauchent souvent. Tester si l'association de deux traitements complémentaires fait mieux que le choix d'un seul.",
  "idea-btk-degrader-frontline": "Si la destruction de BTK fonctionne quand tous les inhibiteurs ont échoué, l'utiliser en premier pourrait empêcher la résistance d'apparaître un jour.",
  "idea-chip-risk-modifiers": "Les inhibiteurs de PARP, les sels de platine et les radioligands peuvent faire évoluer vers une leucémie des clones de cellules sanguines préexistants chez quelques patients. Savoir prédire qui est concerné permettrait de choisir les traitements avec plus de sécurité.",
  "idea-cost-low-dose-immunotherapy-trials": "Un essai randomisé mené au Tata Memorial a montré qu'ajouter une très faible dose de nivolumab à une chimiothérapie peu coûteuse triplait presque la survie à un an chez des patients atteints de cancer de la tête et du cou qui ne pouvaient pas se payer l'immunothérapie standard ; des essais plus vastes devraient confirmer pour quels cancers cela fonctionne.",
  "idea-cost-pooled-procurement-essential": "Les petits pays paient plus cher la même chimiothérapie générique parce qu'ils achètent seuls ; le Fonds stratégique de la PAHO et la liste des médicaments essentiels de la WHO montrent qu'acheter ensemble fait baisser les prix et stabilise l'approvisionnement.",
  "idea-cost-shorter-course-trials": "L'essai PERSEPHONE a montré que six mois de trastuzumab après la chirurgie valent douze mois, ce qui divise par deux le coût du médicament ; aucune entreprise ne mènera de tels essais, c'est donc aux financeurs publics et aux associations caritatives de le faire.",
  "idea-ctdna-escalation-tnbc": "Plutôt que de traiter tout le monde après la chirurgie, analyser le sang tous les quelques mois et ne traiter que lorsque l'ADN tumoral réapparaît.",
  "idea-ctdna-guided-adjuvant-crc": "Utiliser une analyse de sang après la chirurgie pour décider qui reçoit une chimiothérapie : l'épargner aux patients négatifs, et trouver quelque chose qui fonctionne vraiment pour les patients positifs.",
  "idea-data-open-cell-foundation-model": "Construire un modèle d'IA partagé et librement accessible qui a appris comment les cellules cancéreuses réagissent aux perturbations génétiques et médicamenteuses, afin que n'importe quel laboratoire puisse prédire l'effet d'un nouveau médicament ou d'une nouvelle combinaison.",
  "idea-data-precompetitive-cancer-foundation-model": "Entreprises, hôpitaux et financeurs unissent leurs efforts pour entraîner une très grande IA sur les images, les lames, les génomes et les résultats cliniques de millions de patients, conservés dans leurs hôpitaux, puis partagent le modèle obtenu.",
  "idea-dormancy-maintenance-therapy": "Plutôt que de chercher à tuer chaque cellule cancéreuse cachée après la chirurgie, les maintenir en dormance à vie avec des médicaments peu toxiques, comme le fait déjà l'hormonothérapie prolongée dans le cancer du sein.",
  "idea-dtc-colonisation-determinants": "La plupart des cellules cancéreuses qui se disséminent meurent ou restent endormies pour toujours ; quelques-unes se développent en métastases mortelles. Personne ne sait encore les distinguer, et y parvenir indiquerait qui traiter après la chirurgie.",
  "idea-ecdna-targeting": "De nombreuses tumeurs agressives conservent leurs gènes cancéreux sur des cercles d'ADN libres qui leur permettent d'augmenter ou de réduire leur résistance à volonté. Les médicaments qui brisent ces cercles, ou la tolérance de la cellule à leur égard, constituent une nouvelle frontière.",
  "idea-fap-theranostics-pancancer": "Plutôt que de chercher une cible différente pour chaque cancer, s'attaquer aux cellules de soutien que presque toutes les tumeurs solides ont en commun.",
  "idea-field-interception": "Des régions entières de tissu portent des mutations cancéreuses bien avant qu'une tumeur n'existe. Détecter et traiter ce champ, plutôt que la tumeur, permettrait de prévenir les cancers au lieu de les guérir.",
  "idea-fund-abbreviated-pathway-me-too-biologics": "Une fois qu'une classe d'anticorps, comme les bloqueurs de PD-1, a fait ses preuves, les copies ultérieures pourraient être approuvées sur la base d'essais plus petits démontrant leur équivalence, ce qui forcerait la concurrence sur les prix et libérerait des patients et des fonds pour des médicaments réellement nouveaux.",
  "idea-fund-ablation-versus-surgery-trials": "Les ultrasons focalisés, l'histotripsie et l'ablation par la chaleur ou par champ électrique peuvent détruire des tumeurs sans incision, mais chaque fabricant mène sa propre petite étude. Des essais financés par des fonds publics les compareraient équitablement à la chirurgie.",
  "idea-fund-amc-paediatric-rare": "Les payeurs s'engageraient à l'avance à acheter un nombre défini de doses à un prix défini pour tout médicament atteignant un seuil fixé dans un cancer rare ou pédiatrique, afin que les entreprises sachent que le marché existe avant d'investir.",
  "idea-fund-benefit-indexed-exclusivity": "Le cinquième anticorps anti-PD-1 qui ne fait pas mieux que le premier ne devrait pas bénéficier de la même protection commerciale que celui-ci. L'exclusivité serait réduite pour les copies qui n'apportent rien.",
  "idea-fund-biomarker-validation-fund": "Des milliers de tests susceptibles de prédire qui bénéficiera d'un traitement sont publiés sans jamais être validés. Un fonds financerait les études de confirmation, fastidieuses mais indispensables, dans des groupes indépendants de patients.",
  "idea-fund-brain-metastases-programme": "Un cinquième des patients atteints de tumeurs solides développent des métastases cérébrales et sont généralement exclus des essais. Il s'agirait de financer un programme qui les étudie et les traite comme une maladie à part entière.",
  "idea-fund-combination-patent-pool": "Les entreprises mettraient leurs médicaments anticancéreux dans un pool de licences commun, afin que tout investigateur qualifié puisse tester des combinaisons de médicaments appartenant à différents propriétaires dans le cadre d'un accord standard unique, les redevances étant réparties selon une formule fixe.",
  "idea-fund-device-and-technique-translation-fund": "Les nouveaux instruments chirurgicaux, sondes d'imagerie et équipements de radiothérapie inventés dans les universités attirent rarement les investisseurs. Un fonds dédié financerait le prototypage, les tests de sécurité et les premières études chez l'humain.",
  "idea-fund-first-in-class-prize": "Verser un prix fixe, de plusieurs dizaines de millions, à la première équipe qui démontre chez des patients qu'une manière totalement nouvelle de combattre le cancer fonctionne, afin que les paris précoces les plus risqués soient récompensés avant même qu'un produit n'existe.",
  "idea-fund-flash-evidence-programme": "La radiothérapie ultra-rapide pourrait épargner les tissus sains tout en détruisant les tumeurs, mais chaque centre la teste à sa manière. Un programme coordonné harmoniserait les mesures et mènerait les essais qui trancheront la question de son efficacité.",
  "idea-fund-global-academic-phase-one-network": "Les essais académiques de première administration à l'humain recrutent lentement parce que chaque hôpital refait l'examen éthique et réglementaire. Un réseau d'unités de phase 1 doté d'un examen unique et partagé permettrait d'ouvrir des essais dans de nombreux pays à la fois.",
  "idea-fund-global-cancer-fund": "Reproduire le modèle qui a transformé la prise en charge du HIV, de la TB et du paludisme : un fonds international commun qui finance des appareils de radiothérapie, des laboratoires d'anatomopathologie et des médicaments anticancéreux essentiels là où il n'y en a pas.",
  "idea-fund-hospital-exemption-registry": "Le droit européen autorise déjà les hôpitaux à fabriquer des thérapies innovantes pour leurs propres patients. Il s'agirait d'y associer un registre commun des résultats, afin que les CAR-T académiques et les traitements similaires puissent faire leurs preuves sans licence commerciale.",
  "idea-fund-implementation-quota": "Beaucoup de personnes ne reçoivent jamais des traitements dont l'efficacité est déjà prouvée. Les groupes coopératifs d'essais devraient consacrer un dixième de leur budget à tester comment combler cet écart.",
  "idea-fund-ind-enabling-fund": "Les études requises avant un premier essai chez l'humain coûtent quelques millions et aucune subvention ne les finance. Un fonds dédié rendrait sa décision en quelques semaines et prendrait une petite part des revenus futurs éventuels.",
  "idea-fund-lmic-radiotherapy-finance": "Des dizaines de pays n'ont aucun appareil de radiothérapie. Il s'agirait de combiner un financement à long terme avec un appareil conçu pour être peu coûteux, robuste et facile à entretenir là où l'électricité et les ingénieurs sont rares.",
  "idea-fund-neutral-platform-sponsor": "Les essais qui comparent côte à côte les médicaments de nombreuses entreprises à un seul groupe témoin commun fonctionnent mieux quand aucune de ces entreprises ne les pilote. Un promoteur permanent à but non lucratif en ferait la norme plutôt qu'une rare exception.",
  "idea-fund-non-drug-trial-quota": "La chirurgie et la radiothérapie guérissent plus de personnes que les médicaments, mais ne reçoivent qu'une fraction des financements d'essais parce qu'aucune entreprise ne les sponsorise. Une règle leur garantirait une part fixe des fonds publics consacrés aux essais.",
  "idea-fund-omission-deescalation-trials": "Beaucoup de patients à faible risque subissent des opérations et une radiothérapie dont ils n'ont peut-être pas besoin. Les systèmes de santé financeraient les essais permettant de savoir qui peut s'en passer sans danger, et conserveraient les économies réalisées.",
  "idea-fund-pay-for-cure-annuities": "Plutôt que de payer des centaines de milliers d'avance pour une thérapie CAR-T ou une thérapie génique, le système de santé verserait des annuités qui s'arrêteraient si le cancer revient, de sorte que les entreprises soient payées pour des guérisons et non pour des tentatives.",
  "idea-fund-phase-zero-fund": "Avant d'investir dans un essai complet, administrer à quelques patients une dose infime d'un nouveau composé et vérifier par imagerie et analyses de sang s'il atteint la tumeur et touche sa cible. Financer ces petites études de façon systématique.",
  "idea-fund-prevention-moonshot": "Environ quatre cancers sur dix sont évitables avec des outils qui existent déjà. Il s'agirait de financer le travail ingrat et difficile qui consiste à apporter à tous les vaccins, le dépistage et la lutte contre le tabac, avec une rémunération aux résultats.",
  "idea-fund-public-nonprofit-cro": "Mener correctement un essai précoce exige des moniteurs, des gestionnaires de données, une déclaration des événements de sécurité et des dépôts réglementaires que les universités ne peuvent pas s'offrir auprès de prestataires commerciaux. Un organisme public à but non lucratif ferait ce travail à prix coûtant.",
  "idea-fund-radiotherapy-innovation-pathway": "Les nouvelles façons de délivrer la radiothérapie sont adoptées sans les étapes de test que traversent les médicaments, puis deviennent difficiles à évaluer. Un parcours défini, avec exonération de redevances et des étapes de preuve claires, apporterait de la rigueur sans freiner le progrès.",
  "idea-fund-replication-set-aside": "Avant de dépenser des millions pour transformer une découverte de laboratoire en médicament, dépenser un peu pour qu'un laboratoire indépendant vérifie qu'elle est réelle. Les financeurs réserveraient une petite part de leurs fonds précisément à cela.",
  "idea-fund-rt-planning-ai-capacity": "Délimiter les cibles et planifier la radiothérapie prend des heures d'un temps d'expert rare. Une IA correctement testée pourrait en faire une grande partie, permettant à la même équipe de traiter beaucoup plus de patients, à condition que les régulateurs et les payeurs fixent des règles claires pour la valider et la rémunérer.",
  "idea-fund-shelved-asset-escrow": "Lorsqu'une entreprise abandonne le développement d'un médicament anticancéreux pour des raisons commerciales, les droits et les données seraient automatiquement proposés aux associations caritatives et aux universités à des conditions fixées, au bout de deux ans, afin que des composés prometteurs ne disparaissent pas.",
  "idea-fund-surgeon-scientist-pathway": "Presque aucun chirurgien ni oncologue radiothérapeute n'a le temps ou les moyens de faire de la recherche. Des bourses de formation dédiées, avec du temps protégé, constitueraient la main-d'œuvre dont les essais en chirurgie et en radiothérapie ont besoin.",
  "idea-fund-surgical-video-registry": "L'habileté des chirurgiens influe sur le risque de récidive du cancer, mais personne ne la mesure. Enregistrer les opérations et les noter, de plus en plus grâce à l'IA, puis relier ces notes aux résultats rendrait la qualité chirurgicale visible et améliorable.",
  "idea-fund-value-based-patent-extension": "Un médicament qui ajoute des années de vie gagnerait des années supplémentaires de protection commerciale ; un médicament qui n'ajoute que quelques semaines n'en gagnerait aucune. Les prolongations seraient perdues si le bénéfice promis n'est pas confirmé.",
  "idea-immunotherapy-mss-crc": "Quatre-vingt-quinze pour cent des cancers de l'intestin ignorent l'immunothérapie. Les combinaisons qui \"réchauffent\" la tumeur (thérapies ciblées, radiothérapie, nouveaux points de contrôle) sont le principal espoir.",
  "idea-in-vivo-car-solid": "Si une nanoparticule lipidique peut fabriquer des cellules CAR-T à l'intérieur du corps pour traiter un lymphome, elle pourrait être réadministrée chaque semaine contre des cibles de tumeurs solides que les CAR-T autologues ne parviennent pas à tenir dans la durée.",
  "idea-interception-vaccines": "Vacciner les personnes porteuses de mutations BRCA ou Lynch contre les antigènes que leurs futurs cancers exprimeront, avant qu'aucun cancer n'existe.",
  "idea-mced-plus-fapi": "Quand une analyse de sang indique « signal de cancer, origine incertaine », une TEP au FAPI peut le trouver là où le FDG n'y parvient pas.",
  "idea-menin-infant-all": "La leucémie du nourrisson est presque entièrement due à des fusions de KMT2A, que les inhibiteurs de la ménine ont été conçus pour cibler. Il faut les ajouter au nouveau traitement de base contenant du blinatumomab.",
  "idea-moon-closed-loop-adaptive-therapy": "Plutôt que d'administrer la même dose jusqu'à ce que le cancer progresse, mesurer l'ADN tumoral dans le sang toutes les quelques semaines et laisser un algorithme validé augmenter, réduire, suspendre ou changer les médicaments pour maintenir le cancer sous contrôle plus longtemps.",
  "idea-moon-cold-to-hot-programme": "L'immunothérapie agit sur les tumeurs dans lesquelles les cellules immunitaires peuvent pénétrer et reste sans effet sur celles qui les tiennent à l'écart. Tester systématiquement des moyens d'ouvrir ces tumeurs fermées, en mesurant les résultats par des cartes spatiales.",
  "idea-moon-in-vivo-cart-generic-price": "Au lieu de fabriquer en usine une thérapie cellulaire à partir des cellules de chaque patient, injecter une particule produite en masse qui reprogramme les cellules immunitaires directement dans l'organisme, pour qu'une dose coûte des milliers plutôt que des centaines de milliers.",
  "idea-moon-indolence-classifiers-with-screening": "Le dépistage détecte des cancers qui n'auraient jamais causé de tort, à côté de cancers dangereux. Associer à chaque test de dépistage un test qui distingue les uns des autres, pour que les personnes dont les résultats sont bénins puissent surveiller et attendre en toute sécurité.",
  "idea-moon-mrd-weather-service": "Après une chirurgie ou un traitement curatif, chacun bénéficie d'analyses de sang régulières à la recherche d'ADN cancéreux résiduel, et les résultats mis en commun alimentent des prévisions sur qui va rechuter ainsi que des essais d'intervention précoce.",
  "idea-moon-neoantigen-vaccines-at-scale": "Les vaccins adaptés aux mutations tumorales de chaque patient montrent un bénéfice réel, mais leur fabrication coûte une fortune. Automatiser l'ensemble du processus pour qu'un vaccin personnalisé coûte à peu près autant qu'une cure de chimiothérapie.",
  "idea-moon-population-interception": "Plutôt que des programmes de dépistage distincts pour quelques cancers, évaluer le risque global de cancer de chaque adulte et proposer des analyses de sang, de l'imagerie et un traitement préventif adaptés à ce risque, le tout au sein d'un système unique qui apprend.",
  "idea-moon-radiotherapy-for-everyone-2040": "La moitié des patients atteints de cancer ont besoin de radiothérapie et la plupart du monde n'y a pas accès. S'engager sur des appareils à bas coût, une planification automatisée et du personnel formé pour que l'accès soit universel d'ici 2040.",
  "idea-moon-synthetic-lethality-map-every-driver": "Pour chaque mutation cancérigène, identifier tous les gènes dont la cellule cancéreuse devient nouvellement dépendante, dans chaque tissu, afin que même les drivers non ciblables aient des partenaires ciblables.",
  "idea-neoadjuvant-io-glioblastoma": "Administrer l'immunothérapie avant la chirurgie plutôt qu'après, pour que la tumeur soit encore présente et éduque le système immunitaire, puis l'examiner de l'intérieur pour comprendre ce qui s'est passé.",
  "idea-nl-ask-about-diet-prebunking": "Presque tous les patients nouvellement diagnostiqués cherchent ce qu'ils doivent manger et tombent sur des affirmations sur la privation de sucre, les régimes alcalins et les cures de jus. Si l'équipe d'oncologie aborde la question de l'alimentation en premier et fournit une information fiable, les mythes ont moins de place.",
  "idea-nl-sleep-circadian-survivorship-rct": "La thérapie de l'insomnie fonctionne bien chez les survivants du cancer et n'est presque jamais proposée. Un essai qui rétablirait le sommeil puis suivrait les récidives permettrait de vérifier si restaurer l'horloge biologique modifie la maladie et non seulement le symptôme.",
  "idea-nl-upf-controlled-feeding-trial": "Nous ne savons pas si les aliments ultra-transformés augmentent le risque de cancer parce qu'ils font grossir ou à cause de quelque chose dans l'aliment lui-même. Nourrir des volontaires avec des régimes appariés pendant quelques semaines et mesurer la biologie liée au cancer permettrait de distinguer les deux.",
  "idea-organoid-guided-adc": "Cultiver la tumeur du patient en boîte de culture et tester quelle charge d'ADC la tue avant de choisir parmi trois ADC anti-TROP2.",
  "idea-post-neoadjuvant-adc": "Les patientes dont le TNBC résiste à la chimio-immunothérapie préopératoire ont un risque élevé de rechute. Leur donner un ADC après la chirurgie.",
  "idea-prev-glp1-cancer-prevention-rct": "L'obésité augmente le risque de 13 cancers. Les médicaments amaigrissants sont désormais largement utilisés ; un grand essai devrait vérifier s'ils préviennent réellement le cancer, et pas seulement le diabète et les maladies cardiaques.",
  "idea-prev-interval-cancer-audit-blood-tests": "Quand un test de dépistage laisse passer un cancer, nous devrions le savoir. Relier chaque résultat négatif au registre des cancers et publier ce qui a été manqué, par stade, devrait être une condition d'utilisation.",
  "idea-prev-ldct-ai-negative-triage": "La plupart des scanners de dépistage sont normaux. Laisser une IA validée les classer comme tels et n'envoyer au radiologue que les examens signalés permettrait d'étendre le dépistage sans radiologues supplémentaires.",
  "idea-prev-lmic-five-cancer-methylation-test": "La plupart des décès par cancer surviennent dans les pays à revenu faible ou intermédiaire, où l'imagerie et les endoscopies sont rares. Un test sanguin de méthylation peu coûteux, calibré pour les cancers du foie, de l'estomac, de l'œsophage, du col de l'utérus et du sein, pourrait combler ce manque.",
  "idea-prev-lynch-frameshift-vaccine-rct": "Les tumeurs du syndrome de Lynch partagent des mutations prévisibles que le système immunitaire peut cibler. Un vaccin en essais précoces pourrait être évalué pour voir s'il prévient les polypes et les cancers chez les porteurs.",
  "idea-prev-mced-stage-endpoint-surrogate": "Les tests sanguins qui recherchent de nombreux cancers à la fois mettent une décennie à prouver qu'ils sauvent des vies. Les régulateurs pourraient accepter une baisse des cancers de stade avancé comme première réponse, à condition que les essais continuent ensuite à compter les décès.",
  "idea-prev-opportunistic-ct-ai-registry": "Des centaines de millions de scanners sont réalisés chaque année pour d'autres raisons. Un logiciel pourrait examiner chacun d'eux à la recherche de changements précoces du poumon, du rein, du foie et du pancréas, mais seulement si un système de suivi existe.",
  "idea-prev-reflex-germline-testing": "Toute personne atteinte d'un cancer de l'ovaire, du pancréas, de la prostate métastatique ou d'un cancer avec déficience du système de réparation des mésappariements devrait être testée pour des mutations héréditaires, mais beaucoup ne le sont pas. En faire une étape automatique du laboratoire, avec possibilité de refus.",
  "idea-reg-in-vivo-cart-off-the-shelf-vial": "Certains nouveaux médicaments reprogramment les cellules immunitaires directement dans l'organisme par une injection, en se passant totalement de l'usine. Vérifier si cela rend la CAR-T abordable et disponible dans les hôpitaux ordinaires.",
  "idea-senolytics-after-chemo": "La chimiothérapie laisse derrière elle des cellules sénescentes qui enflamment les tissus et favorisent la rechute des tumeurs. Une courte cure de médicaments sénolytiques ensuite pourrait réduire à la fois les rechutes et les effets secondaires à long terme.",
  "idea-single-dose-hpv-self-sampling-elimination": "Une seule injection pour les filles et un auto-prélèvement envoyé par la poste pour les femmes pourraient atteindre les cibles 90-70-90 de l'OMS pour une fraction du coût du modèle traditionnel à trois doses en centre de santé.",
  "idea-splice-neoantigens": "Les mutations de la machinerie d'épissage de la cellule produisent des protéines anormales récurrentes chez de nombreux patients. Si les lymphocytes T peuvent les reconnaître, un seul vaccin pourrait servir à beaucoup de personnes au lieu d'être fabriqué pour chaque patient.",
  "idea-tr1-adc-dose-and-schedule-optimisation": "Les anticorps conjugués transportent une chimiothérapie puissante jusque dans les tumeurs, mais provoquent aussi des atteintes pulmonaires, oculaires et nerveuses qui dépendent de l'exposition totale. Des essais comparant des doses plus faibles, des intervalles plus longs et des plafonds de charge pourraient préserver le bénéfice tout en réduisant ces effets.",
  "idea-tr1-brain-mets-default-included": "Jusqu'à un cinquième des personnes atteintes de tumeurs solides avancées ont des métastases cérébrales et sont généralement exclues des essais. Admettre celles dont l'atteinte cérébrale est traitée, stable ou asymptomatique élargirait les essais et nous dirait si les médicaments agissent dans le cerveau.",
  "idea-tr1-ctdna-guided-stop-in-metastatic-disease": "Si une analyse de sang ne montre plus d'ADN tumoral après des mois de traitement, un essai pourrait tester l'arrêt temporaire du médicament, repris seulement lorsque l'ADN réapparaît, offrant aux patients une pause sans attendre que l'imagerie montre une progression.",
  "idea-tr1-extended-interval-checkpoint-dosing": "Les anticorps d'immunothérapie restent actifs dans l'organisme pendant des semaines, mais sont souvent administrés toutes les deux ou trois semaines. Après quelques mois, espacer les doses à tous les deux ou trois mois pourrait fonctionner aussi bien, avec moins de visites à l'hôpital et un coût bien plus faible.",
  "idea-tr1-immunotherapy-stop-trials": "L'immunothérapie est souvent administrée pendant deux ans ou jusqu'à ce qu'elle cesse d'agir, mais les réponses peuvent durer longtemps après l'arrêt. Des essais qui répartissent au hasard les patients répondeurs entre arrêt et poursuite montreraient si l'année supplémentaire est nécessaire.",
  "idea-tr1-low-dose-immunotherapy-for-lmic": "Un essai mené en Inde a montré qu'ajouter à la chimiothérapie une très faible dose d'un médicament d'immunothérapie, environ un vingtième de la quantité habituelle, améliorait la survie dans le cancer de la tête et du cou. Si cela se confirme, l'immunothérapie pourrait devenir abordable pour des millions de personnes.",
  "idea-tr1-ngs-report-live-trial-match": "Le rapport qui indique à un patient les mutations de sa tumeur devrait aussi lui indiquer quels essais recrutent pour ces mutations à portée raisonnable, avec un statut vérifié la semaine même plutôt que copié d'une liste périmée.",
  "idea-tr1-surrogate-validation-programme": "Les essais mesurent souvent un substitut de la survie, comme le délai avant que le cancer progresse à l'imagerie. Un organisme indépendant vérifierait, pour chaque cancer et chaque type de traitement, si ce substitut prédit réellement la survie, et publierait la réponse.",
  "idea-tr1-tumour-agnostic-approval-standard": "Certains médicaments sont approuvés pour tout cancer porteur d'une mutation donnée. Des règles claires sur le nombre de types de cancer à tester et sur la manière de combiner les résultats entre eux rendraient ces approbations plus cohérentes et plus rapides.",
  "idea-tr1-window-of-opportunity-default": "Entre le diagnostic et la chirurgie, il s'écoule généralement quelques semaines. Administrer un nouveau médicament pendant cet intervalle et comparer la tumeur avant et après la chirurgie montre s'il atteint sa cible chez de vraies personnes, rapidement et à faible coût.",
  "idea-tr2-ctdna-mrd-qualification": "Si une analyse de sang indique de façon fiable si le cancer reviendra après la chirurgie, les essais pourraient s'en servir au lieu d'attendre des années la rechute. Les régulateurs disposent d'une procédure pour reconnaître un tel test ; l'oncologie devrait l'utiliser.",
  "idea-tr2-organoid-coclinical-arms": "Pendant que les patients sont traités dans un essai plateforme, leurs cellules tumorales sont cultivées en boîte et testées face à des dizaines de paires de médicaments. Les paires qui l'emportent en culture deviennent les bras suivants.",
  "idea-tr2-pdl1-digital-calibration": "Il existe plusieurs tests PD-L1 différents, chacun lié à un médicament différent, et ils ne concordent pas. Une échelle unique calibrée numériquement permettrait de traduire le résultat de n'importe quel laboratoire dans le seuil de n'importe quel médicament.",
  "idea-tr2-perpetual-platforms": "Plutôt que de lancer un nouvel essai pour chaque paire de médicaments, maintenir pour chaque cancer un essai toujours ouvert que de nouveaux bras peuvent rejoindre et quitter, en partageant le même groupe témoin.",
  "idea-tr2-preclinical-negative-registry": "La plupart des expériences de laboratoire qui échouent ne sont jamais publiées, si bien que d'autres laboratoires les répètent. Un registre simple et structuré, avec une entrée citable pour chaque expérience ratée, mettrait fin à ce gaspillage.",
  "idecabtagene-vicleucel": "Idecabtagene vicleucel a été la première CAR-T contre le myélome (2021) et est désormais approuvée après deux lignes de traitement antérieures, sur la base de KarMMa-3.",
  "idh-2hg": "Une seule mutation dans une enzyme du métabolisme (IDH1 ou IDH2) fait déverser aux cellules une molécule qu'elles ne devraient jamais produire, le 2-hydroxyglutarate. Celle-ci bloque la machinerie qui efface les marques chimiques sur l'ADN et les histones, si bien que les cellules du sang et du cerveau restent bloquées avant d'avoir mûri. Des comprimés qui inhibent l'enzyme mutante leur permettent de mûrir à nouveau.",
  ielsg: "Un groupe international basé en Suisse qui mène les essais définissant le traitement des lymphomes extraganglionnaires rares, dont le lymphome primitif du SNC et le lymphome gastrique du MALT.",
  "ighv-status": "Indique si le gène d'anticorps de la leucémie a été « édité » par le système immunitaire. Non muté signifie une LLC à croissance plus rapide et un bénéfice plus important des traitements ciblés par rapport à la chimiothérapie.",
  illuccix: "Le kit prêt au marquage de Telix qui permet à tout service de médecine nucléaire de préparer l'examen PSMA au gallium pour le cancer de la prostate.",
  "im-seock-ah": "A dirigé MONALEESA-7, qui a prouvé qu'un inhibiteur de CDK4/6 prolonge la survie dans le cancer du sein préménopausique, et pilote le réseau coréen d'essais sur le cancer du sein.",
  "imagene-ai": "Imagene AI entraîne de grands modèles d'intelligence artificielle sur des images de biopsies colorées classiques afin qu'en quelques minutes, une lame puisse prédire quelles altérations génétiques porte une tumeur du poumon, aidant les médecins à choisir un traitement ciblé avant le retour des tests génétiques, plus lents.",
  "imagine-varnimcabtagene": "Le premier essai de CAR-T mené par l'industrie en Inde, qui a testé une version fabriquée à Bengaluru de la thérapie cellulaire d'un hôpital de Barcelone dans le lymphome et la leucémie en rechute ; il a conduit à l'approbation de Qartemi.",
  imbrave150: "L'essai qui a mis fin à l'ère du sorafénib : l'immunothérapie associée à un anticorps anti-VEGF est devenue le nouveau standard de première ligne dans le cancer du foie.",
  "imcgp100-202": "Le premier médicament à avoir prolongé la vie dans le mélanome uvéal métastatique, et le premier traitement fondé sur un récepteur de cellules T à remporter une phase 3.",
  imetelstat: "L'imetelstat est le premier inhibiteur de la télomérase approuvé pour un cancer, quel qu'il soit ; il affranchit des transfusions de nombreux patients atteints de SMD de faible risque après l'échec des facteurs de croissance.",
  imid: "Le thalidomide et ses descendants, le lénalidomide et le pomalidomide, qui agissent en détournant une étiquette cellulaire d'élimination des déchets (le céréblon) pour détruire deux protéines dont dépendent les cellules de myélome, tout en stimulant les cellules T et NK. Les versions plus récentes et plus puissantes sont appelées CELMoDs.",
  imlunestrant: "L'imlunestrant est le dégradeur oral du récepteur des œstrogènes de Lilly, approuvé en 2025 dans le cancer du sein porteur d'une mutation ESR1, et dont l'efficacité en association avec l'abémaciclib a été démontrée quel que soit le statut mutationnel.",
  "immune-endocrinopathy": "L'immunothérapie peut s'attaquer aux glandes productrices d'hormones : le plus souvent la thyroïde (aboutissant généralement à une hypothyroïdie nécessitant des comprimés à vie), plus rarement l'hypophyse (hypophysite) ou les glandes surrénales, ce qui peut mettre la vie en danger si l'atteinte passe inaperçue.",
  "immune-exclusion": "Une tumeur où les cellules immunitaires arrivent mais sont bloquées en périphérie, retenues par du tissu cicatriciel et par des signaux tels que le TGF-β.",
  "immune-stimulating-adc": "Un conjugué anticorps-immunostimulant (ISAC) est un ADC dont la charge utile réveille le système immunitaire à l'intérieur de la tumeur au lieu d'empoisonner la cellule.",
  immuneel: "Une société de thérapie cellulaire de Bengaluru qui a apporté en Inde le CAR-T anti-CD19 académique de Barcelone sous le nom de Qartemi, deuxième CAR-T approuvé dans le pays, à l'issue de l'essai IMAGINE.",
  immunocore: "Inventeur du bispécifique ImmTAC à TCR soluble ; le tébentafusp a été le premier à améliorer la survie dans une tumeur solide.",
  impassion130: "IMpassion130 a été le premier succès de l'immunothérapie dans le cancer du sein, remis en cause par la suite lorsqu'un essai jumeau a échoué et que l'approbation a été retirée.",
  imroz: "Dans IMROZ, l'ajout de l'isatuximab au VRd a réduit la progression de 40 % chez des patients âgés non candidats à une greffe.",
  "in-situ": "Du latin « sur place » : des cellules anormales qui ressemblent à un cancer mais n'ont pas encore franchi la couche dans laquelle elles sont apparues. Stade 0. Encore incapables de se propager, et généralement guérissables par exérèse.",
  "in-situ-vaccination": "Traiter une tumeur si vigoureusement que le système immunitaire apprend à attaquer toutes les autres, en utilisant la tumeur elle-même comme vaccin.",
  "in-vitro-in-vivo": "In vitro signifie « dans le verre » : des expériences sur des cellules ou des molécules dans une boîte de culture. In vivo signifie « dans le vivant » : des expériences chez l'animal ou chez l'humain. Un médicament qui tue des cellules cancéreuses in vitro n'a franchi que le premier obstacle, le plus facile.",
  inavo120: "Une triple association qui a doublé le temps sans progression et, fait inhabituel dans cette maladie, prolongé la survie de sept mois dans un groupe difficile à traiter.",
  "inc-colombia": "L'institut national du cancer de Colombie, chargé de la politique de lutte contre le cancer, de l'observatoire national du cancer et des soins spécialisés à Bogotá.",
  indigo: "La première victoire d'une thérapie ciblée dans les tumeurs cérébrales de bas grade : un comprimé qui a plus que doublé le délai avant la croissance de la tumeur, repoussant de plusieurs années la radiothérapie et la chimiothérapie.",
  "induction-therapy": "Le premier bloc de traitement, le plus intensif, destiné à faire entrer le cancer en rémission. Dans la leucémie, c'est l'hospitalisation qui nettoie la moelle ; dans les tumeurs solides, c'est la chimiothérapie administrée avant le traitement local définitif.",
  "inen-peru": "L'institut national du cancer du Pérou, plus grand hôpital de cancérologie de la région andine et coordinateur du plan national et du registre national du cancer du Pérou.",
  inflammation: "La réaction de l'organisme à une blessure ou à une infection : les cellules immunitaires et le liquide affluent, provoquant rougeur, chaleur et gonflement. Les poussées brèves guérissent ; l'inflammation chronique qui couve favorise le cancer.",
  "infusion-devices-vascular-access": "Les dispositifs de perfusion sont les chambres implantables, les pompes intelligentes et les pompes portables qui administrent la chimiothérapie en toute sécurité, y compris les perfusions de 46 heures que les patients emportent chez eux.",
  inivata: "Inivata était une société de biopsie liquide de Cambridge, au Royaume-Uni, dont les tests sanguins détectent des traces d'ADN tumoral ; elle a été rachetée en 2021 par le groupe de laboratoires américain NeoGenomics, qui commercialise désormais son test RaDaR.",
  insightec: "Société d'ultrasons focalisés guidés par IRM, dont l'application en oncologie est l'ouverture de la barrière hémato-encéphalique pour les tumeurs cérébrales.",
  "insilico-medicine": "Société de découverte de médicaments par IA générative, cotée à Hong Kong depuis décembre 2025, avec un candidat pan-KRAS et un inhibiteur pan-TEAD en développement clinique.",
  "institut-bergonie": "L'hôpital de Bordeaux dédié au cancer, un centre UNICANCER reconnu pour les sarcomes, les essais de phase précoce et la médecine de précision.",
  "institut-national-oncologie-rabat": "L'institut national d'oncologie du Maroc, centre de référence en cancérologie du CHU de Rabat et pilier du plan national de lutte contre le cancer de la Fondation Lalla Salma.",
  "institut-paoli-calmettes": "Le centre de lutte contre le cancer de Marseille, réputé en hématologie et greffe, chirurgie pancréatique, cancer du sein et recherche en immuno-oncologie.",
  "institut-pasteur": "L'institut de recherche parisien historique fondé par Louis Pasteur, dont les travaux sur le cancer portent sur les virus oncogènes, l'immunologie et le microbiome.",
  "institut-salah-azaiez": "L'institut national du cancer de Tunisie, l'un des plus anciens d'Afrique (1969), et le principal centre d'Afrique du Nord pour l'enregistrement des cancers et la recherche sur le cancer du sein et le carcinome du nasopharynx.",
  "int-milan": "L'Istituto Nazionale dei Tumori est l'institut national du cancer d'Italie et un leader dans les sarcomes, l'oncologie thoracique et l'immunothérapie.",
  "interception-vaccination": "Vacciner des personnes qui n'ont pas encore de cancer mais qui ont de fortes chances d'en développer un, contre les antigènes que portera leur future tumeur.",
  "interferon-alfa": "L'interféron alfa a été le premier médicament biologique anticancéreux (1986). Il a servi à traiter la leucémie à tricholeucocytes, la LMC, le mélanome, le cancer du rein et le sarcome de Kaposi, et a été remplacé presque partout par des agents mieux tolérés.",
  interlace: "Six semaines de chimiothérapie générique peu coûteuse avant la chimioradiothérapie standard ont réduit les décès de 40 %, une avancée applicable partout dans le monde.",
  "intraoperative-radiotherapy": "Délivrer une dose unique élevée de radiation directement sur le lit tumoral pendant l'opération, les organes sains étant écartés ; utilisée surtout dans le cancer du sein comme alternative à des semaines de radiothérapie externe.",
  "intraperitoneal-chemotherapy": "Administrer la chimiothérapie directement dans la cavité abdominale par un cathéter, afin que les dépôts tumoraux sur le péritoine reçoivent une dose bien plus élevée que ce que le reste du corps tolérerait.",
  "intrathecal-therapy": "Administrer des médicaments directement dans le liquide qui entoure le cerveau et la moelle épinière, par une ponction dans le bas du dos ou via un petit réservoir placé sous le cuir chevelu, car la plupart des médicaments ne peuvent pas passer du sang vers cet espace.",
  "io-first-then-braf-mek": "Dans le mélanome porteur d'une mutation BRAF, commencer par l'immunothérapie et garder les comprimés ciblés en réserve ; l'ordre inverse coûte des vies.",
  "io-rechallenge-caution-rcc": "Reprendre l'immunothérapie en association avec un comprimé ciblé après un échec de l'immunothérapie ajoute des effets secondaires sans apporter de bénéfice.",
  "irreversible-electroporation": "L'électroporation irréversible utilise de brèves impulsions à haute tension qui percent des trous permanents dans les cellules tumorales tout en épargnant les vaisseaux et les canaux voisins.",
  "isabelle-ray-coquard": "A dirigé PAOLA-1, qui a montré que l'association olaparib et bevacizumab aide les femmes atteintes d'un cancer de l'ovaire HRD positif, au-delà des seules porteuses de BRCA.",
  "isb-2001": "Un anticorps découvert en Inde qui s'accroche simultanément à deux cibles des cellules de myélome tout en recrutant des lymphocytes T pour les détruire, licencié à AbbVie en 2025 dans le plus gros accord jamais conclu pour un médicament anticancéreux indien.",
  "isolated-limb-perfusion": "Isoler la circulation sanguine d'un bras ou d'une jambe pour y faire circuler des doses de chimiothérapie 15 à 20 fois supérieures à ce que le corps pourrait tolérer, afin de sauver des membres atteints de mélanome ou de sarcome qui seraient sinon amputés.",
  "isomorphic-labs": "La société de conception de médicaments d'Alphabet issue d'AlphaFold ; son premier candidat en oncologie conçu par IA a été autorisé à entrer en essais chez l'humain en janvier 2026, après une levée de fonds de 2,1 milliards de dollars.",
  isoqol: "La société savante des résultats rapportés par les patients et de la recherche sur la qualité de vie, dont les normes guident la façon dont les symptômes et la qualité de vie sont mesurés dans les essais en cancérologie.",
  "istanbul-oncology-institute": "L'institut d'oncologie de l'Université d'Istanbul, sur le campus de Çapa, un grand centre turc de formation et de recherche en oncologie mammaire, pédiatrique et en radiothérapie.",
  "itm-11": "Un deuxième radioligand au lutétium pour les tumeurs neuroendocrines, qui a surpassé le comprimé de référence everolimus dans un essai comparatif direct et attend une décision de la FDA.",
  "jaffer-ajani": "Oncologue spécialiste des cancers gastro-œsophagiens, qui a codirigé CheckMate 649, l'essai ayant ajouté le nivolumab à la chimiothérapie de première ligne du cancer gastrique.",
  "jain-hasmukh": "Premier auteur de l'essai de phase 1/2 de la première thérapie CAR-T indienne, qui a traité des adultes atteints de lymphome et de leucémie en rechute dans six centres en Inde.",
  "janet-rowley": "Travaillant à temps partiel sur la table de sa salle à manger en 1972, elle a montré que le chromosome de Philadelphie de la LMC est un échange entre les chromosomes 9 et 22. Le cancer avait une cause génétique, et l'imatinib a plus tard ciblé le gène fusionné.",
  "javier-cortes": "Oncologue spécialiste du sein, qui a dirigé DESTINY-Breast03 et DESTINY-Breast09, les essais qui ont fait d'Enhertu le traitement de référence des cancers HER2 positifs.",
  jco: "Le Journal of Clinical Oncology est la revue phare de l'ASCO et le pilier de l'oncologie clinique ; il publie des essais, les recommandations de l'ASCO et les suppléments de résumés du congrès annuel de l'ASCO.",
  "jeanne-tie": "A dirigé DYNAMIC, le premier essai randomisé à montrer que l'ADN tumoral circulant (ctDNA) peut guider en toute sécurité le choix des patients qui ont besoin d'une chimiothérapie après une chirurgie du cancer du côlon.",
  "jeffrey-weber": "A dirigé CheckMate 238, qui a fait du nivolumab adjuvant le traitement de référence après chirurgie du mélanome, et a codirigé l'essai de vaccin à ARNm KEYNOTE-942.",
  jfcr: "Le Cancer Institute Hospital of JFCR est le plus ancien institut du cancer du Japon (1908), reconnu pour la chirurgie du cancer gastrique et l'oncologie mammaire.",
  "johann-de-bono": "Johann de Bono a dirigé les essais qui ont apporté l'abiratérone et l'olaparib aux patients atteints d'un cancer de la prostate.",
  "john-haanen": "John Haanen a dirigé le premier essai randomisé de phase 3 de thérapie par TIL, qui a surpassé l'ipilimumab dans le mélanome.",
  "jonathan-rosenberg": "A dirigé les premiers essais de l'enfortumab vedotin et l'étude de l'atezolizumab qui a introduit pour la première fois l'immunothérapie dans le cancer de la vessie.",
  "jsmo-jsco-guidelines": "Les recommandations de la JSMO et de la JSCO sont les référentiels oncologiques du Japon, particulièrement solides pour les cancers de l'estomac, de l'œsophage, du foie et des voies biliaires, où les essais japonais ont fixé les standards mondiaux (gastrectomie D2, S-1, résection endoscopique), ainsi que pour les autorisations propres au Japon via la PMDA.",
  "judy-garber": "Une autorité de premier plan sur le risque héréditaire de cancer et sur la façon de traiter et de dépister les porteurs de BRCA.",
  "jupiter-02": "A introduit l'immunothérapie dans le cancer du nasopharynx, un cancer lié au virus d'Epstein-Barr et fréquent dans le sud de la Chine, et a obtenu la première autorisation américaine pour cette maladie.",
  "jw-therapeutics": "JW Therapeutics, coentreprise de Juno et de WuXi AppTec, a mis au point le relma-cel, la première CAR-T développée et fabriquée en Chine à avoir été approuvée.",
  "k-hospital-hanoi": "L'hôpital et institut national du cancer du Vietnam, le plus grand établissement de cancérologie du pays, qui coordonne son registre du cancer et son programme de lutte contre le cancer.",
  "kang-yoon-koo": "A dirigé l'essai ATTRACTION-2 du nivolumab et l'essai SPOTLIGHT du zolbetuximab, deux des études sur le cancer gastrique qui ont marqué la décennie.",
  "kara-kelly": "Dirige le comité lymphome de Hodgkin du COG et les essais qui apportent le brentuximab et le nivolumab aux enfants atteints de cette maladie.",
  katherine: "Passer à un ADC après la chirurgie, lorsque le traitement préopératoire avait laissé du cancer résiduel, a réduit de moitié le risque de récidive et amélioré la survie.",
  "keap1-nrf2": "KEAP1-NRF2 est l'interrupteur de défense antioxydante de la cellule. Les cancers du poumon cassent souvent le bouton d'arrêt (KEAP1), ce qui laisse NRF2 allumé en permanence ; celui-ci détoxifie la chimiothérapie et la radiothérapie et rend ces tumeurs résistantes à presque tout.",
  "keio-university-hospital": "Le plus ancien hôpital universitaire privé de Tokyo, connu pour la chirurgie des cancers digestifs et de l'œsophage, le profilage génomique des cancers et la recherche translationnelle.",
  "ken-she": "Une seule dose de vaccin contre le HPV s'est révélée efficace à 97,5 % contre les deux types de HPV les plus dangereux, ce qui rend réaliste la vaccination du monde entier.",
  "kentucky-markey": "Le centre intégré du NCI du Kentucky, qui dessert les Appalaches, où les taux de cancer du poumon et de cancer colorectal sont parmi les plus élevés des États-Unis.",
  "kerala-oral-screening": "Des agents de santé formés, qui examinaient l'intérieur de la bouche des consommateurs de tabac et d'alcool au Kerala, ont réduit d'un tiers les décès par cancer de la bouche, et des quatre cinquièmes chez ceux qui se sont présentés à chaque tour de dépistage.",
  "kevin-harrington": "Kevin Harrington est un oncologue spécialiste des cancers de la tête et du cou et un pionnier des virus oncolytiques, qui a dirigé l'essai OPTiM du T-VEC.",
  "keynote-006": "L'essai qui a fait du blocage de PD-1 le premier choix devant l'ancien médicament anti-CTLA-4, avec un tiers des patients en vie à dix ans.",
  "keynote-024-189": "Les deux essais qui ont fait de l'immunothérapie, seule ou associée à la chimiothérapie, le premier traitement de la plupart des cancers du poumon avancés.",
  "keynote-048": "A fait de l'immunothérapie le premier traitement du cancer de la tête et du cou avancé, seule pour les tumeurs riches en PD-L1 et associée à la chimiothérapie pour les autres.",
  "keynote-177": "L'essai qui a fait de l'immunothérapie seule, sans chimiothérapie, le premier traitement des 5 % de cancers de l'intestin dont le correcteur d'orthographe de l'ADN est défaillant. Plus de la moitié des patients étaient en vie à cinq ans.",
  "keynote-426": "La première association d'une immunothérapie et d'un comprimé de thérapie ciblée dans le cancer du rein, améliorant la survie dans tous les groupes de risque.",
  "keynote-689": "Le premier nouveau traitement en six ans pour les cancers de la tête et du cou curables : l'immunothérapie encadrant la chirurgie a doublé la durée pendant laquelle les patients sont restés sans événement.",
  "keynote-b96": "Après une décennie d'échecs, le premier essai d'immunothérapie à prolonger la survie dans le cancer de l'ovaire, conduisant à la première autorisation d'un inhibiteur de point de contrôle dans cette maladie.",
  "kim-chi": "A dirigé TITAN et MAGNITUDE, apportant l'apalutamide dans la maladie hormonosensible et le niraparib dans le cancer de la prostate porteur de mutations HRR.",
  "komal-jhaveri": "Mène la prochaine vague de l'hormonothérapie : les SERD oraux comme l'imlunestrant et l'inhibiteur de PI3K inavolisib.",
  "koo-foundation-sun-yat-sen-cancer-center": "Le premier hôpital de Taïwan entièrement dédié au cancer, fondé en 1990 sur le modèle du MD Anderson et connu pour sa prise en charge multidisciplinaire et la transparence de ses résultats.",
  kymera: "Société spécialisée dans les dégradeurs oraux, principalement en immunologie, dont le dégradeur de type colle moléculaire ciblant CDK2 a fait l'objet d'une option de Gilead en 2026 pour les cancers dépendants de CCNE1.",
  "kyushu-university-hospital": "Le principal hôpital universitaire de l'ouest du Japon, remarquable pour sa recherche en chirurgie digestive, la transplantation hépatique et l'hématologie.",
  "la-fe-valencia": "Le grand hôpital public de Valence, dont le service d'hématologie a façonné le traitement de la leucémie aiguë promyélocytaire au sein du groupe PETHEMA.",
  lantheus: "Lantheus fabrique Pylarify, le principal agent de TEP ciblant le PSMA, avec une nouvelle formulation TruVu approuvée en mars 2026.",
  "laurence-albiges": "Spécialiste française du cancer du rein qui a codirigé CheckMate 214 et les essais du belzutifan.",
  lazertinib: "Comprimé anti-EGFR de troisième génération, utilisé avec l'amivantamab dans le premier schéma thérapeutique à avoir surpassé l'osimertinib dans le cancer du poumon avec mutation de l'EGFR.",
  "lch-iii": "Le troisième essai international de la Histiocyte Society a montré que traiter l'histiocytose langerhansienne multisystémique pendant une année complète, plutôt que six mois, réduit environ de moitié le risque de rechute, tandis que l'ajout de méthotrexate n'a apporté que de la toxicité.",
  lesion: "Le mot neutre qu'emploient les médecins pour toute zone anormale de tissu vue à l'imagerie ou à l'examen : une masse, un nodule, une ombre. Il peut s'agir ou non d'un cancer tant qu'une biopsie ne l'a pas établi.",
  "letetresgene-autoleucel": "Letetresgene autoleucel est une deuxième thérapie par récepteur de lymphocytes T modifié pour le sarcome, ciblant NY-ESO-1 dans le sarcome synovial et le liposarcome myxoïde/à cellules rondes ; une BLA est attendue d'ici la fin de 2026.",
  "leukemia-lymphoma-society": "La Leukemia & Lymphoma Society est la principale association caritative américaine consacrée aux cancers du sang ; elle a la particularité de mener ses propres essais de médecine de précision (Beat AML, PedAL) et d'investir directement dans les biotechs, tout en proposant une aide au reste à charge et des spécialistes de l'information en entretien individuel.",
  leuprolide: "La leuproréline est l'injection qui coupe la production de testostérone, socle de l'hormonothérapie du cancer de la prostate depuis les années 1980 ; elle sert aussi à la suppression ovarienne dans le cancer du sein avant la ménopause.",
  lgsoc: "Le cancer séreux de l'ovaire de bas grade est une forme de cancer de l'ovaire à croissance lente, dépendante de RAS, qui résiste à la chimiothérapie mais répond aux bloqueurs hormonaux et aux médicaments de la voie MEK.",
  "li-zonghai": "Zonghai Li a fait passer la thérapie CAR-T des cancers du sang au cancer de l'estomac, en fondant CARsgen et en développant satri-cel, la première CAR-T approuvée pour une tumeur solide.",
  "lidocaine-peritumoral-tmh": "Injecter un anesthésique local courant autour de la tumeur quelques minutes avant l'opération a réduit le risque de récidive et de décès dans un essai indien portant sur 1,583 femmes, pour un coût presque nul.",
  ligand: "La molécule qui s'emboîte dans un récepteur et l'active, la clé de la serrure du récepteur. Les facteurs de croissance, les hormones et les cytokines sont tous des ligands.",
  "liger-hn1": "Évalue si un anticorps à deux bras dirigé contre l'EGFR et un marqueur de cellules souches peut améliorer les résultats de l'immunothérapie de première ligne dans les cancers de la tête et du cou.",
  "limited-extensive-stage": "Le cancer du poumon à petites cellules se classe en deux catégories au lieu des quatre stades habituels : limité (confiné à un côté du thorax et traitable dans un seul champ d'irradiation, environ un tiers des patients) ou étendu (tout le reste).",
  linvoseltamab: "Linvoseltamab est le bispécifique anti-BCMA de Regeneron, approuvé en juillet 2025 avec le taux de réponse complète le plus élevé de sa classe dans son étude pivot.",
  litt: "La thermothérapie interstitielle par laser fait passer une fibre laser par un petit orifice dans le crâne, sous surveillance IRM en temps réel, pour chauffer et détruire des tumeurs cérébrales profondes qu'un chirurgien ne pourrait pas atteindre sans danger.",
  locametz: "Le kit de Novartis pour l'imagerie PSMA au gallium, approuvé le même jour que Pluvicto comme l'examen qui détermine quels hommes peuvent recevoir ce médicament radioactif.",
  "logic-gated-therapeutics": "Des cellules ou des médicaments qui ne s'activent que lorsque deux conditions sont réunies en même temps, de sorte que les tissus sains n'en présentant qu'une seule sont épargnés.",
  lomustine: "Un ancien comprimé de chimiothérapie utilisé lorsque le glioblastome récidive, et le bras témoin que la plupart des nouveaux médicaments contre le glioblastome doivent surpasser.",
  "low-risk-dtc": "Petits cancers de la thyroïde confinés à la glande, sans extension. Ils sont presque toujours guéris par la chirurgie seule et ne nécessitent plus d'iode radioactif.",
  "lu-shun": "Investigateur d'essais cliniques sur le cancer du poumon à Shanghai, qui a dirigé de nombreuses études chinoises de phase 3 sur les anti-PD-1 et les EGFR-TKI.",
  "lu177-psma-it": "Le 177Lu-PSMA-I&T est un deuxième radioligand PSMA, chimiquement différent de Pluvicto, qui a réussi deux essais de phase 3 sur la progression mais n'a pas encore démontré de bénéfice en survie.",
  "ludwig-cancer-research": "L'institut de recherche sur le cancer que l'armateur Daniel K. Ludwig a doté en 1971 de la quasi-totalité de ses avoirs internationaux ; il a consacré plus de 1.8 milliard de dollars de ses propres fonds à la science du cancer.",
  "lugano-classification": "La classification de Lugano est le système de stadification des lymphomes : stades I à IV selon le nombre de territoires ganglionnaires et d'organes atteints, avec des critères de réponse fondés sur la TEP.",
  "luis-diaz": "A codirigé les travaux qui ont fait du pembrolizumab le premier médicament anticancéreux approuvé indépendamment du type de tumeur, pour les tumeurs présentant un déficit du système de réparation des mésappariements.",
  lumpectomy: "Retirer uniquement la tumeur avec une marge de tissu mammaire sain, en conservant le sein ; presque toujours suivie d'une radiothérapie.",
  "lymph-node-status": "Indique si le cancer a atteint les ganglions lymphatiques voisins, les filtres situés le long du drainage lymphatique. C'est le facteur prédictif le plus puissant pour savoir si le cancer a quitté l'organe, et il oriente la plupart des décisions de traitement complémentaire après la chirurgie.",
  lymphodepletion: "Une courte cure de chimiothérapie (généralement fludarabine et cyclophosphamide) administrée dans les jours précédant une perfusion de CAR-T pour éliminer les propres lymphocytes du patient, ce qui libère de la place et des signaux de croissance pour que les cellules modifiées se multiplient.",
  "lymphoedema-decongestive-therapy": "Le gonflement du bras ou de la jambe après une chirurgie ganglionnaire ou une radiothérapie se traite par vêtements de compression, massages spécialisés, soins de la peau et exercice. La musculation, autrefois interdite, s'est révélée dans un essai randomisé réduire les poussées plutôt que les provoquer.",
  "mage-a4": "Une protéine normalement présente uniquement dans le testicule, que certains sarcomes et d'autres tumeurs réactivent ; des lymphocytes T peuvent être modifiés pour en reconnaître des fragments.",
  "maha-hussain": "A dirigé PROSPER et l'analyse de survie de PROfound, et a tranché la question de l'hormonothérapie intermittente avec SWOG 9346.",
  "maintenance-therapy": "Traitement continu et plus léger, administré après que le traitement principal a fait régresser le cancer, pour le maintenir sous contrôle aussi longtemps que possible plutôt que pour le réduire davantage.",
  "major-pathological-response": "Lorsque, après un traitement préopératoire, la tumeur retirée ne contient que peu ou pas de cancer vivant : 10% ou moins de cellules viables.",
  mammaprint: "Un test de 70 gènes qui indique si un cancer du sein précoce est à risque génomique faible ou élevé, utilisé pour décider qui peut se passer de chimiothérapie.",
  "mansoor-raza-mirza": "A dirigé NOVA et RUBY, les essais qui ont établi le niraparib en maintenance dans le cancer de l'ovaire et le dostarlimab dans le cancer de l'endomètre avancé.",
  "mark-foundation": "Un bailleur de fonds philanthropique qui soutient des projets à haut risque en biologie du cancer, en immunologie des tumeurs et en calcul, et qui investit dans les start-ups qui les traduisent en applications.",
  "mary-claire-king": "En 1990, elle a montré qu'un seul gène du chromosome 17, BRCA1, cause le cancer héréditaire du sein et de l'ovaire, alors que la plupart des chercheurs doutaient qu'un tel gène existe. Le dépistage génétique et les soins de réduction du risque ont suivi.",
  "masked-adc": "Un ADC qui porte un masque ne se retirant qu'à l'intérieur de la tumeur, de sorte qu'il ignore la même protéine sur les tissus sains.",
  mastectomy: "Retirer la totalité du sein. Pratiquée en cas de cancer, ou à titre préventif chez les femmes présentant un risque héréditaire très élevé.",
  matterhorn: "L'ajout d'une immunothérapie avant et après la chirurgie a réduit les décès dans le cancer de l'estomac précoce ; près de sept patients sur dix étaient en vie à trois ans.",
  "mayo-clinic-arizona": "Le campus de la Mayo Clinic en Arizona, doté de la protonthérapie depuis 2016, d'un vaste programme sur le myélome et de l'unité de phase 1 de Mayo en Arizona.",
  "mays-cancer-center": "Hôte du San Antonio Breast Cancer Symposium et héritier de l'institut de phase 1 CTRC qui a testé en premier nombre des médicaments de l'oncologie ; désigné par le NCI depuis 1991.",
  "mc-vc-pabc": "Le linker mc-Val-Cit-PABC est le pilier des ADC vedotine : un dipeptide valine-citrulline clivé par la cathepsine B, qui libère le MMAE avec un effet de voisinage.",
  "mechanobiology-therapy": "Les tumeurs rigides et sous forte pression écrasent leurs propres vaisseaux sanguins, ce qui empêche les médicaments d'entrer. Les assouplir est un moyen d'y pénétrer.",
  "medical-cyclotrons-synthesis-modules": "Les accélérateurs de particules et les enceintes robotisées de chimie blindées qui fabriquent les traceurs TEP dans les sous-sols des hôpitaux et dans les pharmacies commerciales.",
  "megestrol-progestins": "Des hormones apparentées à la progestérone qui peuvent faire régresser un cancer de l'endomètre précoce chez les femmes souhaitant conserver leur utérus, et contrôler la maladie avancée hormonosensible.",
  "men1-hereditary-net": "Des maladies héréditaires (MEN1, VHL, NF1, sclérose tubéreuse) qui provoquent des tumeurs neuroendocrines, souvent multiples et à un jeune âge, si bien que les familles ont besoin de tests génétiques et d'une surveillance.",
  "menin-kmt2a": "Dans certaines leucémies, une protéine de la chromatine défectueuse (KMT2A, autrefois appelée MLL) ou une NPM1 mutée maintient allumés des gènes de croissance embryonnaire (HOXA9, MEIS1), si bien que les cellules sanguines ne parviennent jamais à maturité. Toutes deux ont besoin d'un partenaire appelé ménine pour rester fixées à l'ADN. Les inhibiteurs de ménine coupent le courant et les cellules mûrissent ; le premier a été approuvé en 2024.",
  "menin-plus-venetoclax-hma": "L'association de la classe la plus récente de médicaments contre la leucémie au socle vénétoclax donne, dans les leucémies NPM1 et KMT2A en première ligne, des taux de rémission que les monothérapies n'avaient jamais atteints.",
  mesothelin: "La mésothéline est une protéine de surface présente sur le mésothéliome et les cancers de l'ovaire et du pancréas, ciblée par des ADC, des CAR-T et des engageurs de lymphocytes T.",
  "met-amplification": "Quand un cancer du poumon active le récepteur MET pour contourner un comprimé bloquant l'EGFR.",
  "met-hours": "L'unité qui sert à mesurer la quantité d'exercice d'une personne. Un MET correspond à l'énergie dépensée assis au repos ; la marche rapide vaut environ 4 MET, donc 45 minutes de marche rapide font 3 MET-heures. Les recommandations visent environ 10 MET-heures par semaine.",
  "metro-plus-varanasi": "L'ajout de comprimés métronomiques oraux peu coûteux au paclitaxel-carboplatine standard a doublé la survie médiane, de 5 à 10 mois, dans un essai randomisé mené à Varanasi.",
  "metronomic-vs-cisplatin-tmh": "Deux comprimés bon marché pris à domicile ont égalé, et même dépassé, le cisplatine intraveineux dans le cancer avancé de la tête et du cou lors d'un essai indien de 422 patients, avec moins d'effets secondaires.",
  mevrometostat: "Un médicament épigénétique qui pourrait resensibiliser le cancer de la prostate à l'hormonothérapie, évalué dans trois essais de phase 3 avec l'enzalutamide.",
  "michael-hallek": "Dirige le groupe d'étude allemand sur la LLC, dont les essais (CLL8, CLL14, CLL13) ont fixé les standards mondiaux du traitement de la LLC.",
  "michael-postow": "A dirigé CheckMate 069, premier essai randomisé du nivolumab associé à l'ipilimumab, et définit la prise en charge des effets secondaires de l'immunothérapie.",
  "mimic-01": "Vingt patients atteints de mélanome ont pris des gélules de selles de donneurs sains avant de commencer l'immunothérapie. Treize ont répondu, plus que ce à quoi on s'attend habituellement, et la transplantation s'est avérée sûre.",
  mitotane: "Un cousin de l'insecticide DDT, seul médicament spécifique du cancer de la corticosurrénale ; il exige une surveillance des taux sanguins et une substitution permanente en stéroïdes.",
  "molecular-glue-platforms": "Les colles moléculaires sont de petites molécules qui accolent deux protéines pour que la cellule détruise l'une d'elles. Elles sont plus petites et plus proches d'un médicament que les dégradeurs bifonctionnels.",
  "molecular-response": "Dans la leucémie myéloïde chronique, l'ampleur de la baisse du signal du gène leucémique dans le sang, mesurée en logarithmes : une baisse de 1 000 fois est une réponse moléculaire majeure, une baisse de 10 000 fois (MR4) est dite « profonde ». Une réponse profonde maintenue pendant deux ans permet à certains patients d'arrêter leurs comprimés.",
  momelotinib: "Le momélotinib est l'inhibiteur de JAK conçu pour les patients atteints de myélofibrose avec anémie : il peut améliorer l'hémoglobine tout en réduisant la rate.",
  "monoclonal-antibody-manufacturing": "La fabrication d'anticorps consiste à produire des médicaments comme le pembrolizumab ou le trastuzumab dans des cuves de cellules de hamster modifiées, puis à les purifier. C'est le socle industriel de la plupart des médicaments modernes contre le cancer.",
  "monte-rosa": "Société spécialisée dans les dégradeurs à colle moléculaire, avec un dégradeur de GSPT1 en phase 2 dans le cancer de la prostate à AR muté et une colle dirigée contre CCNE1 en développement préclinique.",
  "montefiore-einstein": "Le centre de cancérologie intégré du NCI dans le Bronx, où Joseph Sparano a mené TAILORx, l'essai qui a permis à la plupart des femmes atteintes d'un cancer du sein précoce HR-positif de se passer de chimiothérapie.",
  movember: "L'association de santé masculine à la moustache, devenue l'un des plus grands financeurs mondiaux de la recherche sur les cancers de la prostate et du testicule.",
  "mrna-translation-eif4f": "Les cellules cancéreuses doivent fabriquer des protéines à un rythme effréné. Le complexe eIF4F, qui lance la synthèse des protéines, est l'entonnoir où convergent les signaux de croissance, et les médicaments qui resserrent cet entonnoir privent la tumeur des protéines dont elle a le plus besoin.",
  "mslt-ii": "A montré que retirer tous les ganglions lymphatiques restants après un ganglion sentinelle positif n'allonge pas la survie des patients, mettant fin à une opération de routine.",
  "mss-pmmr": "Le résultat « normal » du test de réparation des mésappariements : la tumeur conserve un correcteur orthographique de l'ADN intact et présente peu de mutations. Il concerne environ 95 % des cancers colorectaux métastatiques et signifie que les inhibiteurs de points de contrôle seuls ont peu de chances d'agir.",
  mtd: "La dose la plus élevée d'un médicament que les patients peuvent recevoir sans trop d'effets secondaires sévères, traditionnellement l'objectif des essais de phase 1 et la dose retenue pour les essais ultérieurs. Pour la chimiothérapie, plus signifiait mieux ; pour les thérapies ciblées et les anticorps, la meilleure dose est souvent plus basse.",
  muc16: "La mucine géante libérée dans le sang sous la forme du marqueur CA-125 du cancer de l'ovaire ; sa tige membranaire est ciblée par des ADC et des engageurs de lymphocytes T.",
  mucositis: "Inflammation douloureuse et ulcères de la muqueuse de la bouche et de l'intestin, parce que les cellules à division rapide qui la renouvellent sont touchées par la chimiothérapie et la radiothérapie. Elle peut rendre l'alimentation impossible et constitue une raison majeure pour laquelle les patients sous chimioradiothérapie de la tête et du cou ont besoin d'une sonde d'alimentation.",
  "mumbai-via-screening": "Des agentes de santé munies d'une lampe torche et de vinaigre, dépistant tous les deux ans les femmes des bidonvilles de Mumbai, ont réduit de 31 % les décès par cancer du col de l'utérus dans un essai portant sur plus de 150 000 femmes.",
  "muscle-invasive": "Le cancer de la vessie est classé selon qu'il a ou non envahi la paroi musculaire de la vessie. Les tumeurs n'infiltrant pas le muscle (75 %) sont retirées par résection et traitées par des médicaments instillés dans la vessie ; les tumeurs infiltrant le muscle (25 %) nécessitent l'ablation de la vessie ou une chimioradiothérapie intensive.",
  mutation: "Un changement dans la séquence de l'ADN, comme une faute de frappe dans une recette. La plupart sont sans conséquence ; quelques-uns modifient une protéine d'une façon qui aide une cellule à proliférer sans contrôle.",
  "mychoice-cdx": "Un test tumoral qui mesure les cicatrices de la réparation de l'ADN afin que les femmes atteintes d'un cancer de l'ovaire, au-delà des porteuses de BRCA, puissent bénéficier des inhibiteurs de PARP.",
  myelomatch: "myeloMATCH est un essai-cadre à l'échelle des États-Unis qui séquence chaque nouvelle leucémie en quelques jours et oriente le patient vers le bon bras expérimental, puis le réoriente au fur et à mesure que les résultats de MRD arrivent.",
  "nadofaragene-firadenovec": "Le nadofaragene firadenovec est la première thérapie génique du cancer de la vessie : un virus qui fait produire de l'interféron par les cellules vésicales pendant des semaines, administré une fois tous les trois mois.",
  nalirifox: "NALIRIFOX est une version de FOLFIRINOX utilisant un irinotécan encapsulé dans un liposome, approuvée en 2024 comme option de première ligne dans le cancer du pancréas métastatique.",
  natalee: "A étendu les inhibiteurs de CDK4/6 à un large groupe de patientes atteintes d'un cancer du sein précoce hormonosensible, y compris sans atteinte ganglionnaire.",
  natco: "Le fabricant de génériques en oncologie au cœur des deux batailles de brevets historiques de l'Inde : la première licence obligatoire, pour le sorafénib en 2012, et le refus par la Cour suprême, en 2013, du brevet de Novartis sur l'imatinib.",
  "nationwide-childrens": "Hôpital pédiatrique de Columbus doté d'un institut de génomique des cancers de l'enfant de premier plan et menant des essais pionniers de virus oncolytiques dans les sarcomes de l'enfant.",
  naxitamab: "Le naxitamab est un anticorps humanisé anti-GD2 issu du Memorial Sloan Kettering, administré en ambulatoire avec du GM-CSF pour le neuroblastome en rechute osseuse ou médullaire.",
  "nccn-org": "Le NCCN est une alliance de 33 centres de cancérologie américains dont les recommandations déterminent, en pratique, ce que font les oncologues américains et ce que remboursent les assureurs.",
  "nci-cairo": "L'institut national du cancer de l'Égypte et le plus grand hôpital de cancérologie d'Afrique et du monde arabe, qui soigne des patients de toute la région depuis 1969.",
  neladalkib: "Un comprimé anti-ALK de quatrième génération qui agit après le lorlatinib et évite les effets secondaires cérébraux liés à TRK ; en examen prioritaire à la FDA avec une décision attendue le 27 novembre 2026.",
  "neoadjuvant-io-dmmr": "Rechercher dans la tumeur un correcteur orthographique de l'ADN défaillant ; si c'est le cas, l'immunothérapie avant la chirurgie fait fondre la plupart des tumeurs et, dans le rectum, peut remplacer complètement la chirurgie.",
  "neoadjuvant-io-response-adapted": "Traiter avant la chirurgie, examiner la tumeur retirée et ne poursuivre le traitement que si la réponse a été incomplète.",
  "next-gen-short-read-platforms": "Des concurrents d'Illumina qui promettent des génomes moins chers, ce qui compte pour faire du séquençage tumoral un examen de routine.",
  "nhs-targeted-lung-health-check": "Le programme anglais de dépistage du cancer du poumon : les personnes de 55 à 74 ans ayant déjà fumé sont invitées à une évaluation du risque et, si le risque est élevé, à un scanner à faible dose, souvent dans une unité mobile installée sur le parking d'un supermarché.",
  "niche-2": "Dans NICHE-2, quatre semaines d'immunothérapie avant la chirurgie ont éliminé la plupart des cancers du côlon déficients en réparation des mésappariements, et personne n'avait rechuté trois ans plus tard.",
  "nicholas-turner": "Chercheur en cancérologie mammaire qui a fait de l'ADN tumoral circulant un outil de choix du traitement, à la tête de SERENA-6 et de CAPItello-291.",
  "nicoletta-colombo": "A dirigé KEYNOTE-826, qui a fait du pembrolizumab associé à la chimiothérapie le standard de première ligne du cancer du col de l'utérus récidivant ou métastatique.",
  "noi-budapest": "L'institut national du cancer de Hongrie, qui abrite le registre national du cancer et un programme de curiethérapie du sein de premier plan.",
  "nordic-lymphoma-group": "Le réseau d'essais sur les lymphomes réunissant le Danemark, la Finlande, la Norvège, la Suède et l'Islande, surtout connu pour le protocole nordique du lymphome à cellules du manteau.",
  "northwell-cancer-institute": "Le service de cancérologie du plus grand système de santé de l'État de New York, héritier de la tradition de recherche sur la LLC des Feinstein Institutes fondée par Kanti Rai.",
  novocure: "Novocure fabrique les champs électriques antitumoraux Optune, approuvés dans le glioblastome, le cancer du poumon, le mésothéliome et (2026) le cancer du pancréas.",
  "nrg-gy018-keynote-868": "NRG-GY018 est le jumeau de RUBY avec le pembrolizumab : l'immunothérapie associée à la chimiothérapie a réduit le risque de progression de 70% dans les tumeurs dMMR et de 46% dans les autres.",
  "nrg-hn002-hn005": "Les tentatives de réduire la radiothérapie chez les patients atteints d'un cancer de la gorge HPV positif n'ont pas abouti : la dose standard est restée supérieure, la désescalade n'est donc pas encore la norme.",
  nurix: "Nurix Therapeutics développe le bexobrutideg, un dégradeur de BTK qui pénètre dans le cerveau, en essais pivots dans la LLC et codéveloppé avec Roche depuis juin 2026.",
  "obecabtagene-autoleucel": "Un CAR-T anti-CD19 conçu pour s'accrocher et se détacher rapidement, ce qui a réduit les effets secondaires graves et offert aux adultes atteints de LAL en rechute une réelle chance de rémission durable.",
  "ocean-road-cancer-institute": "L'institut national du cancer de Tanzanie, pendant de longues années le seul centre de traitement du cancer du pays et le siège de son programme de lutte contre le cancer.",
  odronextamab: "L'odronextamab est l'anticorps bispécifique anti-CD20 de Regeneron, approuvé en Europe dans le lymphome et aux États-Unis dans le lymphome folliculaire, après des refus antérieurs de la FDA liés au recrutement de l'essai de confirmation.",
  oesophagectomy: "Intervention chirurgicale qui retire la plus grande partie de l'œsophage et le reconstruit en remontant l'estomac dans le thorax.",
  oicr: "L'institut de recherche sur le cancer de l'Ontario, financé par la province, qui a coordonné l'International Cancer Genome Consortium et mène des essais de génomique du cancer du pancréas.",
  "oliver-sartor": "A dirigé VISION, l'essai qui a fait du lutétium-PSMA la première radiothérapie par ligand du cancer de la prostate.",
  olutasidenib: "L'olutasidenib est un deuxième inhibiteur d'IDH1 pour la LAM en rechute, avec un taux de réponse dans sa cohorte pivot supérieur à celui de l'ivosidenib dans la sienne.",
  "omega3-epa-cachexia": "On attendait de l'huile de poisson riche en EPA qu'elle freine la fonte musculaire liée au cancer en atténuant l'inflammation. Les essais randomisés et une revue Cochrane n'ont trouvé aucun effet convaincant sur le poids ou la survie, même si l'huile de poisson est sûre et trouve naturellement sa place dans le soutien nutritionnel général.",
  oncokb: "Indique, pour une mutation donnée, s'il existe un médicament approuvé ou expérimental et quelle est la solidité des preuves.",
  "oncology-nursing": "Les infirmières spécialisées assurent l'essentiel des traitements anticancéreux et une grande partie de leur sécurité, de l'éducation et du soutien ; les consultations infirmières, l'accompagnement des parcours et la gestion des symptômes améliorent les résultats et constituent l'épine dorsale des soins dans les contextes à faibles ressources.",
  "onj-cancer-centre": "Le centre de cancérologie et institut de recherche de l'Austin Hospital de Melbourne, pôle d'essais précoces d'immunothérapie et héritier de la lignée du Ludwig Institute en immunologie des tumeurs.",
  "open-targets": "Open Targets évalue la force du lien entre chaque gène et chaque maladie, avec les preuves qui l'étayent.",
  "oral-cryotherapy-mucositis": "Sucer des glaçons pendant une demi-heure autour d'une injection en bolus de fluorouracile ou de melphalan à haute dose réduit environ de moitié le risque d'aphtes douloureux. Cela ne coûte rien et figure dans les recommandations internationales sur la mucite.",
  "oral-serd": "Un SERD oral est un comprimé qui détruit le récepteur des œstrogènes au lieu de simplement le bloquer, remplaçant l'injection mensuelle de fulvestrant.",
  "oral-serd-plus-cdk46-after-esr1": "Lorsqu'une mutation ESR1 apparaît, remplacer l'inhibiteur de l'aromatase par un SERD oral et poursuivre l'inhibiteur de CDK4/6.",
  "orano-med": "Orano Med est le premier producteur de plomb-212 et le développeur du 212Pb-DOTAMTATE (AlphaMedix).",
  organoid: "Une version tridimensionnelle miniature d'un tissu ou d'une tumeur, cultivée en laboratoire à partir des propres cellules du patient. Les organoïdes tumoraux conservent davantage le caractère du cancer d'origine que les lignées cellulaires en culture plate et permettent de tester des médicaments sur le cancer du patient lui-même.",
  "organoid-guided-therapy-scale": "La thérapie guidée par organoïdes consiste à cultiver systématiquement un fragment de la tumeur de chaque patient et à y tester des médicaments avant de choisir, plutôt que de s'appuyer sur la seule génétique.",
  "orna-therapeutics": "Société de CAR in vivo à ARN circulaire, rachetée par Eli Lilly pour environ 2,4 milliards de dollars en février 2026.",
  "osaka-international-cancer-institute": "Le centre de cancérologie de la préfecture d'Osaka, l'un des plus grands hôpitaux exclusivement dédiés au cancer du Japon et siège du registre du cancer d'Osaka.",
  "osmanabad-hpv-screening": "Une seule campagne de test HPV dans des villages ruraux de l'Inde a réduit de moitié les décès par cancer du col de l'utérus en huit ans, alors que le frottis ou l'inspection visuelle n'y sont pas parvenus, ce qui explique pourquoi le test HPV est aujourd'hui le dépistage privilégié dans le monde.",
  "osu-james": "Là où l'équipe de John Byrd a fait de l'ibrutinib le médicament qui a transformé la leucémie lymphoïde chronique ; le centre intégré du NCI de l'Ohio State.",
  "ottawa-hospital": "Le centre universitaire de cancérologie d'Ottawa, leader mondial des virus oncolytiques (John Bell), site du premier essai de CAR-T fabriqué au Canada et des essais pragmatiques REaCT.",
  outback: "Ajouter de la chimiothérapie après la chimioradiothérapie a augmenté les effets secondaires sans apporter de bénéfice de survie ; le moment compte donc : la chimiothérapie aide avant la radiothérapie (INTERLACE), pas après.",
  "ovarian-function-suppression": "Mettre temporairement les ovaires au repos par des injections (ou les retirer) afin de priver d'œstrogènes le cancer d'une femme non ménopausée.",
  overdiagnosis: "Découvrir un cancer qui n'aurait jamais provoqué de symptômes ni de décès au cours de la vie d'une personne, de sorte que le diagnostic et le traitement nuisent sans apporter de bénéfice. C'est le principal inconvénient du dépistage.",
  overexpression: "Lorsqu'une cellule produit beaucoup plus d'une protéine donnée que les cellules normales. Les médicaments qui ciblent cette protéine peuvent alors frapper la tumeur plus fort que les tissus sains.",
  oxaliplatin: "Le dérivé du platine efficace dans le cancer colorectal là où le cisplatine ne l'est pas, le « OX » de FOLFOX et de CAPOX ; son prix est une atteinte des nerfs des mains et des pieds.",
  pam50: "Un test de 50 gènes qui classe les cancers du sein en luminal A, luminal B, HER2-enrichi et basal-like.",
  "paolo-ascierto": "Oncologue italien spécialiste du mélanome qui a codirigé CheckMate 238, CheckMate 067 et l'essai COLUMBUS sur BRAF/MEK.",
  "paper-admiral-gilteritinib-flt3-nejm-2019": "Un inhibiteur oral de FLT3 a prolongé la survie par rapport à la chimiothérapie de rattrapage dans la LAM en rechute porteuse d'une mutation FLT3, en doublant le taux de rémission.",
  "paper-agile-ivosidenib-azacitidine-nejm-2022": "L'ajout de l'inhibiteur d'IDH1 ivosidenib à l'azacitidine a triplé la survie médiane, de 7,9 à 24 mois, chez des patients âgés atteints de LAM avec mutation IDH1.",
  "paper-alphafold2-jumper-nature-2021": "Le réseau de neurones de DeepMind a prédit des structures de protéines à CASP14 avec une erreur médiane du squelette inférieure à 1 angström, comparable aux méthodes expérimentales, et l'équipe a publié en moins d'un an les structures prédites de pratiquement toutes les protéines humaines.",
  "paper-basch-epro-survival-jama-2017": "Les patients sous chimiothérapie pour un cancer avancé qui signalaient chaque semaine 12 symptômes via un outil en ligne, avec alerte des infirmières en cas de symptôme sévère, ont vécu en médiane 5 mois de plus que ceux recevant les soins habituels.",
  "paper-comfort-1-ruxolitinib-myelofibrosis-nejm-2012": "Le ruxolitinib a réduit la rate hypertrophiée de plus d'un tiers chez 42% des patients atteints de myélofibrose, contre moins de 1% sous placebo, et a divisé par deux les scores de symptômes chez près de la moitié d'entre eux.",
  "paper-commands-luspatercept-mds-lancet-2023": "Dans COMMANDS, le luspatercept, un médicament qui libère les derniers stades de la production de globules rouges du frein exercé par la famille du TGF-bêta, a affranchi des transfusions pendant au moins 12 semaines 59% des patients atteints de SMD dépendants des transfusions, contre 31% avec l'injection standard d'érythropoïétine.",
  "paper-doll-hill-smoking-lung-cancer-bmj-1950": "En comparant 649 hommes atteints d'un cancer du poumon à des témoins hospitaliers appariés à Londres, Doll et Hill ont constaté que presque aucun des patients cancéreux n'était non-fumeur et que le risque augmentait fortement avec la quantité fumée.",
  "paper-gap70-geriatric-assessment-lancet-2021": "Lorsque les oncologues ont reçu une synthèse d'évaluation gériatrique accompagnée de recommandations de prise en charge pour les patients de 70 ans et plus, la toxicité de grade 3 à 5 est passée de 71% à 51% sans perte de survie.",
  "paper-hpv-self-sampling-bmj-2018": "Une méta-analyse de 56 études de précision et 25 essais randomisés a montré que les auto-prélèvements analysés par PCR détectent les lésions précancéreuses aussi bien que les prélèvements réalisés par un clinicien, et que l'envoi de kits par la poste aux femmes insuffisamment dépistées double environ la participation.",
  "paper-hpv-vaccine-england-lancet-2021": "Dix ans après le début de la vaccination des jeunes de 12 à 13 ans par le vaccin bivalent contre le HPV en Angleterre, le cancer du col de l'utérus avait reculé de 87% dans cette cohorte et les lésions précancéreuses sévères (CIN3) de 97%.",
  "paper-ibis-i-tamoxifen-lancet-oncol-2015": "Chez les femmes à risque accru, 5 ans de tamoxifène ont réduit le cancer du sein de 29% sur un suivi médian de 16 ans, le bénéfice se prolongeant bien après l'arrêt des comprimés, mais sans réduction des décès par cancer du sein.",
  "paper-indigo-nejm-2023": "Un médicament oral qui bloque l'enzyme IDH mutée a plus que doublé le délai avant progression des tumeurs cérébrales à croissance lente porteuses d'une mutation IDH, permettant aux patients de repousser de plusieurs années la radiothérapie et la chimiothérapie.",
  "paper-momentum-momelotinib-lancet-2023": "Un inhibiteur de JAK qui bloque aussi la voie ACVR1, responsable de l'anémie, a amélioré les symptômes et la taille de la rate sans aggraver l'anémie, et l'a souvent améliorée, chez des patients déjà traités.",
  "paper-nelson-nejm-2020": "Dans un essai néerlando-belge, le dépistage par scanner fondé sur le volume des nodules plutôt que sur leur diamètre a réduit d'environ un quart les décès par cancer du poumon chez les hommes à 10 ans, avec un taux de faux positifs bien plus faible que dans NLST.",
  "paper-nordicc-nejm-2022": "Le premier essai randomisé de dépistage par coloscopie a montré une baisse de 18% de l'incidence du cancer colorectal à 10 ans chez les personnes invitées, sans réduction significative des décès par cancer colorectal; seuls 42% des invités ont effectivement passé l'examen.",
  "paper-patil-low-dose-nivolumab-jco-2023": "L'administration d'environ un vingtième de la dose standard de nivolumab avec une chimiothérapie orale peu coûteuse a presque triplé la survie à un an dans le cancer avancé de la tête et du cou, montrant que l'immunothérapie peut être rendue abordable sans perdre son efficacité.",
  "paper-protac-concept-sakamoto-pnas-2001": "Crews et Deshaies ont construit une molécule à deux têtes reliant un ligand de la protéine cible MetAP-2 à un peptide reconnu par une ubiquitine ligase E3, et ont montré qu'elle induisait l'ubiquitination et la dégradation de la cible, fondant ainsi la dégradation ciblée des protéines.",
  "paper-reproducibility-project-cancer-biology-elife-2021": "Un effort de huit ans pour reproduire 50 expériences issues de 23 articles à fort impact en biologie du cancer a montré que les tailles d'effet des réplications étaient en moyenne 85% plus faibles que les originales, et que moins de la moitié des effets se reproduisaient selon la plupart des critères.",
  "paper-sankaranarayanan-hpv-screening-nejm-2009": "Chez 131 746 femmes de l'Inde rurale, un seul cycle de test HPV a réduit d'environ moitié les décès par cancer du col de l'utérus en huit ans, alors que le frottis et l'inspection visuelle n'y sont pas parvenus.",
  "paper-scalp-trial-jama-2017": "Dans le premier essai randomisé d'un système moderne de refroidissement du cuir chevelu, la moitié des femmes ayant utilisé le dispositif Paxman pendant une chimiothérapie par taxane ou anthracycline pour un cancer du sein précoce ont conservé l'essentiel de leurs cheveux, contre aucune de celles qui ne l'avaient pas utilisé.",
  "paper-spearhead-1-afami-cel-sarcoma-lancet-2024": "Des lymphocytes T dotés d'un récepteur reconnaissant l'antigène tumoral MAGE-A4 ont fait régresser les tumeurs chez 37% des patients atteints d'un sarcome synovial avancé ou d'un liposarcome myxoïde, conduisant à la première approbation d'une thérapie TCR-T.",
  "paper-spearhead-1-lancet-2024": "Des lymphocytes T prélevés chez les patients et modifiés pour reconnaître la protéine MAGE-A4 ont fait régresser les tumeurs chez environ quatre patients sur dix atteints d'un sarcome synovial avancé, conduisant à la première approbation d'une thérapie par lymphocytes T à TCR pour un cancer solide.",
  "paper-temel-early-palliative-care-nejm-2010": "Les patients venant de recevoir un diagnostic de cancer du poumon métastatique et suivis par une équipe de soins palliatifs dès le diagnostic ont eu une meilleure qualité de vie, moins de dépression, des soins de fin de vie moins agressifs et ont vécu en médiane 2,7 mois de plus que ceux ne recevant que des soins oncologiques.",
  "paper-unger-trial-participation-barriers-jnci-2019": "En regroupant 13 études portant sur 8 883 patients, 56% n'avaient aucun essai disponible dans leur centre et 22% de plus n'étaient pas éligibles aux essais existants; parmi les patients à qui un essai a réellement été proposé, environ la moitié ont accepté, si bien que la participation globale était d'environ 8%.",
  "parathyroid-carcinoma": "Le carcinome parathyroïdien est un cancer très rare des glandes qui régulent le calcium sanguin, et l'essentiel de ses méfaits vient d'un taux de calcium extrêmement élevé plutôt que de la dissémination. Retirer la tumeur intacte, en un seul bloc, lors de la première opération offre les meilleures chances de guérison, et les médicaments hypocalcémiants contrôlent la maladie lorsqu'elle ne peut pas être retirée.",
  "parp-pet": "Un traceur TEP qui mesure la quantité de PARP, une enzyme de réparation de l'ADN, présente dans une tumeur, afin de prédire la réponse aux inhibiteurs de PARP.",
  "partial-response": "Les tumeurs ont nettement diminué (d'au moins 30% du diamètre total) sans disparaître. Avec les réponses complètes, elle constitue le taux de réponse d'un essai.",
  pathai: "PathAI exploite la plateforme de pathologie par IA AISight et quantifie des biomarqueurs pour les essais de l'industrie pharmaceutique.",
  "pathos-ai": "Pathos AI utilise de très grands modèles d'intelligence artificielle entraînés sur les dossiers, les examens d'imagerie et les données génétiques de millions de patients atteints de cancer pour choisir quels médicaments anticancéreux expérimentaux développer et chez quels patients les tester, et constitue son propre portefeuille de tels médicaments.",
  "patient-data-vault": "Outil d'appariement aux essais cliniques par IA pour les patients atteints de cancer : téléchargez vos dossiers ou connectez un système de santé, et recevez des correspondances expliquées, mises à jour chaque jour à partir de ClinicalTrials.gov.",
  pbac: "Le comité indépendant qui décide, sur la base de données de coût-efficacité, quels médicaments le Pharmaceutical Benefits Scheme australien prend en charge, et à quel prix.",
  "pdac-organoid-pharmacotyping": "Cultiver la tumeur pancréatique d'un patient sous forme de mini-organes en boîte de culture et y tester des chimiothérapies pour choisir le protocole le plus susceptible de fonctionner.",
  "pegylated-liposomal-doxorubicin": "De la doxorubicine enveloppée dans une bulle lipidique pour atteindre les tumeurs en abîmant moins le cœur ; un pilier du traitement du cancer de l'ovaire en rechute.",
  pemigatinib: "Le pemigatinib a été la première thérapie ciblée du cancer des voies biliaires, pour les tumeurs porteuses d'une fusion du gène FGFR2.",
  penpulimab: "Le penpulimab est un anticorps anti-PD-1 chinois approuvé aux États-Unis en 2025 pour le carcinome du nasopharynx, le deuxième après le toripalimab.",
  "peptide-drug-conjugate": "Comme un ADC, mais avec un petit peptide de ciblage à la place de l'anticorps, ce qui lui permet de pénétrer plus vite dans les tumeurs et coûte moins cher à fabriquer.",
  "peritoneal-metastasis": "Dissémination sur la membrane qui tapisse l'abdomen, la façon la plus fréquente dont le cancer de l'estomac récidive et la plus difficile à traiter.",
  persephone: "Six mois de trastuzumab ont été presque aussi efficaces que douze, avec deux fois moins de toxicité cardiaque, même si douze mois restent le standard mondial.",
  "peter-sasieni": "Épidémiologiste qui a montré que la vaccination contre le HPV a presque éliminé le cancer du col de l'utérus chez les Anglaises vaccinées et qui dirige NHS-Galleri.",
  "peter-schmid": "A dirigé KEYNOTE-522 et IMpassion130, les essais qui ont introduit l'immunothérapie dans le cancer du sein triple négatif.",
  pexidartinib: "Le pexidartinib est le premier médicament contre la tumeur ténosynoviale à cellules géantes, une tumeur articulaire bénigne mais destructrice ; il est efficace mais présente une toxicité hépatique qui impose un programme d'accès restreint.",
  phallcon: "En comparaison directe, le TKI de troisième génération ponatinib a doublé le taux de rémission profonde et indétectable par rapport à l'imatinib dans la LAL Ph-positive nouvellement diagnostiquée.",
  "philadelphia-chromosome": "Un fragment échangé entre les chromosomes 9 et 22 qui fusionne deux gènes en BCR::ABL1, une kinase emballée. Il provoque la leucémie myéloïde chronique et un quart, difficile à traiter, des leucémies aiguës lymphoblastiques de l'adulte, et a été la cible de l'imatinib, premier médicament anticancéreux ciblé moderne.",
  "philippe-moreau": "A dirigé MajesTEC-1 et CASSIOPEIA, qui ont apporté au myélome le premier anticorps bispécifique et les quadruplets à base de daratumumab.",
  "pi3k-pathway-plus-endocrine": "Bloquer la voie de croissance PI3K en plus de l'hormonothérapie ne fonctionne que lorsque la tumeur porte une mutation de cette voie, et fonctionne mieux lorsqu'on s'y prend tôt.",
  "pla-general-hospital": "L'hôpital militaire de référence de la Chine, connu en oncologie pour ses premiers essais de CAR-T et de lymphocytes T génétiquement modifiés, la chirurgie hépatique mini-invasive et la médecine nucléaire.",
  "plasma-ebv-dna": "Fragments d'ADN du virus d'Epstein-Barr dans le sang qui mesurent le carcinome du nasopharynx : utilisés pour dépister des personnes en bonne santé dans les régions endémiques, pour établir le stade, pour décider qui a besoin d'un traitement complémentaire après la radiothérapie et pour détecter la rechute.",
  "platinum-sensitivity": "Selon qu'un cancer ayant répondu à une chimiothérapie à base de platine est revenu plus de six mois après (sensible, le platine peut donc être réutilisé) ou plus tôt (résistant, il faut donc autre chose). Cette ligne de partage oriente le traitement du cancer de l'ovaire et du cancer du poumon à petites cellules.",
  "pleural-effusion": "Liquide qui s'accumule autour du poumon (épanchement pleural) ou dans l'abdomen (ascite) parce que les cellules cancéreuses irritent la membrane et bloquent le drainage lymphatique ; il provoque un essoufflement ou un ventre gonflé et tendu.",
  pmda: "L'agence japonaise d'évaluation des médicaments et des dispositifs, qui travaille avec le ministère de la santé pour approuver les médicaments anticancéreux et a largement comblé le « retard d'accès aux médicaments » historique par rapport aux États-Unis et à l'Europe.",
  polo: "La première approbation d'un médicament guidée par un biomarqueur dans le cancer du pancréas, pour les 5-7% environ porteurs de mutations BRCA héréditaires, même si elle n'a pas prolongé la survie globale.",
  "polygenic-risk-scores": "Un score construit à partir de centaines de variants génétiques fréquents qui indique si votre risque hérité d'un cancer est supérieur ou inférieur à la moyenne, actuellement testé comme moyen de décider qui dépister et à quelle fréquence.",
  "portec-3": "Ajouter une chimiothérapie à la radiothérapie après la chirurgie a aidé les femmes atteintes d'un cancer de l'endomètre à haut risque, surtout celles dont la tumeur présente un gène p53 défectueux.",
  "prabhash-kumar": "Dirige l'oncologie médicale au Tata Memorial et son programme d'essais pragmatiques qui rendent les traitements abordables.",
  "precision-mri": "PRECISION a prouvé qu'une IRM réalisée en premier détecte plus de cancers dangereux avec moins de biopsies.",
  preclinical: "Tout ce que l'on fait subir à un médicament potentiel avant de l'administrer à un être humain : expériences de laboratoire, tests sur l'animal, et travaux de sécurité et de fabrication exigés par les autorités réglementaires. La plupart des candidats n'en sortent jamais.",
  prednisone: "Prednisone est le comprimé de corticoïde du quotidien en cancérologie. C'est le P de CHOP et de MOPP dans le lymphome, un élément du traitement des leucémies de l'enfant, et il se prend avec abiraterone dans le cancer de la prostate.",
  "prehabilitation-term": "Mettre à profit les semaines qui séparent le diagnostic de la chirurgie ou de la chimiothérapie pour améliorer sa forme physique, sa nutrition et sa préparation psychologique, afin que le traitement se passe mieux et que la récupération soit plus rapide.",
  prima: "A étendu le traitement d'entretien par inhibiteur de PARP aux femmes sans mutation BRCA, mais le bénéfice de survie ne s'est pas confirmé avec un suivi plus long.",
  "primary-endpoint": "Le critère principal est la mesure unique pour laquelle un essai est conçu et dimensionné, déclarée à l'avance ; s'il est atteint, l'essai est dit « positif ». Les critères secondaires sont des mesures supplémentaires qui peuvent étayer un essai, mais pas sauver un essai qui a manqué son critère principal.",
  "prism-mel-301": "Évalue si un engageur de lymphocytes T dirigé contre PRAME apporte un bénéfice à l'immunothérapie de première ligne dans le mélanome cutané classique, après le succès du tebentafusp dans la forme oculaire.",
  "probiotics-treatment-diarrhoea": "Les compléments de bactéries vivantes peuvent réduire la diarrhée pendant la radiothérapie pelvienne et certaines chimiothérapies, mais les essais sont de petite taille, les souches diffèrent et une revue Cochrane a jugé le niveau de preuve faible. Les personnes dont le taux de globules blancs est très bas ou qui portent un cathéter central ne doivent pas en prendre sans avis médical.",
  prodrug: "Un médicament administré sous une forme inactive que l'organisme transforme en principe actif. Cela peut rendre un médicament plus facile à prendre, plus durable, ou actif uniquement là où il est nécessaire.",
  prognosis: "L'évolution attendue d'une maladie : les chances de guérison, la durée de vie probable et l'état dans lequel la personne risque de se trouver. C'est toujours une estimation fondée sur des groupes de patients comparables, jamais une prédiction pour une personne donnée.",
  "programmable-dna-targeting-therapeutics": "Les thérapies programmables ciblant l'ADN sont une idée expérimentale : un médicament qui lit l'ADN d'une cellule, reconnaît une séquence propre au cancer et ne tue que les cellules qui la portent. Il suffit de changer le guide pour que le même médicament devienne un nouveau médicament.",
  "project-optimus": "Un programme de la FDA qui pousse les entreprises à trouver la meilleure dose d'un médicament anticancéreux, et pas seulement la dose maximale tolérée.",
  prolaris: "Un test génétique réalisé sur une biopsie de prostate qui estime l'agressivité du cancer, pour aider à choisir entre surveillance active et traitement.",
  "prostate-cancer-foundation": "La fondation de Michael Milken contre le cancer de la prostate, qui a financé la science à l'origine de l'abiraterone, de l'enzalutamide et de la thérapie PSMA, et qui anime un réseau d'oncologie de précision dans les hôpitaux des vétérans américains.",
  protect: "A montré que les hommes dont le cancer de la prostate a été détecté par dépistage en meurent rarement, qu'ils soient surveillés ou traités, ce qui a établi la surveillance active.",
  protein: "Les machines moléculaires qui font presque tout dans une cellule : recevoir des signaux, copier l'ADN, bâtir des structures, digérer la nourriture. La plupart des médicaments anticancéreux agissent en se fixant sur une protéine précise.",
  "prrt-term": "Un médicament radioactif contre les tumeurs neuroendocrines : un petit peptide qui se fixe sur le récepteur de la somatostatine des cellules tumorales transporte du lutétium-177, qui les irradie de l'intérieur. Administré quatre fois, à deux mois d'intervalle.",
  psa: "Une protéine sanguine produite par la prostate ; un taux élevé conduit à des examens complémentaires, et un taux qui baisse montre que le traitement agit.",
  "psma-pet-to-rlt": "L'imagerie montre si la cible est présente ; le traitement utilise la même adresse. Seuls les patients dont les tumeurs s'illuminent sont traités.",
  psmafore: "PSMAfore a avancé Pluvicto avant la chimiothérapie dans le cancer de la prostate.",
  pumch: "L'hôpital général le plus prestigieux de Chine, fondé en 1921 grâce à des fonds Rockefeller, et centre national de référence pour les tumeurs rares, endocriniennes et gynécologiques.",
  "purdue-cancer-research": "Le centre de recherche fondamentale sur le cancer du NCI à Purdue, où les ligands ciblant le folate et le PSMA de Philip Low ont donné naissance à Endocyte, l'entreprise que Novartis a rachetée pour son programme de radioligands.",
  "purwar-rahul": "L'immunologiste de l'IIT Bombay dont le laboratoire a conçu la première thérapie CAR-T approuvée en Inde et qui a fondé l'entreprise qui la fabrique pour une fraction des prix occidentaux.",
  "puxitatug-samrotecan": "Puxitatug samrotecan est un ADC anti-B7-H4 qui cible une protéine apparentée aux points de contrôle immunitaires, abondante dans les cancers du sein, de l'ovaire et de l'endomètre.",
  pyrotinib: "Pyrotinib est le comprimé anti-HER2 de la Chine, largement utilisé là-bas avec capecitabine et comme comparateur pour les nouveaux ADC anti-HER2 chinois.",
  "qimr-berghofer": "L'institut de recherche médicale du Queensland, leader mondial en génétique du mélanome et des cancers de la peau, en épidémiologie du cancer et en thérapie cellulaire T adoptive contre les cancers associés à des virus.",
  "qing-zhou": "Oncologue thoracique chinoise à l'origine de HARMONi-2, où le bispécifique anti-PD-1/VEGF ivonescimab a battu pembrolizumab en comparaison directe.",
  "qol-pro": "Mesures de ce que les patients ressentent eux-mêmes et de leur capacité à fonctionner pendant le traitement (douleur, fatigue, nausées, activités quotidiennes), recueillies par questionnaire plutôt que par le médecin. Les autorités réglementaires et les payeurs les attendent désormais aux côtés de la survie, et l'on sait que l'évaluation par les cliniciens sous-estime les symptômes.",
  "qst-hospital": "Le premier hôpital de thérapie par ions carbone au monde (HIMAC, 1994), qui a établi la base de preuves cliniques de la radiothérapie par ions lourds.",
  "quantum-first": "A à peu près doublé la survie médiane dans le sous-type FLT3 le plus agressif en ajoutant un inhibiteur sélectif de FLT3 à la chimiothérapie, y compris chez les patients de plus de 60 ans.",
  "queen-mary-hospital-hku": "Le principal hôpital universitaire de Hong Kong, où la transplantation hépatique à partir de donneur vivant pour le cancer du foie et la recherche sur le cancer du nasopharynx ont progressé.",
  quizartinib: "Quizartinib est un inhibiteur de FLT3 plus sélectif qui, ajouté à la chimiothérapie, a à peu près doublé la survie médiane dans le sous-type FLT3 à plus haut risque.",
  "radar-mrd": "Le test sanguin personnalisé de NeoGenomics pour détecter d'infimes quantités de cancer résiduel, qui suit jusqu'à 48 mutations issues de la tumeur du patient lui-même.",
  "radiation-plus-io": "La radiothérapie transforme la tumeur irradiée en vaccin ; l'immunothérapie propage la réponse.",
  "radiofrequency-ablation": "Détruire une tumeur en la chauffant par un courant électrique délivré à travers une aiguille placée sous guidage par imagerie, sans l'enlever.",
  "radioiodine-term": "Avaler une gélule d'iode radioactif après une chirurgie de la thyroïde : les cellules thyroïdiennes (y compris les cellules cancéreuses) sont les seules à absorber l'iode, si bien que le rayonnement détruit le tissu thyroïdien restant et les métastases en épargnant tout le reste. Ce fut la première radiothérapie ciblée, en 1946.",
  "radionuclide-generators-kits": "Des appareils de paillasse qui « traient » un isotope à vie courte à partir d'un isotope parent à vie longue, plus des flacons de ligand prêt à marquer. C'est ainsi que la plupart des hôpitaux fabriquent des traceurs PET PSMA et somatostatine sans cyclotron.",
  "radionuclide-parp-combination": "Ajouter un inhibiteur de PARP ou d'ATR à un médicament radioactif pour que la tumeur ne puisse pas réparer les dégâts causés par le rayonnement.",
  radiotherapy: "Utiliser des rayons X ou des particules de haute énergie pour endommager l'ADN des cellules cancéreuses dans un volume du corps visé avec précision. Elle guérit de nombreux cancers localisés et soulage les symptômes des cancers avancés, et environ la moitié des patients atteints de cancer en reçoivent.",
  "rai-refractory": "Cancer de la thyroïde qui ne capte plus l'iode radioactif, ou qui continue de progresser malgré lui. C'est là qu'interviennent les inhibiteurs de kinases en comprimés.",
  "ramathibodi-hospital": "Le deuxième grand hôpital universitaire de Mahidol, doté de programmes thaïlandais de premier plan en oncologie pédiatrique, hématologie, génétique du cancer et chirurgie hépatobiliaire.",
  rambam: "L'hôpital de recours du nord d'Israël, affilié au Technion, où ont été faites les découvertes sur le système ubiquitine-protéasome à l'origine des inhibiteurs du protéasome et des dégradeurs.",
  "rasolute-302": "L'essai qui a presque doublé la survie dans le cancer du pancréas déjà traité, présenté en séance plénière de l'ASCO 2026. Le plus grand résultat de l'histoire de cette maladie.",
  ratify: "L'essai qui a fait de FLT3 la première mutation ciblable dans l'AML : l'ajout de midostaurin à la chimiothérapie a triplé la survie médiane.",
  rcb: "Un score qui mesure la quantité de cancer restant après le traitement préopératoire, de 0 (aucun) à III (beaucoup).",
  "re-irradiation": "Réadministrer une radiothérapie dans une région déjà traitée, ce que l'on croyait autrefois impossible parce que les tissus sains gardent la mémoire de la première dose. Les techniques modernes de précision la rendent possible chez des patients sélectionnés.",
  "rebecca-dent": "Oncologue médicale spécialisée dans le cancer du sein et directrice générale adjointe chargée des opérations cliniques au National Cancer Centre Singapore, figure internationale de premier plan des essais sur le cancer du sein triple négatif.",
  "redifferentiation-rai": "Une courte cure d'un comprimé inhibiteur de MEK ou de BRAF peut amener un cancer de la thyroïde résistant à l'iode à recapter l'iode, ce qui permet à l'iode radioactif d'agir de nouveau.",
  "regulatory-agencies": "Chaque pays ou bloc a son propre régulateur du médicament : l'EMA (avec son comité CHMP) pour l'UE, la MHRA pour le Royaume-Uni, la PMDA pour le Japon, la NMPA pour la Chine, la TGA pour l'Australie. Un même médicament peut être approuvé à un endroit des années avant un autre, ou sur la base de preuves différentes.",
  "reinhard-dummer": "Dermato-oncologue suisse qui a dirigé COLUMBUS et les études néoadjuvantes du talimogene laherparepvec.",
  "relapse-recurrence": "Le cancer est revenu après une période pendant laquelle il n'était plus détectable. « Récidive » est le mot habituel pour les tumeurs solides et « rechute » pour les cancers du sang ; ils désignent la même chose.",
  "relativity-047": "A prouvé que l'ajout d'un bloqueur de LAG-3 au blocage de PD-1 retarde la progression, avec bien moins de toxicité que l'association avec l'ipilimumab.",
  "remote-patient-monitoring": "Des applications et des capteurs qui permettent aux patients de signaler leurs symptômes entre les consultations, ce qui, dans les essais, a amélioré la survie et réduit les passages aux urgences.",
  resectability: "Le verdict du chirurgien sur la possibilité d'enlever complètement la tumeur. Résécable veut dire oui ; non résécable veut dire qu'elle enserre des vaisseaux vitaux, qu'elle est trop étendue ou que le patient est trop fragile ; borderline veut dire peut-être, surtout après qu'une chimiothérapie l'a fait rétrécir.",
  rgci: "Le plus grand hôpital privé à but non lucratif consacré au cancer du nord de l'Inde, pionnier dans l'adoption de la chirurgie robotique, de l'oncologie de précision et de la greffe de moelle osseuse en Inde.",
  "richard-carvajal": "Oncologue spécialiste du mélanome qui a dirigé le programme tebentafusp aux États-Unis et défini la thérapie ciblée des sous-types rares de mélanome.",
  "richter-transformation": "Lorsqu'une LLC d'évolution lente se transforme brusquement en lymphome agressif. Rare, difficile à traiter, et au centre de nouveaux essais d'immunothérapie.",
  "rinatabart-sesutecan": "Le rinatabart sesutecan est un ADC de nouvelle génération ciblant le récepteur du folate, avec une charge utile inhibitrice de topoisomérase, qui donne des réponses dans le cancer de l'ovaire comme dans celui de l'endomètre, quel que soit le niveau d'expression du récepteur.",
  "risk-directed-first-line-rcc": "Un simple score clinique décide entre deux immunothérapies associées ou une immunothérapie avec un comprimé ciblé.",
  "risk-factor": "Tout ce qui augmente le risque de développer un cancer : tabac, alcool, obésité, exposition au soleil, certaines infections, gènes hérités, âge. Avoir un facteur de risque ne signifie pas qu'on aura un cancer, et beaucoup de cancers surviennent sans aucun facteur connu.",
  rivoceranib: "L'apatinib, commercialisé sous le nom de rivoceranib hors de Chine, a été le premier comprimé de sa catégorie approuvé dans le cancer de l'estomac et il est aujourd'hui le partenaire du camrelizumab en première ligne du cancer du foie.",
  "roar-atc": "A transformé le cancer de la thyroïde le plus mortel, jusque-là une condamnation à quelques mois, en une maladie traitable pour le tiers des patients dont la tumeur porte une mutation de BRAF.",
  "roger-stupp": "A dirigé l'essai EORTC/NCIC qui a fait du témozolomide associé à la radiothérapie le standard du glioblastome, ainsi que l'essai EF-14 sur les champs électriques antitumoraux.",
  "rtog-0129": "L'analyse qui a montré que les cancers de la gorge HPV-positifs sont une maladie différente et bien plus curable, ouvrant deux décennies de recherche sur la désescalade thérapeutique.",
  ruby: "L'ajout d'une immunothérapie à la première chimiothérapie du cancer de l'endomètre avancé a prolongé la vie de plus d'un an en moyenne, de façon la plus spectaculaire dans les tumeurs dont le correcteur d'orthographe de l'ADN est défaillant.",
  rucaparib: "Un inhibiteur de PARP pour les cancers de l'ovaire et de la prostate avec mutation BRCA, dont le fabricant d'origine a fait faillite ; il reste disponible, avec une indication restreinte.",
  rxponder: "Les femmes ménopausées avec quelques ganglions lymphatiques atteints et un score génomique bas peuvent se passer de chimiothérapie ; les femmes non ménopausées en tirent encore un bénéfice.",
  "ryu-min-hee": "Min-Hee Ryu est une investigatrice d'essais cliniques dans le cancer gastrique et les GIST, au cœur des volets asiatiques des études sur le ramucirumab, le pembrolizumab et le zolbetuximab.",
  "sagar-lonial": "A dirigé SIRIUS et le programme DREAMM, apportant au myélome la monothérapie par daratumumab et l'ADC anti-BCMA belantamab.",
  "salpingo-oophorectomy": "Ablation des ovaires et des trompes de Fallope. Réalisée pour un cancer de l'ovaire, pour le prévenir chez les porteuses d'une mutation BRCA, ou pour couper la production d'œstrogènes dans le cancer du sein.",
  "salvage-therapy": "Traitement donné après l'échec du premier traitement ou le retour du cancer, dans le but de sauver la situation. Il peut encore être curatif (chirurgie de rattrapage après l'échec d'une préservation d'organe) ou constituer une ligne ultérieure de traitement palliatif.",
  "samarium-153-lexidronam": "Quadramet est une injection radioactive qui gagne les métastases osseuses douloureuses et les irradie de l'intérieur, soulageant la douleur des cancers de la prostate, du sein et d'autres cancers largement disséminés dans les os.",
  "samsung-medical-center": "L'hôpital le mieux classé de Corée pour le cancer, un site majeur des essais asiatiques sur les ADC et le cancer du poumon.",
  "sara-hurvitz": "Sara Hurvitz est une investigatrice d'essais cliniques dans le cancer du sein qui a dirigé DESTINY-Breast03, l'essai où Enhertu a surpassé Kadcyla.",
  "sattva-neelapu": "A dirigé ZUMA-1, l'essai qui a fait de l'axicabtagene ciloleucel la première thérapie CAR-T approuvée dans le lymphome.",
  savolitinib: "Le savolitinib est un comprimé découvert en Chine qui bloque le signal de croissance MET, approuvé en Chine dans les cancers du poumon porteurs d'une mutation de l'exon 14 de MET et testé dans le monde entier en association avec l'osimertinib.",
  "sbrt-term": "Quelques (1 à 5) doses de radiation très élevées et d'une précision millimétrique qui détruisent une tumeur hors du cerveau presque comme une chirurgie, chez des patients qui ne peuvent pas ou préfèrent ne pas être opérés.",
  "scott-antonia": "A dirigé PACIFIC, qui a fait d'un an de durvalumab après chimioradiothérapie le standard du cancer du poumon de stade III.",
  "select-lenvatinib": "A fait du lenvatinib le principal médicament des cancers de la thyroïde qui ne captent plus l'iode radioactif, en quadruplant le délai avant progression de la maladie.",
  sengine: "Réalise le test PARIS : la tumeur d'un patient est cultivée sous forme d'organoïdes et testée contre plus de 240 médicaments pour trouver des options que le séquençage ne peut pas révéler.",
  "sensitivity-specificity": "La sensibilité est la part des personnes malades qu'un test détecte ; la spécificité est la part des personnes en bonne santé qu'il écarte correctement. Aucun test n'atteint 100 % sur les deux, et pour le dépistage, ce compromis détermine le nombre de fausses alertes.",
  "seoul-st-marys-hospital": "Le plus grand centre de Corée pour les cancers du sang, où s'est construite une grande partie de l'expertise du pays en greffe hématopoïétique et en leucémie.",
  serplulimab: "Le serplulimab est un anticorps anti-PD-1 chinois qui a obtenu le plus grand gain de survie de tous les essais d'immunothérapie de première ligne dans le cancer du poumon à petites cellules ; il est approuvé en Chine, en Europe et au Royaume-Uni, mais pas encore aux États-Unis.",
  "serum-institute-of-india": "Le plus grand fabricant de vaccins du monde en nombre de doses, qui a mis au point CERVAVAC, le premier vaccin anti-HPV fabriqué en Inde, afin que la prévention du cancer du col de l'utérus ne dépende plus de vaccins importés.",
  sevabertinib: "Le sevabertinib est un inhibiteur oral de HER2 pour les cancers du poumon porteurs de mutations de HER2, approuvé en novembre 2025 comme alternative à Enhertu et au zongertinib.",
  "seven-plus-three": "Le traitement initial classique de la leucémie myéloïde aiguë, inchangé depuis 1973 : sept jours de cytarabine en continu plus trois jours d'une anthracycline, administrés à l'hôpital. Les patients en bon état général le reçoivent toujours, désormais avec un médicament ciblé ajouté selon la génétique de leur leucémie.",
  "shandong-cancer-hospital": "L'un des plus grands centres de radiothérapie de Chine et l'un de ses sites les plus actifs pour les essais de radiothérapie dans les cancers du poumon et de l'œsophage, doté d'un centre de protonthérapie.",
  "shanghai-pulmonary-hospital": "Un hôpital de Shanghai consacré uniquement au poumon, avec l'un des plus gros volumes de chirurgie thoracique au monde et un groupe d'oncologie médicale qui a dirigé de nombreux essais chinois sur le cancer du poumon.",
  "shanu-modi": "A dirigé DESTINY-Breast01 et DESTINY-Breast04, les essais qui ont créé la catégorie HER2-low et ouvert le T-DXd à la plupart des cancers du sein.",
  "sharon-belvin": "Diagnostiquée d'un mélanome métastatique à 22 ans, elle a reçu l'anticorps anti-CTLA-4 ipilimumab dans un essai précoce au Memorial Sloan Kettering et n'a plus de cancer depuis. Sa rencontre avec James Allison en 2006 fait partie de l'histoire de l'immunothérapie.",
  "shitara-kohei": "Investigateur principal de SPOTLIGHT et de DESTINY-Gastric01, deux essais qui ont créé de nouvelles classes de médicaments dans le cancer de l'estomac.",
  "shizuoka-cancer-center": "Un centre anticancéreux préfectoral près du mont Fuji, doté d'un centre de protonthérapie et du Project HOPE, l'un des plus grands programmes japonais de profilage multi-omique du cancer.",
  "side-effect-vs-adverse-event": "Un événement indésirable est tout ce qui arrive de mauvais à un patient pendant un essai, que le médicament en soit la cause ou non ; un effet secondaire est un dommage que le médicament est connu pour provoquer. Les tableaux des essais recensent les événements indésirables, puis évaluent lesquels étaient liés au traitement.",
  sidedness: "L'endroit du côlon où naît une tumeur modifie sa biologie et les médicaments qui agissent. Les tumeurs du côté gauche répondent aux anticorps anti-EGFR ; celles du côté droit non.",
  "siemens-healthineers": "Siemens Healthineers fabrique le TEP corps entier Biograph Vision Quadra et le scanner à comptage photonique, et possède Varian.",
  "simplescreen-crc": "Le deuxième test sanguin approuvé par la FDA pour le dépistage du cancer colorectal, développé par Freenome et commercialisé par Abbott à partir de fin 2026.",
  "siriraj-hospital": "Le plus ancien et le plus grand hôpital de Thaïlande, qui abrite les principaux programmes universitaires du pays en oncologie, hématologie et hépatobiliaire ainsi qu'un nouveau centre de cancérologie équipé de la protonthérapie.",
  smc: "L'organisme écossais d'évaluation des technologies de santé, qui conseille le NHS Scotland sur les nouveaux médicaments et applique une approche plus souple aux anticancéreux de fin de vie et aux médicaments orphelins.",
  snuh: "Le Seoul National University Hospital est l'hôpital universitaire national de Corée et l'un des premiers recruteurs mondiaux pour les essais sur les cancers de l'estomac et du poumon.",
  "sofie-biosciences": "SOFIE Biosciences est un réseau de radiopharmacies américain qui mène deux essais de phase 3 du traceur TEP ciblant FAP, le [18F]FAPI-74, dans les cancers du pancréas et gastro-œsophagiens.",
  "solo-1": "Deux ans d'olaparib en comprimé après la chimiothérapie ont fait d'une large part des femmes atteintes d'un cancer de l'ovaire avec mutation BRCA des survivantes à long terme.",
  "spatial-omics-guided-therapy": "Choisir le traitement à partir d'une carte indiquant où se situe chaque type de cellule dans la tumeur, et pas seulement à partir d'une liste de ses mutations.",
  "spotlight-glow": "Deux essais qui ont fait de Claudin 18.2 le troisième biomarqueur du cancer de l'estomac, en apportant environ deux à trois mois de survie supplémentaires grâce à un anticorps dirigé contre elle.",
  "squamous-cell-carcinoma": "Un carcinome qui naît des cellules plates et stratifiées qui tapissent les surfaces exposées à l'usure : peau, bouche, gorge, œsophage, col de l'utérus, grosses voies aériennes. Souvent lié au tabac, au soleil ou au HPV.",
  "squamous-cell-carcinoma-term": "Cancer qui naît des cellules plates, en forme d'écailles, qui forment la peau et tapissent la bouche, la gorge, l'œsophage, les voies aériennes, le col de l'utérus et l'anus. Le tabac, l'alcool, le soleil et le HPV en sont les principales causes.",
  "st-baldricks": "Une collecte de fonds fondée sur le rasage de la tête, devenue le premier financeur caritatif de la recherche sur les cancers de l'enfant aux États-Unis, qui soutient une grande partie de l'infrastructure des essais des groupes coopératifs traitant la majorité des enfants américains atteints de cancer.",
  "st-johns-wort-interaction": "Le millepertuis est un antidépresseur à base de plantes qui active les enzymes hépatiques dégradant de nombreux anticancéreux, réduisant jusqu'à de moitié les concentrations d'irinotécan, d'imatinib et de nombreux comprimés de thérapie ciblée. Il ne doit pas être pris pendant un traitement contre le cancer.",
  "statistical-significance": "Un résultat est « statistiquement significatif » lorsqu'il serait peu probable (généralement moins de 5 %) qu'il survienne par hasard si le traitement n'avait aucun effet. C'est un seuil, pas une mesure d'importance : un bénéfice minuscule peut être significatif dans un essai immense, et un bénéfice important non significatif dans un petit essai.",
  "step-up-dosing": "Commencer un immunothérapeutique puissant à une dose infime et l'augmenter sur plusieurs jours, afin que le système immunitaire s'active progressivement et que la dangereuse réaction de fièvre et d'hypotension (libération de cytokines) reste légère.",
  "stephen-johnston": "Investigateur principal de monarchE, l'essai qui a ajouté l'abémaciclib à l'hormonothérapie adjuvante dans le cancer du sein précoce à haut risque.",
  "stephenson-oklahoma": "Le seul centre désigné par le NCI en Oklahoma, régulièrement parmi les premiers recruteurs des essais gynécologiques du NRG et siège de l'investigateur principal des essais SOLO1 et MIRASOL sur le cancer de l'ovaire.",
  "steven-rosenberg": "Père de l'immunothérapie du cancer : le premier à avoir guéri des patients avec l'IL-2 et avec leurs propres lymphocytes infiltrant la tumeur.",
  sugemalimab: "Le sugemalimab est l'anticorps anti-PD-L1 de CStone, approuvé en Chine pour le cancer du poumon en première ligne avec chimiothérapie et après chimioradiothérapie au stade III, et le premier anticorps anti-PD-L1 développé en Chine à obtenir une approbation européenne.",
  "sumanta-pal": "A dirigé SWOG 1500, le premier essai randomisé à établir un standard pour le cancer du rein papillaire, ainsi que des études sur le microbiome dans l'immunothérapie du carcinome rénal.",
  "sumit-gupta": "A dirigé COG AALL1731, qui a montré que l'ajout du blinatumomab à la chimiothérapie améliore la survie des enfants atteints d'une leucémie de risque standard.",
  "sun-pharma": "Le premier laboratoire pharmaceutique indien, propriétaire des anticancéreux de marque Odomzo et Yonsa aux États-Unis, qui a racheté en 2025 Checkpoint Therapeutics, fabricant d'un anticorps anti-PD-L1.",
  "surgical-morbidity": "Les préjudices de l'opération elle-même : complications (fistules, infections, hémorragies, pneumonie), durée d'hospitalisation et décès dans les 30 ou 90 jours. Les grandes interventions en cancérologie comportent un risque réel, mis en balance avec leurs chances de guérison, ce qui motive la recherche d'alternatives moins invasives.",
  "surrogate-endpoint": "Une mesure plus rapide et plus facile, utilisée à la place de ce qui compte vraiment. La réduction de la tumeur ou le retard de sa croissance remplacent le fait de vivre plus longtemps, en supposant, ce qui n'est pas toujours vrai, que l'un entraîne l'autre.",
  "susan-domchek": "Dirige le premier centre au monde consacré aux cancers liés à BRCA ainsi que les essais associant inhibiteurs de PARP et immunothérapie.",
  "sutro-biopharma": "Société d'ADC fondée sur la synthèse protéique acellulaire, qui s'est recentrée sur les ADC à exatécan et à double charge, en reléguant au second plan son ADC anti-récepteur des folates, le luveltamab.",
  swissmedic: "L'autorité suisse de régulation des médicaments, dans le pays qui abrite Roche et Novartis, membre du Project Orbis et de l'Access Consortium.",
  "swog-s1801": "Le simple fait d'administrer trois doses du même médicament avant la chirurgie plutôt qu'après a amélioré les résultats, un constat qui a changé la façon dont la discipline envisage le moment du traitement.",
  "systemic-vs-local-therapy": "Le traitement local (chirurgie, radiothérapie) traite un seul endroit du corps ; le traitement systémique (médicaments pris par la bouche ou par voie intraveineuse) circule dans le sang et traite tout le corps, y compris les cellules cancéreuses trop petites pour être visibles.",
  systimmune: "SystImmune a développé l'iza-bren, le premier ADC bispécifique à remporter un essai de phase 3.",
  tadpole: "Le premier essai randomisé à montrer qu'une association de médicaments ciblés fait mieux que la chimiothérapie chez des enfants atteints d'une tumeur cérébrale. Les enfants dont le gliome de bas grade porte une mutation BRAF V600 ont eu une réduction tumorale bien plus importante et un délai avant progression bien plus long sous dabrafénib plus tramétinib que sous carboplatine et vincristine standard.",
  "tai-chi-qigong": "Ces pratiques de mouvement lent et à faible impact issues de la tradition chinoise améliorent la fatigue, le sommeil et l'équilibre des personnes atteintes de cancer. Les essais randomisés sont de taille modérée et positifs, et la recommandation 2024 sur la fatigue les préconise pendant le traitement.",
  tailorx: "A montré que la plupart des femmes atteintes du cancer du sein le plus fréquent peuvent se passer de chimiothérapie en toute sécurité si un test génétique indique un risque faible ou intermédiaire.",
  "taipei-veterans-general-hospital": "L'un des trois grands centres médicaux de Taïwan, doté d'un centre de thérapie par ions lourds et d'une solide recherche en oncologie pulmonaire, hépatique et digestive.",
  talquetamab: "Le talquetamab est le premier médicament dirigé contre GPRC5D, une deuxième cible dans le myélome utilisée lorsque les traitements anti-BCMA cessent d'agir ; les effets indésirables sur le goût et la peau en sont la signature.",
  "tandem-transplant": "Deux cycles de chimiothérapie à très haute dose avec réinjection de cellules souches, enchaînés l'un après l'autre, utilisés dans le neuroblastome à haut risque en Amérique du Nord.",
  "tango-therapeutics": "Tango Therapeutics conçoit des comprimés anticancéreux qui exploitent la faiblesse créée lorsqu'une tumeur perd un gène particulier. Son médicament phare cible les cancers ayant perdu un gène appelé MTAP, fréquent dans les cancers du pancréas et du poumon.",
  "tanios-bekaii-saab": "Oncologue digestif à l'origine des essais de thérapies ciblant KRAS, HER2 et FGFR dans le cancer colorectal et le cancer des voies biliaires.",
  "tar-200": "Le TAR-200 est un petit dispositif en forme de bretzel placé dans la vessie qui libère de la gemcitabine pendant trois semaines d'affilée. Il a été approuvé en 2025 pour le cancer de la vessie précoce qui ne répond plus au BCG.",
  tare: "Injecter de minuscules billes radioactives de verre ou de résine dans l'artère du foie pour qu'elles se logent dans la tumeur et l'irradient de l'intérieur.",
  "targeted-before-io-nsclc": "Si un cancer du poumon présente une mutation ciblable, il faut donner le comprimé en premier ; l'immunothérapie agit mal sur ces tumeurs et augmente le risque d'effets indésirables graves lorsqu'un comprimé lui fait suite.",
  "tasuku-honjo": "Il a découvert la molécule PD-1 sur les lymphocytes T en 1992 et montré qu'elle agit comme un frein à l'attaque immunitaire. Son blocage a donné naissance au nivolumab et au pembrolizumab, aujourd'hui utilisés dans des dizaines de cancers ; prix Nobel 2018.",
  "tata-medical-center-kolkata": "Le premier hôpital de cancérologie de l'est de l'Inde, ouvert par les Tata Trusts en 2011, doté d'un solide programme de pédiatrie et d'hématologie et d'un institut de recherche translationnelle.",
  "tawam-hospital": "L'hôpital national de référence pour le cancer des Émirats arabes unis, doté du premier institut d'oncologie complet du pays, d'un service de greffe de moelle osseuse et d'une affiliation de longue date avec Johns Hopkins.",
  "tegafur-gimeracil-oteracil": "Teysuno (S-1) est une chimiothérapie orale qui associe un promédicament du fluorouracile à deux protecteurs. C'est un standard au Japon, et il est approuvé en Europe pour le cancer de l'estomac avec le cisplatine et pour le cancer colorectal lorsque d'autres fluoropyrimidines provoquent un syndrome main-pied ou des problèmes cardiaques.",
  "tehran-cancer-institute": "Le plus ancien et le plus grand centre de cancérologie d'Iran, fondé en 1955 au sein du complexe hospitalier Imam Khomeini de Téhéran, et principal pôle de formation et de recherche en oncologie du pays.",
  "tel-aviv-sourasky": "Le principal hôpital universitaire municipal de Tel Aviv, un centre d'essais cliniques en oncologie très actif, particulièrement fort en cancers digestifs, sarcomes et neuro-oncologie.",
  "telehealth-oncology": "Les consultations en vidéo, la surveillance à distance et l'administration à domicile de certains traitements anticancéreux se sont massivement développées pendant la COVID-19 et se sont maintenues; elles réduisent la contrainte des déplacements, surtout pour les patients ruraux, sans preuve de résultats moins bons.",
  telix: "Telix est la société australienne de théranostique à l'origine des agents d'imagerie PSMA Illuccix et Gozellix et d'un large portefeuille thérapeutique en développement.",
  "tempus-xt-cdx": "Le panel génétique tumeur et tissu normal de Tempus, approuvé par la FDA en 2023 comme test compagnon des anticorps anti-EGFR dans le cancer colorectal.",
  temsirolimus: "Une perfusion hebdomadaire qui a été le premier médicament à prolonger la survie dans le cancer du rein de mauvais pronostic (2007) et, en 2024, le premier traitement ciblé à améliorer les résultats dans le rhabdomyosarcome de l'enfant.",
  tga: "L'autorité australienne de régulation des médicaments et des dispositifs médicaux, partenaire du Project Orbis et de l'Access Consortium, qui enregistre les médicaments anticancéreux avant que le PBAC décide de les rembourser ou non.",
  therap: "L'essai randomisé qui a pour la première fois opposé un radioligand à la chimiothérapie et l'a emporté sur le taux de réponse, avec moins d'effets secondaires.",
  "therapeutic-index": "L'écart entre la dose qui agit et la dose qui nuit. La chimiothérapie classique a une fenêtre étroite (la dose qui tue la tumeur tue presque le patient); une fenêtre plus large est tout l'intérêt des traitements ciblés, des ADC et de l'immunothérapie.",
  "therapy-isotope-supply-chain": "D'où viennent réellement les atomes radioactifs utilisés en imagerie et en thérapie: des réacteurs vieillissants, de nouveaux accélérateurs et une course à l'actinium.",
  "thermo-fisher": "Thermo Fisher est la plus grande entreprise d'outils et de services pour les sciences de la vie, couvrant le séquençage Ion Torrent (Oncomine), la production de vecteurs viraux et le remplissage aseptique (Patheon), ainsi que l'organisme de recherche clinique PPD.",
  "thierry-andre": "A dirigé MOSAIC, qui a fait de FOLFOX le standard adjuvant, et KEYNOTE-177, qui a fait du pembrolizumab le traitement de première ligne du cancer du côlon MSI-high.",
  thiotepa: "Le thiotépa est une chimiothérapie ancienne avec un rôle moderne: à forte dose, il prépare les patients à la greffe de cellules souches, et il est encore instillé dans la vessie ou les cavités du corps pour le cancer superficiel de la vessie et les épanchements malins.",
  tigit: "TIGIT est un frein immunitaire qui semblait prometteur, puis a échoué dans plusieurs grands essais sur le cancer du poumon. C'est un cas d'école à méditer.",
  "tilatamig-samrotecan": "L'ADC bispécifique EGFR×c-MET d'AstraZeneca, le plus avancé dans le couple de cibles le plus disputé des ADC de nouvelle génération.",
  tim3: "Un point de contrôle immunitaire présent sur les lymphocytes T épuisés et sur les cellules souches leucémiques; les anticorps dirigés contre lui ont échoué dans le cancer du poumon et les SMD, après des résultats précliniques très prometteurs.",
  "tina-cascone": "A dirigé CheckMate 77T, l'un des essais d'immunothérapie périopératoire qui ont changé la prise en charge du cancer du poumon opérable.",
  tinengotinib: "Un inhibiteur de FGFR de nouvelle génération conçu pour agir après l'échec du pémigatinib ou du futibatinib, actuellement en phase 3 mondiale.",
  tiragolumab: "Un bloqueur de frein immunitaire qui avait donné d'excellents résultats dans un essai de phase 2 sur le cancer du poumon, puis a échoué dans toutes les phases 3.",
  tivozanib: "Le tivozanib est un comprimé très sélectif du récepteur du VEGF pour le cancer du rein après au moins deux traitements antérieurs, remarquable par sa tolérance et par un essai qui a fermé la porte à la reprise de l'immunothérapie.",
  "tki-plus-blinatumomab-ph-all": "Un comprimé qui coupe le moteur de la leucémie, associé à une immunothérapie qui élimine les cellules survivantes, sans aucune chimiothérapie.",
  tmucih: "Le berceau de l'oncologie chinoise (un hôpital missionnaire de 1861, devenu hôpital de cancérologie en 1952 sous Jin Xianzhai) et un centre national pour les cancers du sein et du pancréas.",
  "tnm-staging": "La classification TNM est le système universel qui décrit la taille de la tumeur (T), l'atteinte des ganglions lymphatiques (N) et les métastases à distance (M).",
  "tohoku-university-hospital": "L'hôpital universitaire de Sendai et bras clinique du Tohoku Medical Megabank, avec des points forts en cancer du sein, gastro-entérologie et imagerie.",
  "toni-choueiri": "Dirige la recherche mondiale sur le cancer du rein, notamment les essais sur le pembrolizumab adjuvant et le belzutifan.",
  "topaz-1": "TOPAZ-1 a été le premier succès de l'immunothérapie dans le cancer des voies biliaires, avec un gain médian modeste mais une proportion croissante de survivants à long terme.",
  "total-body-pet-screening": "Des appareils assez sensibles pour imager le corps entier en quelques secondes avec une fraction de la dose de radiation, ce qui pose la question de savoir s'il faut vraiment scanner des personnes en bonne santé.",
  "total-neoadjuvant-therapy": "Administrer toute la chimiothérapie et la radiothérapie du cancer du rectum avant la chirurgie plutôt que de les répartir autour de l'opération. Cela améliore l'achèvement de la chimiothérapie, fait disparaître complètement davantage de tumeurs et permet à certains patients d'éviter la chirurgie.",
  "toxicity-grade": "Une échelle de gravité de 1 à 5 pour les effets secondaires: grade 1 léger, grade 2 modéré, grade 3 sévère et nécessitant une intervention, grade 4 menaçant la vie, grade 5 mortel. Les essais rapportent le pourcentage de patients ayant un grade 3 ou plus.",
  "tp53-mutated": "La perte de p53, le 'gardien du génome', le gène le plus fréquemment muté dans le cancer. Dans les cancers du sang et plusieurs tumeurs solides, une mutation de TP53 définit le groupe le plus à risque, résistant à la chimiothérapie et difficile à traiter.",
  tps: "Le score PD-L1 utilisé dans le cancer du poumon: le pourcentage de cellules tumorales dont le marquage est positif.",
  trabectedin: "Une chimiothérapie dérivée d'une ascidie marine, utilisée avec la doxorubicine liposomale dans le cancer de l'ovaire en rechute en Europe et dans les sarcomes.",
  trametinib: "Le tramétinib (Mekinist) bloque MEK, la protéine située juste en aval de BRAF dans la chaîne des signaux de croissance. Associé au dabrafénib, il traite le mélanome, le cancer du poumon, de la thyroïde et d'autres cancers porteurs d'une mutation BRAF, y compris des tumeurs cérébrales chez l'enfant.",
  "trastuzumab-biosimilars": "Des copies quasi identiques de l'Herceptin, approuvées depuis 2017, qui ont fait baisser le prix du traitement anti-HER2 et élargi l'accès dans le monde entier.",
  "trastuzumab-rezetecan": "L'ADC anti-HER2 de Hengrui, approuvé en Chine dans le cancer du poumon et affichant des résultats de l'ampleur d'Enhertu dans le cancer du sein, fait partie d'une vague d'ADC chinois en route vers des essais mondiaux.",
  tremelimumab: "Le trémélimumab est l'anticorps anti-CTLA-4 d'AstraZeneca, administré en une dose unique d'amorçage avec le durvalumab et la chimiothérapie dans les cancers du poumon et du foie.",
  "trial-phases": "Les trois étapes que franchit un nouveau médicament: la phase 1 détermine une dose sûre chez quelques dizaines de patients, la phase 2 recherche des signes d'activité chez une centaine environ, et la phase 3 le compare au traitement standard chez des centaines ou des milliers.",
  "trifluridine-tipiracil": "Une chimiothérapie orale en comprimé pour le cancer colorectal qui ne répond plus à aucun autre traitement; associée au bévacizumab, elle prolonge la vie d'environ trois mois.",
  triptorelin: "La triptoréline (Trelstar) est une injection mensuelle, trimestrielle ou semestrielle qui coupe la production de testostérone chez les hommes atteints d'un cancer de la prostate avancé.",
  "trop2-pet-to-adc": "Proposition: une TEP TROP2 pour choisir entre trois ADC anti-TROP2 et prédire qui répondra, puisque le marquage tissulaire n'a pas fonctionné.",
  "tumor-lysis-syndrome": "Lorsqu'un traitement tue tant de cellules cancéreuses si vite que leur contenu submerge les reins et le cœur. C'est la raison pour laquelle le vénétoclax débute à une dose minime, augmentée progressivement.",
  "tumour-marker": "Une substance, généralement une protéine, que la tumeur libère dans le sang en quantités mesurables. La hausse ou la baisse de son taux indique si le cancer progresse ou répond au traitement, mais elle suffit rarement à elle seule pour poser le diagnostic.",
  uicc: "L'organisation de membres basée à Genève qui fédère plus de 1,100 organisations de lutte contre le cancer et qui pilote la Journée mondiale contre le cancer, le Congrès mondial sur le cancer et le système de classification TNM.",
  ukctocs: "Le plus grand essai de dépistage jamais mené pour le cancer de l'ovaire a montré une détection plus précoce mais aucune réduction des décès; il n'existe donc toujours aucun dépistage recommandé.",
  "ummc-kuala-lumpur": "Le premier hôpital universitaire de Malaisie, qui abrite l'UM Cancer Research Institute et des études multiethniques de référence sur la génétique et l'évolution du cancer du sein.",
  "unc-lineberger": "C'est là que Charles Perou a défini les sous-types intrinsèques PAM50 du cancer du sein; un centre d'université publique doté de sa propre production de CAR-T.",
  "union-hospital-wuhan": "L'autre hôpital universitaire de rang national de Wuhan, remarquable pour les programmes de cancer du sein, de lymphome et de radiothérapie de son centre de cancérologie et pour la protonthérapie.",
  "unlocking-phenotypic-plasticity": "Les cellules cancéreuses échappent à la règle normale selon laquelle les cellules matures restent ce qu'elles sont : elles se dédifférencient, se transdifférencient ou refusent de parvenir à maturité.",
  "upmc-hillman": "Le centre de cancérologie intégré du NCI à Pittsburgh : berceau du NSABP de Bernard Fisher, découvreur de deux virus cancérigènes et chef de file dans le mélanome et l'immunothérapie ciblant LAG-3.",
  "us-worldmeds": "Société privée américaine qui a repris Tecelra et lete-cel d'Adaptimmune en 2025 et commercialise l'eflornithine (Iwilfin) pour le neuroblastome.",
  "usc-norris": "L'un des huit premiers centres de cancérologie intégrés du NCI (1973), chef de file des essais en oncologie digestive, de l'épigénétique du cancer et de l'épidémiologie multiethnique.",
  "utsw-simmons": "Le centre de cancérologie intégré du NCI du nord du Texas, où sont nés l'inhibiteur de HIF-2 belzutifan, la radiothérapie stéréotaxique corporelle et la voie cGAS-STING.",
  "uw-carbone": "L'un des premiers centres de cancérologie intégrés du NCI en 1973, où le 5-fluorouracil a été synthétisé, la transcriptase inverse découverte et la TomoTherapy inventée.",
  "uwe-haberkorn": "Médecin nucléaire dont le groupe a inventé les traceurs PET FAPI et a ouvert la voie à la thérapie par radioligands ciblant PSMA et FAP.",
  "uz-gent": "Le centre de cancérologie universitaire de Gand, accrédité par l'OECI, connu pour la génomique du neuroblastome, les essais de phase précoce et l'immuno-oncologie.",
  "vanderbilt-ingram": "Le centre de cancérologie intégré du NCI dans le Tennessee, berceau de la base de connaissances My Cancer Genome et des sous-types moléculaires du cancer du sein triple négatif.",
  vandetanib: "Vandetanib a été le premier médicament approuvé dans le cancer médullaire de la thyroïde (2011), aujourd'hui largement remplacé par le selpercatinib, sélectif de RET.",
  "velindre-cardiff": "Le centre de cancérologie spécialisé non chirurgical du pays de Galles, qui assure la radiothérapie et les traitements systémiques pour le sud-est du pays de Galles et héberge le Wales Cancer Research Centre.",
  "ventana-mmr-rxdx": "Un test à quatre colorations qui montre si un cancer de l'utérus a perdu son correcteur orthographique du DNA, ce qui rend l'immunothérapie susceptible de fonctionner.",
  "viale-a": "L'essai qui a offert aux patients âgés atteints d'AML un vrai traitement : l'ajout de venetoclax à l'azacitidine a doublé les taux de rémission et prolongé la survie.",
  vinorelbine: "Vinorelbine est une chimiothérapie de la famille des vinca-alcaloïdes pour le cancer du poumon et du sein, disponible par voie orale, et fait désormais partie du traitement d'entretien qui a amélioré la survie dans le rhabdomyosarcome de l'enfant.",
  vismodegib: "Vismodegib a été le premier médicament ciblant la voie hedgehog, pour les carcinomes basocellulaires trop avancés pour la chirurgie ; il fait régresser la plupart des tumeurs, mais les crampes musculaires, la perte du goût et la chute des cheveux rendent son utilisation prolongée difficile.",
  vivli: "La plateforme à but non lucratif par laquelle les laboratoires pharmaceutiques et les financeurs partagent les données individuelles anonymisées des patients issues d'essais terminés, dont des milliers d'études en oncologie.",
  vrd: "La soupe de lettres du traitement du myélome : V (bortezomib, Velcade), R (lenalidomide, Revlimid), d (dexamethasone), Dara (daratumumab), Isa (isatuximab), K (carfilzomib). Dara-VRd, une quadrithérapie à quatre médicaments, est désormais le traitement initial standard pour la plupart des patients.",
  vte: "Caillots de sang dans les veines des jambes ou dans les poumons. Le cancer rend le sang plus coagulable et certains traitements (IMiDs, médicaments anti-VEGF, hormonothérapie, cathéters centraux, chirurgie) ajoutent un risque ; les caillots sont la deuxième cause de décès la plus fréquente chez les patients atteints de cancer, après le cancer lui-même.",
  vus: "Un variant de signification incertaine (VUS) est une altération génétique qui a été détectée, mais dont personne ne sait encore si elle a de l'importance.",
  "warburg-effect": "Les cellules cancéreuses transforment le glucose en lactate même lorsque l'oxygène abonde, une façon peu efficace mais rapide de fabriquer des briques élémentaires. Otto Warburg l'a décrit dans les années 1920.",
  wellcome: "L'un des plus grands financeurs caritatifs de la science au monde et partenaire fondateur du Francis Crick Institute et du Wellcome Sanger Institute, qui héberge la base de données de mutations du cancer COSMIC.",
  whel: "Trois mille femmes ayant survécu à un cancer du sein ont été accompagnées pendant des années pour manger beaucoup plus de légumes, de fruits et de fibres. Elles l'ont fait, et cela n'a rien changé à la récidive ni à la survie.",
  "wigs-cranial-prosthesis": "Une perruque, un foulard ou un bonnet bien ajustés redonnent intimité et confiance en soi pendant la chute des cheveux. Au Royaume-Uni, les perruques sont disponibles sur prescription du NHS (gratuites en Écosse, au pays de Galles et en Irlande du Nord, et gratuites en Angleterre pour de nombreux groupes) ; aux États-Unis, une ordonnance médicale pour une 'prothèse crânienne' permet à certains assureurs d'en rembourser une, et des associations caritatives offrent des perruques gratuitement.",
  wjog: "Le deuxième groupe coopératif national du Japon, né en oncologie thoracique ; son essai WJTOG3405 a contribué à imposer les inhibiteurs d'EGFR comme traitement de première ligne du cancer du poumon.",
  xaluritamig: "Xaluritamig est l'engageur de lymphocytes T d'Amgen pour le cancer de la prostate, actuellement en deux essais de phase 3, qui vise à faire pour le cancer de la prostate ce que tarlatamab a fait pour le cancer du poumon à petites cellules.",
  xilis: "Spin-out de Duke dont les gouttelettes MicroOrganoSphere font pousser la tumeur d'un patient et testent des médicaments en deux semaines.",
  "xu-binghe": "Investigateur principal d'OptiTROP-Breast01, l'essai chinois qui a permis l'approbation de l'ADC anti-TROP2 sacituzumab tirumotecan avant toute approbation occidentale.",
  "xu-rui-hua": "Dirige le plus grand centre de cancérologie de Chine et a mené les essais de phase 3 chinois qui ont introduit les anticorps anti-PD-1 dans les cancers digestifs.",
  "yoshino-takayuki": "Dirige CIRCULATE-Japan, le plus grand programme adjuvant guidé par le ctDNA dans le cancer colorectal, ainsi que les initiatives PARADIGM et SCRUM-Japan GI.",
  "zai-lab": "Zai Lab est le pionnier de l'achat de licences qui apporte les médicaments anticancéreux occidentaux en Chine (niraparib, zanidatamab, repotrectinib, Tumour Treating Fields) et exporte désormais ses propres bispécifiques et ADC.",
  "zhou-caicun": "Investigateur principal de HARMONi-2, l'essai dans lequel ivonescimab a battu pembrolizumab en comparaison directe, et du premier essai de phase 3 d'un EGFR-TKI chez des patients chinois.",
  "zoledronic-acid": "L'acide zolédronique (Zometa) est une perfusion de quinze minutes administrée toutes les quelques semaines ou tous les quelques mois pour renforcer l'os et prévenir les fractures, la compression de la moelle épinière et le recours à la radiothérapie chez les personnes atteintes d'un myélome ou d'un cancer ayant atteint les os ; il traite aussi le taux de calcium dangereusement élevé provoqué par le cancer.",
  zynlonta: "Loncastuximab tesirine (Zynlonta) est un ADC anti-CD19 doté d'une charge utile qui crée des pontages dans le DNA, destiné au lymphome B à grandes cellules en rechute.",
  // ---- fourth wave (2026-09) ----
  "10x-genomics": "Leader des outils de biologie unicellulaire et spatiale (Chromium, Visium, Xenium) utilisés pour disséquer les tumeurs.",
  "abc-02": "L'essai britannique de 2010 qui a donné au cancer des voies biliaires sa première chimiothérapie standard.",
  "abdera-therapeutics": "Abdera Therapeutics a conçu des anticorps qui transportent un isotope radioactif jusqu'aux cellules cancéreuses, en réglant leur durée de circulation pour que davantage de rayonnement atteigne la tumeur et moins les tissus sains. Son premier médicament cible une protéine du cancer du poumon à petites cellules.",
  accrual: "Le nombre de patients qu'un essai a recrutés, et à quelle vitesse. Un recrutement lent est la raison la plus fréquente pour laquelle des essais durent des années de plus que prévu ou ferment sans réponse ; seuls 5-8% environ des adultes atteints de cancer participent un jour à un essai.",
  "acrivon-therapeutics": "Acrivon Therapeutics utilise un test d'activité protéique pour sélectionner les patients les plus susceptibles de répondre à ses médicaments anticancéreux. Son médicament phare bloque les protéines des points de contrôle des dommages à l'ADN et est testé dans le cancer de l'utérus et de l'ovaire.",
  "act-iv": "Un essai en double aveugle d'un vaccin prometteur contre le glioblastome qui n'a montré aucun bénéfice, et qui a appris au domaine à quel point les comparaisons avec des contrôles historiques peuvent être trompeuses.",
  "actinium-pharmaceuticals": "Actinium Pharmaceuticals fixe l'isotope émetteur alpha actinium-225 à des anticorps pour traiter la leucémie aiguë myéloïde et, plus récemment, des tumeurs solides comme les cancers de la prostate et du poumon. C'est une petite société cotée dont le programme phare approche de nouvelles étapes cliniques.",
  "action-dmg": "ACTION est le premier essai de phase 3 contrôlé par placebo jamais mené dans le gliome diffus de la ligne médiane, la tumeur du tronc cérébral de l'enfant que la radiothérapie seule n'a jamais guérie. Il cherche à savoir si la prise de dordaviprone après la radiothérapie prolonge la vie.",
  "acupuncture-nausea": "Stimuler le point P6 à la face interne du poignet, par aiguilles, stimulation électrique ou bracelet de pression, apporte une petite réduction supplémentaire des vomissements de la chimiothérapie en plus des antiémétiques modernes. C'est sûr et peu coûteux, et les recommandations indiquent que cela peut être proposé.",
  "acupuncture-xerostomia": "La radiothérapie de la tête et du cou peut assécher la bouche de façon permanente. Un essai randomisé mené aux États-Unis et en Chine a constaté que l'acupuncture pratiquée pendant la radiothérapie réduisait la sécheresse buccale un an plus tard par rapport aux soins standard, un effet qui reste à confirmer.",
  "adc-payload-neutralizer": "Un neutralisant de charge utile d'ADC est un anticorps administré en même temps qu'un ADC, qui capte le poison une fois qu'il fuit dans la circulation sanguine, afin que l'ADC puisse frapper la tumeur avec moins d'effets secondaires.",
  adela: "Adela développe des tests sanguins qui lisent des marques chimiques sur l'ensemble du génome des fragments d'ADN présents dans le sang, d'abord pour vérifier si le cancer est toujours présent après le traitement, puis pour dépister de nombreux cancers à la fois.",
  admiral: "A montré qu'un comprimé fait mieux qu'une chimiothérapie de rattrapage intensive dans la LAM en rechute avec mutation de FLT3, avec moins de jours d'hospitalisation.",
  "adu-s100": "ADU-S100 a été le premier agoniste de STING en clinique. Injecté directement dans les tumeurs, il n'a produit presque aucune réponse, seul ou avec un blocage des points de contrôle immunitaires.",
  "adventris-pharmaceuticals": "Adventris fabrique des vaccins anticancéreux prêts à l'emploi dirigés contre KRAS, le gène oncogène le plus fréquent, avec l'idée à long terme d'un vaccin annuel qui préviendrait de nombreux cancers.",
  aeneas: "L'essai qui a montré que l'aumolertinib de Hansoh double environ la survie sans progression par rapport au gefitinib dans le cancer du poumon avec mutation d'EGFR.",
  agilent: "Agilent fabrique les tests diagnostiques compagnons Dako PD-L1 IHC 22C3 et 28-8 et la plateforme de coloration Omnis.",
  "ahn-myung-ju": "Myung-Ju Ahn est l'une des investigatrices d'essais sur le cancer du poumon les plus prolifiques d'Asie, une présence constante dans les comités de pilotage des essais sur EGFR, ALK et l'immunothérapie qui fixent les standards actuels.",
  "ai-oncology-roadmap": "L'intelligence artificielle en cancérologie a commencé comme un logiciel qui signalait des taches sur une mammographie. Elle conçoit désormais des molécules, lit les lames mieux que n'importe quel pathologiste seul pour certaines tâches, et commence à apparier les patients aux essais et à rédiger le compte rendu de la réunion de concertation pluridisciplinaire ; la question est de savoir ce qui, dans tout cela, sera prouvé utile.",
  aidoc: "Société d'IA en radiologie disposant de la première plateforme de triage à modèle de fondation autorisée par la FDA (CARE, janvier 2026) ; pertinente en oncologie pour les découvertes fortuites et le flux de travail.",
  "aiims-network": "L'Inde a multiplié ses instituts médicaux phares AIIMS, passant d'un à plus de vingt, chacun doté d'un service d'oncologie, pour apporter des soins spécialisés contre le cancer et une formation aux États qui n'en avaient pas.",
  "ajai-chari": "A dirigé l'essai pivot du talquetamab, établissant GPRC5D comme deuxième cible bispécifique dans le myélome.",
  "aktis-oncology": "Société de radiopharmaceutiques alpha à base de miniprotéines ; la première introduction en bourse biotech de 2026 (~365 M$) finance des programmes à l'Ac-225 contre Nectin-4 et B7-H3.",
  "alan-ashworth": "A co-découvert que les cancers déficients en BRCA meurent quand PARP est bloqué, l'idée à l'origine de toute une classe de médicaments.",
  "alan-dandrea": "A cartographié la voie de réparation de l'ADN de l'anémie de Fanconi/BRCA et la façon dont les tumeurs deviennent résistantes aux inhibiteurs de PARP.",
  aldesleukin: "L'interleukine-2 à haute dose a été la première immunothérapie à guérir une petite fraction des patients atteints de mélanome métastatique et de cancer du rein, au prix d'une toxicité de niveau réanimation ; aujourd'hui elle sert surtout de soutien à la thérapie par TIL.",
  "aleix-prat": "Oncologue translationnel qui a mis au point des tests génomiques (HER2DX) pour décider quelles patientes HER2-positives peuvent se passer de chimiothérapie.",
  "alentis-therapeutics": "Alentis Therapeutics cible Claudin-1, une protéine exposée sur les cancers épidermoïdes et les organes cicatriciels, avec des anticorps qui soit transportent un médicament tuant les cellules cancéreuses, soit bloquent la signalisation de la maladie. Son premier médicament anticancéreux est entré en essais chez l'humain en 2025.",
  "alex-herrera": "A dirigé l'essai SWOG S1826 qui a fait du nivolumab une composante du traitement de première ligne du lymphome de Hodgkin.",
  "alexander-drilon": "A dirigé les essais du larotrectinib, de l'entrectinib, du repotrectinib et du selpercatinib qui ont transformé des fusions génétiques rares en cibles traitables.",
  "alfa-0701": "ALFA-0701 est l'essai qui a sauvé le premier ADC : administrer le gemtuzumab en trois petites doses avec la chimiothérapie a amélioré la survie sans événement, sans la toxicité qui avait conduit à son retrait.",
  "alice-yu": "A dirigé l'essai prouvant qu'un anticorps anti-GD2 améliore la survie dans le neuroblastome à haut risque.",
  alina: "A montré que donner un comprimé anti-ALK après la chirurgie, au lieu d'une chimiothérapie, réduit fortement les récidives, y compris dans le cerveau.",
  "alkove-1": "L'étude d'enregistrement d'un comprimé anti-ALK de quatrième génération conçu pour agir après le lorlatinib et éviter les effets secondaires cérébraux.",
  allogene: "Leader du CAR-T allogénique : cema-cel (CD19) comme consolidation de première ligne guidée par la MRD dans le lymphome, et ALLO-316 (CD70) avec des réponses dans le cancer du rein.",
  "alpha-nanogenerators": "L'actinium-225 libère quatre particules alpha en se désintégrant, mais les noyaux fils s'échappent et irradient les reins et les glandes salivaires. Les nanovecteurs tentent de les maintenir en place.",
  "alpha-tau-medical": "Alpha Tau Medical place de minuscules grains radioactifs directement dans les tumeurs afin qu'un rayonnement alpha de courte portée détruise le cancer de l'intérieur. Elle teste cette approche dans les cancers du pancréas, de la peau, de la tête et du cou, du cerveau et de la prostate.",
  alphabreak: "Les essais de phase 3 qui décideront si les médicaments anti-PSMA émetteurs alpha deviennent la prochaine étape après Pluvicto.",
  alphafold3: "Prédit la forme 3D des protéines avec l'ADN, l'ARN, les petites molécules et les anticorps, le point de départ d'une grande partie de la conception moderne des médicaments.",
  alsympca: "ALSYMPCA est l'essai qui a obtenu l'approbation du premier médicament émetteur alpha.",
  "aminolevulinic-acid": "L'acide aminolévulinique est appliqué sur la peau abîmée par le soleil puis activé par une lampe, détruisant les kératoses actiniques avant qu'elles ne deviennent des cancers de la peau ; en Europe, le gel est aussi approuvé pour le carcinome basocellulaire superficiel.",
  "aml-signalling": "La carte de la LAM de KEGG montre les deux coups qui transforment une cellule souche sanguine normale en leucémie : un signal de croissance bloqué en position allumée (FLT3, KIT ou RAS) plus un interrupteur de maturation cassé (protéines de fusion comme PML-RARA ou AML1-ETO, ou CEBPA et RUNX1 mutés). Des médicaments existent désormais pour les deux moitiés.",
  "amphista-therapeutics": "Amphista Therapeutics, installée près de Cambridge au Royaume-Uni, conçoit de petites molécules qui font détruire des protéines précises par les cellules cancéreuses au moyen d'une enzyme d'élimination moins courante appelée DCAF16. Son premier médicament, contre la leucémie aiguë myéloïde, a été autorisé à entrer en essais chez l'humain en 2026.",
  "amunix-pharmaceuticals": "Amunix a développé des médicaments anticancéreux de type engageur de lymphocytes T et cytokine dotés d'un masque protecteur que des enzymes présentes dans les tumeurs viennent cliver, de sorte que les médicaments s'activent surtout au niveau du cancer. Sanofi a accepté d'acheter la société en décembre 2021 pour environ 1 milliard de dollars de paiement initial.",
  anaemia: "Un manque de globules rouges ou d'hémoglobine, provoquant fatigue et essoufflement. Dans le cancer, elle provient de la maladie elle-même (infiltration de la moelle, saignements, inflammation), de la suppression de la moelle par la chimiothérapie et de certains médicaments ciblés.",
  anbl0032: "L'essai qui a fait de l'immunothérapie anti-GD2 le standard pour les enfants atteints de neuroblastome à haut risque, améliorant la survie d'environ 20 points.",
  anbl0532: "COG ANBL0532 a montré que deux greffes consécutives font mieux qu'une seule dans le neuroblastome à haut risque.",
  "andrea-cercek": "A dirigé l'étude dans laquelle tous les patients atteints d'un cancer du rectum avec déficience de la réparation des mésappariements ont eu une réponse complète au dostarlimab, sans chirurgie ni radiothérapie.",
  "andrea-necchi": "A dirigé PURE-01, le premier essai de pembrolizumab néoadjuvant dans le cancer de la vessie, et dirige aujourd'hui des études d'immunothérapie de préservation vésicale.",
  "anitocabtagene-autoleucel": "L'anitocabtagene autoleucel est un CAR-T anti-BCMA doté d'un nouveau petit ligand synthétique qui a produit des réponses chez 97% de patients lourdement prétraités ; une décision de la FDA est attendue en décembre 2026.",
  "annals-of-oncology": "Annals of Oncology est la revue phare de l'ESMO, publiant les essais européens de phase 3, les recommandations de pratique clinique de l'ESMO et les recueils de résumés du Congrès de l'ESMO.",
  "annals-of-surgical-oncology": "Annals of Surgical Oncology est la principale revue de la Society of Surgical Oncology et le premier lieu de publication de la recherche en chirurgie oncologique, lue par les chirurgiens oncologues du monde entier.",
  "anthony-letai": "A inventé le profilage BH3, le test fonctionnel à l'origine du succès du venetoclax, avant de devenir directeur du NCI.",
  "anti-gd2-plus-chemo-relapse": "L'ajout de l'anticorps anti-GD2 à la chimiothérapie de rechute a doublé les taux de réponse dans le neuroblastome en rechute, et l'idée passe maintenant à l'induction de première ligne.",
  antineoplastons: "Les antinéoplastons sont des fractions peptidiques isolées à l'origine dans les urines et administrées dans une seule clinique privée du Texas depuis près de cinquante ans, surtout à des enfants atteints de tumeurs cérébrales. Malgré des dizaines d'essais enregistrés, aucun n'a été publié intégralement, aucun groupe indépendant n'a confirmé de bénéfice, et le traitement est coûteux et provoque de graves déséquilibres en sels.",
  "antoni-ribas": "Figure de proue de l'immunothérapie du mélanome, à l'origine des premiers essais du pembrolizumab et de la science expliquant pourquoi l'immunothérapie échoue.",
  "antonio-gonzalez-martin": "Oncologue médical spécialisé en gynécologie qui dirige le Cancer Center Clínica Universidad de Navarra ; il a mené l'essai PRIMA sur le niraparib en maintenance dans le cancer de l'ovaire.",
  anvisa: "L'autorité brésilienne du médicament, partenaire du Project Orbis et gardienne de l'approbation des médicaments anticancéreux sur le plus grand marché d'Amérique latine.",
  apalutamide: "Un bloqueur du récepteur des androgènes (AR) approuvé pour le cancer de la prostate qui s'est propagé et pour la maladie à haut risque avant qu'elle n'apparaisse à l'imagerie.",
  apheresis: "Faire passer le sang d'un patient dans une machine qui prélève un type de cellules (lymphocytes T ou cellules souches) et restitue le reste ; les cellules recueillies deviennent la matière première d'un CAR-T ou d'une greffe.",
  "apollo-hospitals": "Le plus grand groupe hospitalier privé d'Inde, qui a ouvert à Chennai en 2019 le premier centre de protonthérapie d'Asie du Sud et gère des centres de cancérologie dans tout le pays.",
  aprepitant: "L'aprépitant (Emend) a été le premier d'une nouvelle classe de médicaments antinauséeux. Pris avec un antagoniste 5-HT3 et de la dexaméthasone, il prévient les nausées et vomissements retardés qui suivent les chimiothérapies hautement émétisantes comme le cisplatine.",
  "apt-trial": "Pour les petites tumeurs HER2-positives, un schéma léger de paclitaxel hebdomadaire plus trastuzumab donne d'excellents taux de guérison, en évitant une chimiothérapie plus lourde.",
  "ar-v7": "Une forme tronquée du récepteur des androgènes qui est activée en permanence et ignore les comprimés bloquant les hormones.",
  arasens: "A démontré la « trithérapie » : l'ajout du darolutamide à l'hormonothérapie plus chimiothérapie réduit la mortalité d'un tiers.",
  "arizona-cancer-center": "Le centre de cancérologie intégré du NCI en Arizona, historiquement fort en chimioprévention du cancer de la peau et en science des populations du Sud-Ouest américain.",
  "arsenal-bio": "Société de CAR-T programmables utilisant des portes logiques pour que les cellules ne s'activent qu'en présence de deux protéines tumorales ; AB-2100 (PSMA + CA9) est en phase 1/2 dans le cancer du rein.",
  "arsenic-trioxide": "Un poison antique devenu remède : associé à l'acide rétinoïque, il guérit plus de 95 % des leucémies aiguës promyélocytaires sans chimiothérapie conventionnelle.",
  artbio: "ARTBIO développe des traitements anticancéreux qui délivrent un rayonnement alpha à courte portée issu du plomb-212 directement aux cellules tumorales, en commençant par le cancer de la prostate. Son premier médicament est en essais précoces chez l'homme, actuellement mis en pause par la société pendant qu'elle examine les données.",
  arx788: "ARX788 est un ADC anti-HER2 doté d'une charge non clivable positionnée avec précision, qui a battu lapatinib-capécitabine en Chine et a montré une activité sur les métastases cérébrales.",
  ascent: "L'essai qui a prouvé qu'un ADC anti-TROP2 pouvait presque doubler la survie dans le cancer du sein triple négatif lourdement prétraité.",
  "ascent-05": "Teste si l'administration d'un ADC anti-TROP2 après la chirurgie peut guérir davantage de patientes triple négatives dont le cancer a survécu à la chimio-immunothérapie préopératoire.",
  "asher-bio": "Asher Bio conçoit des molécules immunostimulantes qui n'activent qu'un seul type de cellule immunitaire, comme les lymphocytes T tueurs, de sorte que le médicament est plus puissant contre les tumeurs et provoque moins d'effets secondaires.",
  aspree: "Chez des personnes âgées en bonne santé, l'aspirine quotidienne à faible dose n'a pas prolongé la vie sans incapacité et, de façon inattendue, a été associée à davantage de décès par cancer. Elle a fait évoluer les recommandations contre l'aspirine systématique chez les personnes âgées.",
  "astrum-005": "Dans ASTRUM-005, un anticorps anti-PD-1 chinois a produit la plus longue survie en première ligne des essais de chimio-immunothérapie ; il est désormais approuvé en Europe et au Royaume-Uni, mais pas encore aux États-Unis.",
  "ataraxis-ai": "Ataraxis AI analyse par intelligence artificielle des lames numérisées de tumeurs du sein pour estimer la probabilité que le cancer récidive et si la chimiothérapie a des chances d'aider, en rendant les résultats en un jour sans consommer de tissu.",
  atirmociclib: "Un comprimé de nouvelle génération qui bloque uniquement CDK4, et non CDK6, pour conserver le bénéfice des médicaments actuels sans la baisse des numérations sanguines.",
  atomic: "L'ajout d'un an d'immunothérapie à la chimiothérapie après la chirurgie a réduit de moitié les récidives dans les cancers du côlon de stade III dont le correcteur orthographique de l'ADN est défaillant.",
  "auckland-city-hospital": "Le plus grand hôpital et service de cancérologie de Nouvelle-Zélande, qui travaille avec l'Auckland Cancer Society Research Centre de l'University of Auckland, où ont été développés des anticancéreux activés par l'hypoxie et ciblant l'ADN.",
  "auger-electron-therapy": "Des atomes radioactifs qui projettent des électrons à très courte portée, létaux seulement si l'atome se trouve sur ou dans l'ADN de la cellule.",
  aumolertinib: "L'aumolertinib est le comprimé de troisième génération de Hansoh contre le cancer du poumon, premier médicament de sa classe développé en Chine, approuvé en première ligne du cancer du poumon avec mutation d'EGFR sur la base de l'essai AENEAS.",
  aurigene: "La société de découverte en oncologie de Dr. Reddy's, avec plus de 20 programmes en développement clinique dans le monde via des partenaires et son propre portefeuille de petites molécules et de thérapies cellulaires.",
  "badwe-rajendra": "Un chirurgien-chercheur dont les essais randomisés à faible coût, de la lidocaïne péritumorale au moment de la chirurgie, ont remis en question des idées reçues dans le cancer du sein.",
  "bang-yung-jue": "Investigateur principal de ToGA, l'essai qui a fait du trastuzumab le standard dans le cancer gastrique HER2-positif, et fondateur de l'oncologie de phase 1 en Corée.",
  "barbara-eichhorst": "A dirigé CLL13 (GAIA), montrant qu'un traitement de durée fixe à base de venetoclax surpasse la chimio-immunothérapie chez les patients atteints de LLC en bonne condition.",
  "barretts-oesophagus": "Une modification de la muqueuse du bas de l'œsophage, causée par des années de reflux acide, dans laquelle des cellules de type gastrique remplacent les cellules normales. C'est le terreau d'où naissent la plupart des adénocarcinomes de l'œsophage en Occident, même si la plupart des personnes qui en sont atteintes ne développent jamais de cancer.",
  "barrios-carlos": "Carlos Barrios est la voix latino-américaine la plus visible dans les essais mondiaux sur le cancer du sein et un fondateur du groupe coopératif régional LACOG.",
  "basal-cell-carcinoma-signalling": "La carte KEGG du carcinome basocellulaire est la voie Hedgehog : la perte du frein PTCH1 ou l'activation de SMO laisse les facteurs de transcription GLI allumés en permanence. Les inhibiteurs de Hedgehog (vismodegib, sonidegib) l'éteignent dans la maladie avancée.",
  "bcma-then-gprc5d": "Quand un médicament anti-BCMA cesse d'agir, passer à un médicament dirigé contre une autre protéine du myélome produit encore des réponses chez environ deux tiers des patients.",
  bemarituzumab: "Le bemarituzumab est un anticorps dirigé contre FGFR2b, un récepteur de croissance surproduit dans environ un tiers des cancers de l'estomac. Il a amélioré la survie au début de son essai de phase 3, mais le gain s'est estompé avec un suivi plus long.",
  bempegaldesleukin: "Le bempegaldesleukin était une interleukine-2 remaniée censée être une version plus sûre d'une célèbre immunothérapie ancienne. Il n'a rien apporté au nivolumab dans trois essais de phase 3.",
  "benjamin-besse": "Benjamin Besse est un investigateur d'essais dans le cancer du poumon, au cœur des programmes pulmonaires du Dato-DXd et du HER3-DXd.",
  "benjamin-ebert": "A découvert comment agit le lénalidomide, lançant le domaine des dégradeurs de type colle moléculaire, et a défini l'hématopoïèse clonale avant de diriger le Dana-Farber.",
  bicalutamide: "L'ancien comprimé antiandrogène utilisé pour bloquer la poussée de testostérone provoquée par les agonistes de la GnRH et dans le blocage androgénique combiné ; supplanté par les médicaments de la classe de l'enzalutamide.",
  "bicycle-therapeutics": "Inventeur des conjugués peptide bicyclique-médicament ; son conjugué anti-Nectin-4 de tête a été déprioritisé en 2026 après un retour des autorités réglementaires.",
  "bighat-biosciences": "BigHat utilise l'apprentissage automatique et un laboratoire automatisé rapide pour concevoir des anticorps. Son premier médicament anticancéreux, un anticorps transportant une charge de chimiothérapie vers les tumeurs de l'estomac et de l'intestin, est entré en essais chez l'homme en 2026.",
  "biliary-stent": "Mettre en place un petit tube en treillis ou en plastique pour maintenir ouvert un canal ou un conduit qu'une tumeur comprime, soulageant la jaunisse, les difficultés à avaler ou l'essoufflement.",
  "bill-gates": "La Gates Foundation a engagé 4,1 milliards de dollars pour Gavi, l'alliance pour les vaccins qu'elle a aidé à fonder en 2000, dont le programme HPV avait complètement vacciné près de 60 millions de filles contre le cancer du col de l'utérus fin 2024.",
  "bimatoprost-eyelash-regrowth": "Les cils et les sourcils tombent souvent avec la chimiothérapie et peuvent être lents à repousser. Le bimatoprost, un collyre contre le glaucome approuvé pour les cils clairsemés, appliqué chaque soir le long de la ligne des cils, a augmenté la longueur et l'épaisseur des cils dans un essai randomisé incluant des personnes après chimiothérapie.",
  "bispecific-infection-prophylaxis": "Les bispécifiques et les CAR-T du myélome suppriment la production d'anticorps si profondément que les infections, et non le cancer, sont devenues une cause majeure de décès dans les premiers essais.",
  "bl-b01d1-307": "La première victoire de phase 3 d'un ADC bispécifique, dans le cancer du sein triple négatif, annoncée en février 2026.",
  "black-diamond-therapeutics": "Black Diamond Therapeutics conçoit des comprimés anticancéreux qui frappent d'un coup des familles entières de mutations d'une protéine de croissance. Son médicament de tête, le silevertinib, cible l'EGFR muté dans le cancer du poumon et les tumeurs cérébrales.",
  "bladder-cancer-signalling": "La carte KEGG du cancer de la vessie montre deux voies : des tumeurs papillaires de bas grade portées par FGFR3 ou HRAS activant la cascade MAPK, et des tumeurs invasives de haut grade qui perdent TP53 et RB1. L'erdafitinib cible la première voie ; les conjugués anticorps-médicament et les anticorps anti-PD-1 sont aujourd'hui le socle du traitement de la seconde.",
  blasts: "Des cellules sanguines immatures qui devraient mûrir dans la moelle mais qui, dans la leucémie aiguë, se multiplient sans jamais mûrir. Le pourcentage de blastes dans la moelle définit la maladie : 20 % ou plus, c'est une leucémie aiguë.",
  "blinatumomab-frontline-consolidation": "Intercaler une immunothérapie entre les cycles de chimiothérapie standard améliore la survie des adultes et des enfants atteints de LAL nouvellement diagnostiquée.",
  "ca19-9": "Une molécule de sucre libérée dans le sang par la plupart des cancers du pancréas ; utile pour suivre le traitement, pas pour le dépistage.",
  "capmatinib-tepotinib": "Le capmatinib et le tépotinib sont deux comprimés destinés aux environ 3 % de cancers du poumon porteurs d'une mutation de saut de l'exon 14 de MET.",
  cd123: "Un récepteur d'interleukine surabondant sur un cancer du sang rare et agressif ainsi que sur les cellules souches leucémiques.",
  cd33: "CD33 est un marqueur myéloïde et la cible du tout premier ADC jamais approuvé, en 2000.",
  cd70: "CD70 est une protéine normalement présente uniquement sur les cellules immunitaires activées, mais activée en permanence dans le cancer du rein et certaines leucémies.",
  cdh6: "CDH6 est une protéine d'adhésion issue du développement du rein qui réapparaît sur les cancers de l'ovaire et du rein.",
  ceacam5: "Le marqueur tumoral classique « CEA » mesuré dans le sang, également présent à la surface des cellules où les ADC peuvent l'atteindre.",
  dar: "Le rapport médicament/anticorps (DAR) est le nombre de molécules de charge utile portées par chaque anticorps, généralement de 2 à 8.",
  "david-cameron": "David Cameron est un oncologue spécialisé dans le cancer du sein qui préside le Breast International Group.",
  "david-koch": "Traité pour un cancer de la prostate à partir de 1992, il a donné 100 millions de dollars au MIT en 2007 pour construire un institut réunissant sous un même toit ingénieurs et biologistes du cancer, et 150 millions de dollars au MSK en 2015 pour un nouveau bâtiment de cancérologie ambulatoire.",
  "david-porter": "Il a traité les premiers patients adultes atteints de LLC par CAR-T et a rapporté une décennie de rémissions durables.",
  "dawna-1": "L'essai qui a fait du dalpiciclib le premier inhibiteur de CDK4/6 chinois approuvé, en faisant plus que doubler le temps avant la progression du cancer du sein lorsqu'il est ajouté au fulvestrant.",
  "day-one-biopharmaceuticals": "Société d'oncologie à vocation d'abord pédiatrique, dont le tovorafenib est devenu la première thérapie ciblée du gliome de bas grade de l'enfant.",
  dcis: "Cellules de cancer du sein confinées à l'intérieur des canaux galactophores, découvertes surtout par mammographie sous forme de calcifications. Il n'est pas mortel en lui-même, mais environ un tiers évoluerait vers un cancer invasif s'il était laissé en place.",
  "dcruz-anil": "Il a dirigé l'essai du Tata Memorial qui a tranché une question vieille de plusieurs décennies, en montrant que l'ablation des ganglions lymphatiques du cou lors de la première opération d'un cancer buccal précoce sauve des vies.",
  "dcvax-l": "Un vaccin personnalisé fabriqué à partir des propres cellules immunitaires et de la tumeur du patient. Son essai de phase 3 vieux de 20 ans a rapporté une survie plus longue, mais la manière dont le résultat a été analysé a divisé le domaine.",
  "deauville-score": "Un score de 1 à 5 mesurant la brillance d'un lymphome au TEP par rapport au foie ; 1-3 est considéré comme une réponse métabolique complète.",
  "deb-schrag": "Elle a dirigé PATHFINDER, la première étude prospective d'un test sanguin multi-cancers en pratique, et l'essai PROSPECT sur le cancer du rectum.",
  debiopharm: "Debiopharm est la société privée suisse qui développe l'inhibiteur de WEE1 zedoresertib (Debio 0123) et des recherches sur les ADC à double charge.",
  deciphera: "Société spécialisée dans le contrôle des commutateurs de kinases, à l'origine du ripretinib pour les GIST et du vimseltinib pour la tumeur ténosynoviale à cellules géantes ; rachetée par Ono Pharmaceutical en 2024.",
  decitabine: "La décitabine (Dacogen) est une perfusion qui desserre l'extinction chimique des gènes dans les syndromes myélodysplasiques et la leucémie myéloïde aiguë, aidant la moelle osseuse à fonctionner de nouveau. Une version orale associée à la cédazuridine possède sa propre fiche.",
  "declan-murphy": "Urologue qui a codirigé proPSMA, l'essai ayant montré que le TEP au PSMA doit remplacer le scanner et la scintigraphie osseuse pour la stadification du cancer de la prostate.",
  "delfi-diagnostics": "Société de fragmentomique dont le test sanguin FirstLook Lung vise à accroître la participation au dépistage du cancer du poumon ; premières données randomisées d'utilité clinique en 2026.",
  "destiny-breast05": "Enhertu a réduit de plus de moitié la récidive ou le décès par rapport à Kadcyla chez les femmes présentant un cancer résiduel après le traitement préopératoire, remplaçant le standard KATHERINE.",
  "destiny-breast12": "Enhertu a fait régresser les métastases cérébrales chez la majorité des patientes, y compris celles présentant des lésions non traitées, répondant à une question que ses essais antérieurs avaient exclue.",
  "devices-roadmap": "Les dispositifs traitent le cancer par la physique plutôt que par la chimie : chaleur, froid, lumière, champs électriques et sons. Après des décennies en marge, plusieurs disposent désormais de preuves randomisées et d'approbations, et la prochaine génération vise à amorcer le système immunitaire tout en détruisant la tumeur.",
  dexrazoxane: "Le dexrazoxane protège le cœur des dommages cumulatifs de la doxorubicine chez les femmes atteintes d'un cancer du sein métastatique qui doivent continuer à la recevoir et, sous le nom de Totect, limite la destruction des tissus lorsqu'une anthracycline s'échappe d'une veine.",
  "diagnostics-roadmap": "Le diagnostic du cancer est passé de l'aspect d'une tumeur au microscope à ce qui la pilote, puis désormais à sa lecture dans un échantillon de sang. La prochaine étape consiste en des tests qui disent au médecin quoi faire, et non seulement ce qui est présent.",
  divarasib: "Le divarasib est le comprimé anti-KRAS G12C de Roche, le premier à battre les deux médicaments anti-KRAS approuvés en comparaison directe (juillet 2026).",
  "dose-dense-chemotherapy": "Deux façons opposées de reprogrammer les mêmes médicaments : la dose dense administre des doses standard plus souvent (toutes les deux semaines au lieu de trois, avec le soutien de facteurs de croissance) pour priver la tumeur de temps de récupération ; la métronomique administre de petites doses en continu pour attaquer les vaisseaux sanguins de la tumeur avec peu de toxicité.",
  "dose-escalation-design": "Comment un essai de phase 1 passe d'une dose initiale infime à une dose utile : l'ancien schéma 3+3 traite trois patients à la fois et monte si aucun ne présente de toxicité grave ; les schémas statistiques plus récents (BOIN, CRM) utilisent toutes les données pour choisir les doses avec plus de précision, avec moins de patients à des niveaux inefficaces.",
  "doublet-triplet": "Raccourci désignant le nombre de médicaments actifs combinés : un doublet en compte deux, un triplet trois, un quadruplet quatre. Plus de médicaments signifie généralement plus de réponses et plus d'effets secondaires, et les essais vérifient si le médicament supplémentaire mérite sa place.",
  "douglas-lowy": "Il a codéveloppé la technologie du vaccin contre le HPV qui élimine le cancer du col de l'utérus dans les populations vaccinées.",
  "doxorubicin-cardio-caution": "Chaque dose de doxorubicine s'ajoute à un total cumulé sur la vie ; au-dessus d'environ 450 mg/m2, le risque d'insuffisance cardiaque augmente fortement, de sorte que les protocoles pour sarcomes et lymphomes sont plafonnés et le cœur est surveillé.",
  "drug-discovery-roadmap": "Trouver le prochain médicament anticancéreux consistait autrefois à tester des composés sur des souris et des lignées cellulaires en espérant. Cela consiste désormais à cartographier les gènes dont chaque cancer ne peut se passer, à cultiver la tumeur d'un patient en boîte et à concevoir des molécules par ordinateur ; le défi est de faire en sorte que ces outils prédisent ce qui se passe chez l'humain.",
  "drugbank-chembl": "DrugBank et ChEMBL rassemblent la chimie et le mécanisme de chaque médicament et de la plupart des composés outils.",
  "dual-her2-blockade": "Utiliser deux anticorps anti-HER2 (trastuzumab et pertuzumab) en même temps, ce qui fonctionne mieux qu'un seul.",
  "dung-le": "Première auteure des études ayant montré que les tumeurs déficientes en réparation des mésappariements répondent au blocage de PD-1 quelle que soit leur origine.",
  eacr: "La société professionnelle européenne des chercheurs en cancérologie, qui organise l'EACR Congress et publie la revue en libre accès Molecular Oncology.",
  "ef-14": "L'essai qui a intégré un dispositif portable à champs électriques dans la prise en charge du glioblastome, prolongeant la survie médiane d'environ cinq mois.",
  "egfr-exon20-insertion": "Une mutation d'EGFR plus rare (~2 % des cancers du poumon) qui ne répond pas aux comprimés anti-EGFR standard et nécessite ses propres médicaments.",
  "elective-neck-dissection-tmh": "Un essai du Tata Memorial a mis fin à un débat de 50 ans en montrant que l'ablation des ganglions lymphatiques du cou lors de la première opération d'un cancer de la bouche précoce fait passer la survie à trois ans d'environ deux tiers à quatre cinquièmes.",
  "elena-elez": "Elena Élez est une chercheuse en cancer colorectal qui a dirigé le programme clinique de l'essai BREAKWATER.",
  elironrasib: "Un médicament anti-KRAS G12C de nouvelle génération qui frappe la forme active de la protéine, issu de la même société que le daraxonrasib.",
  embark: "A montré que traiter par enzalutamide un PSA en hausse rapide après chirurgie ou radiothérapie retarde la dissémination.",
  "emerald-1": "Le premier essai à montrer que l'ajout d'une immunothérapie et d'un anti-VEGF à la TACE retarde la progression du cancer du foie de stade intermédiaire.",
  "emerald-3": "En 2026, un schéma de double immunothérapie plus lenvatinib ajouté à la TACE a réduit le risque de progression d'environ 30 % ; on ne sait pas encore s'il prolonge la vie.",
  "emergence-therapeutics": "Emergence Therapeutics était une start-up allemande fabriquant un anticorps qui transporte un médicament anticancéreux vers une protéine appelée Nectin-4, présente sur la plupart des cancers de la vessie. Eli Lilly a racheté la société en 2023.",
  "emily-bergsland": "Spécialiste des tumeurs neuroendocrines qui participe à la conception des essais fixant le traitement de ces cancers rares.",
  "endocrine-related-cancer": "Endocrine-Related Cancer est la revue de cancérologie de la Society for Endocrinology, couvrant les tumeurs endocrines et les cancers hormonodépendants tels que ceux du sein, de la prostate, de la thyroïde et les tumeurs neuroendocrines. Elle est lue par les endocrinologues et les biologistes du cancer.",
  "endometrial-cancer-signalling": "La carte du cancer de l'endomètre de KEGG montre des tumeurs de type I liées aux œstrogènes, avec perte de PTEN, mutations de KRAS et de la bêta-caténine et réparation des mésappariements défaillante, et des tumeurs de type II avec mutation de TP53 et amplification de HER2. L'immunothérapie des tumeurs déficientes en réparation des mésappariements et la thérapie dirigée contre HER2 découlent directement de cette division.",
  endopredict: "Un test de 12 gènes qui combine l'activité génique avec la taille de la tumeur et les ganglions lymphatiques pour dire si l'hormonothérapie seule suffit, et s'il faut la poursuivre au-delà de cinq ans.",
  "enlaza-therapeutics": "Enlaza Therapeutics conçoit des médicaments protéiques qui se verrouillent définitivement sur leur cible une fois qu'ils l'ont trouvée, ce qui pourrait permettre aux médicaments anticancéreux à base d'anticorps d'agir à des doses plus faibles avec moins d'effets secondaires. Ses programmes sont encore en développement au laboratoire.",
  "enliven-therapeutics": "Enliven Therapeutics conçoit des versions plus propres de comprimés anticancéreux qui fonctionnent déjà. Son médicament phare cible la protéine BCR-ABL dans la leucémie myéloïde chronique et un second médicament cible HER2 muté dans le cancer du poumon.",
  envafolimab: "L'envafolimab est le premier anticorps anti-PD-L1 administré par une injection rapide sous la peau plutôt qu'en perfusion, approuvé en Chine pour les tumeurs avancées présentant une déficience de la réparation des mésappariements.",
  enzyme: "Une protéine qui accélère une réaction chimique précise. De nombreuses cibles médicamenteuses sont des enzymes, car bloquer l'enzyme arrête la réaction.",
  epacadostat: "Un bloqueur d'enzyme censé empêcher les tumeurs de priver les lymphocytes T de tryptophane. Son échec en phase 3 en 2018 a mis fin à toute une classe du jour au lendemain.",
  "epcore-nhl-1": "EPCORE NHL-1 a été l'étude pivot à bras unique à l'origine de l'approbation de l'epcoritamab ; environ la moitié des répondeurs complets sont encore en rémission à trois ans.",
  "epigenetics-roadmap": "Les médicaments épigénétiques modifient la façon dont les gènes sont lus plutôt que les gènes eux-mêmes. Ils ont débuté comme une chimiothérapie douce pour les cancers du sang et deviennent des médicaments précis contre les enzymes et les échafaudages dont dépendent certains cancers.",
  "epithelioid-vs-sarcomatoid": "Le mésothéliome existe sous une forme « épithélioïde » plus lente et une forme « sarcomatoïde » agressive. La chimiothérapie fonctionne mieux dans la première ; l'immunothérapie aide surtout dans la seconde.",
  epitope: "La petite zone exacte d'un antigène qu'un anticorps ou un lymphocyte T saisit réellement, comme l'endroit précis d'une poignée de porte que la main attrape. Deux anticorps peuvent se lier à la même protéine sur des épitopes différents.",
  eprenetapopt: "L'eprenetapopt (APR-246) était un médicament censé replier le p53 mutant, la protéine défectueuse la plus fréquente dans le cancer. Sa phase 3 dans les cancers du sang a échoué en 2020.",
  erasca: "Erasca développe des comprimés qui éteignent la voie de signalisation RAS, l'un des moteurs les plus fréquents du cancer. Ses deux médicaments phares visent à bloquer toutes les formes de RAS ou de KRAS plutôt qu'une seule mutation.",
  eribulin: "Une chimiothérapie dérivée d'une éponge marine qui a prolongé la survie dans le cancer du sein lourdement prétraité et dans le liposarcome, où presque rien d'autre n'y était parvenu.",
  "escort-1st": "ESCORT-1st est l'essai chinois d'immunothérapie de première ligne dans le cancer épidermoïde de l'œsophage, l'un des cinq essais qui, ensemble, ont fait de la chimio-immunothérapie le standard mondial.",
  esm3: "ESM3 est un modèle génératif de protéines qui a conçu une protéine fluorescente fonctionnelle très éloignée de toute séquence naturelle.",
  "ev-303": "Chez les patients ne pouvant pas recevoir de cisplatine, l'association ADC-immunothérapie encadrant la chirurgie a réduit le risque de récidive ou de décès de 60% et le risque de décès de moitié.",
  evaxion: "Evaxion utilise l'intelligence artificielle pour concevoir des vaccins contre le cancer et les infections. Son principal vaccin anticancéreux est personnalisé selon la tumeur de chaque patient atteint de mélanome, et un vaccin plus récent, prêt à l'emploi, cible le cancer du cerveau.",
  "everett-vokes": "Figure de proue du cancer de la tête et du cou qui a établi la chimioradiothérapie avec préservation d'organe et a dirigé l'ASCO en 2021-22.",
  "evergreen-theragnostics": "Evergreen Theragnostics fabrique des médicaments anticancéreux radioactifs pour d'autres entreprises et développe son propre agent d'imagerie pour les tumeurs neuroendocrines ainsi qu'un traitement du cancer du poumon à petites cellules. Lantheus a accepté de la racheter en 2025.",
  "exai-bio": "Exai Bio développe des tests sanguins qui recherchent de petits fragments d'ARN produits uniquement par les tumeurs, plutôt que de l'ADN tumoral, et utilise l'intelligence artificielle pour détecter le cancer précocement à partir d'une prise de sang de routine.",
  "exosome-therapeutics": "Charger d'un médicament anticancéreux les minuscules vésicules que les cellules utilisent naturellement pour communiquer entre elles, afin que l'organisme traite le transporteur comme lui appartenant.",
  "extravasation-infusion-reaction": "Réactions survenant autour du moment de l'administration d'un médicament : frissons, fièvre ou essoufflement dus aux anticorps (réactions à la perfusion), véritable allergie (hypersensibilité, rarement anaphylaxie) et fuite d'un médicament toxique dans les tissus autour de la veine (extravasation).",
  extreme: "Le protocole qui a défini le traitement de première ligne du cancer avancé de la tête et du cou de 2008 jusqu'à son remplacement par l'immunothérapie.",
  "fabrice-andre": "Généticien du cancer du sein qui a dirigé SOLAR-1 et les essais de médecine de précision SAFIR ; président de l'ESMO 2025-2026.",
  "fang-wenfeng": "Wenfeng Fang est un oncologue spécialiste du cancer du poumon au cœur des essais chinois sur les anti-PD-1 et les anticorps bispécifiques, dont l'ivonescimab dans la maladie mutée EGFR.",
  "fate-therapeutics": "Fate Therapeutics développe des cellules CAR-T et CAR-NK prêtes à l'emploi dérivées d'iPSC (FT819, FT522) pour le cancer et les maladies auto-immunes.",
  "fda-ldt-rule": "La plupart des tests oncologiques aux États-Unis, dont Galleri, Signatera et Oncotype DX, sont des « tests développés en laboratoire » encadrés par des normes de laboratoire plutôt que par une approbation de la FDA ; la tentative de la FDA de changer cela en 2024 a été invalidée par la justice en 2025.",
  "federated-learning-medical-ai": "Entraîner des modèles d'IA dans de nombreux hôpitaux sans déplacer les données des patients, de sorte que le modèle apprend de tous tandis que les données restent sur place.",
  fedratinib: "Un deuxième inhibiteur de JAK pour la myélofibrose, efficace après l'échec du ruxolitinib ; il porte un avertissement encadré pour une toxicité cérébrale rare (encéphalopathie de Wernicke), d'où la surveillance de la thiamine.",
  "fertility-sparing-endometrial": "Chez les jeunes femmes atteintes des cancers de l'endomètre les plus précoces et de bas grade, des comprimés de progestatif ou un DIU hormonal peuvent éliminer le cancer et permettre une grossesse avant une hystérectomie ultérieure.",
  "ficerafusp-alfa": "Le ficerafusp alfa est un anticorps anti-EGFR fusionné à une « éponge » à TGF-bêta, conçu pour supprimer le signal immunosuppresseur qui maintient froids les cancers de la gorge HPV-négatifs.",
  filgrastim: "Le filgrastim (Neupogen et ses biosimilaires) est une injection quotidienne qui accélère la récupération des globules blancs anti-infectieux après la chimiothérapie, permet aux médecins d'administrer la chimiothérapie dans les délais prévus et mobilise les cellules souches en vue d'une greffe.",
  "financial-navigation": "Le traitement du cancer peut ruiner les patients même assurés. Les programmes de navigation financière dépistent les difficultés d'argent et orientent les patients vers des aides, une optimisation de l'assurance et un soutien juridique, et les essais montrent qu'ils réduisent la détresse et l'endettement.",
  "firefly-bio": "Firefly Bio fixe des molécules destructrices de protéines à des anticorps afin qu'elles ne soient délivrées qu'à l'intérieur des cellules cancéreuses, une nouvelle variante des anticorps conjugués. Johnson & Johnson a racheté l'entreprise pour environ 1 milliard de dollars en 2026.",
  "flatiron-health": "Dossier médical électronique oncologique (OncoEMR) et plus grande base de données oncologiques en vie réelle curées, racheté par Roche pour 1,9 milliard de dollars en 2018.",
  flotufolastat: "Le flotufolastat est un troisième traceur TEP du PSMA, avec une chimie radiohybride conçue pour être réutilisée en thérapie.",
  "fludeoxyglucose-f18": "Le sucre radioactif utilisé dans presque tous les TEP-scans en cancérologie, approuvé dans les années 1990 et produit frais chaque jour par des cyclotrons régionaux.",
  "foghorn-therapeutics": "Foghorn Therapeutics fabrique des médicaments agissant sur la machinerie qui compacte l'ADN et contrôle quels gènes sont activés. Son médicament phare, en partenariat avec Lilly, cible les cancers du poumon ayant perdu un gène appelé SMARCA4.",
  "fondation-arc": "La plus grande fondation caritative de France entièrement consacrée à la recherche sur le cancer, finançant des projets de laboratoire et cliniques dans tout le pays.",
  "fortitude-101": "Une nouvelle cible, FGFR2b, a montré un gain de survie à la première analyse qui s'est réduit avec un suivi plus long, et l'essai n'incluait pas l'immunothérapie que les patients reçoivent désormais en routine.",
  "fourlight-1": "Dans FOURLIGHT-1, un inhibiteur sélectif de CDK4, conçu pour éviter les baisses de numération sanguine des médicaments anti-CDK4/6 actuels, a amélioré la survie sans progression en deuxième ligne.",
  "fox-chase": "Le centre anticancéreux indépendant de Philadelphie, où ont été découverts le chromosome de Philadelphie, l'hypothèse des deux coups et l'hépatite B.",
  "francois-clement-bidard": "A dirigé PADA-1, le premier essai à changer d'hormonothérapie sur la base d'une mutation ESR1 en hausse dans le sang.",
  "frank-mccormick": "Biologiste de RAS qui a fondé Onyx Pharmaceuticals et dirigé l'effort national du NCI pour cibler RAS par des médicaments.",
  "frederick-locke": "A dirigé l'essai ZUMA-7, qui a placé les CAR-T devant la greffe dans le lymphome B à grandes cellules en rechute.",
  freenome: "Freenome fabrique SimpleScreen CRC, le deuxième test sanguin approuvé par la FDA pour le dépistage du cancer colorectal (juillet 2026), commercialisé par Abbott.",
  "fresco-2": "Un comprimé sélectif ciblant le récepteur du VEGF a apporté un gain de survie modeste mais réel chez des patients n'ayant plus aucun traitement standard disponible.",
  "frontier-medicines": "Société de chimioprotéomique avec le FMC-376, un inhibiteur de KRAS G12C qui frappe à la fois les états ON et OFF de la protéine, en phase 1/2.",
  "frozen-gloves-compression-taxane": "Porter des gants et des chaussettes réfrigérés, ou des gants chirurgicaux serrés, pendant les perfusions de taxanes réduit les lésions des ongles et peut réduire les engourdissements des mains et des pieds, en rétrécissant les vaisseaux sanguins au moment où le médicament est à son pic. Les essais sont petits mais concordants, et c'est peu coûteux.",
  "full-approval": "La forme ordinaire d'approbation d'un médicament, accordée lorsqu'un essai a démontré un bénéfice clinique réel, comme une survie plus longue, par opposition à l'approbation accélérée accordée sur un critère de substitution précoce et toujours en attente de confirmation.",
  furmonertinib: "Le furmonertinib est un comprimé chinois contre le cancer du poumon de la même classe que l'osimertinib, qui a plus que doublé le délai avant progression du cancer par rapport au gefitinib dans l'essai FURLONG.",
  "ga68-psma-11": "Le gallium-68 PSMA-11 a été le premier traceur TEP du PSMA approuvé aux États-Unis (2020), et il est produit sur place à partir d'un générateur ou d'un cyclotron.",
  gastrectomy: "Ablation d'une partie (subtotale) ou de la totalité (totale) de l'estomac pour un cancer de l'estomac, l'intestin étant raccordé à ce qui reste.",
  "gastric-cancer-signalling": "Cette carte KEGG divise le cancer de l'estomac en deux voies : le type intestinal, qui accumule pas à pas des altérations de TP53, APC et HER2, et le type diffus, porté par la perte de la « colle » cellulaire E-cadhérine plus une amplification de MET ou de FGFR2. C'est important car le statut HER2, FGFR2, claudine 18.2 et PD-1 décide désormais du traitement de première ligne.",
  "gastric-endoscopic-screening": "En Corée et au Japon, où le cancer de l'estomac est fréquent, les adultes passent un examen de l'estomac par caméra tous les deux ans, de sorte que la plupart des cancers sont détectés assez tôt pour être retirés par l'endoscope.",
  gej: "L'endroit où l'œsophage rejoint l'estomac. Les cancers de cette zone sont classés selon la distance à laquelle ils se centrent au-dessus ou en dessous de la jonction (Siewert I-III), ce qui décide s'ils sont traités comme un cancer de l'œsophage ou de l'estomac.",
  geneformer: "Le premier transformer largement utilisé entraîné sur des millions de cellules uniques, capable de prédire quels gènes comptent dans une maladie.",
  "generic-drug-shortage-response": "Maintenir la disponibilité de médicaments de chimiothérapie essentiels et peu coûteux comme le cisplatine ; les pénuries de 2023 ont contraint les hôpitaux américains au rationnement.",
  "genomic-assay-to-chemo-omission": "Un test génétique sur la tumeur décide qui peut se passer de chimiothérapie sans perdre en protection.",
  "germline-to-parp": "Un test sanguin de mutations BRCA héréditaires donne accès à un an d'olaparib après la chirurgie, ce qui améliore la survie.",
  "ghayas-issa": "Premier auteur de l'essai sur le revumenib qui a créé la classe des inhibiteurs de la ménine pour la leucémie aiguë.",
  "gilda-radner": "La star du Saturday Night Live a raconté son cancer de l'ovaire dans It's Always Something et est morte à 42 ans en 1989. Son nom perdure dans Gilda's Club et dans le registre des cancers de l'ovaire familiaux de Roswell Park.",
  "giovanni-scambia": "Giovanni Scambia est un oncologue gynécologue qui dirige la recherche à l'hôpital Gemelli.",
  gleason: "Le système de gradation du cancer de la prostate : le pathologiste note les deux modes de croissance les plus fréquents de 3 à 5 et les additionne (6 à 10), aujourd'hui simplifié en groupes de grade 1 à 5. Le groupe de grade 1 (Gleason 6) est si indolent que beaucoup soutiennent qu'il ne devrait pas être appelé cancer.",
  "gleason-grade-group": "Le grade de 1 à 5 attribué par le pathologiste selon l'aspect anormal du cancer de la prostate, qui guide la plupart des décisions thérapeutiques.",
  "glioma-signalling": "Cette carte KEGG montre les deux voies génétiques menant au glioblastome : les tumeurs primaires amplifient EGFR et perdent PTEN et p16 ; les tumeurs secondaires, issues d'astrocytomes de plus bas grade, surexpriment PDGF et CDK4 et perdent TP53 et RB. Elle explique pourquoi les médicaments ciblant les facteurs de croissance et le cycle cellulaire sont les principales options ciblées dans les tumeurs cérébrales, et pourquoi les gliomes pédiatriques de bas grade porteurs d'altérations de BRAF répondent aux inhibiteurs de MAPK.",
  gpc3: "Le glypican-3 est une protéine du foie fœtal qui réapparaît dans le cancer du foie, offrant une cible nette aux CAR-T et aux anticorps bispécifiques.",
  grpr: "GRPR est un récepteur hormonal abondant dans le cancer de la prostate précoce et hormonosensible, imagé et traité avec des radioligands de type bombésine.",
  "idea-acc-metronomic-lmic-platform-trial": "De petites doses fréquentes de vieux comprimés de chimiothérapie bon marché ont montré un bénéfice surprenant dans certains cancers. Un seul grand réseau d'essais en Inde et en Afrique pourrait déterminer où cela fonctionne et où cela ne fonctionne pas.",
  "idea-acc-nurse-led-chemotherapy-units": "Des infirmières formées suivant des protocoles écrits stricts peuvent gérer en toute sécurité des cliniques de chimiothérapie pour les cancers courants, avec un oncologue disponible par vidéo pour les décisions et les problèmes.",
  "idea-acc-one-stop-breast-diagnostic-clinic": "Une femme présentant une masse au sein devrait être examinée, passer une imagerie et subir une biopsie le même jour, et connaître le résultat en quelques jours, plutôt que de venir quatre fois en deux mois.",
  "idea-acc-open-hardware-linac": "Concevoir de zéro un appareil de radiothérapie pour les hôpitaux confrontés à une électricité irrégulière, à la chaleur et au manque d'ingénieurs, et publier les plans pour que plusieurs entreprises puissent le fabriquer à bas coût.",
  "idea-acc-pooled-procurement-radiotherapy": "Les pays qui achètent les appareils de radiothérapie un par un paient des prix élevés et reçoivent un service médiocre. Un acheteur mondial unique négociant des dizaines d'appareils par an pourrait faire baisser les prix et exiger un soutien à long terme.",
  "idea-acc-prehabilitation-older-surgery": "Quelques semaines d'exercice, de nutrition et de préparation mentale avant une opération lourde aident les patients âgés à récupérer plus vite et avec moins de complications. Cela coûte peu et devrait être systématique.",
  "idea-acc-reflex-biomarker-panels-by-tumour": "Pour chaque type de cancer, convenir de l'ensemble des colorations et des tests toujours nécessaires, et faire en sorte que le laboratoire les réalise automatiquement au diagnostic plutôt que d'attendre que quelqu'un les demande.",
  "idea-acc-reflex-genomic-profiling-at-diagnosis": "De nombreux patients atteints d'un cancer avancé du poumon ou de l'intestin commencent leur traitement sans les tests génétiques qui montreraient si un médicament ciblé fonctionnerait. Laissons le pathologiste prescrire le test complet dès que le cancer est confirmé, sans attendre un oncologue.",
  "idea-acc-registries-as-aid-condition": "On ne peut pas corriger ce que l'on ne peut pas compter. Tout programme de lutte contre le cancer financé par des donateurs devrait financer et exiger un registre du cancer en population afin que les résultats puissent être mesurés dans le temps.",
  "idea-acc-remote-planning-hubs": "Les hôpitaux manquant de physiciens pourraient téléverser les images vers un centre de planification partagé, où l'IA rédige le plan de traitement et où des experts à distance le finalisent et le vérifient en une journée.",
  "idea-acc-risk-stratified-cardio-oncology-pathway": "Certaines chimiothérapies et certains anticorps endommagent le cœur. Vérifier la fonction cardiaque avant et pendant le traitement et commencer tôt des médicaments protecteurs chez les personnes à risque pourrait prévenir une grande partie de ces dommages.",
  "idea-acc-risk-stratified-follow-up": "Tous les survivants n'ont pas besoin de voir un oncologue tous les six mois pendant des années. Trier les personnes selon le risque de récidive, renvoyer les survivants à faible risque vers leur médecin de famille avec un plan clair, et garantir un retour rapide si quelque chose change.",
  "idea-adjuvant-selection-rcc": "L'immunothérapie adjuvante aide quelques patients et en expose beaucoup à des effets néfastes. Des tests identifiant ces quelques patients rendraient le compromis bien meilleur.",
  "idea-alpha-first-mhspc": "Si Pluvicto aide dès le premier diagnostic, une version alpha pourrait faire davantage contre la maladie microscopique, lorsque la charge tumorale est la plus faible.",
  "idea-bio1-adaptive-therapy-platform": "Plutôt que de frapper une tumeur avec la dose maximale jusqu'à ce qu'elle cesse d'agir, ajuster la dose pour garder la tumeur petite et laisser les cellules sensibles au médicament supprimer les cellules résistantes. Tester cela correctement dans plusieurs cancers.",
  "idea-bio1-cin-vulnerability-kif18a": "Les tumeurs très instables survivent à des erreurs chromosomiques constantes en s'appuyant sur une protéine motrice. La bloquer tue les cellules cancéreuses instables tout en épargnant les cellules normales.",
  "idea-bio1-clonal-neoantigen-vaccines": "Les vaccins anticancéreux personnalisés ciblent de nombreuses mutations, dont certaines ne sont présentes que dans une partie de la tumeur. Ne viser que les mutations partagées par toutes les cellules devrait empêcher la tumeur de s'échapper en les perdant.",
  "idea-bio1-co-clinical-avatar-trials": "Plutôt que de tester d'abord un médicament sur des modèles de laboratoire en espérant que les résultats se transposent, construire les mêmes modèles à partir des participants à l'essai et mener les deux expériences en parallèle pour voir dans quelle mesure les modèles prédisent bien.",
  "idea-bio1-ctdna-adaptive-tki": "Utiliser l'ADN tumoral dans le sang comme signal pour suspendre et reprendre un comprimé contre le cancer du poumon, en gardant la tumeur sous contrôle tout en ralentissant la montée des cellules résistantes.",
  "idea-bio1-ctdna-clone-report": "Les tests sanguins peuvent déjà détecter l'ADN tumoral. Indiquer quelles sous-populations de la tumeur grandissent ou régressent, cycle après cycle, transformerait le test en moniteur d'évolution.",
  "idea-bio1-drug-holiday-resensitisation": "Les cellules cancéreuses résistantes en viennent parfois à dépendre du médicament même auquel elles ont résisté. Arrêter le médicament pendant un temps peut les rendre à nouveau vulnérables.",
  "idea-bio1-evolution-forecasting": "Les vaccins contre la grippe sont choisis en prédisant quelles souches virales domineront la saison suivante. Les mêmes mathématiques prévisionnelles pourraient prédire quelle mutation de résistance la tumeur d'un patient développera ensuite.",
  "idea-bio1-evolutionary-double-bind": "Choisir deux traitements de sorte que, quoi que fasse la tumeur pour échapper au premier, elle devienne plus facile à tuer avec le second. Le système immunitaire est un bon partenaire candidat.",
  "idea-bio1-fusion-tf-degraders": "Certains sarcomes de l'enfant sont causés par deux gènes fusionnés en une protéine anormale. Cette protéine est toute la maladie, mais aucun médicament ne s'y lie. La détruire plutôt que la bloquer pourrait fonctionner.",
  "idea-bio1-glue-degrader-atlas": "Certains médicaments agissent en collant deux protéines ensemble pour que l'une détruise l'autre. On les découvre généralement par hasard. Une grande recherche systématique, publiée ouvertement, en trouverait beaucoup d'autres.",
  "idea-bio1-in-silico-trials-dose": "Simuler des milliers de patients virtuels sur ordinateur peut suggérer quelle dose et quel schéma tester, afin que moins de patients réels reçoivent des doses trop fortes ou trop faibles.",
  "idea-bio1-model-patient-matching": "Les laboratoires utilisent généralement les modèles tumoraux dont ils disposent déjà. Un index consultable qui trouve le modèle le plus proche de la tumeur d'un patient donné rendrait les expériences plus pertinentes.",
  "idea-bio1-molecular-progression-add-on": "Lorsqu'une mutation de résistance apparaît pour la première fois dans le sang, le médicament en cours contrôle souvent encore la majeure partie de la tumeur. Ajouter un second médicament plutôt que de changer peut garder les deux sous contrôle.",
  "idea-bio1-multi-organ-chip-tox": "Les dommages aux poumons, au cœur ou au foie sont une cause fréquente d'échec des médicaments anticancéreux. Des puces de tissu humain connectées pourraient les repérer plus tôt que les tests sur animaux.",
  "idea-bio1-multiregion-blocks-default": "Les hôpitaux conservent généralement un seul fragment d'une tumeur retirée. En conserver trois provenant de différentes zones montrerait à quel point la tumeur est hétérogène, pour un coût supplémentaire quasi nul.",
  "idea-bio1-organoid-assay-clinical-validation": "Des mini-tumeurs cultivées en laboratoire sont déjà vendues pour guider le traitement, mais ces tests ne sont pas validés comme les autres tests médicaux. Ils devraient l'être.",
  "idea-bio1-organoid-immune-coculture": "Les mini-tumeurs cultivées en laboratoire ne contiennent généralement que des cellules cancéreuses. Y ajouter les propres cellules immunitaires du patient permet aux chercheurs de tester l'immunothérapie hors du corps.",
  "idea-bio1-outlier-lesion-biopsy": "Lorsqu'un examen montre que la plupart des tumeurs régressent mais qu'une seule grossit, cette lésion atypique renferme le mécanisme d'échappement. La prélever, et la traiter localement, devrait être systématique.",
  "idea-bio1-paralog-synthetic-lethality": "Les tumeurs perdent souvent l'un des deux gènes d'une paire presque identique. Elles dépendent alors entièrement de la copie restante, qu'un médicament peut bloquer, ne tuant que le cancer.",
  "idea-bio1-rare-cancer-organoid-bank": "Pour de nombreux cancers rares, il n'existe pas un seul modèle de laboratoire au monde, si bien que personne ne peut tester de médicaments. Une banque partagée à distribution gratuite changerait cela.",
  "idea-bio1-resistance-mutation-vaccine": "La résistance survient souvent sous la forme des mêmes quelques mutations. Apprendre au système immunitaire à les reconnaître à l'avance pourrait éliminer les cellules qui s'échappent alors qu'elles sont encore rares.",
  "idea-bio1-resistance-platform-trial": "Plutôt qu'un nouvel essai pour chaque mécanisme de résistance, un seul essai continu pourrait répartir les patients dans des bras selon la raison de l'échec de leur dernier traitement.",
  "idea-bio1-slfn11-payload-guidance": "Une seule protéine prédit si une tumeur répondra aux charges médicamenteuses qui endommagent l'ADN. La mesurer pourrait éviter aux patients de recevoir un second médicament du même type qui ne fonctionnera pas.",
  "idea-bio1-truncal-branch-labelling": "Un médicament visant une mutation présente dans toutes les cellules tumorales agit différemment d'un médicament visant une mutation présente dans certaines cellules seulement. Les comptes rendus des tests devraient préciser de laquelle il s'agit.",
  "idea-bio1-tumour-on-chip-penetration": "Les grosses molécules comme les anticorps conjugués doivent traverser les parois des vaisseaux et cheminer dans un tissu dense. Une puce avec des canaux à flux et du tissu humain peut mesurer jusqu'où elles parviennent.",
  "idea-bio1-undruggable-market-commitment": "Les gouvernements ont promis à l'avance d'acheter des vaccins qui n'existaient pas encore, et ils ont été fabriqués. La même promesse pourrait être faite pour un médicament contre une cible que tout le monde a abandonnée.",
  "idea-bio1-virtual-cell-perturbation": "Entraîner un modèle sur des millions d'expériences où gènes et médicaments ont été modifiés, afin qu'il puisse prédire l'effet d'une nouvelle combinaison sans réaliser l'expérience.",
  "idea-bio1-wrn-msi-programme": "Les cancers dont la relecture de l'ADN est défaillante dépendent d'une enzyme de déroulement particulière pour survivre. La bloquer les tue et épargne les cellules normales.",
  "idea-bio2-ai-sarcopenia-from-ct": "Chaque examen de bilan d'extension contient une mesure précise de la masse musculaire que personne ne regarde. Un logiciel pourrait la rapporter automatiquement et signaler les patients qui se dirigent vers la cachexie.",
  "idea-bio2-anamorelin-access": "Un médicament qui améliore l'appétit et la masse maigre dans la cachexie cancéreuse est approuvé au Japon mais presque nulle part ailleurs. Réexaminer les données existantes pourrait élargir rapidement l'accès.",
  "idea-bio2-antibiotic-stewardship-io": "Les antibiotiques administrés dans les semaines précédant l'immunothérapie sont associés à des résultats bien pires. Une règle simple de bon usage pourrait préserver le bénéfice sans aucun coût.",
  "idea-bio2-cachexia-function-endpoint": "Les régulateurs ne savent pas quoi accepter comme preuve qu'un médicament contre la cachexie est utile. S'accorder sur une mesure simple comme la montée d'escaliers débloquerait tout le domaine.",
  "idea-bio2-circadian-mrd-sampling": "Les cellules cancéreuses passent dans le sang surtout pendant le repos, si bien qu'une prise de sang matinale peut les manquer. Prélever et administrer les doses à la bonne heure pourrait être une amélioration gratuite.",
  "idea-bio2-cns-cohort-mandate": "Une personne sur cinq atteinte d'un cancer avancé a des métastases cérébrales, pourtant la plupart des essais les refusent. Exiger des cohortes cérébrales donnerait à ces patients des preuves au lieu de suppositions.",
  "idea-bio2-complement-c5ar-blockade": "Une partie ancienne du système immunitaire appelée complément peut être détournée par les tumeurs pour recruter des cellules protectrices. Des médicaments qui la bloquent existent déjà pour d'autres maladies.",
  "idea-fund-duration-trial-exclusivity": "Les entreprises perdent de l'argent lorsqu'elles prouvent qu'un traitement plus court fonctionne, donc elles ne le testent jamais. Il faut leur accorder une récompense modeste, comme des mois d'exclusivité supplémentaires, lorsqu'elles le font.",
  "idea-fund-federated-learning-consortium": "Les hôpitaux pourraient entraîner des modèles d'IA partagés sur les imageries et les dossiers de tous leurs patients sans qu'aucune donnée ne quitte le bâtiment, et détenir conjointement les résultats, si quelqu'un construisait et gouvernait le réseau.",
  "idea-fund-head-to-head-mandate": "Dès que deux médicaments d'un même type existent, un troisième devrait avoir à faire ses preuves face au meilleur d'entre eux, et non face à une comparaison dépassée, afin que les patients et les payeurs sachent lequel est réellement meilleur.",
  "idea-fund-intraoperative-imaging-trials": "Les outils qui montrent aux chirurgiens où s'arrête la tumeur pendant l'opération pourraient réduire le nombre de patients ayant besoin d'une seconde opération, mais aucun n'a été correctement testé à grande échelle. Un réseau mènerait ces essais et paierait selon les résultats.",
  "idea-fund-mcbs-linked-pricing": "Payer davantage pour les médicaments qui aident clairement les gens à vivre plus longtemps ou mieux, et moins pour ceux qui ne changent presque rien, en utilisant une échelle publique de bénéfice que les médecins utilisent déjà.",
  "idea-fund-milestone-venture-philanthropy": "Les associations de lutte contre le cancer financeraient des entreprises pour atteindre des jalons de développement précis, comme l'a fait l'association de la mucoviscidose pour créer Kalydeco, et percevraient une redevance qu'elles réinvestiraient dans le médicament suivant.",
  "idea-fund-national-drug-development-office": "Le gouvernement américain gère déjà un petit programme qui transforme les découvertes universitaires sur le cancer en médicaments prêts pour les essais chez l'humain. Il faut le multiplier par dix et le copier dans d'autres pays.",
  "idea-fund-organoid-translation-gate": "Avant qu'un composé universitaire ne reçoive de l'argent pour des études précliniques, il devrait montrer une activité dans un panel standard de modèles tumoraux dérivés de patients géré par un centre indépendant, afin que les candidats faibles soient arrêtés tôt.",
  "idea-fund-paediatric-deferral-escrow": "Les entreprises retardent souvent les études sur les cancers de l'enfant qu'elles sont tenues de mener. Une part des revenus du médicament pour adultes serait retenue jusqu'à l'achèvement de l'essai pédiatrique.",
  "idea-fund-public-option-generic-oncology": "Les médicaments de chimiothérapie essentiels et bon marché comme le cisplatine sont régulièrement en rupture parce que leur fabrication rapporte peu. Un fabricant à but non lucratif soutenu par les pouvoirs publics garantirait l'approvisionnement à un prix équitable.",
  "idea-fund-shared-personalised-therapy-gmp": "Les vaccins personnalisés contre le cancer et les thérapies cellulaires nécessitent une usine pour chaque patient. Des unités de production partagées et automatisées au service de nombreux hôpitaux universitaires permettraient aux universités de mener ces essais sans construire leurs propres installations.",
  "idea-fund-social-impact-bonds-prevention": "Des investisseurs financeraient d'avance des campagnes de vaccination et de dépistage et seraient remboursés par les systèmes de santé uniquement si les campagnes atteignaient des objectifs vérifiés, transformant des économies futures en argent pour la prévention dès maintenant.",
  "idea-fund-surgical-ai-robotics-evaluation": "Les hôpitaux achètent des robots chirurgicaux et des outils d'IA à plusieurs millions de dollars avec peu de preuves qu'ils aident les patients. Un organisme indépendant mènerait les essais comparatifs, et les payeurs ne paieraient un supplément que pour ce qui a démontré son efficacité.",
  "idea-fund-surgical-outcomes-public-reporting": "L'endroit où vous subissez votre opération du cancer influence fortement vos chances d'y survivre. Publier les résultats ajustés de chaque hôpital orienterait la chirurgie complexe vers les centres qui la pratiquent bien.",
  "idea-fund-survivorship-endowment-levy": "Des dizaines de millions de personnes vivent après un cancer avec des lésions cardiaques, une infertilité et des seconds cancers. Un prélèvement minime sur le prix des traitements curatifs constituerait un fonds permanent pour étudier et traiter les effets tardifs.",
  "idea-fund-target-validation-consortium": "Les entreprises et les financeurs publics paieraient conjointement des expériences standardisées qui confirment ou réfutent de nouvelles cibles contre le cancer, en partageant tous les résultats ouvertement, afin que personne ne perde des années sur une cible qui ne tient pas.",
  "idea-fund-technique-innovation-prize": "Personne ne peut breveter une meilleure façon d'opérer ou un schéma de radiothérapie plus court, donc personne n'est récompensé pour en faire la preuve. Des prix pour les améliorations de technique dont l'efficacité est démontrée dans des essais combleraient ce vide.",
  "idea-fund-trial-biospecimen-commons": "Les échantillons de sang et de tissu prélevés lors des essais sur le cancer sont le meilleur matériel pour valider de nouveaux tests, mais la plupart restent inutilisés sous des contrats qui rendent l'accès impossible. Un fonds commun les rendrait disponibles pour la recherche approuvée.",
  "idea-fund-trial-completion-bonus": "Les centres d'essai sont payés par patient recruté, donc personne n'est payé pour terminer l'étude ou en rapporter la réponse. Il faut déplacer une partie du paiement vers l'achèvement et la publication dans un délai d'un an.",
  "idea-fus-plus-adc-glioma": "Les tumeurs cérébrales ont des cibles que les ADC pourraient atteindre, mais les anticorps ne peuvent pas franchir la barrière. Il faut d'abord ouvrir la barrière par ultrasons.",
  "idea-gd2-car-t-frontline-consolidation": "Administrer des lymphocytes T modifiés contre GD2 aux enfants en rémission après le traitement standard, là où les données à long terme montrent les guérisons les plus profondes et les plus durables.",
  "idea-her2-adc-sequencing-payload": "Lorsque Enhertu cesse d'agir, l'ADC suivant devrait probablement porter un autre type de charge, comme les inhibiteurs de la tubuline de Kadcyla ou d'ARX788, plutôt qu'un autre médicament ciblant la topoisomérase.",
  "idea-late-recurrence-interception": "La moitié des récidives des cancers hormonodépendants surviennent après la cinquième année. Des analyses de sang pendant le suivi à long terme pourraient les détecter tôt et un SERD oral pourrait les arrêter.",
  "idea-mesothelin-car-t-regional": "Administrer des lymphocytes T modifiés directement dans la cavité thoracique où se développe le mésothéliome, et donner une immunothérapie pour les maintenir actifs.",
  "idea-metabolic-vulnerability-mapping": "Les médicaments métaboliques échouent sans cesse parce que les tumeurs changent de carburant. Mesurer ce que la tumeur d'un patient consomme réellement, avec des traceurs et l'imagerie PET, pourrait permettre de choisir le bon médicament métabolique pour la bonne tumeur.",
  "idea-microbiome-io-fmt": "Des transplantations de selles provenant de répondeurs à l'immunothérapie ont sauvé certains non-répondeurs atteints de mélanome. Si des cocktails bactériens définis fonctionnent aussi bien, chaque patient sous immunothérapie pourrait en recevoir un.",
  "idea-molecular-class-adjuvant-endometrial": "Donner le traitement adjuvant selon la classe moléculaire de la tumeur plutôt que selon le stade et le grade : rien pour les tumeurs mutées POLE, immunothérapie pour les MMRd, chimiothérapie plus agents ciblés pour les p53 anormales, hormonothérapie pour les NSMP.",
  "idea-moon-automated-combination-discovery": "Il existe bien plus de combinaisons de médicaments possibles qu'on ne pourra jamais en essayer chez des patients. Il faut en tester des milliers sur des échantillons vivants de vraies tumeurs, puis ne faire entrer que les gagnantes dans des essais adaptatifs.",
  "idea-moon-brain-delivery-platform": "La plupart des médicaments contre le cancer ne peuvent pas passer dans le cerveau. Combiner des ultrasons qui ouvrent brièvement la barrière avec des médicaments conçus pour être transportés à travers elle, et en faire une plateforme standard pour chaque tumeur cérébrale et chaque métastase cérébrale.",
  "idea-moon-cachexia-as-treatable-disease": "La cachexie qui tue de nombreux patients atteints de cancer n'a jamais eu de médicament efficace. De nouveaux anticorps contre GDF-15 ont restauré le poids dans des essais précoces. Il faut les combiner à l'exercice et à la nutrition et les tester correctement.",
  "idea-moon-cardioprotection-by-default": "Les anthracyclines, les médicaments anti-HER2 et certains agents plus récents peuvent endommager le cœur. Il faut surveiller par analyses de sang et imagerie et commencer tôt des médicaments cardioprotecteurs bon marché chez les personnes à risque.",
  "idea-moon-dormancy-eradication-programme": "De nombreuses rechutes proviennent de cellules cancéreuses restées cachées et dormantes pendant des années. Il faut trouver des médicaments qui soit les forcent à se réveiller pour que la chimiothérapie les tue, soit les maintiennent endormies à vie.",
  "idea-moon-eliminate-infection-cancers": "Environ un cancer sur huit est causé par une infection que nous pouvons prévenir par un vaccin, guérir ou éradiquer. Un programme mondial concerté pourrait rendre ces cancers rares en une génération.",
  "idea-moon-engineered-immune-surveillance": "Chez les personnes à très haut risque de cancer, installer une petite population de cellules immunitaires modifiées qui vivent pendant des années et détruisent les cellules présentant des signaux précoces de cancer avant qu'une tumeur ne se forme.",
  "idea-moon-hearing-protection-cisplatin": "Le cisplatine provoque une perte auditive permanente. Un médicament bon marché, le thiosulfate de sodium, protège les enfants ; il faut le tester et le déployer aussi chez les adultes.",
  "idea-moon-image-guided-surgery-everywhere": "Les chirurgiens ne voient souvent pas où s'arrête une tumeur. Des colorants fluorescents et une imagerie interprétée par l'IA au bloc opératoire peuvent le leur montrer, réduisant les réinterventions. Il faut en faire une pratique de routine partout.",
  "idea-moon-lynch-vaccine-phase3": "Les personnes atteintes du syndrome de Lynch ont un risque de cancer très élevé au cours de leur vie, dû à un ensemble prévisible de mutations. Il faut les vacciner contre ces mutations communes avant l'apparition du cancer.",
  "idea-moon-neuropathy-prevention-programme": "Les lésions nerveuses dues aux taxanes et aux platines sont fréquentes, souvent permanentes et n'ont aucun traitement préventif approuvé. Il faut tester les candidats les plus prometteurs face à face dans un seul programme.",
  "idea-moon-open-cancer-cell-state-model": "Cartographier chaque état dans lequel une cellule cancéreuse peut se trouver, et la manière dont les médicaments et le tissu environnant la font passer d'un état à l'autre, dans un modèle informatique ouvert que chacun peut interroger et améliorer.",
  "idea-moon-open-degrader-consortium": "Les moteurs les plus importants du cancer, comme MYC et p53 mutée, ne peuvent pas être bloqués par des médicaments classiques. Il faut mutualiser les efforts et partager les résultats ouvertement pour construire des molécules qui les détruisent à la place.",
  "idea-moon-population-germline-screening": "La plupart des personnes porteuses d'un gène de cancer à haut risque l'ignorent jusqu'à ce qu'un membre de la famille ait un cancer. Il faut proposer le test à tous les adultes afin que les porteurs puissent être protégés avant que cela n'arrive.",
  "idea-moon-rare-cancer-global-network": "Les cancers rares sont collectivement fréquents, mais chacun est trop rare pour des essais classiques. Il faut relier chaque patient atteint d'un cancer rare dans le monde au sein d'un seul réseau, avec des registres et des plans d'essai conçus pour de petits effectifs.",
  "idea-moon-self-driving-cancer-labs": "Des laboratoires robotisés guidés par l'IA qui conçoivent des expériences sur des modèles tumoraux, les réalisent, lisent les résultats et conçoivent les suivantes, en continu, chaque résultat étant publié ouvertement.",
  "idea-moon-universal-sequencing-learning-system": "Séquencer chaque cancer au diagnostic, ainsi que les gènes hérités du patient, et regrouper les résultats avec les traitements et les issues afin que chaque patient apprenne au système comment traiter le suivant.",
  "idea-mrd-guided-stop-cll": "Au lieu de 12 ou 15 mois fixes, arrêter le traitement de chaque patient lorsque son sang ne montre plus de leucémie détectable, et le reprendre si elle revient.",
  "idea-mrd-guided-stop-myeloma": "Si un patient n'a eu aucun myélome détectable depuis un an ou plus, arrêter le traitement d'entretien et surveiller, en ne le reprenant que si la maladie réapparaît.",
  "idea-neoadjuvant-adc-io": "Remplacer la partie la plus dure de la chimiothérapie préopératoire par un ADC plus une immunothérapie, en visant le même taux de guérison avec moins de dommages.",
  "idea-neoantigen-immunogenicity-rules": "Les vaccins peuvent désormais coder des dizaines de mutations d'une tumeur, mais seule une minorité provoque des lymphocytes T utiles. En apprendre les règles rendrait les vaccins plus petits, moins chers et plus puissants.",
  "idea-nerve-tumour-blockade": "Les nerfs alimentent les tumeurs du pancréas, de la prostate et d'autres organes. Les bêtabloquants et la toxine botulique sont bon marché, sûrs et déjà en essais pour voir si couper ce lien ralentit le cancer.",
  "idea-non-endoscopic-barretts-screening": "Une éponge avalée au bout d'un fil peut prélever un échantillon de l'œsophage au cabinet du médecin généraliste. Il faut dépister les personnes souffrant de reflux chronique pour détecter l'adénocarcinome à un stade curable.",
  iniparib: "Présenté comme le premier inhibiteur de PARP pour le cancer du sein triple négatif, il a échoué en phase 3 en 2011. Il s'est avéré qu'il n'inhibait pas du tout PARP.",
  "ion-trial": "L'essai britannique confirmant que les patients atteints d'un cancer de la thyroïde à faible risque peuvent éviter en toute sécurité l'iode radioactif, publié en 2025.",
  iovance: "Iovance fabrique Amtagvi, la première thérapie TIL approuvée.",
  "iowa-holden": "Le seul centre désigné par le NCI de l'Iowa, siège du SPORE national sur les tumeurs neuroendocrines et de la recherche sur l'ascorbate pharmacologique.",
  "irish-cancer-society": "L'association caritative nationale irlandaise contre le cancer, qui finance la recherche et Cancer Trials Ireland et propose des soins infirmiers de nuit, des lignes d'écoute et des Daffodil Centres dans les hôpitaux.",
  isatuximab: "L'isatuximab est l'anticorps anti-CD38 de Sanofi, approuvé dans le myélome de première ligne non éligible à la greffe (IMROZ) et, à partir de juillet 2026, sous forme d'injection sous-cutanée.",
  "isono-health": "iSono Health fabrique un échographe portable (wearable) qui image automatiquement l'ensemble du sein en environ deux minutes, avec un logiciel signalant les masses suspectes, destiné à un usage en dehors des centres d'imagerie spécialisés.",
  itm: "ITM est le plus grand fournisseur de lutétium-177 sans entraîneur ajouté et le développeur d'ITM-11 (177Lu-édotréotide).",
  "iu-simon": "Berceau du protocole au cisplatine de Lawrence Einhorn qui a fait du cancer du testicule une maladie curable, et centre intégré du NCI de l'Indiana.",
  "jackson-laboratory": "L'institut de génétique de la souris qui fournit au monde entier ses souches de souris de laboratoire et ses modèles PDX ; centre de recherche fondamentale sur le cancer du NCI depuis 1983.",
  "james-larkin": "Investigateur en mélanome et cancer du rein qui a codirigé CheckMate 067, l'essai disposant de données de survie à 10 ans sous immunothérapie.",
  "jan-van-lanschot": "Chirurgien qui a dirigé l'essai CROSS, qui a fait de la chimioradiothérapie avant la chirurgie le standard pour le cancer de l'œsophage.",
  "janux-therapeutics": "Janux fabrique des anticorps engageurs de cellules T « masqués » qui restent inactifs dans la circulation sanguine et ne s'activent qu'à l'intérieur des tumeurs, dans le but de réduire les effets secondaires qui limitent cette classe de médicaments. Ses programmes principaux ciblent PSMA dans le cancer de la prostate avancé.",
  "jason-luke": "A dirigé KEYNOTE-716, qui a étendu le pembrolizumab adjuvant au mélanome de stade II à haut risque.",
  "jason-westin": "A dirigé l'analyse de survie globale de ZUMA-7 qui a fait des CAR-T le traitement standard de deuxième ligne du lymphome en rechute précoce.",
  "javelin-hn-100": "L'ajout d'un bloqueur de PD-L1 à la chimioradiothérapie curative n'a pas apporté de bénéfice, le premier de plusieurs échecs de ce type dans les cancers de la tête et du cou.",
  "jean-yves-blay": "Expert des sarcomes qui dirige le Centre Léon Bérard et le réseau français des centres de lutte contre le cancer UNICANCER.",
  "jedd-wolchok": "A dirigé CheckMate 067, l'essai dont les données à dix ans ont montré que la moitié des patients atteints de mélanome avancé traités par nivolumab plus ipilimumab sont en vie.",
  "jefferson-kimmel": "Le centre de cancérologie désigné par le NCI de la Thomas Jefferson University, connu pour la biologie du cancer de la prostate et l'immunothérapie ciblant GUCY2C dans le cancer colorectal.",
  "jennifer-brown": "A dirigé ALPINE, le premier essai comparatif direct dans lequel un inhibiteur de BTK de nouvelle génération (zanubrutinib) a surpassé l'ibrutinib.",
  "jennifer-litton": "Jennifer Litton a dirigé l'essai EMBRACA qui a apporté le talazoparib au cancer du sein avec mutation BRCA.",
  "jian-zhou": "Virologue chinois dont le savoir-faire dans l'expression des protéines virales a permis de produire les premières pseudo-particules virales de HPV en 1991. Il est mort en 1999 à 42 ans, sept ans avant que le vaccin n'atteigne le public.",
  "jiangsu-hengrui": "Jiangsu Hengrui est le plus grand laboratoire pharmaceutique innovant de Chine, fabricant de l'anticorps anti-PD-1 camrelizumab et détenteur d'un large portefeuille d'ADC.",
  "john-heymach": "Figure de proue du cancer du poumon, à l'origine d'essais qui ont changé le traitement de la maladie avec mutation d'EGFR et de stade III.",
  "jonathan-ledermann": "A dirigé Study 19, l'essai qui a montré pour la première fois que l'entretien par inhibiteur de PARP fonctionne dans le cancer de l'ovaire.",
  "jonathan-strosberg": "A dirigé NETTER-1, l'essai qui a fait du lutétium dotatate la première radiothérapie par ligand approuvée pour les tumeurs neuroendocrines.",
  "josep-tabernero": "Investigateur en cancer colorectal qui a dirigé BEACON et BREAKWATER, apportant la thérapie ciblée à la maladie avec mutation BRAF ; ancien président de l'ESMO.",
  "journal-of-gastrointestinal-cancer": "Une revue clinique consacrée aux cancers du tube digestif : œsophage, estomac, foie, vésicule biliaire, pancréas, intestin et rectum. Lue par les oncologues digestifs, les chirurgiens et les gastro-entérologues.",
  "journal-of-gynecologic-oncology": "Une revue asiatique en libre accès sur les cancers du col de l'utérus, de l'utérus, des ovaires, de la vulve et du vagin, dirigée par l'Asian Society of Gynecologic Oncology avec ses sociétés partenaires coréenne et japonaise. Lue par les oncologues gynécologiques et les chirurgiens, en particulier en Asie.",
  "journal-of-neuro-oncology": "Une revue à fort volume sur les tumeurs du cerveau et de la moelle épinière, de la biologie des gliomes à la chirurgie, la radiothérapie et les essais de médicaments. Lue par les neuro-oncologues, les neurochirurgiens et les chercheurs sur les tumeurs cérébrales.",
  "judah-folkman": "En 1971, il a proposé que les tumeurs ne peuvent pas dépasser quelques millimètres sans recruter des vaisseaux sanguins, et que les bloquer pourrait traiter le cancer. Rejetée pendant des décennies, l'idée a donné naissance au bevacizumab et à une classe de médicaments.",
  "julie-brahmer": "A dirigé CheckMate 017, le premier essai à montrer que l'immunothérapie surpasse la chimiothérapie dans le cancer du poumon.",
  "julie-park": "Julie Park a dirigé l'essai du COG qui a fait de la greffe en tandem le standard pour le neuroblastome à haut risque.",
  "k36-therapeutics": "K36 Therapeutics fabrique des comprimés qui bloquent une enzyme appelée NSD2 (également connue sous le nom de MMSET), suractive dans environ un cas de myélome multiple sur cinq en raison d'un échange chromosomique. Elle teste aussi cette approche dans le cancer de la prostate.",
  "kapoor-akhil": "Premier auteur de METRO PLUS, l'essai de Varanasi qui a doublé la survie dans le cancer avancé de la tête et du cou en ajoutant des médicaments métronomiques oraux peu coûteux à la chimiothérapie standard.",
  "karim-fizazi": "A dirigé LATITUDE et PEACE-1, qui ont introduit l'abiratérone dans le cancer de la prostate métastatique de première ligne.",
  karmanos: "Le centre intégré de cancérologie du NCI de Detroit, où la lignée cellulaire de cancer du sein MCF-7 a été dérivée en 1973, aujourd'hui rattaché à McLaren Health Care.",
  "kathy-albain": "Oncologue spécialiste du sein et du poumon qui a dirigé les essais montrant que les tests génétiques peuvent guider les décisions de chimiothérapie.",
  "kelonia-therapeutics": "Kelonia a mis au point un moyen de créer des cellules CAR T directement dans l'organisme à l'aide d'une particule ciblée de transfert de gènes, de sorte que les patients n'ont pas besoin que leurs cellules soient prélevées et fabriquées. Son programme principal concerne le myélome multiple et Eli Lilly a accepté de racheter la société en 2026 pour un montant pouvant atteindre 7 milliards de dollars.",
  "ken-kato": "Oncologue japonais qui a dirigé ATTRACTION-3 et KEYNOTE-590, apportant l'immunothérapie au cancer de l'œsophage.",
  "kenneth-kinzler": "A codécouvert APC, le gène gardien du cancer colorectal, et a codirigé les premiers séquençages de génomes cancéreux.",
  "kernal-biologics": "Kernal Bio conçoit des médicaments à mRNA qui ne s'activent que dans le type cellulaire visé, par exemple pour programmer les cellules T d'un patient contre le cancer à l'intérieur de l'organisme sans les prélever au préalable.",
  "kevan-shokat": "Le chimiste dont le laboratoire a trouvé la poche cachée de KRAS G12C qui a rendu ciblable la cible réputée « inciblable ».",
  "keynote-355": "A établi l'immunothérapie plus chimiothérapie comme traitement de première ligne du cancer du sein triple négatif métastatique exprimant PD-L1.",
  "keynote-483": "A montré que l'ajout d'un bloqueur de PD-1 à la chimiothérapie standard est bénéfique dans le mésothéliome, offrant une deuxième option de première ligne fondée sur l'immunothérapie.",
  "keynote-564": "Le premier médicament à prolonger la vie des patients atteints d'un cancer du rein après la chirurgie, et la première immunothérapie adjuvante dans une tumeur solide, quelle qu'elle soit, à montrer un gain de survie globale.",
  "keynote-590": "A ajouté l'immunothérapie à la chimiothérapie de première ligne pour tous les types de cancer de l'œsophage, avec un bénéfice de survie maintenu à cinq ans.",
  "keynote-671": "A montré que l'immunothérapie administrée avant et après la chirurgie du cancer du poumon prolonge la survie.",
  "keynote-716": "A étendu l'immunothérapie adjuvante aux mélanomes épais sans atteinte ganglionnaire, un groupe dont le risque de rechute rivalise avec celui du stade III.",
  "keynote-775": "Un comprimé qui bloque les vaisseaux sanguins de la tumeur plus une immunothérapie a prolongé la survie après chimiothérapie, y compris dans les tumeurs sur lesquelles l'immunothérapie seule n'a aucun effet.",
  "keynote-966": "Un deuxième essai d'immunothérapie a confirmé le bénéfice de survie modeste de l'ajout d'un blocage de PD-1 à la chimiothérapie dans le cancer des voies biliaires.",
  "kheiron-medical-technologies": "Kheiron a créé Mia, un système d'intelligence artificielle qui lit les mammographies de dépistage afin qu'un radiologue plus le logiciel égalent la qualité de deux lecteurs humains. L'unité DeepHealth de RadNet a racheté l'entreprise londonienne en 2024.",
  "kidwai-memorial-institute-of-oncology": "L'institut public du cancer de l'État du Karnataka, l'un des centres régionaux du cancer de l'Inde, qui traite à faible coût un très grand nombre de patients du sud de l'Inde.",
  "kim-sung-bae": "Sung-Bae Kim est un oncologue du sein coréen de premier plan, membre des comités de pilotage des essais sur le trastuzumab emtansine et le deruxtecan.",
  "kim-tae-won": "Tae Won Kim est le principal investigateur d'essais en cancer colorectal de Corée, investigateur des études sur le fruquintinib, la trifluridine/tipiracil et les anti-EGFR utilisées dans le monde entier.",
  "kirsten-fischer": "A dirigé CLL14, qui a établi un an de venetoclax plus obinutuzumab comme traitement de la LLC à durée fixe et sans chimiothérapie.",
  "klaus-pantel": "Klaus Pantel est un pionnier de la recherche sur les cellules tumorales circulantes et du domaine de la biopsie liquide.",
  klk2: "Un parent du PSA qui reste attaché aux cellules du cancer de la prostate, utilisé par J&J comme adresse pour un engageur de lymphocytes T.",
  "komet-001": "KOMET-001 a été l'essai d'enregistrement du ziftomenib : un quart des patients lourdement prétraités atteints de LAM avec mutation NPM1 ont obtenu une rémission complète avec un comprimé pris une fois par jour.",
  "kras-plus-egfr-crc": "Dans le cancer colorectal, un bloqueur de KRAS seul fonctionne à peine parce que la cellule augmente l'activité d'EGFR ; l'ajout d'un anticorps anti-EGFR empêche cela.",
  "krascendo-1": "Le premier essai comparatif direct entre médicaments anti-KRAS : le divarasib de Roche a battu les deux comprimés approuvés sur la progression et la survie.",
  "ku-cancer-center": "Le centre intégré du NCI pour le Kansas et l'ouest du Missouri, actif dans le repositionnement de médicaments, les essais sur le cancer du sein triple négatif et l'accès aux soins en zone rurale.",
  lacc: "La chirurgie mini-invasive, supposée équivalente, s'est révélée pire : plus de récidives et plus de décès que la chirurgie ouverte, ce qui a renversé la pratique du jour au lendemain.",
  "lag3-adjuvant-caution": "Les bloqueurs de LAG-3 ont aidé dans le mélanome mesurable avec une association de médicaments, mais ont échoué en traitement adjuvant et avec un autre partenaire anti-PD-1.",
  "lance-armstrong": "Traité en 1996 pour un cancer du testicule qui s'était propagé aux poumons et au cerveau, il a fondé la fondation qui a fait de la survie au cancer une cause publique et a vendu 80 millions de bracelets jaunes. Son dopage et sa révélation en 2012 compliquent l'héritage.",
  lapatinib: "Le lapatinib a été le premier comprimé bloquant HER2 (2007) et n'est plus aujourd'hui qu'un bras comparateur et une option de ligne tardive, supplanté par le tucatinib et les ADC.",
  latitude: "LATITUDE a établi l'abiraterone dès le premier diagnostic métastatique dans la maladie à haut risque.",
  "lattice-radiotherapy": "Traiter délibérément une grosse tumeur de façon inégale, avec un réseau de pics de très forte dose à l'intérieur, plutôt qu'avec une dose uniforme.",
  laura: "Dans les cancers du poumon de stade III avec mutation EGFR, un comprimé ciblé après chimioradiothérapie a réduit la progression de plus de 80 %.",
  "laura-esserman": "Chirurgienne du sein qui a construit la plateforme I-SPY, l'essai adaptatif qui teste de nouveaux médicaments avant la chirurgie.",
  "laurence-zitvogel": "Immunologiste qui a montré que le microbiome intestinal façonne les réponses à l'immunothérapie et à la chimiothérapie.",
  "leap-012": "L'ajout du lenvatinib et du pembrolizumab à la TACE a retardé la progression de quatre mois et demi mais n'a pas aidé les patients à vivre plus longtemps.",
  "lee-dae-ho": "Dae Ho Lee est un oncologue thoracique à l'origine de la participation coréenne aux essais d'inhibiteurs d'EGFR, d'ALK et de MET qui ont façonné la prise en charge du cancer du poumon.",
  "lee-jae-lyun": "Jae Lyun Lee est un oncologue génito-urinaire qui a intégré des cohortes coréennes aux essais génito-urinaires sur l'enfortumab, le pembrolizumab et les inhibiteurs de PARP.",
  "legend-2": "Le petit essai chinois dont les taux de réponse saisissants à l'ASCO 2017 ont attiré Johnson and Johnson vers Legend Biotech et qui est devenu le CAR-T du myélome Carvykti.",
  "legend-biotech": "Legend Biotech est le développeur d'origine chinoise de Carvykti, le CAR-T le plus efficace dans le myélome, avec J&J.",
  "leon-black": "Après le diagnostic de mélanome de son épouse Debra en 2007, le couple a fondé la Melanoma Research Alliance, qui a consacré plus de 200 millions de dollars à la recherche tandis qu'ils en paient les frais de fonctionnement pour que chaque dollar donné aille à la science.",
  "leptomeningeal-disease": "Des cellules cancéreuses qui se propagent dans le liquide et les membranes qui baignent le cerveau et la moelle épinière, plutôt que sous forme de masse solide. Cela provoque des maux de tête, des paralysies nerveuses et de la confusion, et a été l'une des situations les plus difficiles à traiter.",
  "leukemia-and-lymphoma": "Une revue pour les hématologues et les scientifiques travaillant sur les cancers du sang, de la biologie des leucémies et des lymphomes aux nouveaux médicaments et aux résultats cliniques.",
  "leukemia-research": "Une revue d'Elsevier sur la leucémie et les cancers du sang apparentés, et revue officielle de la Myelodysplastic Syndromes Foundation. Lue par les hématologues et les chercheurs de laboratoire.",
  lgr5: "Un marqueur des cellules souches de l'intestin et des cellules de type souche dans les tumeurs, utilisé pour cibler les médicaments sur les cellules qui font repousser un cancer.",
  lidera: "Le premier SERD oral à réduire les récidives après chirurgie, d'environ 30 %, par rapport aux comprimés hormonaux actuels.",
  "ligue-contre-le-cancer": "La plus ancienne et la plus grande association française de lutte contre le cancer, avec un comité dans chaque département, qui finance la recherche et soutient les patients et la prévention depuis 1918.",
  "litespark-005": "L'inhibiteur de HIF-2α a battu l'ancien standard everolimus après l'échec de l'immunothérapie et de la thérapie ciblée, avec des réponses durables dans un sous-groupe.",
  lobectomy: "Ablation d'un lobe du poumon (le poumon droit en compte trois, le gauche deux). L'opération standard du cancer du poumon à un stade précoce.",
  "locally-advanced": "Cancer qui a dépassé son organe d'origine pour atteindre les tissus voisins ou les ganglions lymphatiques, mais ne s'est pas propagé à distance. Il est traité dans un but curatif, mais nécessite généralement plusieurs traitements combinés (chirurgie, radiothérapie, médicaments).",
  "loi-sherene": "A montré que les cellules immunitaires présentes dans les tumeurs du sein prédisent le pronostic, base de la désescalade de la chimiothérapie dans le TNBC.",
  "long-read-sequencing": "Lire l'ADN par très longs segments, ce qui révèle des réarrangements et une méthylation que les machines à lectures courtes ne détectent pas.",
  "lori-pierce": "Lori Pierce est une radiothérapeute spécialisée dans le cancer du sein et ancienne présidente de l'ASCO, engagée pour l'équité dans les soins du cancer.",
  "lori-wirth": "A dirigé LIBRETTO-001 dans le cancer de la thyroïde, qui a fait du selpercatinib le premier médicament sélectif de RET approuvé pour les tumeurs dépendantes de RET.",
  lumicell: "Spin-off du MIT dont le colorant Lumisight et le système d'imagerie montrent le cancer du sein résiduel dans la cavité de tumorectomie avant la fin de l'opération.",
  "lung-cancer-journal": "La principale revue spécialisée sur le cancer du poumon et les autres tumeurs thoraciques, publiant essais, études translationnelles et revues. Lue par les oncologues thoraciques, les chirurgiens et les pneumologues.",
  lungevity: "LUNGevity est la plus grande association américaine de lutte contre le cancer du poumon, qui veille à ce que chaque patient bénéficie d'un test complet des biomarqueurs et d'un accès aux thérapies ciblées et aux essais, avec GO2 comme partenaire pour la promotion du dépistage.",
  "luveltamab-tazevibulin": "Un ADC ciblant le récepteur des folates, conçu pour agir aussi bien à des niveaux faibles qu'élevés du récepteur, en essai pivot dans le cancer de l'ovaire.",
  "lyell-immunopharma": "Lyell fabrique des thérapies par cellules CAR-T de nouvelle génération conçues pour durer plus longtemps dans l'organisme et résister à l'épuisement. Son produit phare, ronde-cel, cible simultanément deux protéines des cellules de lymphome et est en essais pivots dans le lymphome à grandes cellules B.",
  "lymph-node": "Petits filtres en forme de haricot le long des vaisseaux lymphatiques où se rassemblent les cellules immunitaires. Ils sont souvent le premier endroit où un cancer se propage, et les chirurgiens les examinent donc pour voir jusqu'où la maladie s'est étendue.",
  "lymphoma-research-foundation": "La Lymphoma Research Foundation est la plus grande association américaine consacrée spécifiquement au lymphome, avec des guides en langage simple pour plus de 20 sous-types de lymphome et un programme de recherche centré sur le lymphome à cellules du manteau et le lymphome des adolescents et jeunes adultes.",
  "lymphovascular-invasion": "Le pathologiste a vu des cellules cancéreuses dans de petits vaisseaux lymphatiques ou sanguins du tissu retiré : un signe que la tumeur a trouvé les voies de sortie, même si les ganglions sont indemnes.",
  macrophage: "Grandes cellules immunitaires qui engloutissent et digèrent les débris, les microbes et les cellules mortes et coordonnent l'inflammation. Les tumeurs les recrutent et les reprogramment, si bien que dans de nombreux cancers les macrophages finissent par aider la tumeur plutôt que de la combattre.",
  "magnetic-nanoparticle-hyperthermia": "L'hyperthermie par nanoparticules magnétiques consiste à injecter des nanoparticules d'oxyde de fer dans une tumeur et à les chauffer de l'extérieur avec un champ magnétique alternatif.",
  magnitude: "Un inhibiteur de PARP plus abiraterone a aidé les hommes porteurs de mutations BRCA et n'a rien fait pour ceux qui n'en avaient pas, tranchant un débat.",
  "majestec-3": "Un bispécifique plus daratumumab a réduit le risque de progression de plus de 80 % par rapport aux doublets standard, amenant les bispécifiques en deuxième ligne.",
  masofaniten: "Un médicament conçu pour bloquer la partie du récepteur des androgènes que conservent les variants résistants ; sa phase 2 a été arrêtée pour futilité et le développement a pris fin.",
  melflufen: "Un médicament contre le myélome ayant reçu une approbation accélérée en 2021 et retiré aux États-Unis quelques mois plus tard lorsque son essai de confirmation a suggéré qu'il raccourcissait la survie.",
  mrtx1133: "MRTX1133 a été le premier outil chimique puissant contre KRAS G12D, et a prouvé que cette mutation pouvait être ciblée par un médicament bien qu'elle ne possède pas la poignée réactive de G12C.",
  myocarditis: "Inflammation rare mais souvent mortelle du muscle cardiaque déclenchée par les inhibiteurs de points de contrôle, généralement au cours des deux premiers mois. Elle s'accompagne souvent d'une inflammation musculaire et de la jonction neuromusculaire, et nécessite d'urgence des corticoïdes à forte dose.",
  "myriam-chalabi": "A dirigé NICHE-2, dans lequel presque tous les cancers du côlon avec déficience de la réparation des mésappariements ont répondu à une immunothérapie courte avant la chirurgie.",
  "myricx-bio": "Myricx Bio a inventé un nouveau type de charge utile tuant les cellules cancéreuses, qui bloque une enzyme dont les cellules tumorales ont besoin pour survivre, et la fixe à des anticorps qui la transportent dans les tumeurs. Novartis a acheté l'entreprise londonienne en 2026 pour 1,1 milliard de dollars versés d'avance.",
  "mythic-therapeutics": "Mythic Therapeutics a conçu des anticorps-médicaments conjugués, des anticorps qui transportent un médicament cytotoxique dans les tumeurs, avec une astuce d'ingénierie pour faire entrer plus de médicament dans les cellules cancéreuses. Son principal médicament contre le cancer du poumon a atteint les essais de phase intermédiaire avant que l'entreprise ne cesse ses activités fin 2025.",
  "napoli-3": "Le premier essai comparatif direct entre les deux schémas de base de chimiothérapie, remporté de justesse par le protocole à quatre médicaments.",
  "narula-gaurav": "Oncologue pédiatrique au Tata Memorial qui a dirigé le volet leucémie des premiers essais de CAR-T en Inde et coordonne les protocoles nationaux de leucémie de l'enfant.",
  "national-brain-tumor-society": "La National Brain Tumor Society est la plus grande organisation à but non lucratif consacrée aux tumeurs cérébrales aux États-Unis, connue pour avoir contribué à créer GBM AGILE, l'essai de plateforme adaptatif qui teste de nombreux médicaments contre le glioblastome en même temps, et pour son plaidoyer sur les critères d'évaluation de la FDA pour les tumeurs cérébrales.",
  "ncc-china": "Le National Cancer Center est l'organisme qui recense les cancers de la Chine, définit les programmes nationaux de dépistage et de qualité et publie les statistiques officielles du cancer du pays.",
  "nebraska-buffett": "Le centre désigné par le NCI du Nebraska, leader de longue date dans la classification des lymphomes et la transplantation ainsi que dans la recherche sur la détection précoce du cancer du pancréas.",
  "neeraj-agarwal": "Oncologue génito-urinaire qui a dirigé TALAPRO-2 et d'autres essais associant des inhibiteurs de PARP à l'hormonothérapie.",
  nemtabrutinib: "Le nemtabrutinib est l'inhibiteur réversible de BTK de Merck, actif contre la mutation d'échappement C481S, testé face à l'ibrutinib et à l'acalabrutinib dans la LLC de première ligne.",
  "neogene-therapeutics": "Neogene a développé des thérapies par récepteurs de cellules T capables de reconnaître des mutations spécifiques du cancer cachées à l'intérieur des cellules tumorales, une approche visant les tumeurs solides. AstraZeneca a acheté l'entreprise en janvier 2023 pour un montant pouvant atteindre 320 millions de dollars.",
  nephrectomy: "Ablation d'un rein (radicale) ou seulement de la partie qui porte la tumeur (partielle).",
  neratinib: "Un comprimé pris pendant un an après le trastuzumab pour réduire encore les récidives dans le cancer du sein HER2-positif à récepteurs hormonaux positifs, limité par des diarrhées sévères.",
  "nerve-tumour-denervation": "Les tumeurs recrutent des nerfs et utilisent les signaux nerveux pour croître. Le blocage de ce trafic, par des bêtabloquants ou la toxine botulique, est en cours d'évaluation.",
  "nested-therapeutics": "Nested Therapeutics traque les mutations cachées qui pilotent le cancer et conçoit des médicaments qui s'y adaptent. Son premier médicament, NST-628, colle ensemble deux protéines de signalisation (RAF et MEK) pour éteindre une voie de croissance fréquente du cancer.",
  neutropenia: "Un manque de neutrophiles, les globules blancs qui combattent les bactéries, causé par l'atteinte de la moelle osseuse par la chimiothérapie. Il atteint généralement son point le plus bas (le nadir) 7-14 jours après chaque cycle et se rétablit avant le suivant ; pendant la période basse, le risque d'infection est élevé.",
  "nha-pmjay": "L'agence qui gère l'assurance maladie publique de l'Inde pour les 40 % les plus pauvres de la population, qui prend en charge la chirurgie du cancer, la chimiothérapie et la radiothérapie jusqu'à un plafond annuel par famille.",
  nhsa: "La NHSA gère l'assurance maladie publique de la Chine et négocie une fois par an quels nouveaux médicaments anticancéreux sont remboursés, et à quel prix, par le biais de la National Reimbursement Drug List.",
  niagara: "La première immunothérapie ayant démontré une amélioration de la survie lorsqu'elle est administrée autour de la chirurgie d'ablation de la vessie.",
  "nice-guidance": "L'organisme britannique qui décide quels traitements du cancer le NHS prend en charge, en publiant des évaluations détaillées du coût par année de vie ajustée sur la qualité pour chaque médicament, ainsi que des recommandations cliniques. Ses décisions sont largement lues comme un avis indépendant sur la valeur.",
  "nicholas-james": "Nicholas James est l'investigateur principal de STAMPEDE, l'essai de plateforme qui a remodelé le traitement du cancer de la prostate avancé.",
  "nikhil-munshi": "A dirigé KarMMa, qui a conduit à l'approbation de l'idecabtagene vicleucel, le premier CAR-T pour le myélome.",
  "nimbus-therapeutics": "Nimbus Therapeutics est une entreprise de Boston qui utilise la chimie assistée par ordinateur pour concevoir des comprimés contre des cibles thérapeutiques difficiles. Son médicament anticancéreux bloque une enzyme appelée WRN dont dépendent certains cancers de l'intestin et de l'utérus présentant une réparation de l'ADN défectueuse.",
  nintedanib: "Un comprimé anti-angiogénique qui semblait prometteur dans le mésothéliome dans un petit essai mais a échoué dans le grand essai.",
  "nk-cell": "Cellules tueuses naturelles : des cellules immunitaires à action rapide qui détruisent les cellules anormales sans avoir besoin d'être entraînées contre une cible précise. Elles se spécialisent dans l'élimination des cellules qui se sont cachées des cellules T.",
  "nmibc-vs-mibc": "Le cancer de la vessie est classé selon qu'il a ou non envahi la paroi musculaire de la vessie. Avant cela, il est traité à l'intérieur de la vessie ; après, la vessie est généralement retirée ou irradiée.",
  noetik: "Noetik construit des modèles d'intelligence artificielle des tumeurs à partir d'immenses ensembles d'images de tissus et de données moléculaires, pour prédire quels patients répondront à un médicament anticancéreux et pour trouver de nouvelles cibles.",
  "non-inferiority": "Un essai conçu pour montrer qu'un nouveau traitement n'est pas significativement moins bon que le traitement de référence, plutôt que meilleur : utilisé lorsque la nouvelle option est plus courte, moins chère, moins toxique ou plus simple (cinq fractions de radiothérapie au lieu de 25, six mois de trastuzumab au lieu de douze).",
  "nonmutational-epigenetic-reprogramming": "Les cancers peuvent changer de comportement, y compris devenir tolérants aux médicaments, sans aucune nouvelle mutation, en réécrivant les marques chimiques qui contrôlent quels gènes sont lus.",
  "noronha-vanita": "Oncologue médicale qui codirige les essais sur le cancer du poumon du Tata Memorial et a bâti le programme d'oncologie gériatrique de l'Inde.",
  nouscom: "Nouscom développe Nous-209, un vaccin à vecteur viral prêt à l'emploi codant 209 néoantigènes partagés issus de décalages du cadre de lecture, pour intercepter le cancer chez les porteurs du syndrome de Lynch.",
  "nsclc-signalling": "La carte KEGG du cancer du poumon non à petites cellules montre un ensemble d'interrupteurs d'activation alternatifs (mutation d'EGFR, mutation de KRAS, EML4-ALK, altérations de RET et MET) qui alimentent tous les mêmes relais RAS/ERK, PI3K/AKT et STAT, plus la perte des freins p16 et p53. Chaque interrupteur dispose désormais de son propre comprimé ciblé, ce qui explique pourquoi les tests moléculaires précèdent le traitement.",
  "nuclear-medicine-hardware": "Le matériel de médecine nucléaire désigne les scanners eux-mêmes : TEP/TDM, TEMP/TDM et la nouvelle TEP corps entier qui image tout le corps en une seule fois.",
  nucleix: "Nucleix fabrique des tests urinaires et sanguins qui lisent les marques chimiques sur l'ADN pour repérer la récidive du cancer de la vessie et, en développement, pour détecter précocement le cancer du poumon.",
  "nutrition-lifestyle-roadmap": "Ce que les gens mangent, pèsent et font détermine qui a un cancer et comment se déroule le traitement. Des décennies d'essais ont séparé ce qui est établi (l'obésité, l'alcool et l'inactivité causent le cancer ; l'exercice après le traitement réduit les récidives) de ce qui relève du battage, et les prochaines questions sont posées avec la rigueur d'un essai médicamenteux.",
  "obsidian-therapeutics": "Obsidian cultive les propres cellules immunitaires antitumorales du patient et les modifie avec un interrupteur qui permet aux médecins de contrôler un signal de croissance (IL-15) avec un médicament oral, dans le but de rendre la thérapie TIL plus sûre et plus efficace pour le mélanome et le cancer du poumon. Elle est entrée au Nasdaq en août 2026 après avoir levé 350 millions de dollars.",
  "obstructive-jaundice": "Jaunissement de la peau et des yeux parce qu'une tumeur bloque le canal biliaire, le plus souvent un cancer du pancréas ou des voies biliaires. Il provoque des démangeaisons, un risque d'infection et des urines foncées, et doit être levé (généralement par une endoprothèse) avant que la chimiothérapie puisse être administrée en toute sécurité.",
  "ocular-toxicity": "Problèmes oculaires dus aux médicaments anticancéreux : vision floue et lésions de la cornée avec certains ADC (belantamab, tisotumab), liquide rétinien avec les inhibiteurs de MEK, et inflammation avec l'immunothérapie. Généralement réversibles avec des interruptions de dose, mais ils nécessitent des examens ophtalmologiques réguliers.",
  ofatumumab: "L'ofatumumab (Arzerra) est un anticorps anti-CD20 entièrement humain pour la leucémie lymphoïde chronique, utilisé avec le chlorambucil chez les patients non traités ou seul après l'échec d'autres médicaments ; la même molécule est vendue sous le nom de Kesimpta pour la sclérose en plaques.",
  "oh-do-youn": "Investigateur principal de TOPAZ-1, l'essai qui a ajouté l'immunothérapie à la chimiothérapie de première ligne pour le cancer des voies biliaires.",
  oligoprogression: "Lorsque seulement un ou deux foyers progressent sous une thérapie ciblée par ailleurs efficace ; on traite les foyers et on garde le comprimé.",
  olomorasib: "L'olomorasib est le comprimé anti-KRAS G12C de Lilly, conçu pour se combiner en toute sécurité avec l'immunothérapie en première ligne du cancer du poumon.",
  "on-target-laboratories": "Spin-out de Purdue qui a développé Cytalux, le colorant lumineux qui révèle les dépôts de cancer de l'ovaire et du poumon pendant la chirurgie.",
  "onc-ai": "Onc.AI entraîne une intelligence artificielle sur des scanners CT de routine pour prédire précocement si l'immunothérapie d'un patient atteint d'un cancer du poumon fonctionne, afin que les médecins et les développeurs de médicaments puissent changer de cap plus tôt.",
  oncohost: "OncoHost vend un test sanguin qui mesure des centaines de protéines avant le début du traitement pour prédire si un patient atteint d'un cancer du poumon bénéficiera des médicaments d'immunothérapie.",
  "oncotype-dx-gps": "Un test de biopsie à 17 gènes qui aide les hommes ayant un cancer de la prostate à faible risque nouvellement diagnostiqué à décider entre surveiller ou traiter.",
  "oneal-uab": "Le seul centre de cancérologie intégré désigné par le NCI de l'Alabama, l'un des premiers désignés en 1971, desservant le Deep South et étudiant les disparités face au cancer.",
  "ontario-health-cancer-care-ontario": "Le programme provincial de lutte contre le cancer de la province la plus peuplée du Canada, anciennement Cancer Care Ontario et désormais intégré à Ontario Health.",
  "oric-pharmaceuticals": "ORIC Pharmaceuticals développe des comprimés conçus pour vaincre les mécanismes par lesquels les cancers résistent au traitement. L'un bloque un complexe d'extinction des gènes dans le cancer de la prostate ; l'autre cible EGFR et HER2 mutés dans le cancer du poumon et peut atteindre le cerveau.",
  "orient-11": "L'essai qui a fait du sintilimab un traitement de première ligne du cancer du poumon en Chine, et celui que la FDA a ensuite refusé d'accepter comme preuve pour les patients américains.",
  "orient-16": "L'essai chinois sur le cancer de l'estomac qui a montré que l'ajout du sintilimab à la chimiothérapie aide les patients à vivre plus longtemps, surtout lorsque la tumeur exprime PD-L1.",
  pasritamig: "L'engageur de lymphocytes T spécifique de la prostate de J&J, remarquable pour une très faible libération de cytokines dans les essais précoces.",
  "pet-mri": "La TEP combinée à l'IRM plutôt qu'au scanner, offrant la biologie plus le meilleur détail des tissus mous, à une dose de rayonnement plus faible.",
  psa50: "Le PSA50 est la proportion de patients dont le PSA baisse d'au moins la moitié sous traitement, et le PSA90 la proportion dont le PSA baisse de 90 %.",
  pylarify: "Le piflufolastat F-18 (Pylarify) est le principal traceur TEP du PSMA pour le cancer de la prostate, avec une nouvelle formulation approuvée en mars 2026.",
  relacorilant: "Un médicament premier de sa classe qui bloque la signalisation du cortisol dans les cellules tumorales, approuvé en 2026 pour le cancer de l'ovaire résistant au platine en association avec la chimiothérapie.",
  relugolix: "Le relugolix est le premier comprimé de suppression hormonale pour le cancer de la prostate, agissant en quelques jours et s'estompant rapidement à l'arrêt.",
  rindopepimut: "Un vaccin contre une protéine mutante spécifique du glioblastome qui a semblé prometteur pendant des années puis a échoué en phase 3 en 2016. C'est un échec marquant.",
  "robotic-bronchoscopy": "Un endoscope souple guidé par robot qui atteint de petits nodules pulmonaires par les voies respiratoires pour les biopsier sans aiguille à travers la paroi thoracique.",
  ror1: "ROR1 est un récepteur embryonnaire ré-exprimé par de nombreux cancers, utilisé comme adresse d'ADC dans le lymphome et le cancer du sein.",
  "rovalpituzumab-tesirine": "Le rovalpituzumab tésirine (Rova-T) a été le premier médicament dirigé contre DLL3 dans le cancer du poumon à petites cellules. AbbVie l'a acheté pour 5,8 milliards de dollars et l'a abandonné après deux essais de phase 3 ratés. La cible a fonctionné plus tard avec une arme différente.",
  steap1: "STEAP1 est une protéine à la surface de la plupart des cellules du cancer de la prostate, désormais l'adresse d'un engageur de lymphocytes T en phase 3.",
  suv: "La valeur de fixation normalisée (SUV) est un nombre indiquant l'intensité avec laquelle un foyer s'illumine sur une TEP.",
  "tissue-factor": "Le facteur tissulaire est une protéine de la coagulation que les cancers exposent anormalement à leur surface, utilisée comme cible d'ADC dans le cancer du col de l'utérus.",
  "trastuzumab-duocarmazine": "Un ADC anti-HER2 à charge utile alkylante de l'ADN qui a battu la chimiothérapie dans un essai de phase 3 mais n'a jamais atteint le marché, en raison de sa toxicité oculaire et pulmonaire et de l'arrivée préalable d'un rival plus puissant.",
  "tusamitamab-ravtansine": "Le tusamitamab ravtansine était l'ADC de Sanofi dirigé contre le marqueur tumoral classique CEA, arrêté pour futilité dans le cancer du poumon en 2023.",
  zidesamtinib: "Un inhibiteur de ROS1 approuvé en juillet 2026 qui agit après l'échec des autres médicaments anti-ROS1 et évite leurs effets secondaires cérébraux.",
  "zilovertamab-vedotin": "Le zilovertamab védotine est un ADC dirigé contre ROR1 en phase 3 pour le lymphome à grandes cellules B.",
  zongertinib: "Le zongertinib a été le premier inhibiteur oral de HER2 pour le cancer du poumon avec mutations de HER2, approuvé en 2025 et passé en première ligne en 2026.",
};
